    def __init__(self, config: dict) -> None:
        super().__init__(config)
        self._squeeze_count: dict[str, int] = {}
        self._pending_breakout: dict[str, Optional[dict]] = {}
        self._pending_panic: dict[str, Optional[dict]] = {}
        self._bar_counters: dict[str, int] = {}
        self._tpc_last_entry_bar: dict[str, int] = {}
        self._tpc_zone_entry_bar: dict[str, int] = {}  # bar when price entered pullback zone
        self._trbk_last_entry_bar: dict[str, int] = {}  # TRBK cooldown tracking
        self._bearvol_last_entry_bar: dict[str, int] = {}  # BEAR_VOL cooldown
        self._brf_cooldown_until_idx: dict[str, int] = {}  # BRF pair cooldown after stoploss hits
        self._brf_debug_last_log_rows: dict[str, int] = {}  # BRF debug log rate-limit per pair
