    # ══════════════════════════════════════════════════════════
    # informative_pairs  (HTF data for TPC)
    # ══════════════════════════════════════════════════════════

    def informative_pairs(self):
        """Request 4h candles for each whitelist pair (TPC + TRBK HTF trend filter)
        and BTC/USDT:USDT 4h for market-regime filter."""
        pairs = self.dp.current_whitelist()
        pair_set = set(pairs)

        result = [(pair, "4h") for pair in pairs]
        # BTC 4h for market filter + bear gate (always fetch)
        btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
        if btc_pair in pair_set and (btc_pair, "4h") not in result:
            result.append((btc_pair, "4h"))
        if bool(self.buy_relstr_enabled.value):
            rel_tf = str(self.buy_relstr_tf.value or "4h")
            if btc_pair in pair_set and rel_tf in {"1h", "4h"} and (btc_pair, rel_tf) not in result:
                result.append((btc_pair, rel_tf))
        if bool(self.buy_idle_fr_enabled.value):
            fr_tf = str(self.buy_idle_fr_tf.value or "15m")
            allow_pairs = {
                p.strip()
                for p in str(self.buy_idle_fr_allow_pairs.value or "").split(",")
                if p.strip()
            }
            for p in pairs:
                if (not allow_pairs) or (p in allow_pairs):
                    tup = (p, fr_tf)
                    if tup not in result:
                        result.append(tup)
            btc_fr = (btc_pair, fr_tf)
            if btc_pair in pair_set and btc_fr not in result:
                result.append(btc_fr)
        if bool(self.buy_lc_enabled.value):
            lc_tf = str(self.buy_lc_tf.value or "5m")
            lc_allow_pairs = {
                p.strip()
                for p in str(self.buy_lc_allow_pairs.value or "").split(",")
                if p.strip()
            }
            for p in pairs:
                if (not lc_allow_pairs) or (p in lc_allow_pairs):
                    tup = (p, lc_tf)
                    if tup not in result:
                        result.append(tup)
        if bool(self.buy_lc2_enabled.value):
            lc2_tf = str(self.buy_lc2_tf.value or "5m")
            lc2_allow_pairs = {
                p.strip()
                for p in str(self.buy_lc2_allow_pairs.value or "").split(",")
                if p.strip()
            }
            for p in pairs:
                if (not lc2_allow_pairs) or (p in lc2_allow_pairs):
                    tup = (p, lc2_tf)
                    if tup not in result:
                        result.append(tup)
        if bool(self.buy_evtpulse_enabled.value):
            evt_tf = str(self.buy_evtpulse_tf.value or "5m")
            evt_allow_pairs = {
                p.strip()
                for p in str(self.buy_evtpulse_allow_pairs.value or "").split(",")
                if p.strip()
            }
            for p in pairs:
                if (not evt_allow_pairs) or (p in evt_allow_pairs):
                    tup = (p, evt_tf)
                    if tup not in result:
                        result.append(tup)
        if bool(self.buy_fimr_enabled.value):
            fimr_tf = str(self.buy_fimr_tf.value or "1h")
            fimr_allow_pairs = {
                p.strip()
                for p in str(self.buy_fimr_allow_pairs.value or "").split(",")
                if p.strip()
            }
            for p in pairs:
                if (not fimr_allow_pairs) or (p in fimr_allow_pairs):
                    tup = (p, fimr_tf)
                    if tup not in result:
                        result.append(tup)
                    if bool(self.buy_fimr_use_funding.value):
                        fr_tup = (p, fimr_tf, "funding_rate")
                        if fr_tup not in result:
                            result.append(fr_tup)
                    if bool(self.buy_fimr_use_basis.value):
                        for candle_type in ("mark", "index"):
                            basis_tup = (p, fimr_tf, candle_type)
                            if basis_tup not in result:
                                result.append(basis_tup)
        if self._base_deriv_basis_needed():
            base_tf = str(self.timeframe)
            for p in pairs:
                for candle_type in ("mark", "index"):
                    basis_tup = (p, base_tf, candle_type)
                    if basis_tup not in result:
                        result.append(basis_tup)
        if bool(self.buy_fcarry_enabled.value):
            fcarry_tf = str(self.buy_fcarry_tf.value or "1h")
            fcarry_allow_pairs = {
                p.strip()
                for p in str(self.buy_fcarry_allow_pairs.value or "").split(",")
                if p.strip()
            }
            for p in pairs:
                if (not fcarry_allow_pairs) or (p in fcarry_allow_pairs):
                    tup = (p, fcarry_tf)
                    if tup not in result:
                        result.append(tup)
                    fr_tup = (p, fcarry_tf, "funding_rate")
                    if fr_tup not in result:
                        result.append(fr_tup)
        if bool(self.buy_lagcatch_enabled.value):
            market_pair = str(self.buy_lagcatch_market_pair.value or "")
            if market_pair not in pair_set:
                market_pair = btc_pair if btc_pair in pair_set else ""
            market_tup = (market_pair, self.timeframe)
            if market_pair and market_tup not in result:
                result.append(market_tup)
        if self._novel_alpha_any_enabled():
            for ref_pair in (self._resolve_ref_pair("BTC"), self._resolve_ref_pair("ETH")):
                if not ref_pair:
                    continue
                ref_tup = (ref_pair, self.timeframe)
                if ref_tup not in result:
                    result.append(ref_tup)
        if bool(self.buy_corr_cap_enabled.value):
            corr_tf = str(self.buy_corr_cap_tf.value or self.timeframe)
            if corr_tf != self.timeframe:
                for p in pairs:
                    tup = (p, corr_tf)
                    if tup not in result:
                        result.append(tup)
        return result

    @staticmethod
    def _pair_base_asset(pair: str) -> str:
        token = str(pair or "").strip().upper()
        if not token:
            return ""
        if "/" in token:
            return token.split("/", 1)[0].strip()
        return token

    def _trbk_pair_adx_floor(self, pair: str) -> float:
        base_floor = float(self.buy_trbk_adx_min.value)
        profile = str(self.buy_trbk_pair_profile.value or "off").strip().lower()
        asset = self._pair_base_asset(pair)
        if profile == "off" or asset not in {"ETC", "TRX", "FIL"}:
            return base_floor
        add_by_profile = {
            "kraken_etf_soft": {"ETC": 2.0, "TRX": 1.0, "FIL": 1.0},
            "kraken_etf_med": {"ETC": 4.0, "TRX": 2.0, "FIL": 2.0},
            "kraken_etf_hard": {"ETC": 6.0, "TRX": 3.0, "FIL": 3.0},
        }
        return base_floor + float(add_by_profile.get(profile, {}).get(asset, 0.0))

    def _trbk_pair_breakout_buffer_atr(self, pair: str) -> float:
        if self._pair_base_asset(pair) != "ETC":
            return 0.0
        profile = str(self.buy_trbk_etc_breakout_profile.value or "off").strip().lower()
        return {
            "atr_0p10": 0.10,
            "atr_0p20": 0.20,
            "atr_0p30": 0.30,
        }.get(profile, 0.0)

    def _trbk_pair_gate_allows(self, pair: str) -> bool:
        profile = str(self.buy_trbk_pair_gate_profile.value or "off").strip().lower()
        if profile == "off":
            return True
        asset = self._pair_base_asset(pair)
        if profile == "deny_etc":
            return asset != "ETC"
        if profile == "deny_etc_trx":
            return asset not in {"ETC", "TRX"}
        if profile == "deny_etc_trx_fil":
            return asset not in {"ETC", "TRX", "FIL"}
        if profile == "allow_only_trx_fil":
            return asset in {"TRX", "FIL"}
        if profile == "allow_only_fil":
            return asset == "FIL"
        return True

    def _trendpb_pair_reclaim_mode(self, pair: str) -> str:
        profile = str(self.buy_trendpb_pair_profile.value or "off").strip().lower()
        asset = self._pair_base_asset(pair)
        if profile != "off" and asset in {"ETC", "FIL"}:
            return "CROSS_EMA_SLOW"
        return str(self.buy_trendpb_reclaim_mode.value).upper()

    def _trendpb_pair_vol_ratio_min(self, pair: str) -> float:
        base_min = float(self.buy_trendpb_vol_ratio_min.value)
        profile = str(self.buy_trendpb_pair_profile.value or "off").strip().lower()
        asset = self._pair_base_asset(pair)
        if asset not in {"ETC", "FIL"}:
            return base_min
        override = {
            "etcfil_slow_vol14": 1.40,
            "etcfil_slow_vol15": 1.50,
            "etcfil_slow_vol16": 1.60,
        }.get(profile)
        if override is None:
            return base_min
        return max(base_min, float(override))

    def _trendpb_pair_gate_allows(self, pair: str) -> bool:
        profile = str(self.buy_trendpb_pair_gate_profile.value or "off").strip().lower()
        if profile == "off":
            return True
        asset = self._pair_base_asset(pair)
        if profile == "deny_etc":
            return asset != "ETC"
        if profile == "deny_etc_fil":
            return asset not in {"ETC", "FIL"}
        if profile == "allow_strong_kraken":
            return asset in {"ETH", "LTC", "UNI", "TRX", "ADA", "INJ"}
        if profile == "allow_strong_plus_fil":
            return asset in {"ETH", "LTC", "UNI", "TRX", "ADA", "INJ", "FIL"}
        return True

    def _bearvol_pair_profile_allows(self, pair: str) -> bool:
        profile = str(self.sell_bearvol_pair_expectancy_profile.value or "off").strip().lower()
        if profile == "off":
            return True
        asset = self._pair_base_asset(pair)
        if profile == "kraken_positive_only":
            return asset in {"LTC", "WLD", "FIL", "DOGE"}
        if profile == "kraken_positive_plus_btc":
            return asset in {"LTC", "WLD", "FIL", "DOGE", "BTC"}
        return True

    def _current_whitelist_pairs(self) -> list[str]:
        try:
            pairs = self.dp.current_whitelist() if self.dp else []
        except Exception:
            pairs = []
        if pairs:
            return [str(p) for p in pairs if p]
        try:
            wl = (self.config or {}).get("exchange", {}).get("pair_whitelist", [])
        except Exception:
            wl = []
        return [str(p) for p in wl if p]

    def _resolve_ref_pair(self, base: str, preferred_pair: str | None = None) -> str | None:
        """Resolve a reference pair by base asset across quote/collateral variants."""
        base_u = str(base or "").strip().upper()
        if not base_u:
            return None

        hint = str(preferred_pair or "").strip()
        candidates: list[str] = []
        if hint:
            candidates.append(hint)
        candidates.extend([
            f"{base_u}/USDT:USDT",
            f"{base_u}/USD:USD",
            f"{base_u}/USD",
            f"{base_u}/USDT",
        ])

        pairs = self._current_whitelist_pairs()
        pair_set = set(pairs)
        for cand in candidates:
            if cand in pair_set:
                return cand
        for cand in pairs:
            if self._pair_base_asset(cand) == base_u:
                return cand
        if hint:
            return hint
        return candidates[0] if candidates else None

    def _resolve_pair_hint(self, pair_hint: str | None, fallback_base: str = "BTC") -> str | None:
        hint = str(pair_hint or "").strip()
        base = self._pair_base_asset(hint) or str(fallback_base or "BTC").upper()
        return self._resolve_ref_pair(base, preferred_pair=hint if hint else None)

    def _pairs_same_base(self, left: str, right: str) -> bool:
        lb = self._pair_base_asset(left)
        rb = self._pair_base_asset(right)
        return bool(lb) and bool(rb) and lb == rb

    def _trendpb_diag_target_month(self, pair: str, row: pd.Series) -> str | None:
        """
        Return YYYY-MM month key for targeted TrendPB diagnostics, else None.

        Targets only:
        - TRX / FIL
        - 2024-12 and 2025-07
        """
        base = self._pair_base_asset(pair)
        if base not in {"TRX", "FIL"}:
            return None
        try:
            ts = pd.Timestamp(row.get("date"))
        except Exception:
            return None
        if ts is pd.NaT:
            return None
        if ts.tzinfo is not None:
            try:
                ts = ts.tz_convert("UTC")
            except Exception:
                pass
        month = str(ts.strftime("%Y-%m"))
        if month in {"2024-12", "2025-07"}:
            return month
        return None

    def _trendpb_diag_record_first_fail(
        self,
        pair: str,
        row: pd.Series,
        reason: str,
        details: dict[str, Any] | None = None,
    ) -> None:
        """Append first-fail telemetry rows for targeted TRX/FIL pair-month windows."""
        month = self._trendpb_diag_target_month(pair, row)
        if month is None:
            return
        try:
            if not hasattr(self, "_trendpb_diag_file_initialized"):
                self._trendpb_diag_file_initialized = False
            diag_path = Path("user_data/backtest_results/trendpb_first_fail_diag.jsonl")
            if not self._trendpb_diag_file_initialized:
                try:
                    diag_path.unlink(missing_ok=True)
                except Exception:
                    pass
                self._trendpb_diag_file_initialized = True
            event = {
                "ts": str(row.get("date")),
                "pair": str(pair),
                "base": self._pair_base_asset(pair),
                "month": month,
                "reason": str(reason),
            }
            if details:
                event.update(details)
            diag_path.parent.mkdir(parents=True, exist_ok=True)
            with diag_path.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(event, ensure_ascii=True) + "\n")
        except Exception:
            # Never let diagnostics alter strategy behavior.
            return

    def _trendpb_repair_active(self) -> bool:
        """Repair path is active only when enabled and exchange is krakenfutures."""
        if not bool(self.buy_trendpb_repair_enabled.value):
            return False
        try:
            ex_name = str((self.config or {}).get("exchange", {}).get("name", "") or "").lower()
        except Exception:
            ex_name = ""
        return ex_name == "krakenfutures"

    def _trendpb_repair_inc(self, key: str) -> None:
        if hasattr(self, "_trendpb_repair_counts"):
            self._trendpb_repair_counts[key] = int(self._trendpb_repair_counts.get(key, 0)) + 1

    def trendpb_repair_counts_snapshot(self) -> dict[str, int]:
        try:
            return dict(self._trendpb_repair_counts)
        except Exception:
            return {}

    def _trendpb_repair_pair_day_key(self, pair: str, current_time: Any) -> str:
        try:
            ts = pd.Timestamp(current_time)
            return f"{pair}|{ts.strftime('%Y-%m-%d')}"
        except Exception:
            return f"{pair}|unknown"

    def _trendpb_repair_pair_day_allow(self, pair: str, current_time: Any) -> bool:
        cap = int(self.buy_trendpb_repair_pair_day_cap.value)
        if cap <= 0:
            return True
        key = self._trendpb_repair_pair_day_key(pair, current_time)
        return int(self._trendpb_repair_pair_day_counts.get(key, 0)) < cap

    def _trendpb_repair_pair_day_mark(self, pair: str, current_time: Any) -> None:
        key = self._trendpb_repair_pair_day_key(pair, current_time)
        self._trendpb_repair_pair_day_counts[key] = int(self._trendpb_repair_pair_day_counts.get(key, 0)) + 1

    def _tpb_csv_float_map(self, raw: str) -> dict[str, float]:
        out: dict[str, float] = {}
        try:
            parts = [x.strip() for x in str(raw or "").split(",") if x.strip()]
            for part in parts:
                if "=" not in part:
                    return {}
                k, v = part.split("=", 1)
                key = str(k).strip()
                if not key:
                    return {}
                out[key] = float(str(v).strip())
            return out
        except Exception:
            return {}

    def _tpb_pair_allowlist(self) -> set[str]:
        return {
            x.strip() for x in str(self.buy_trendpb_repair_pair_allowlist.value or "").split(",")
            if x.strip()
        }

    def _tpb_pair_allowed(self, pair: str) -> bool:
        allow = self._tpb_pair_allowlist()
        if not allow:
            return False
        if pair in allow:
            return True
        base = self._pair_base_asset(pair)
        if not base:
            return False
        allow_bases = {self._pair_base_asset(x) for x in allow}
        return base in allow_bases

    def _tpb_pair_zone_depth_mult(self, pair: str) -> float | None:
        if not bool(self.buy_trendpb_repair_pair_zone_relief_enabled.value):
            return None
        fmap = self._tpb_csv_float_map(str(self.buy_trendpb_repair_pair_zone_depth_mult_map.value or ""))
        if not fmap:
            return None
        if pair in fmap:
            return float(fmap[pair])
        base = self._pair_base_asset(pair)
        if not base:
            return None
        matches = [float(v) for k, v in fmap.items() if self._pair_base_asset(k) == base]
        if len(matches) == 1:
            return matches[0]
        # Fail-closed on ambiguous mappings for a base.
        return None

    def _trendpb_repair_local_evidence_allows(
        self,
        row: dict[str, Any],
        pair: str,
        side: str = "long",
    ) -> tuple[bool, str]:
        del side
        if not self._tpb_pair_allowed(pair):
            self._trendpb_repair_inc("relief_block_pair_not_allowed")
            return False, "pair_not_allowed"

        if bool(self.buy_trendpb_repair_require_reclaim.value):
            reclaim_ok = row.get("trendpb_reclaim_ok", row.get("tpb_reclaim_ok", None))
            if reclaim_ok is None or not bool(reclaim_ok):
                self._trendpb_repair_inc("relief_block_reclaim")
                return False, "reclaim_block"

        if bool(self.buy_trendpb_repair_require_volume.value):
            relvol = row.get("trendpb_relvol", row.get("relvol", None))
            if relvol is None:
                vol_now = row.get("volume", None)
                vol_ma = row.get("trendpb_vol_ma20", None)
                try:
                    if vol_now is not None and vol_ma is not None and float(vol_ma) > 0:
                        relvol = float(vol_now) / float(vol_ma)
                except Exception:
                    relvol = None
            try:
                if relvol is None or float(relvol) < float(self.buy_trendpb_repair_min_relvol.value):
                    self._trendpb_repair_inc("relief_block_volume")
                    return False, "volume_block"
            except Exception:
                self._trendpb_repair_inc("relief_block_volume")
                return False, "volume_block"

        if bool(self.buy_trendpb_repair_require_relstr.value):
            relstr = row.get("relstr_excess", row.get("pair_relstr", None))
            try:
                if relstr is None or float(relstr) < float(self.buy_trendpb_repair_min_relstr.value):
                    self._trendpb_repair_inc("relief_block_relstr")
                    return False, "relstr_block"
            except Exception:
                self._trendpb_repair_inc("relief_block_relstr")
                return False, "relstr_block"

        if bool(self.buy_trendpb_repair_require_rsi_ok.value):
            rsi_ok = row.get("trendpb_rsi_ok", None)
            if rsi_ok is None or not bool(rsi_ok):
                self._trendpb_repair_inc("relief_block_rsi")
                return False, "rsi_block"

        close_in_range = row.get("close_in_range", row.get("trendpb_close_in_range", None))
        if close_in_range is None:
            try:
                high = float(row.get("high", np.nan))
                low = float(row.get("low", np.nan))
                close = float(row.get("close", np.nan))
                if np.isfinite(high) and np.isfinite(low) and np.isfinite(close) and high > low:
                    close_in_range = (close - low) / (high - low)
            except Exception:
                close_in_range = None
        try:
            if close_in_range is None or float(close_in_range) < float(self.buy_trendpb_repair_min_close_in_range.value):
                self._trendpb_repair_inc("relief_block_close_quality")
                return False, "close_quality_block"
        except Exception:
            self._trendpb_repair_inc("relief_block_close_quality")
            return False, "close_quality_block"

        return True, "pass"

    def _trendpb_repair_diag_record(self, payload: dict[str, Any]) -> None:
        if not self._trendpb_repair_active():
            return
        try:
            user_dir = (self.config or {}).get("user_data_dir", "user_data")
            out_path = Path(str(user_dir)) / "backtest_results" / "trendpb_repair_diag.jsonl"
            if not self._trendpb_repair_diag_file_initialized:
                try:
                    out_path.unlink(missing_ok=True)
                except Exception:
                    pass
                self._trendpb_repair_diag_file_initialized = True
            out_path.parent.mkdir(parents=True, exist_ok=True)
            with out_path.open("a", encoding="utf-8") as f:
                f.write(json.dumps(payload, default=str, ensure_ascii=True) + "\n")
        except Exception:
            return

    def bot_start(self, **kwargs) -> None:
        """Startup hooks: log recovered trades and optional recovery-mode entry block."""
        if not self._startup_recovery_logged:
            recovered = 0
            try:
                open_trades = Trade.get_open_trades()
                recovered = 0 if open_trades is None else len(open_trades)
            except Exception:
                recovered = 0
            logger.info("Recovered open trades: %s", recovered)
            self._startup_recovery_logged = True

        if self.recovery_mode_enabled and int(self.recovery_mode_candles) > 0:
            try:
                runmode = str(getattr(self.dp, "runmode", "")).lower()
            except Exception:
                runmode = ""
            if "backtest" not in runmode and "hyperopt" not in runmode:
                minutes = self._timeframe_to_minutes(self.timeframe)
                block_minutes = minutes * int(self.recovery_mode_candles)
                self._recovery_mode_until = datetime.utcnow() + timedelta(minutes=block_minutes)
                logger.info(
                    "Recovery mode enabled: blocking new entries for %s candles (%sm) until %s",
                    int(self.recovery_mode_candles),
                    block_minutes,
                    self._recovery_mode_until.isoformat(),
                )

        # CBX V2 preset application (one-time, fail-open, runs in both backtest and live)
        if not self._cbx_v2_preset_applied:
            try:
                self._cbx_v2_apply_preset()
            except Exception:
                pass
            self._cbx_v2_preset_applied = True

    def _timeframe_to_minutes(self, timeframe: str) -> int:
        """Convert Freqtrade timeframe notation to minutes."""
        try:
            if timeframe.endswith("m"):
                return int(timeframe[:-1])
            if timeframe.endswith("h"):
                return int(timeframe[:-1]) * 60
            if timeframe.endswith("d"):
                return int(timeframe[:-1]) * 1440
        except Exception:
            pass
        return 60

    def _can_merge_informative_timeframe(self, base_tf: str, informative_tf: str) -> bool:
        """Freqtrade allows merge only when informative timeframe >= base timeframe."""
        return self._timeframe_to_minutes(informative_tf) >= self._timeframe_to_minutes(base_tf)

    def _recovery_mode_active(self, current_time: datetime) -> bool:
        if self._recovery_mode_until is None:
            return False
        return current_time < self._recovery_mode_until

    def _add_regime2d_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        """
        Compute 2-axis regime state for exposure throttling:
        - trend axis: TREND / CHOP
        - stress axis: NORMAL / STRESS
        Includes optional dwell+hysteresis smoothing to reduce flip churn.
        """
        comp = (
            dataframe.get("composite_regime", pd.Series("", index=dataframe.index))
            .fillna("")
            .astype(str)
            .str.upper()
        )
        atrp = (
            dataframe.get("atr_phase", pd.Series("", index=dataframe.index))
            .fillna("")
            .astype(str)
            .str.upper()
        )
        volz = pd.to_numeric(
            dataframe.get("vol_zscore", pd.Series(np.nan, index=dataframe.index)),
            errors="coerce",
        )

        trend_raw = np.where(
            comp.str.contains("TREND_UP", na=False) | comp.str.contains("VOL_EXP", na=False),
            "TREND",
            "CHOP",
        )

        stress_raw = np.zeros(len(dataframe), dtype=bool)
        if bool(self.buy_regime2d_stress_from_panic_bear.value):
            stress_raw |= comp.str.contains("PANIC", na=False).to_numpy()
            stress_raw |= comp.str.contains("BEARVOL", na=False).to_numpy()

        if bool(self.buy_regime2d_stress_require_expand.value):
            stress_vol_mask = atrp.eq("EXPAND")
        else:
            stress_vol_mask = pd.Series(True, index=dataframe.index)
        stress_vol_mask = stress_vol_mask.fillna(False)
        stress_raw |= (
            stress_vol_mask
            & volz.ge(float(self.buy_regime2d_stress_volz_min.value)).fillna(False)
        ).to_numpy()

        stress_raw_label = np.where(stress_raw, "STRESS", "NORMAL")
        bucket_raw = np.char.add(np.char.add(trend_raw, "_"), stress_raw_label)

        if not bool(self.buy_regime2d_use_hysteresis.value):
            bucket_stable = bucket_raw.tolist()
        else:
            dwell = max(1, int(self.buy_regime2d_dwell_bars.value))
            trend_extra = max(0, int(self.buy_regime2d_trend_flip_extra_bars.value))
            stress_extra = max(0, int(self.buy_regime2d_stress_flip_extra_bars.value))

            bucket_stable: list[str] = []
            state = ""
            candidate = ""
            cand_count = 0
            for raw, t_raw, s_raw in zip(bucket_raw.tolist(), trend_raw.tolist(), stress_raw_label.tolist()):
                if not state:
                    state = raw
                    candidate = ""
                    cand_count = 0
                    bucket_stable.append(state)
                    continue
                if raw == state:
                    candidate = ""
                    cand_count = 0
                    bucket_stable.append(state)
                    continue

                if raw != candidate:
                    candidate = raw
                    cand_count = 1
                else:
                    cand_count += 1

                st_t, st_s = state.split("_", 1) if "_" in state else ("CHOP", "NORMAL")
                req = dwell
                if str(t_raw) != str(st_t):
                    req += trend_extra
                if str(s_raw) != str(st_s):
                    req += stress_extra

                if cand_count >= req:
                    state = raw
                    candidate = ""
                    cand_count = 0
                bucket_stable.append(state)

        dataframe["regime2d_trend_axis_raw"] = pd.Series(trend_raw, index=dataframe.index)
        dataframe["regime2d_stress_axis_raw"] = pd.Series(stress_raw_label, index=dataframe.index)
        dataframe["regime2d_bucket_raw"] = pd.Series(bucket_raw, index=dataframe.index)
        dataframe["regime2d_bucket"] = pd.Series(bucket_stable, index=dataframe.index)
        return dataframe

    # ══════════════════════════════════════════════════════════
    # populate_indicators
    # ══════════════════════════════════════════════════════════

    def populate_indicators(self, dataframe: pd.DataFrame, metadata: dict) -> pd.DataFrame:
        """Add all regime columns + strategy-specific indicators."""
        regime_cfg = RegimeConfig(
            er_trend_min=self.buy_er_trend_min.value,
            chop_trend_max=self.buy_chop_trend_max.value,
            bbw_compression_pctl=self.buy_bbw_compression_pctl.value,
        )
        dataframe = populate_regime_indicators(dataframe, config=regime_cfg)
        dataframe = self._add_regime2d_indicators(dataframe)

        # ── Pair-level attention: volume anomaly z-score ──
        if bool(self.buy_pair_attention_enabled.value):
            vol_lb = max(5, int(self.buy_pair_attention_vol_lookback.value))
            vol_series = dataframe["volume"].replace(0, np.nan)
            vol_mean = vol_series.rolling(vol_lb, min_periods=max(3, vol_lb // 2)).mean()
            vol_std = vol_series.rolling(vol_lb, min_periods=max(3, vol_lb // 2)).std()
            vol_std = vol_std.replace(0, np.nan)
            vol_zscore = ((vol_series - vol_mean) / vol_std).fillna(0.0)
            clip_val = float(self.buy_pair_attention_zscore_clip.value)
            dataframe["attention_vol_zscore"] = vol_zscore.clip(-clip_val, clip_val)
        else:
            dataframe["attention_vol_zscore"] = 0.0

        # Pre-compute rolling highs/lows for breakout lookback
        lb = int(self.buy_veb_breakout_lookback.value)
        dataframe["range_high"] = dataframe["high"].rolling(lb).max().shift(1)
        dataframe["range_low"] = dataframe["low"].rolling(lb).min().shift(1)

        # ATR for stop calculation
        dataframe["atr14"] = dataframe["atr_raw"]  # already computed by detector

        # Previous ATR for expansion ratio
        dataframe["atr14_prev"] = dataframe["atr14"].shift(1)

        # ── TPC indicators (base timeframe) ───────────────────
        ema_len = int(self.buy_tpc_ema_len.value)
        dataframe["tpc_ema"] = ta.EMA(dataframe, timeperiod=ema_len)
        dataframe["tpc_rsi"] = ta.RSI(dataframe, timeperiod=14)
        # Elliott Wave Oscillator: (EMA5 − EMA35) / close × 100
        ema_fast = ta.EMA(dataframe, timeperiod=5)
        ema_slow = ta.EMA(dataframe, timeperiod=35)
        dataframe["tpc_ewo"] = (ema_fast - ema_slow) / dataframe["close"] * 100

        # ── TPC 4-hour HTF trend filter + pullback reference ──
        pair = metadata.get("pair", "")
        dataframe = self._add_volex_indicators(dataframe)
        dataframe = self._add_volex_informative(pair, dataframe)
        dataframe = self._add_relstr_indicators(dataframe, pair)
        if self._base_deriv_basis_needed():
            dataframe = self._add_deriv_basis_informative(dataframe, pair)
        if bool(self.buy_idle_fr_enabled.value):
            dataframe = self._idle_fr_add_informative(dataframe, pair)
        if bool(self.buy_lc_enabled.value):
            dataframe = self._liqcascade_add_informative(dataframe, pair)
        if bool(self.buy_lc2_enabled.value):
            dataframe = self._liqcascade_v2_add_informative(dataframe, pair)
        if bool(self.buy_fimr_enabled.value):
            dataframe = self._fimr_add_informative(dataframe, pair)
        if bool(self.buy_cpdf_enabled.value):
            dataframe = self._cpdf_add_informative(dataframe, pair)
        inf_tf = "4h"
        can_merge_4h = self._can_merge_informative_timeframe(self.timeframe, inf_tf)
        inf_source_tf = inf_tf if can_merge_4h else self.timeframe
        informative = self.dp.get_pair_dataframe(pair=pair, timeframe=inf_source_tf)
        if informative is not None and not informative.empty:
            informative = informative.copy()
            informative["htf_ema50"] = ta.EMA(informative, timeperiod=50)
            informative["htf_ema200"] = ta.EMA(informative, timeperiod=200)
            informative["htf_slope"] = informative["htf_ema50"].pct_change(5)
            brf_ema_len = int(self.sell_brf_pair_bear_ema_len.value)
            brf_atr_len = int(self.sell_brf_atr_len.value)
            brf_expand_len = int(self.sell_brf_atr_expand_len.value)
            informative["brf_pair_bear_ema"] = ta.EMA(informative, timeperiod=brf_ema_len)
            informative["brf_pair_atr"] = ta.ATR(informative, timeperiod=brf_atr_len)
            informative["brf_pair_atr_sma"] = informative["brf_pair_atr"].rolling(
                brf_expand_len, min_periods=1
            ).mean()
            informative["brf_pair_atr_expand"] = (
                informative["brf_pair_atr"] / informative["brf_pair_atr_sma"]
            ) - 1.0
            classic_atr_len = int(self.sell_brf_classic_atr_len_4h.value)
            classic_atr_lookback = max(1, int(self.sell_brf_classic_atr_rise_lookback.value))
            informative["brf_classic_pair_atr"] = ta.ATR(informative, timeperiod=classic_atr_len)
            informative["brf_classic_pair_atr_ratio"] = (
                informative["brf_classic_pair_atr"] / informative["brf_classic_pair_atr"].shift(classic_atr_lookback)
            )
            informative["htf_uptrend"] = (
                (informative["htf_ema50"] > informative["htf_ema200"])
                & (informative["htf_slope"] > 0.002)  # require meaningful slope
            ).astype(int)
            informative["htf_downtrend"] = (
                (informative["htf_ema50"] < informative["htf_ema200"])
                & (informative["htf_slope"] < -0.002)
            ).astype(int)
            # TRBK: 4h Donchian channels for structure breaks
            donch_len = int(self.buy_trbk_donch_len.value)
            informative["trbk_donch_high"] = informative["high"].rolling(donch_len).max().shift(1)
            informative["trbk_donch_low"] = informative["low"].rolling(donch_len).min().shift(1)
            # TREND_PULLBACK 4h context: ATR%, EMA trend
            _tpb_4h_fast = int(self.buy_trendpb_4h_ema_fast.value)
            _tpb_4h_slow = int(self.buy_trendpb_4h_ema_slow.value)
            informative["trendpb4h_ema_fast"] = ta.EMA(informative, timeperiod=_tpb_4h_fast)
            informative["trendpb4h_ema_slow"] = ta.EMA(informative, timeperiod=_tpb_4h_slow)
            informative["trendpb4h_ema_up"] = (
                informative["trendpb4h_ema_fast"] > informative["trendpb4h_ema_slow"]
            ).astype(int)
            _tpb_atr14_4h = ta.ATR(informative, timeperiod=14)
            informative["trendpb4h_atr"] = _tpb_atr14_4h
            _tpb_close_safe = informative["close"].replace(0, np.nan)
            informative["trendpb4h_atr_pct"] = (_tpb_atr14_4h / _tpb_close_safe).replace(
                [np.inf, -np.inf], np.nan
            )
            # Keep EMA50 value for pullback reference in 1h
            informative = informative[[
                "date",
                "htf_uptrend",
                "htf_downtrend",
                "htf_ema50",
                "htf_ema200",
                "trbk_donch_high",
                "trbk_donch_low",
                "brf_pair_bear_ema",
                "brf_pair_atr",
                "brf_pair_atr_sma",
                "brf_pair_atr_expand",
                "brf_classic_pair_atr",
                "brf_classic_pair_atr_ratio",
                "trendpb4h_ema_fast",
                "trendpb4h_ema_slow",
                "trendpb4h_ema_up",
                "trendpb4h_atr",
                "trendpb4h_atr_pct",
            ]].copy()
            dataframe = merge_informative_pair(
                dataframe, informative, self.timeframe, inf_source_tf, ffill=True,
            )
            inf_suffix = f"_{inf_source_tf}"
            dataframe["htf_uptrend_4h"] = dataframe.get(f"htf_uptrend{inf_suffix}", 0)
            dataframe["htf_downtrend_4h"] = dataframe.get(f"htf_downtrend{inf_suffix}", 0)
            dataframe["htf_ema50_4h"] = dataframe.get(f"htf_ema50{inf_suffix}", np.nan)
            dataframe["htf_ema200_4h"] = dataframe.get(f"htf_ema200{inf_suffix}", np.nan)
            dataframe["trbk_donch_high_4h"] = dataframe.get(f"trbk_donch_high{inf_suffix}", np.nan)
            dataframe["trbk_donch_low_4h"] = dataframe.get(f"trbk_donch_low{inf_suffix}", np.nan)
            dataframe["brf_pair_bear_ema_4h"] = dataframe.get(f"brf_pair_bear_ema{inf_suffix}", np.nan)
            dataframe["brf_pair_atr_4h"] = dataframe.get(f"brf_pair_atr{inf_suffix}", np.nan)
            dataframe["brf_pair_atr_sma_4h"] = dataframe.get(f"brf_pair_atr_sma{inf_suffix}", np.nan)
            dataframe["brf_pair_atr_expand_4h"] = dataframe.get(f"brf_pair_atr_expand{inf_suffix}", np.nan)
            dataframe["brf_classic_pair_atr_4h"] = dataframe.get(f"brf_classic_pair_atr{inf_suffix}", np.nan)
            dataframe["brf_classic_pair_atr_ratio_4h"] = dataframe.get(
                f"brf_classic_pair_atr_ratio{inf_suffix}", np.nan
            )
            dataframe["trendpb4h_ema_fast_4h"] = dataframe.get(f"trendpb4h_ema_fast{inf_suffix}", np.nan)
            dataframe["trendpb4h_ema_slow_4h"] = dataframe.get(f"trendpb4h_ema_slow{inf_suffix}", np.nan)
            dataframe["trendpb4h_ema_up_4h"] = dataframe.get(f"trendpb4h_ema_up{inf_suffix}", 0)
            dataframe["trendpb4h_atr_4h"] = dataframe.get(f"trendpb4h_atr{inf_suffix}", np.nan)
            dataframe["trendpb4h_atr_pct_4h"] = dataframe.get(f"trendpb4h_atr_pct{inf_suffix}", np.nan)
            # Compute TPC pullback level from 4h EMA50 (smoother support)
            dataframe["tpc_pullback_lvl"] = dataframe["htf_ema50_4h"] * self.buy_tpc_ma_offset.value
        else:
            dataframe["htf_uptrend_4h"] = 0
            dataframe["htf_downtrend_4h"] = 0
            dataframe["htf_ema50_4h"] = 0
            dataframe["htf_ema200_4h"] = 0
            dataframe["trbk_donch_high_4h"] = np.nan
            dataframe["trbk_donch_low_4h"] = np.nan
            dataframe["brf_pair_bear_ema_4h"] = np.nan
            dataframe["brf_pair_atr_4h"] = np.nan
            dataframe["brf_pair_atr_sma_4h"] = np.nan
            dataframe["brf_pair_atr_expand_4h"] = np.nan
            dataframe["brf_classic_pair_atr_4h"] = np.nan
            dataframe["brf_classic_pair_atr_ratio_4h"] = np.nan
            dataframe["trendpb4h_ema_fast_4h"] = np.nan
            dataframe["trendpb4h_ema_slow_4h"] = np.nan
            dataframe["trendpb4h_ema_up_4h"] = 0
            dataframe["trendpb4h_atr_4h"] = np.nan
            dataframe["trendpb4h_atr_pct_4h"] = np.nan
            dataframe["tpc_pullback_lvl"] = 0

        # ── LAGCATCH market-context merge (BTC/ETH lead vs alt catch-up) ──
        dataframe["lagcatch_mkt_ret"] = np.nan
        dataframe["lagcatch_mkt_ema_fast"] = np.nan
        dataframe["lagcatch_mkt_ema_slow"] = np.nan
        dataframe["lagcatch_pair_ret"] = pd.to_numeric(dataframe["close"], errors="coerce").pct_change(
            max(1, int(self.buy_lagcatch_lead_ret_bars.value))
        )
        dataframe["lagcatch_pair_ema_fast"] = ta.EMA(dataframe, timeperiod=max(2, int(self.buy_lagcatch_ema_fast.value)))
        dataframe["lagcatch_pair_ema_slow"] = ta.EMA(dataframe, timeperiod=max(3, int(self.buy_lagcatch_ema_slow.value)))
        dataframe["lagcatch_pair_relvol"] = (
            pd.to_numeric(dataframe["volume"], errors="coerce")
            / pd.to_numeric(dataframe["volume"], errors="coerce").rolling(max(2, int(self.buy_lagcatch_relvol_len.value))).mean().replace(0, np.nan)
        )
        dataframe["lagcatch_pair_breakout"] = (
            pd.to_numeric(dataframe["close"], errors="coerce")
            > pd.to_numeric(dataframe["high"], errors="coerce").rolling(max(2, int(self.buy_lagcatch_breakout_lookback.value))).max().shift(1)
        ).fillna(False)
        if bool(self.buy_lagcatch_enabled.value):
            lag_mkt_pair = self._resolve_pair_hint(str(self.buy_lagcatch_market_pair.value or "BTC/USDT:USDT"), "BTC")
            try:
                lag_inf = self.dp.get_pair_dataframe(pair=lag_mkt_pair, timeframe=self.timeframe)
            except Exception:
                lag_inf = None
            if lag_inf is not None and not lag_inf.empty:
                lag_inf = lag_inf.copy()
                lag_inf["lagcatch_mkt_ret"] = pd.to_numeric(lag_inf["close"], errors="coerce").pct_change(
                    max(1, int(self.buy_lagcatch_lead_ret_bars.value))
                )
                lag_inf["lagcatch_mkt_ema_fast"] = ta.EMA(lag_inf, timeperiod=max(2, int(self.buy_lagcatch_ema_fast.value)))
                lag_inf["lagcatch_mkt_ema_slow"] = ta.EMA(lag_inf, timeperiod=max(3, int(self.buy_lagcatch_ema_slow.value)))
                lag_inf = lag_inf[["date", "lagcatch_mkt_ret", "lagcatch_mkt_ema_fast", "lagcatch_mkt_ema_slow"]].copy()
                dataframe = merge_informative_pair(
                    dataframe, lag_inf, self.timeframe, self.timeframe, ffill=True,
                )
                if "lagcatch_mkt_ret_1h" in dataframe.columns:
                    dataframe["lagcatch_mkt_ret"] = dataframe["lagcatch_mkt_ret_1h"]
                    dataframe["lagcatch_mkt_ema_fast"] = dataframe["lagcatch_mkt_ema_fast_1h"]
                    dataframe["lagcatch_mkt_ema_slow"] = dataframe["lagcatch_mkt_ema_slow_1h"]
        dataframe["lagcatch_gap"] = (
            pd.to_numeric(dataframe["lagcatch_mkt_ret"], errors="coerce")
            - pd.to_numeric(dataframe["lagcatch_pair_ret"], errors="coerce")
        )
        dataframe["lagcatch_signal_long"] = (
            (pd.to_numeric(dataframe["lagcatch_mkt_ret"], errors="coerce") >= float(self.buy_lagcatch_lead_ret_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["lagcatch_gap"], errors="coerce") >= float(self.buy_lagcatch_gap_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["lagcatch_gap"], errors="coerce") <= float(self.buy_lagcatch_gap_max.value)).fillna(False)
            & (pd.to_numeric(dataframe["close"], errors="coerce") > pd.to_numeric(dataframe["lagcatch_pair_ema_fast"], errors="coerce")).fillna(False)
            & (pd.to_numeric(dataframe["lagcatch_pair_ema_fast"], errors="coerce") > pd.to_numeric(dataframe["lagcatch_pair_ema_slow"], errors="coerce")).fillna(False)
            & dataframe["lagcatch_pair_breakout"].astype(bool)
            & (pd.to_numeric(dataframe["lagcatch_pair_relvol"], errors="coerce") >= float(self.buy_lagcatch_relvol_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["lagcatch_mkt_ema_fast"], errors="coerce") > pd.to_numeric(dataframe["lagcatch_mkt_ema_slow"], errors="coerce")).fillna(False)
        ).fillna(False)

        # ── TRBK indicators (namespaced trbk_*) ──────────────
        dataframe["trbk_rsi"] = ta.RSI(dataframe, timeperiod=14)

        # ADX (trend quality on base timeframe)
        dataframe["trbk_adx"] = ta.ADX(dataframe, timeperiod=int(self.buy_trbk_adx_len.value))

        # BB width proxy: (upper-lower)/mid  — anti-chop filter
        bb = ta.BBANDS(dataframe, timeperiod=int(self.buy_trbk_bb_len.value),
                       nbdevup=2.0, nbdevdn=2.0)
        dataframe["trbk_bbwidth"] = (bb["upperband"] - bb["lowerband"]) / bb["middleband"]

        # ── TREND_PULLBACK 1h signal indicators ─────────────────────────────────
        _tpb_ema_fast_len = int(self.buy_trendpb_ema_fast.value)
        _tpb_ema_slow_len = int(self.buy_trendpb_ema_slow.value)
        _tpb_ema_anch_len = int(self.buy_trendpb_ema_anchor.value)
        dataframe["trendpb_ema_fast"] = ta.EMA(dataframe, timeperiod=_tpb_ema_fast_len)
        dataframe["trendpb_ema_slow"] = ta.EMA(dataframe, timeperiod=_tpb_ema_slow_len)
        dataframe["trendpb_ema_anchor"] = ta.EMA(dataframe, timeperiod=_tpb_ema_anch_len)
        dataframe["trendpb_prev_ema_fast"] = dataframe["trendpb_ema_fast"].shift(1)
        dataframe["trendpb_prev_ema_slow"] = dataframe["trendpb_ema_slow"].shift(1)
        dataframe["trendpb_prev_close"] = dataframe["close"].shift(1)
        dataframe["trendpb_3bar_high"] = dataframe["high"].rolling(3).max().shift(1)
        dataframe["trendpb_3bar_low"] = dataframe["low"].rolling(3).min().shift(1)
        # Zone-touch lookback: did price pull back into the EMAs in the last 3 bars?
        # Using shift(1) so we look at COMPLETED bars only.
        dataframe["trendpb_close_min_3"] = dataframe["close"].rolling(3).min().shift(1)
        dataframe["trendpb_low_min_3"] = dataframe["low"].rolling(3).min().shift(1)
        dataframe["trendpb_close_max_3"] = dataframe["close"].rolling(3).max().shift(1)
        dataframe["trendpb_high_max_3"] = dataframe["high"].rolling(3).max().shift(1)
        dataframe["trendpb_rsi"] = ta.RSI(
            dataframe, timeperiod=int(self.buy_trendpb_rsi_len.value)
        )
        # Volume 20-bar moving average (shifted — no current-bar lookahead)
        dataframe["trendpb_vol_ma20"] = dataframe["volume"].rolling(20).mean().shift(1)
        # Reclaim cross (CROSS_EMA_FAST mode) — precomputed for confirm_bar mode.
        # 1 on the bar where close crossed above ema_fast from below.
        dataframe["trendpb_reclaim_bar"] = (
            (dataframe["close"] > dataframe["trendpb_ema_fast"])
            & (dataframe["trendpb_prev_close"] <= dataframe["trendpb_prev_ema_fast"])
        ).astype(int)
        # Shift by 1: was the PREVIOUS bar a reclaim bar? (used when confirm_bar=True)
        dataframe["trendpb_prev_reclaim_bar"] = (
            dataframe["trendpb_reclaim_bar"].shift(1).fillna(0).astype(int)
        )
        dataframe["trendpb_reject_bar"] = (
            (dataframe["close"] < dataframe["trendpb_ema_fast"])
            & (dataframe["trendpb_prev_close"] >= dataframe["trendpb_prev_ema_fast"])
        ).astype(int)
        dataframe["trendpb_prev_reject_bar"] = (
            dataframe["trendpb_reject_bar"].shift(1).fillna(0).astype(int)
        )
        # Previous-bar RSI (shifted 1) — used by rsi_rising quality filter in confirm_bar mode
        dataframe["trendpb_prev_rsi"] = dataframe["trendpb_rsi"].shift(1).fillna(0.0)
        # Regime persistence: was composite_regime TREND_UP in the last N 1h bars?
        # Rolling lookback (shifted by 1 = no current-bar lookahead).
        # Used by _trendpb_regime_allows when buy_trendpb_gate_regime_lookback > 0.
        _tpb_regime_lb = max(1, int(self.buy_trendpb_gate_regime_lookback.value))
        _regime_raw = dataframe["composite_regime"].fillna("").astype(str).str.upper()
        _regime_trend_up = _regime_raw.str.startswith("TREND_UP").astype(int)
        dataframe["trendpb_regime_up_recent"] = (
            _regime_trend_up.rolling(_tpb_regime_lb, min_periods=1).max().shift(1).fillna(0).astype(int)
        )

        # ── BTC 4h informative merge for market-regime filter ──
        btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
        btc_tf = "4h"
        can_merge_btc_4h = self._can_merge_informative_timeframe(self.timeframe, btc_tf)
        btc_source_tf = btc_tf if can_merge_btc_4h else self.timeframe
        btc_inf = self.dp.get_pair_dataframe(pair=btc_pair, timeframe=btc_source_tf)
        if btc_inf is not None and not btc_inf.empty:
            btc_inf = btc_inf.copy()
            btc_inf["trbk_btc_ema50"] = ta.EMA(btc_inf, timeperiod=50)
            btc_inf["trbk_btc_ema200"] = ta.EMA(btc_inf, timeperiod=200)
            slope_n = int(self.buy_trbk_btc_slope_len.value)
            btc_inf["trbk_btc_slope"] = btc_inf["trbk_btc_ema50"].pct_change(slope_n)
            btc_inf = btc_inf[["date", "trbk_btc_ema50", "trbk_btc_ema200", "trbk_btc_slope"]].copy()
            dataframe = merge_informative_pair(
                dataframe, btc_inf, self.timeframe, btc_source_tf, ffill=True,
            )
            btc_suffix = f"_{btc_source_tf}"
            dataframe["trbk_btc_ema50_4h"] = dataframe.get(f"trbk_btc_ema50{btc_suffix}", np.nan)
            dataframe["trbk_btc_ema200_4h"] = dataframe.get(f"trbk_btc_ema200{btc_suffix}", np.nan)
            dataframe["trbk_btc_slope_4h"] = dataframe.get(f"trbk_btc_slope{btc_suffix}", np.nan)
            fast_col = "trbk_btc_ema50_4h"
            slow_col = "trbk_btc_ema200_4h"
            slope_col = "trbk_btc_slope_4h"
            # trbk_market_on: veto-only — block when BTC in clear downtrend,
            # allow everything else (ranging + uptrend)
            dataframe["trbk_market_on"] = ~(
                (dataframe[fast_col] < dataframe[slow_col])
                & (dataframe[slope_col] < float(self.buy_trbk_btc_slope_min.value))
            )
        else:
            dataframe["trbk_market_on"] = 1  # if BTC data unavailable, don't block

        # ── BTC 4h macro bear flag (for TRBK short gating) ─────
        # Requires: death cross + EMA50 declining + minimum EMA spread.
        # The spread condition filters convergence (recovery) periods where
        # death cross persists but gap is narrowing → false bear signals.
        fast_col = "trbk_btc_ema50_4h"
        slow_col = "trbk_btc_ema200_4h"
        slope_col = "trbk_btc_slope_4h"
        if fast_col in dataframe.columns and slow_col in dataframe.columns:
            # EMA spread: (EMA50 - EMA200) / EMA200 — negative when death cross
            ema_spread = (dataframe[fast_col] - dataframe[slow_col]) / dataframe[slow_col]
            dataframe["trbk_btc_bear"] = (
                (dataframe[fast_col] < dataframe[slow_col])  # death cross
                & (dataframe[slope_col] < 0)                  # EMA50 declining
                & (ema_spread <= -0.03)                       # ≥ 3% spread (optimal)
            ).fillna(False)
            # Deeper bear flag for BEAR_VOL: require wider EMA spread
            dataframe["bearvol_btc_deep_bear"] = (
                (dataframe[fast_col] < dataframe[slow_col])  # death cross
                & (dataframe[slope_col] < 0)                  # EMA50 declining
                & (ema_spread <= -0.05)                       # ≥ 5% spread
            ).fillna(False)
            brf_spread_min = float(self.sell_brf_btc_spread_min.value)
            dataframe["brf_btc_deep_bear"] = (
                (dataframe[fast_col] < dataframe[slow_col])
                & (dataframe[slope_col] < 0)
                & (ema_spread <= -brf_spread_min)
            ).fillna(False)
        else:
            dataframe["trbk_btc_bear"] = False
            dataframe["bearvol_btc_deep_bear"] = False
            dataframe["brf_btc_deep_bear"] = False

        # ── BEAR_VOL indicators (ATR impulse on resampled 4h bars) ───
        dataframe = self._add_bearvol_indicators(dataframe)

        # ── BRF indicators (bear rally fade rejection setup) ───
        dataframe["brf_rsi"] = ta.RSI(dataframe, timeperiod=int(self.sell_brf_rsi_len.value))
        dataframe["brf_ema_reject"] = ta.EMA(dataframe, timeperiod=int(self.sell_brf_reject_ema_len.value))
        dataframe["brf_ema200_4h"] = dataframe.get("brf_pair_bear_ema_4h", np.nan)
        dataframe["brf_atr_4h"] = dataframe.get("brf_pair_atr_4h", np.nan)
        dataframe["brf_atr_4h_sma"] = dataframe.get("brf_pair_atr_sma_4h", np.nan)
        dataframe["brf_atr_expand"] = dataframe.get("brf_pair_atr_expand_4h", np.nan)
        brf_atr_sma_safe = dataframe["brf_atr_4h_sma"].replace(0, np.nan)
        dataframe["brf_atr_ratio"] = dataframe["brf_atr_4h"] / brf_atr_sma_safe
        brf_range = (dataframe["high"] - dataframe["low"]).replace(0, np.nan)
        brf_body = (dataframe["close"] - dataframe["open"]).abs().replace(0, np.nan)
        brf_upper_wick = dataframe["high"] - dataframe[["open", "close"]].max(axis=1)
        dataframe["brf_wick_ratio"] = brf_upper_wick / brf_body
        dataframe["brf_upper_wick_pct"] = (brf_upper_wick / brf_range).replace([np.inf, -np.inf], np.nan).fillna(0.0)
        dataframe["brf_close_pos"] = (dataframe["close"] - dataframe["low"]) / brf_range
        dataframe["brf_red_candle"] = (dataframe["close"] < dataframe["open"]).fillna(False)
        reject_buf = float(self.sell_brf_reject_buffer_atr.value)
        dataframe["brf_touch_ema_reject"] = (
            dataframe["high"] >= dataframe["brf_ema_reject"]
        ).fillna(False)
        dataframe["brf_reject_below_ema"] = (
            dataframe["close"] < (dataframe["brf_ema_reject"] - reject_buf * dataframe["atr14"])
        ).fillna(False)
        wick_min = float(self.sell_brf_wick_ratio_min.value)
        close_pos_max = 1.0 - float(self.sell_brf_reject_close_frac.value)
        dataframe["brf_base_reject"] = (
            (dataframe["brf_wick_ratio"] >= wick_min)
            & (dataframe["brf_close_pos"] <= close_pos_max)
            & dataframe["brf_red_candle"]
        ).fillna(False)
        dataframe["brf_ema_reject_ok"] = (
            dataframe["brf_touch_ema_reject"]
            & dataframe["brf_reject_below_ema"]
            & dataframe["brf_red_candle"]
        ).fillna(False)
        level_len = int(self.sell_brf_level_len.value)
        dataframe["brf_level"] = dataframe["high"].rolling(level_len).max().shift(1)
        level_buf = float(self.sell_brf_level_buffer_atr.value)
        dataframe["brf_near_level"] = (
            dataframe["high"] >= (dataframe["brf_level"] - level_buf * dataframe["atr14"])
        ).fillna(False)
        dataframe["brf_level_reject"] = (
            dataframe["brf_near_level"] & dataframe["brf_red_candle"]
        ).fillna(False)
        brf_bb = ta.BBANDS(dataframe, timeperiod=int(self.sell_brf_bbw_len.value), nbdevup=2.0, nbdevdn=2.0)
        brf_bb_mid = brf_bb["middleband"].replace(0, np.nan)
        dataframe["brf_bbw"] = (brf_bb["upperband"] - brf_bb["lowerband"]) / brf_bb_mid
        brf_bbw_sma = dataframe["brf_bbw"].rolling(int(self.sell_brf_bbw_rise_len.value), min_periods=1).mean()
        dataframe["brf_bbw_sma"] = brf_bbw_sma
        dataframe["brf_bbw_rise"] = dataframe["brf_bbw"] / brf_bbw_sma.replace(0, np.nan) - 1.0

        vol_mode = str(self.sell_brf_vol_confirm_mode.value)
        if not self.sell_brf_require_atr_expand.value or vol_mode == "off":
            dataframe["brf_vol_ok"] = True
        elif vol_mode == "atr_expand":
            dataframe["brf_vol_ok"] = (
                dataframe["brf_atr_expand"] >= float(self.sell_brf_atr_expand_min.value)
            ).fillna(False)
        elif vol_mode == "bbw_rising":
            dataframe["brf_vol_ok"] = (
                dataframe["brf_bbw_rise"] >= float(self.sell_brf_bbw_rise_min.value)
            ).fillna(False)
        else:
            dataframe["brf_vol_ok"] = (
                dataframe["brf_atr_ratio"] >= float(self.sell_brf_atr_rising_ratio.value)
            ).fillna(False)

        reject_mode = str(self.sell_brf_reject_mode.value)
        if reject_mode == "wick_closepos":
            dataframe["brf_reject_ok"] = dataframe["brf_base_reject"]
        elif reject_mode == "wick_closepos_and_level":
            dataframe["brf_reject_ok"] = (
                dataframe["brf_base_reject"] & dataframe["brf_level_reject"]
            ).fillna(False)
        else:
            ema_component = dataframe["brf_ema_reject_ok"] if self.sell_brf_reject_vs_ema.value else False
            dataframe["brf_reject_ok"] = (
                dataframe["brf_base_reject"] | ema_component
            ).fillna(False)

        dataframe["brf_bear_ok"] = (
            dataframe["brf_btc_deep_bear"] if self.sell_brf_use_btc_deep_bear.value else True
        )
        dataframe["brf_below_ema200"] = (
            dataframe["close"] < dataframe["brf_ema200_4h"]
        ).fillna(False)
        dataframe["brf_rsi_ok"] = (
            dataframe["brf_rsi"] >= float(self.sell_brf_rsi_min.value)
        ).fillna(False)
        retest_rsi_mode = str(self.sell_brf_retest_rsi_mode.value)
        if retest_rsi_mode == "lower":
            dataframe["brf_rsi_ok_retest"] = (
                dataframe["brf_rsi"] >= float(self.sell_brf_retest_rsi_min.value)
            ).fillna(False)
        elif retest_rsi_mode == "off":
            dataframe["brf_rsi_ok_retest"] = True
        else:
            dataframe["brf_rsi_ok_retest"] = dataframe["brf_rsi_ok"].astype(bool)
        dataframe["brf_roll_ema"] = ta.EMA(dataframe, timeperiod=int(self.sell_brf_roll_ema_len.value))
        dataframe["brf_rsi_prev"] = dataframe["brf_rsi"].shift(1)
        dataframe["brf_rsi_crossdown"] = (
            (dataframe["brf_rsi_prev"] >= int(self.sell_brf_rsi_cross_from.value))
            & (dataframe["brf_rsi"] <= int(self.sell_brf_rsi_cross_to.value))
        ).fillna(False)
        dataframe["brf_close_below_ema"] = (
            dataframe["close"] <= (
                dataframe["brf_roll_ema"]
                - float(self.sell_brf_roll_ema_buf_atr.value) * dataframe["atr14"]
            )
        ).fillna(False)
        dataframe["brf_bear_body_ok"] = (
            (dataframe["open"] - dataframe["close"])
            >= float(self.sell_brf_bear_body_min_atr.value) * dataframe["atr14"]
        ).fillna(False)
        roll_mode = str(self.sell_brf_roll_mode.value)
        if roll_mode == "rsi_crossdown":
            dataframe["brf_roll_ok"] = dataframe["brf_rsi_crossdown"]
        elif roll_mode == "close_below_ema":
            dataframe["brf_roll_ok"] = dataframe["brf_close_below_ema"]
        else:
            dataframe["brf_roll_ok"] = (
                dataframe["brf_rsi_crossdown"]
                | dataframe["brf_close_below_ema"]
                | dataframe["brf_bear_body_ok"]
            ).fillna(False)

        dataframe["brf_ema50_1h"] = ta.EMA(dataframe, timeperiod=int(self.sell_brf_stretch_ema_len.value))
        dataframe["brf_stretch_above_ema"] = (
            (dataframe["high"] - dataframe["brf_ema50_1h"])
            >= float(self.sell_brf_stretch_min_atr.value) * dataframe["atr14"]
        ).fillna(False)
        dataframe["brf_stretch_above_bbu"] = (
            dataframe["high"] >= brf_bb["upperband"]
        ).fillna(False)
        stretch_mode = str(self.sell_brf_stretch_mode.value)
        if stretch_mode == "off":
            dataframe["brf_stretch_ok"] = True
        elif stretch_mode == "above_bb_upper":
            dataframe["brf_stretch_ok"] = dataframe["brf_stretch_above_bbu"]
        else:
            dataframe["brf_stretch_ok"] = dataframe["brf_stretch_above_ema"]

        dataframe["brf_candidate_base"] = (
            (dataframe["volume"] > 0)
            & dataframe["brf_bear_ok"].astype(bool)
            & dataframe["brf_below_ema200"].astype(bool)
            & dataframe["brf_rsi_ok"].astype(bool)
            & dataframe["brf_reject_ok"].astype(bool)
            & dataframe["brf_vol_ok"].astype(bool)
        ).fillna(False)
        dataframe["brf_level_ok"] = (
            dataframe["brf_near_level"].astype(bool) if self.sell_brf_require_level.value else True
        )
        dataframe["brf_direct_candidate"] = (
            dataframe["brf_candidate_base"].astype(bool)
            & dataframe["brf_roll_ok"].astype(bool)
            & dataframe["brf_stretch_ok"].astype(bool)
            & dataframe["brf_level_ok"].astype(bool)
        ).fillna(False)

        dataframe["brf_arm"] = dataframe["brf_candidate_base"].astype(bool)
        arm_window = max(1, int(self.sell_brf_arm_window_bars.value))
        arm_idx = np.where(dataframe["brf_arm"].values, np.arange(len(dataframe), dtype=float), np.nan)
        last_arm_idx = pd.Series(arm_idx, index=dataframe.index).ffill()
        bars_since_arm = np.arange(len(dataframe), dtype=float) - last_arm_idx
        dataframe["brf_bars_since_arm"] = pd.Series(bars_since_arm, index=dataframe.index)
        dataframe["brf_armed"] = (
            np.isfinite(bars_since_arm) & (bars_since_arm >= 0) & (bars_since_arm < arm_window)
        )
        arm_high = pd.Series(
            np.where(dataframe["brf_arm"].values, dataframe["high"].values, np.nan),
            index=dataframe.index,
        ).ffill()
        dataframe["brf_reject_high_anchor"] = arm_high.where(dataframe["brf_armed"], np.nan)
        if self.sell_brf_arm_invalidate_on_close_above_reject_high.value:
            invalidate_line = dataframe["brf_reject_high_anchor"] + float(self.sell_brf_invalidate_buf_atr.value) * dataframe["atr14"]
            dataframe["brf_arm_invalidated"] = (
                dataframe["brf_armed"].astype(bool)
                & (dataframe["close"] > invalidate_line)
            ).fillna(False)
            invalid_idx = np.where(
                dataframe["brf_arm_invalidated"].values,
                np.arange(len(dataframe), dtype=float),
                np.nan,
            )
            last_invalid_idx = pd.Series(invalid_idx, index=dataframe.index).ffill()
            still_valid = (~np.isfinite(last_invalid_idx)) | (last_invalid_idx < last_arm_idx)
            dataframe["brf_armed"] = (
                dataframe["brf_armed"].astype(bool) & still_valid
            ).fillna(False)
            dataframe["brf_reject_high_anchor"] = arm_high.where(dataframe["brf_armed"], np.nan)
        else:
            dataframe["brf_arm_invalidated"] = False

        dataframe["brf_trig_ema"] = ta.EMA(dataframe, timeperiod=int(self.sell_brf_trigger_ema_len.value))
        trig_ema_buf = float(self.sell_brf_trigger_ema_buf_atr.value)
        dataframe["brf_trig_ema_cross"] = (
            dataframe["close"] <= (dataframe["brf_trig_ema"] - trig_ema_buf * dataframe["atr14"])
        ).fillna(False)
        dataframe["brf_trig_rsi_cross"] = (
            (dataframe["brf_rsi_prev"] >= int(self.sell_brf_trigger_rsi_from.value))
            & (dataframe["brf_rsi"] <= int(self.sell_brf_trigger_rsi_to.value))
        ).fillna(False)
        rsi_cross_dn_from = int(self.sell_brf_rsi_cross_dn_from.value)
        dataframe["brf_trig_rsi_cross_dn"] = (
            (dataframe["brf_rsi_prev"] >= rsi_cross_dn_from)
            & (dataframe["brf_rsi"] < rsi_cross_dn_from)
        ).fillna(False)
        ll_n = max(1, int(self.sell_brf_trigger_ll_lookback.value))
        dataframe["brf_ll"] = dataframe["low"].rolling(ll_n, min_periods=1).min().shift(1)
        dataframe["brf_trig_ll_break"] = (
            dataframe["close"] <= (
                dataframe["brf_ll"] - float(self.sell_brf_trigger_ll_buf_atr.value) * dataframe["atr14"]
            )
        ).fillna(False)
        reject_close_buf = float(self.sell_brf_reject_close_buf_atr.value)
        dataframe["brf_trig_close_below_anchor"] = (
            dataframe["close"] < (
                dataframe["brf_reject_high_anchor"] - reject_close_buf * dataframe["atr14"]
            )
        ).fillna(False)
        reclaim_mode = str(self.sell_brf_reclaim_mode.value)
        use_fail_reclaim_highweak = (
            str(self.sell_brf_trigger_mode.value) == "fail_reclaim"
            and reclaim_mode == "high_then_weak_close"
        )
        fail_reclaim_atr_ref = dataframe["brf_atr_4h"].where(
            dataframe["brf_atr_4h"].notna(),
            dataframe["atr14"],
        )
        reclaim_buf = (
            float(self.sell_brf_fail_reclaim_buf_atr.value)
            if use_fail_reclaim_highweak
            else float(self.sell_brf_reclaim_buf_atr.value)
        )
        fail_close_buf = float(self.sell_brf_fail_close_buf_atr.value)
        reclaim_atr_ref = fail_reclaim_atr_ref if use_fail_reclaim_highweak else dataframe["atr14"]
        dataframe["brf_reclaim_thr"] = (
            dataframe["brf_reject_high_anchor"] + reclaim_buf * reclaim_atr_ref
        )
        dataframe["brf_fail_thr"] = (
            dataframe["brf_reject_high_anchor"] - fail_close_buf * dataframe["atr14"]
        )
        reclaim_touch_close = (dataframe["close"] > dataframe["brf_reclaim_thr"]).fillna(False)
        reclaim_min_closepos = float(self.sell_brf_reclaim_min_closepos.value)
        if reclaim_min_closepos > 0.0:
            reclaim_touch_close = (
                reclaim_touch_close.astype(bool)
                & (dataframe["brf_close_pos"] >= reclaim_min_closepos)
            ).fillna(False)
        reclaim_touch_high_weak = (
            (dataframe["high"] > dataframe["brf_reclaim_thr"])
            & (dataframe["close"] <= dataframe["brf_reclaim_thr"])
            & (dataframe["brf_close_pos"] <= float(self.sell_brf_reclaim_weak_close_pos_max.value))
        ).fillna(False)
        dataframe["brf_reclaim_touch_close"] = reclaim_touch_close.astype(bool)
        dataframe["brf_reclaim_touch_high_weakclose"] = reclaim_touch_high_weak.astype(bool)
        if reclaim_mode == "high_then_weak_close":
            dataframe["brf_reclaim_touch"] = dataframe["brf_reclaim_touch_high_weakclose"].astype(bool)
        else:
            dataframe["brf_reclaim_touch"] = dataframe["brf_reclaim_touch_close"].astype(bool)
        if self.sell_brf_fail_use_close.value:
            fail_close = dataframe["close"] <= dataframe["brf_fail_thr"]
        else:
            fail_close = dataframe["low"] <= dataframe["brf_fail_thr"]
        dataframe["brf_fail_close"] = pd.Series(fail_close, index=dataframe.index).fillna(False)
        fail_bars = max(1, int(self.sell_brf_fail_max_bars_after_reclaim.value))
        dataframe["brf_reclaim_recent"] = (
            dataframe["brf_reclaim_touch"].astype(int).rolling(fail_bars, min_periods=1).max() >= 1
        ).fillna(False)
        dataframe["brf_fail_now"] = (
            dataframe["brf_reclaim_recent"].astype(bool)
            & dataframe["brf_fail_close"].astype(bool)
        ).fillna(False)
        confirm_buf = float(self.sell_brf_fail_confirm_buf_atr.value)
        dataframe["brf_fail_confirm_thr"] = (
            dataframe["brf_reject_high_anchor"] - confirm_buf * dataframe["atr14"]
        )
        dataframe["brf_confirm_below"] = (
            dataframe["close"] <= dataframe["brf_fail_confirm_thr"]
        ).fillna(False)
        confirm_bars = max(1, int(self.sell_brf_fail_confirm_bars.value))
        prior_fail_recent = (
            dataframe["brf_fail_now"].shift(1).fillna(False).astype(int).rolling(confirm_bars, min_periods=1).max() >= 1
        )
        dataframe["brf_confirm_ok"] = (
            prior_fail_recent.astype(bool)
            & dataframe["brf_confirm_below"].astype(bool)
        ).fillna(False)
        body_range = (dataframe["high"] - dataframe["low"]).replace(0, np.nan)
        dataframe["brf_red"] = (dataframe["close"] < dataframe["open"]).fillna(False)
        dataframe["brf_body_frac"] = (
            (dataframe["open"] - dataframe["close"]).abs() / body_range
        ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
        dataframe["brf_strict_red_ok"] = (
            dataframe["brf_red"]
            & (dataframe["brf_body_frac"] >= float(self.sell_brf_body_frac_min.value))
        ).fillna(False)
        if self.sell_brf_fail_require_2nd_confirm.value:
            dataframe["brf_trigger_fail_reclaim"] = dataframe["brf_confirm_ok"].astype(bool)
        else:
            dataframe["brf_trigger_fail_reclaim"] = dataframe["brf_fail_now"].astype(bool)
        if self.sell_brf_require_strict_red_candle.value:
            dataframe["brf_trigger_fail_reclaim"] = (
                dataframe["brf_trigger_fail_reclaim"].astype(bool)
                & dataframe["brf_strict_red_ok"].astype(bool)
            ).fillna(False)
        dataframe["brf_trigger_fail_reclaim_pre_lh"] = dataframe["brf_trigger_fail_reclaim"].astype(bool)
        fr_lh_lb = int(self.sell_brf_fail_reclaim_lower_high_lookback.value)
        fr_prior_max_high = dataframe["high"].shift(1).rolling(fr_lh_lb, min_periods=fr_lh_lb).max()
        dataframe["brf_fail_reclaim_lh_ok"] = (
            dataframe["high"] < fr_prior_max_high
        ).fillna(False)
        use_fail_reclaim_lh = (
            use_fail_reclaim_highweak and self.sell_brf_fail_reclaim_require_lower_high.value
        )
        if use_fail_reclaim_lh:
            dataframe["brf_trigger_fail_reclaim"] = (
                dataframe["brf_trigger_fail_reclaim"].astype(bool)
                & dataframe["brf_fail_reclaim_lh_ok"].astype(bool)
            ).fillna(False)
        dataframe["brf_trigger_fail_reclaim_pre_failqual"] = dataframe["brf_trigger_fail_reclaim"].astype(bool)
        failqual_ema_len = int(
            self.sell_brf_failqual_ema_len_failreclaim.value
            if use_fail_reclaim_highweak
            else self.sell_brf_failqual_ema_len.value
        )
        dataframe["brf_failqual_ema"] = ta.EMA(dataframe, timeperiod=failqual_ema_len)
        failqual_ema_mode = str(self.sell_brf_failqual_ema_mode.value)
        # Keep the legacy bool as a compatibility fallback for existing overrides.
        if use_fail_reclaim_highweak and not self.sell_brf_failqual_require_close_below_ema.value:
            if failqual_ema_mode == "require":
                failqual_ema_mode = "off"
        failqual_ema_soft_buf = float(self.sell_brf_failqual_ema_soft_buf.value)
        failqual_red_body = (dataframe["open"] - dataframe["close"]).clip(lower=0.0)
        dataframe["brf_failqual_red_body_frac"] = (
            failqual_red_body / body_range
        ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
        dataframe["brf_failqual_strong_red"] = (
            dataframe["brf_failqual_red_body_frac"] >= float(self.sell_brf_failqual_red_body_min.value)
        ).fillna(False)
        if failqual_ema_mode == "soft":
            dataframe["brf_failqual_below_ema"] = (
                dataframe["close"] <= (
                    dataframe["brf_failqual_ema"] * (1.0 + failqual_ema_soft_buf)
                )
            ).fillna(False)
        elif failqual_ema_mode == "off":
            dataframe["brf_failqual_below_ema"] = True
        else:
            dataframe["brf_failqual_below_ema"] = (
                dataframe["close"] < dataframe["brf_failqual_ema"]
            ).fillna(False)
        dataframe["brf_failqual_below_reclaim_buf"] = (
            dataframe["close"] <= (
                dataframe["brf_reclaim_thr"]
                - float(self.sell_brf_failqual_close_below_reclaim_by_atr.value) * fail_reclaim_atr_ref
            )
        ).fillna(False)
        dataframe["brf_failqual_closepos_ok"] = (
            dataframe["brf_close_pos"] <= float(self.sell_brf_failqual_close_pos_max.value)
        ).fillna(False)
        failqual_extra_margin = float(self.sell_brf_failqual_extra_fail_margin_atr.value)
        if use_fail_reclaim_highweak and failqual_ema_mode == "off" and failqual_extra_margin > 0.0:
            dataframe["brf_failqual_extra_margin_ok"] = (
                dataframe["close"] <= (
                    dataframe["brf_fail_thr"] - failqual_extra_margin * fail_reclaim_atr_ref
                )
            ).fillna(False)
        else:
            dataframe["brf_failqual_extra_margin_ok"] = True
        use_fail_quality = use_fail_reclaim_highweak and self.sell_brf_failqual_enabled.value
        if use_fail_quality:
            failqual_ok = (
                dataframe["brf_failqual_strong_red"].astype(bool)
                & dataframe["brf_failqual_below_reclaim_buf"].astype(bool)
                & dataframe["brf_failqual_closepos_ok"].astype(bool)
                & dataframe["brf_failqual_below_ema"].astype(bool)
                & dataframe["brf_failqual_extra_margin_ok"].astype(bool)
            )
            dataframe["brf_trigger_fail_reclaim"] = (
                dataframe["brf_trigger_fail_reclaim"].astype(bool)
                & failqual_ok.astype(bool)
            ).fillna(False)
        dataframe["brf_trigger_fail_reclaim_pre_followthrough"] = dataframe["brf_trigger_fail_reclaim"].astype(bool)
        dataframe["brf_failqual_followthrough_ok"] = True
        dataframe["brf_fr_ref_fail_low_i"] = 0
        dataframe["brf_fr_ref_mid_gap_i"] = 0
        dataframe["brf_fr_ref_reclaim_minus_atr_i"] = 0
        pre_follow_mask = dataframe["brf_trigger_fail_reclaim_pre_followthrough"].astype(bool)
        if use_fail_reclaim_highweak and self.sell_brf_failqual_require_followthrough.value:
            followthrough_bars = max(1, int(self.sell_brf_failqual_followthrough_max_bars.value))
            followthrough_buf = float(self.sell_brf_failqual_followthrough_buf_atr.value)
            followthrough_mode = str(self.sell_brf_failqual_followthrough_mode.value)
            followthrough_ref_mode = str(self.sell_brf_failqual_followthrough_ref_mode.value)
            followthrough_price_source = str(self.sell_brf_failqual_followthrough_price_source.value)
            if followthrough_ref_mode == "mid_gap":
                gap_alpha = float(self.sell_brf_failqual_followthrough_mid_gap_alpha.value)
                followthrough_base_ref = (
                    dataframe["low"] + gap_alpha * (dataframe["brf_reclaim_thr"] - dataframe["low"])
                )
            elif followthrough_ref_mode == "reclaim_thr_minus_atr":
                reclaim_minus_atr_mult = float(self.sell_brf_failqual_followthrough_reclaim_minus_atr_mult.value)
                followthrough_base_ref = (
                    dataframe["brf_reclaim_thr"] - reclaim_minus_atr_mult * fail_reclaim_atr_ref
                )
            else:
                followthrough_base_ref = dataframe["low"]
            followthrough_ref_src = (
                followthrough_base_ref - followthrough_buf * fail_reclaim_atr_ref
            )
            idx_ft = np.arange(len(dataframe), dtype=float)
            seed_idx = np.where(pre_follow_mask.values, idx_ft, np.nan)
            last_seed_idx = pd.Series(seed_idx, index=dataframe.index).ffill()
            bars_since_seed = idx_ft - last_seed_idx
            followthrough_recent = pd.Series(
                np.isfinite(bars_since_seed)
                & (bars_since_seed >= 1)
                & (bars_since_seed <= followthrough_bars),
                index=dataframe.index,
            )
            followthrough_ref = pd.Series(
                np.where(pre_follow_mask.values, followthrough_ref_src.values, np.nan),
                index=dataframe.index,
            ).ffill()
            followthrough_probe = (
                dataframe["low"]
                if followthrough_price_source == "low"
                else dataframe["close"]
            )
            dataframe["brf_failqual_followthrough_ok"] = (
                followthrough_recent.astype(bool)
                & followthrough_ref.notna()
                & (followthrough_probe <= followthrough_ref)
            ).fillna(False)
            dataframe["brf_trigger_fail_reclaim"] = (
                dataframe["brf_failqual_followthrough_ok"].astype(bool)
            ).fillna(False)
            if followthrough_ref_mode == "mid_gap":
                dataframe["brf_fr_ref_mid_gap_i"] = pre_follow_mask.astype(int)
            elif followthrough_ref_mode == "reclaim_thr_minus_atr":
                dataframe["brf_fr_ref_reclaim_minus_atr_i"] = pre_follow_mask.astype(int)
            else:
                dataframe["brf_fr_ref_fail_low_i"] = pre_follow_mask.astype(int)
        elif use_fail_reclaim_highweak:
            dataframe["brf_fr_ref_fail_low_i"] = pre_follow_mask.astype(int)
        dataframe["brf_trigger_fail_reclaim_post_followthrough"] = (
            dataframe["brf_trigger_fail_reclaim"].astype(bool)
        )
        dataframe["brf_trigger_fail_reclaim_direct"] = dataframe["brf_trigger_fail_reclaim"].astype(bool)
        dataframe["brf_entry_reject_high_anchor"] = dataframe["brf_reject_high_anchor"].where(
            dataframe["brf_trigger_fail_reclaim_direct"].astype(bool),
            np.nan,
        )
        dataframe["brf_entry_arm_to_entry_bars"] = dataframe["brf_bars_since_arm"].where(
            dataframe["brf_trigger_fail_reclaim_direct"].astype(bool),
            np.nan,
        )
        dataframe["brf_fr_retest_armed_i"] = 0
        dataframe["brf_fr_retest_in_zone_i"] = 0
        dataframe["brf_fr_retest_seen_above_i"] = 0
        dataframe["brf_fr_retest_signal_ok_i"] = 0
        dataframe["brf_fr_retest_close_back_below_i"] = 0
        dataframe["brf_fr_retest_close_back_into_zone_i"] = 0
        dataframe["brf_fr_retest_red_close_i"] = 0
        dataframe["brf_fr_retest_entries_i"] = 0
        dataframe["brf_fr_retest_entry"] = False
        retest_zone_mode = str(self.sell_brf_fail_reclaim_retest_zone_mode.value)
        retest_zone_alpha_used = float(self.sell_brf_fail_reclaim_retest_close_in_zone_alpha.value)
        use_fail_retest_entry = (
            use_fail_reclaim_highweak
            and str(self.sell_brf_fail_reclaim_entry_mode.value) == "retest"
        )
        if use_fail_retest_entry:
            retest_window = max(1, int(self.sell_brf_fail_reclaim_retest_window_bars.value))
            retest_zone_atr = float(self.sell_brf_fail_reclaim_retest_zone_atr.value)
            retest_zone_mode = str(self.sell_brf_fail_reclaim_retest_zone_mode.value)
            retest_tight_alpha = float(self.sell_brf_fail_reclaim_retest_tight_alpha.value)
            retest_min_bars = max(0, int(self.sell_brf_fail_reclaim_retest_min_bars_after_trigger.value))
            retest_signal_mode = str(self.sell_brf_fail_reclaim_retest_signal_mode.value)
            retest_require_red_close = bool(self.sell_brf_fail_reclaim_retest_require_red_close.value)
            retest_close_in_zone_alpha = float(self.sell_brf_fail_reclaim_retest_close_in_zone_alpha.value)
            retest_close_in_zone_use_low = bool(self.sell_brf_fail_reclaim_retest_close_in_zone_use_low.value)
            retest_body_pct_min = float(self.sell_brf_fail_reclaim_retest_body_pct_min.value)
            retest_wick_pct_min = float(self.sell_brf_fail_reclaim_retest_wick_pct_min.value)
            retest_requires_above = bool(self.sell_brf_fail_reclaim_retest_requires_above_reclaim_first.value)
            idx_rt = np.arange(len(dataframe), dtype=float)
            retest_seed_mask = dataframe["brf_trigger_fail_reclaim_direct"].astype(bool)
            retest_seed_idx = np.where(retest_seed_mask.values, idx_rt, np.nan)
            last_retest_idx = pd.Series(retest_seed_idx, index=dataframe.index).ffill()
            retest_bars_since = idx_rt - last_retest_idx
            retest_pending = pd.Series(
                np.isfinite(retest_bars_since)
                & (retest_bars_since >= 0)
                & (retest_bars_since <= retest_window),
                index=dataframe.index,
            )
            retest_reclaim_anchor = pd.Series(
                np.where(retest_seed_mask.values, dataframe["brf_reclaim_thr"].values, np.nan),
                index=dataframe.index,
            ).ffill()
            retest_reject_high_anchor = pd.Series(
                np.where(retest_seed_mask.values, dataframe["brf_reject_high_anchor"].values, np.nan),
                index=dataframe.index,
            ).ffill()
            retest_atr_anchor = pd.Series(
                np.where(retest_seed_mask.values, fail_reclaim_atr_ref.values, np.nan),
                index=dataframe.index,
            ).ffill()
            retest_arm_bars_anchor = pd.Series(
                np.where(retest_seed_mask.values, dataframe["brf_bars_since_arm"].values, np.nan),
                index=dataframe.index,
            ).ffill()
            retest_zone_width = retest_zone_atr * retest_atr_anchor
            retest_zone_hi = retest_reclaim_anchor + retest_zone_atr * retest_atr_anchor
            retest_zone_lo = retest_reclaim_anchor - retest_zone_atr * retest_atr_anchor
            retest_zone_boundary = retest_reclaim_anchor + retest_close_in_zone_alpha * retest_zone_width
            retest_tight_boundary = retest_reclaim_anchor + retest_tight_alpha * retest_zone_width
            if retest_zone_mode == "tight":
                retest_fail_close_ref = retest_tight_boundary
                retest_zone_alpha_used = retest_tight_alpha
            else:
                retest_fail_close_ref = retest_zone_boundary
                retest_zone_alpha_used = retest_close_in_zone_alpha
            retest_in_zone = (
                retest_pending.astype(bool)
                & retest_reclaim_anchor.notna()
                & retest_atr_anchor.notna()
                & (dataframe["high"] >= retest_zone_lo)
                & (dataframe["low"] <= retest_zone_hi)
            ).fillna(False)
            retest_seed_group = pd.Series(last_retest_idx, index=dataframe.index)
            retest_seen_above = pd.Series(False, index=dataframe.index)
            valid_retest = retest_pending.astype(bool) & retest_seed_group.notna()
            if bool(valid_retest.any()):
                retest_seen_above_src = (
                    dataframe.loc[valid_retest, "high"] >= retest_reclaim_anchor.loc[valid_retest]
                ).astype(int)
                retest_seen_above.loc[valid_retest] = (
                    retest_seen_above_src.groupby(retest_seed_group.loc[valid_retest]).cummax().astype(bool)
                )
            retest_seen_above_ok = (
                retest_seen_above if retest_requires_above else pd.Series(True, index=dataframe.index)
            )
            retest_red_body = (dataframe["open"] - dataframe["close"]).clip(lower=0.0)
            retest_body_pct = (retest_red_body / brf_range).replace([np.inf, -np.inf], np.nan).fillna(0.0)
            s_close_back_below = (
                (dataframe["close"] < retest_reclaim_anchor)
                & (dataframe["high"] >= retest_reclaim_anchor)
            ).fillna(False)
            retest_close_into_zone_src = dataframe["low"] if retest_close_in_zone_use_low else dataframe["close"]
            s_close_back_into_zone = (
                retest_seen_above.astype(bool)
                & (retest_close_into_zone_src <= retest_fail_close_ref)
            ).fillna(False)
            if retest_require_red_close:
                s_close_back_below = (
                    s_close_back_below.astype(bool)
                    & (dataframe["close"] < dataframe["open"])
                ).fillna(False)
                s_close_back_into_zone = (
                    s_close_back_into_zone.astype(bool)
                    & (dataframe["close"] < dataframe["open"])
                ).fillna(False)
            s_bearish_body = (
                (dataframe["close"] < dataframe["open"])
                & (retest_body_pct >= retest_body_pct_min)
                & (dataframe["close"] < retest_reclaim_anchor)
            ).fillna(False)
            s_wick_dom = (
                (dataframe["brf_upper_wick_pct"] >= retest_wick_pct_min)
                & (dataframe["close"] < retest_reclaim_anchor)
            ).fillna(False)
            if retest_signal_mode == "close_back_below":
                retest_signal_ok = s_close_back_below
            elif retest_signal_mode == "close_back_into_zone":
                retest_signal_ok = s_close_back_into_zone
            elif retest_signal_mode == "bearish_body":
                retest_signal_ok = s_bearish_body
            else:
                retest_signal_ok = (
                    s_close_back_below.astype(int)
                    + s_bearish_body.astype(int)
                    + s_wick_dom.astype(int)
                ) >= 2
            retest_entry_candidate = (
                retest_pending.astype(bool)
                & retest_in_zone.astype(bool)
                & retest_seen_above_ok.astype(bool)
                & retest_signal_ok.astype(bool)
                & (pd.Series(retest_bars_since, index=dataframe.index) >= retest_min_bars)
            ).fillna(False)
            retest_entry_rank = pd.Series(0, index=dataframe.index, dtype=int)
            if bool(valid_retest.any()):
                retest_entry_rank.loc[valid_retest] = (
                    retest_entry_candidate.loc[valid_retest]
                    .astype(int)
                    .groupby(retest_seed_group.loc[valid_retest])
                    .cumsum()
                )
            retest_entry = (
                retest_entry_candidate.astype(bool)
                & (retest_entry_rank == 1)
            ).fillna(False)
            retest_arm_to_entry = pd.Series(retest_bars_since, index=dataframe.index) + retest_arm_bars_anchor
            dataframe["brf_entry_reject_high_anchor"] = retest_reject_high_anchor.where(
                retest_entry,
                np.nan,
            )
            dataframe["brf_entry_arm_to_entry_bars"] = retest_arm_to_entry.where(
                retest_entry,
                np.nan,
            )
            dataframe["brf_trigger_fail_reclaim"] = retest_entry.astype(bool)
            dataframe["brf_fr_retest_entry"] = retest_entry.astype(bool)
            dataframe["brf_fr_retest_armed_i"] = retest_pending.astype(int)
            dataframe["brf_fr_retest_in_zone_i"] = (
                retest_pending.astype(bool) & retest_in_zone.astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_seen_above_i"] = (
                retest_pending.astype(bool) & retest_seen_above_ok.astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_close_back_below_i"] = (
                retest_pending.astype(bool) & s_close_back_below.astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_close_back_into_zone_i"] = (
                retest_pending.astype(bool) & s_close_back_into_zone.astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_red_close_i"] = (
                retest_pending.astype(bool) & (dataframe["close"] < dataframe["open"])
            ).astype(int)
            dataframe["brf_fr_retest_signal_ok_i"] = (
                retest_pending.astype(bool) & retest_signal_ok.astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_entries_i"] = retest_entry.astype(int)
        dataframe["brf_frq_pre_rows_i"] = 0
        dataframe["brf_frq_pass_strong_red_i"] = 0
        dataframe["brf_frq_pass_closepos_i"] = 0
        dataframe["brf_frq_pass_below_reclaim_buf_i"] = 0
        dataframe["brf_frq_pass_below_ema_i"] = 0
        dataframe["brf_frq_pass_extra_margin_ok_i"] = 0
        dataframe["brf_frq_pass_followthrough_i"] = 0
        dataframe["brf_frq_fail_below_reclaim_buf_i"] = 0
        if use_fail_quality and self.sell_brf_failqual_debug_on_pretrigger.value:
            pre_mask = dataframe["brf_trigger_fail_reclaim_pre_failqual"].astype(bool)
            dataframe["brf_frq_pre_rows_i"] = pre_mask.astype(int)
            dataframe["brf_frq_pass_strong_red_i"] = (
                pre_mask & dataframe["brf_failqual_strong_red"].astype(bool)
            ).astype(int)
            dataframe["brf_frq_pass_closepos_i"] = (
                pre_mask & dataframe["brf_failqual_closepos_ok"].astype(bool)
            ).astype(int)
            dataframe["brf_frq_pass_below_reclaim_buf_i"] = (
                pre_mask & dataframe["brf_failqual_below_reclaim_buf"].astype(bool)
            ).astype(int)
            dataframe["brf_frq_pass_below_ema_i"] = (
                pre_mask & dataframe["brf_failqual_below_ema"].astype(bool)
            ).astype(int)
            dataframe["brf_frq_pass_extra_margin_ok_i"] = (
                pre_mask & dataframe["brf_failqual_extra_margin_ok"].astype(bool)
            ).astype(int)
            if self.sell_brf_failqual_require_followthrough.value:
                dataframe["brf_frq_pass_followthrough_i"] = (
                    dataframe["brf_failqual_followthrough_ok"].astype(bool)
                ).astype(int)
            else:
                dataframe["brf_frq_pass_followthrough_i"] = pre_mask.astype(int)
            dataframe["brf_frq_fail_below_reclaim_buf_i"] = (
                pre_mask & (~dataframe["brf_failqual_below_reclaim_buf"].astype(bool))
            ).astype(int)
        dataframe["brf_fr_reclaim_touch_close_i"] = dataframe["brf_reclaim_touch_close"].astype(int)
        dataframe["brf_fr_reclaim_touch_highweak_i"] = dataframe["brf_reclaim_touch_high_weakclose"].astype(int)
        dataframe["brf_fr_reclaim_touch_i"] = dataframe["brf_reclaim_touch"].astype(int)
        dataframe["brf_fr_reclaim_recent_i"] = dataframe["brf_reclaim_recent"].astype(int)
        dataframe["brf_fr_fail_close_i"] = (
            dataframe["brf_fail_close"].astype(bool)
            & dataframe["brf_reclaim_recent"].astype(bool)
        ).astype(int)
        dataframe["brf_fr_fail_now_i"] = dataframe["brf_fail_now"].astype(int)
        dataframe["brf_fr_confirm_ok_i"] = (
            dataframe["brf_confirm_ok"].astype(bool)
            & dataframe["brf_fail_now"].astype(bool)
        ).astype(int)
        dataframe["brf_fr_lh_ok_i"] = dataframe["brf_fail_reclaim_lh_ok"].astype(int)
        dataframe["brf_fr_trigger_pre_lh_i"] = dataframe["brf_trigger_fail_reclaim_pre_lh"].astype(int)
        dataframe["brf_fr_trigger_post_lh_i"] = dataframe["brf_trigger_fail_reclaim_pre_failqual"].astype(int)
        dataframe["brf_fr_failqual_red_ok_i"] = dataframe["brf_failqual_strong_red"].astype(int)
        dataframe["brf_fr_failqual_below_ema_i"] = dataframe["brf_failqual_below_ema"].astype(int)
        dataframe["brf_fr_failqual_below_reclaim_buf_i"] = dataframe["brf_failqual_below_reclaim_buf"].astype(int)
        dataframe["brf_fr_failqual_closepos_ok_i"] = dataframe["brf_failqual_closepos_ok"].astype(int)
        dataframe["brf_fr_failqual_extra_margin_ok_i"] = dataframe["brf_failqual_extra_margin_ok"].astype(int)
        dataframe["brf_fr_trigger_pre_failqual_i"] = dataframe["brf_trigger_fail_reclaim_pre_failqual"].astype(int)
        dataframe["brf_fr_trigger_post_failqual_i"] = dataframe["brf_trigger_fail_reclaim_pre_followthrough"].astype(int)
        dataframe["brf_fr_failqual_followthrough_ok_i"] = dataframe["brf_failqual_followthrough_ok"].astype(int)
        dataframe["brf_fr_trigger_pre_followthrough_i"] = dataframe["brf_trigger_fail_reclaim_pre_followthrough"].astype(int)
        dataframe["brf_fr_trigger_post_followthrough_i"] = dataframe["brf_trigger_fail_reclaim_post_followthrough"].astype(int)
        dataframe["brf_fr_trigger_i"] = dataframe["brf_trigger_fail_reclaim"].astype(int)
        dataframe["brf_fr_trigger_in_arm_i"] = (
            dataframe["brf_trigger_fail_reclaim"].astype(bool)
            & dataframe["brf_armed"].astype(bool)
        ).astype(int)
        lh_lookback = max(2, int(self.sell_brf_lower_high_lookback.value))
        recent_high = dataframe["high"].rolling(lh_lookback, min_periods=1).max().shift(1)
        lower_high_ref = dataframe["brf_reject_high_anchor"].where(
            dataframe["brf_reject_high_anchor"].notna(),
            recent_high,
        )
        dataframe["brf_lh_ok"] = (
            dataframe["high"] < lower_high_ref
        ).fillna(False)

        trig_mode = str(self.sell_brf_trigger_mode.value)
        if trig_mode == "rsi_crossdown":
            dataframe["brf_trigger"] = dataframe["brf_trig_rsi_cross"]
        elif trig_mode == "lower_low_break":
            dataframe["brf_trigger"] = dataframe["brf_trig_ll_break"]
        elif trig_mode == "fail_reclaim":
            dataframe["brf_trigger"] = dataframe["brf_trigger_fail_reclaim"]
        elif trig_mode == "any1":
            dataframe["brf_trigger"] = (
                dataframe["brf_trig_ema_cross"]
                | dataframe["brf_trig_rsi_cross"]
                | dataframe["brf_trig_ll_break"]
            ).fillna(False)
        elif trig_mode == "any2_of3":
            trig_sum = (
                dataframe["brf_trig_ema_cross"].astype(int)
                + dataframe["brf_trig_rsi_cross_dn"].astype(int)
                + dataframe["brf_trig_close_below_anchor"].astype(int)
            )
            dataframe["brf_trigger"] = (
                trig_sum >= int(self.sell_brf_trigger_any2_min_signals.value)
            ).fillna(False)
        elif trig_mode == "any2":
            trig_sum = (
                dataframe["brf_trig_ema_cross"].astype(int)
                + dataframe["brf_trig_rsi_cross"].astype(int)
                + dataframe["brf_trig_ll_break"].astype(int)
            )
            dataframe["brf_trigger"] = (trig_sum >= 2).fillna(False)
        else:
            dataframe["brf_trigger"] = dataframe["brf_trig_ema_cross"]

        if self.sell_brf_two_stage_enabled.value:
            dataframe["brf_candidate_direct"] = (
                dataframe["brf_armed"].astype(bool) & dataframe["brf_trigger"].astype(bool)
            ).fillna(False)
        else:
            dataframe["brf_candidate_direct"] = dataframe["brf_direct_candidate"].astype(bool)

        latch_source = str(self.sell_brf_retest_latch_source.value)
        if latch_source == "followthrough":
            brf_retest_ctx_event = dataframe["brf_trigger_fail_reclaim_post_followthrough"].astype(bool)
        elif latch_source == "either":
            brf_retest_ctx_event = (
                dataframe["brf_arm"].astype(bool)
                | dataframe["brf_trigger_fail_reclaim_post_followthrough"].astype(bool)
                | dataframe["brf_fail_now"].astype(bool)
            ).fillna(False)
        else:
            brf_retest_ctx_event = dataframe["brf_arm"].astype(bool)
        dataframe["brf_ctx_below_ema200_latched"] = (
            (
                brf_retest_ctx_event.astype(int)
                * dataframe["brf_below_ema200"].astype(int)
            ).replace(0, np.nan).ffill().fillna(0).astype(int).astype(bool)
        )
        dataframe["brf_ctx_vol_ok_latched"] = (
            (
                brf_retest_ctx_event.astype(int)
                * dataframe["brf_vol_ok"].astype(int)
            ).replace(0, np.nan).ffill().fillna(0).astype(int).astype(bool)
        )
        brf_retest_below_ema200_term = (
            dataframe["brf_ctx_below_ema200_latched"].astype(bool)
            if self.sell_brf_retest_use_arm_latched_below_ema200.value
            else dataframe["brf_below_ema200"].astype(bool)
        )
        brf_retest_vol_ok_term = (
            dataframe["brf_ctx_vol_ok_latched"].astype(bool)
            if self.sell_brf_retest_use_arm_latched_vol_ok.value
            else dataframe["brf_vol_ok"].astype(bool)
        )
        retest_reject_enabled = bool(self.sell_brf_retest_reject_enabled.value)
        retest_reject_require_red_close = bool(self.sell_brf_retest_reject_require_red_close.value)
        dataframe["brf_retest_reject_ok"] = (
            (dataframe["brf_upper_wick_pct"] >= float(self.sell_brf_retest_reject_min_upper_wick_pct.value))
            & ((not retest_reject_require_red_close) | (dataframe["close"] < dataframe["open"]))
            & (dataframe["brf_close_pos"] <= float(self.sell_brf_retest_reject_close_pos_max.value))
        ).fillna(False)
        brf_retest_reject_term = (
            dataframe["brf_retest_reject_ok"].astype(bool)
            if retest_reject_enabled
            else pd.Series(True, index=dataframe.index)
        )
        brf_retest_below_ema50_term = (
            (dataframe["close"] <= dataframe["htf_ema50_4h"]).fillna(False)
            if self.sell_brf_retest_block_if_close_above_ema50_4h.value
            else pd.Series(True, index=dataframe.index)
        )
        dataframe["brf_candidate_retest"] = (
            dataframe["brf_fr_retest_entry"].astype(bool)
            & dataframe["brf_bear_ok"].astype(bool)
            & brf_retest_below_ema200_term
            & brf_retest_vol_ok_term
            & dataframe["brf_rsi_ok_retest"].astype(bool)
            & brf_retest_reject_term.astype(bool)
            & brf_retest_below_ema50_term.astype(bool)
        ).fillna(False)
        dataframe["brf_fr_retest_entry_rows_i"] = 0
        dataframe["brf_fr_retest_pass_bear_ok_i"] = 0
        dataframe["brf_fr_retest_pass_below_ema200_i"] = 0
        dataframe["brf_fr_retest_pass_vol_ok_i"] = 0
        dataframe["brf_fr_retest_pass_below_ema200_latched_i"] = 0
        dataframe["brf_fr_retest_pass_vol_ok_latched_i"] = 0
        dataframe["brf_fr_retest_pass_rsi_ok_i"] = 0
        dataframe["brf_fr_retest_pass_rsi_ok_retest_i"] = 0
        dataframe["brf_fr_retest_reject_ok_i"] = 0
        dataframe["brf_fr_retest_reject_fail_wick_i"] = 0
        dataframe["brf_fr_retest_reject_fail_red_i"] = 0
        dataframe["brf_fr_retest_reject_fail_closepos_i"] = 0
        dataframe["brf_fr_retest_pass_all_retest_i"] = 0
        dataframe["brf_fr_retest_pass_all_retest_post_latch_i"] = 0
        dataframe["brf_fr_retest_tight_mode_used_i"] = 0
        if self.sell_brf_retest_filter_debug_enabled.value:
            retest_entry_mask = dataframe["brf_fr_retest_entry"].astype(bool)
            dataframe["brf_fr_retest_entry_rows_i"] = retest_entry_mask.astype(int)
            dataframe["brf_fr_retest_pass_bear_ok_i"] = (
                retest_entry_mask & dataframe["brf_bear_ok"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_below_ema200_i"] = (
                retest_entry_mask & dataframe["brf_below_ema200"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_vol_ok_i"] = (
                retest_entry_mask & dataframe["brf_vol_ok"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_below_ema200_latched_i"] = (
                retest_entry_mask & dataframe["brf_ctx_below_ema200_latched"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_vol_ok_latched_i"] = (
                retest_entry_mask & dataframe["brf_ctx_vol_ok_latched"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_rsi_ok_i"] = (
                retest_entry_mask & dataframe["brf_rsi_ok"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_rsi_ok_retest_i"] = (
                retest_entry_mask & dataframe["brf_rsi_ok_retest"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_reject_ok_i"] = (
                retest_entry_mask & dataframe["brf_retest_reject_ok"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_reject_fail_wick_i"] = (
                retest_entry_mask
                & (dataframe["brf_upper_wick_pct"] < float(self.sell_brf_retest_reject_min_upper_wick_pct.value))
            ).astype(int)
            dataframe["brf_fr_retest_reject_fail_red_i"] = (
                retest_entry_mask
                & retest_reject_enabled
                & retest_reject_require_red_close
                & ~(dataframe["close"] < dataframe["open"])
            ).astype(int)
            dataframe["brf_fr_retest_reject_fail_closepos_i"] = (
                retest_entry_mask
                & (dataframe["brf_close_pos"] > float(self.sell_brf_retest_reject_close_pos_max.value))
            ).astype(int)
            dataframe["brf_fr_retest_pass_all_retest_i"] = (
                retest_entry_mask & dataframe["brf_candidate_retest"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_pass_all_retest_post_latch_i"] = (
                retest_entry_mask & dataframe["brf_candidate_retest"].astype(bool)
            ).astype(int)
            dataframe["brf_fr_retest_tight_mode_used_i"] = (
                retest_entry_mask.astype(int) * int(retest_zone_mode == "tight")
            ).astype(int)
        dataframe["brf_fr_use_retest"] = bool(
            trig_mode == "fail_reclaim"
            and str(self.sell_brf_fail_reclaim_entry_mode.value) == "retest"
        )
        dataframe["brf_candidate_final"] = pd.Series(
            np.where(
                dataframe["brf_fr_use_retest"].astype(bool),
                dataframe["brf_candidate_retest"].astype(bool),
                dataframe["brf_candidate_direct"].astype(bool),
            ),
            index=dataframe.index,
        ).astype(bool)

        if self.sell_brf_require_lower_high.value:
            dataframe["brf_candidate_final"] = (
                dataframe["brf_candidate_final"].astype(bool) & dataframe["brf_lh_ok"].astype(bool)
            ).fillna(False)
        dataframe["brf_candidate"] = dataframe["brf_candidate_final"].astype(bool)

        if self.sell_brf_debug_counts.value:
            every = max(1, int(self.sell_brf_debug_every_bars.value))
            rows_now = len(dataframe)
            last_logged = self._brf_debug_last_log_rows.get(pair, -(10**9))
            if (rows_now - last_logged) >= every:
                brf_trace_top = ",".join(
                    f"{k}:{v}"
                    for k, v in sorted(
                        self._brf_trace_reason_counts.items(),
                        key=lambda kv: (-int(kv[1]), kv[0]),
                    )[:5]
                ) or "none"
                brf_trace_last_reason = self._brf_trace_last_reason_by_pair.get(pair, "")
                retest_filter_suffix = ""
                if self.sell_brf_retest_filter_debug_enabled.value:
                    retest_entry_rows = int(dataframe["brf_fr_retest_entry_rows_i"].sum())
                    retest_pass_bear_ok = int(dataframe["brf_fr_retest_pass_bear_ok_i"].sum())
                    retest_pass_below_ema200_raw = int(dataframe["brf_fr_retest_pass_below_ema200_i"].sum())
                    retest_pass_below_ema200_latched = int(dataframe["brf_fr_retest_pass_below_ema200_latched_i"].sum())
                    retest_pass_vol_ok_raw = int(dataframe["brf_fr_retest_pass_vol_ok_i"].sum())
                    retest_pass_vol_ok_latched = int(dataframe["brf_fr_retest_pass_vol_ok_latched_i"].sum())
                    retest_pass_rsi_ok = int(dataframe["brf_fr_retest_pass_rsi_ok_i"].sum())
                    retest_pass_rsi_ok_retest = int(dataframe["brf_fr_retest_pass_rsi_ok_retest_i"].sum())
                    retest_reject_ok = int(dataframe["brf_fr_retest_reject_ok_i"].sum())
                    retest_reject_fail_wick = int(dataframe["brf_fr_retest_reject_fail_wick_i"].sum())
                    retest_reject_fail_red = int(dataframe["brf_fr_retest_reject_fail_red_i"].sum())
                    retest_reject_fail_closepos = int(dataframe["brf_fr_retest_reject_fail_closepos_i"].sum())
                    retest_pass_all = int(dataframe["brf_fr_retest_pass_all_retest_i"].sum())
                    retest_pass_all_post_latch = int(dataframe["brf_fr_retest_pass_all_retest_post_latch_i"].sum())
                    retest_tight_mode_used = int(dataframe["brf_fr_retest_tight_mode_used_i"].sum())
                    retest_first_fail = "none"
                    effective_below_ema200 = (
                        retest_pass_below_ema200_latched
                        if self.sell_brf_retest_use_arm_latched_below_ema200.value
                        else retest_pass_below_ema200_raw
                    )
                    effective_vol_ok = (
                        retest_pass_vol_ok_latched
                        if self.sell_brf_retest_use_arm_latched_vol_ok.value
                        else retest_pass_vol_ok_raw
                    )
                    if retest_entry_rows > 0:
                        if retest_pass_bear_ok == 0:
                            retest_first_fail = "bear_ok"
                        elif effective_below_ema200 == 0:
                            retest_first_fail = "below_ema200"
                        elif effective_vol_ok == 0:
                            retest_first_fail = "vol_ok"
                        elif retest_pass_rsi_ok_retest == 0:
                            retest_first_fail = "rsi_ok_retest"
                        elif retest_reject_enabled and retest_reject_ok == 0:
                            retest_first_fail = "retest_reject"
                        elif retest_pass_all_post_latch == 0:
                            retest_first_fail = "other"
                    retest_filter_suffix = (
                        f" fr_retest_entry_rows={retest_entry_rows}"
                        f" fr_retest_pass_bear_ok={retest_pass_bear_ok}"
                        f" fr_retest_pass_below_ema200={retest_pass_below_ema200_raw}"
                        f" fr_retest_pass_below_ema200_raw={retest_pass_below_ema200_raw}"
                        f" fr_retest_pass_below_ema200_latched={retest_pass_below_ema200_latched}"
                        f" fr_retest_pass_vol_ok={retest_pass_vol_ok_raw}"
                        f" fr_retest_pass_vol_ok_raw={retest_pass_vol_ok_raw}"
                        f" fr_retest_pass_vol_ok_latched={retest_pass_vol_ok_latched}"
                        f" fr_retest_pass_rsi_ok={retest_pass_rsi_ok}"
                        f" fr_retest_pass_rsi_ok_retest={retest_pass_rsi_ok_retest}"
                        f" fr_retest_reject_ok={retest_reject_ok}"
                        f" fr_retest_reject_fail_wick={retest_reject_fail_wick}"
                        f" fr_retest_reject_fail_red={retest_reject_fail_red}"
                        f" fr_retest_reject_fail_closepos={retest_reject_fail_closepos}"
                        f" fr_retest_pass_all_retest={retest_pass_all}"
                        f" fr_retest_pass_all_retest_post_latch={retest_pass_all_post_latch}"
                        f" fr_retest_zone_alpha_used={retest_zone_alpha_used:.2f}"
                        f" fr_retest_tight_mode_used={retest_tight_mode_used}"
                        f" fr_retest_first_fail={retest_first_fail}"
                    )
                logger.info(
                    "BRF_DEBUG_COUNTS pair=%s n_rows=%s n_bear=%s n_below_ema200=%s n_rsi=%s n_reject=%s n_vol=%s n_roll=%s n_stretch=%s n_level=%s n_base=%s n_arm=%s n_armed=%s n_invalidated=%s n_trigger=%s n_direct=%s n_final=%s fr_retest_entry=%s fr_candidate_final=%s fr_buf_atr=%s fr_touch_close=%s fr_touch_highweak=%s fr_touch=%s fr_recent=%s fr_fail_close=%s fr_fail_now=%s fr_confirm_ok=%s fr_lh_ok=%s fr_trigger_pre_lh=%s fr_trigger_post_lh=%s fr_failqual_red_ok=%s fr_failqual_below_ema=%s fr_failqual_below_reclaim_buf=%s fr_failqual_closepos_ok=%s fr_failqual_extra_margin_ok=%s fr_failqual_followthrough_ok=%s fr_ref_fail_low=%s fr_ref_mid_gap=%s fr_ref_reclaim_minus_atr=%s fr_trigger_pre_failqual=%s fr_trigger_post_failqual=%s fr_trigger_pre_followthrough=%s fr_trigger_post_followthrough=%s frq_pre_rows=%s frq_pass_strong_red=%s frq_pass_closepos=%s frq_pass_below_reclaim_buf=%s frq_pass_below_ema=%s frq_pass_extra_margin_ok=%s frq_pass_followthrough=%s frq_fail_below_reclaim_buf=%s fr_retest_armed=%s fr_retest_in_zone=%s fr_retest_seen_above=%s fr_retest_close_back_below=%s fr_retest_close_back_into_zone=%s fr_retest_red_close=%s fr_retest_signal_ok=%s fr_retest_entries=%s fr_no_confirm_exits=%s brf_trace_attempts=%s brf_trace_accepted=%s brf_trace_vetoed=%s brf_trace_overwritten=%s brf_trace_reasons=%s brf_trace_last_reason=%s fr_trigger=%s fr_trigger_in_arm=%s mode_vol=%s mode_reject=%s mode_roll=%s mode_stretch=%s mode_trigger=%s mode_reclaim=%s two_stage=%s%s",
                    pair,
                    rows_now,
                    int(dataframe["brf_bear_ok"].astype(bool).sum()),
                    int(dataframe["brf_below_ema200"].astype(bool).sum()),
                    int(dataframe["brf_rsi_ok"].astype(bool).sum()),
                    int(dataframe["brf_reject_ok"].astype(bool).sum()),
                    int(dataframe["brf_vol_ok"].astype(bool).sum()),
                    int(dataframe["brf_roll_ok"].astype(bool).sum()),
                    int(dataframe["brf_stretch_ok"].astype(bool).sum()),
                    int(dataframe["brf_level_ok"].astype(bool).sum()),
                    int(dataframe["brf_candidate_base"].astype(bool).sum()),
                    int(dataframe["brf_arm"].astype(bool).sum()),
                    int(dataframe["brf_armed"].astype(bool).sum()),
                    int(dataframe["brf_arm_invalidated"].astype(bool).sum()),
                    int(dataframe["brf_trigger"].astype(bool).sum()),
                    int(dataframe["brf_direct_candidate"].astype(bool).sum()),
                    int(dataframe["brf_candidate_final"].astype(bool).sum()),
                    int(dataframe["brf_fr_retest_entry"].astype(bool).sum()),
                    int(dataframe["brf_candidate_final"].astype(bool).sum()),
                    round(reclaim_buf, 4),
                    int(dataframe["brf_fr_reclaim_touch_close_i"].sum()),
                    int(dataframe["brf_fr_reclaim_touch_highweak_i"].sum()),
                    int(dataframe["brf_fr_reclaim_touch_i"].sum()),
                    int(dataframe["brf_fr_reclaim_recent_i"].sum()),
                    int(dataframe["brf_fr_fail_close_i"].sum()),
                    int(dataframe["brf_fr_fail_now_i"].sum()),
                    int(dataframe["brf_fr_confirm_ok_i"].sum()),
                    int(dataframe["brf_fr_lh_ok_i"].sum()),
                    int(dataframe["brf_fr_trigger_pre_lh_i"].sum()),
                    int(dataframe["brf_fr_trigger_post_lh_i"].sum()),
                    int(dataframe["brf_fr_failqual_red_ok_i"].sum()),
                    int(dataframe["brf_fr_failqual_below_ema_i"].sum()),
                    int(dataframe["brf_fr_failqual_below_reclaim_buf_i"].sum()),
                    int(dataframe["brf_fr_failqual_closepos_ok_i"].sum()),
                    int(dataframe["brf_fr_failqual_extra_margin_ok_i"].sum()),
                    int(dataframe["brf_fr_failqual_followthrough_ok_i"].sum()),
                    int(dataframe["brf_fr_ref_fail_low_i"].sum()),
                    int(dataframe["brf_fr_ref_mid_gap_i"].sum()),
                    int(dataframe["brf_fr_ref_reclaim_minus_atr_i"].sum()),
                    int(dataframe["brf_fr_trigger_pre_failqual_i"].sum()),
                    int(dataframe["brf_fr_trigger_post_failqual_i"].sum()),
                    int(dataframe["brf_fr_trigger_pre_followthrough_i"].sum()),
                    int(dataframe["brf_fr_trigger_post_followthrough_i"].sum()),
                    int(dataframe["brf_frq_pre_rows_i"].sum()),
                    int(dataframe["brf_frq_pass_strong_red_i"].sum()),
                    int(dataframe["brf_frq_pass_closepos_i"].sum()),
                    int(dataframe["brf_frq_pass_below_reclaim_buf_i"].sum()),
                    int(dataframe["brf_frq_pass_below_ema_i"].sum()),
                    int(dataframe["brf_frq_pass_extra_margin_ok_i"].sum()),
                    int(dataframe["brf_frq_pass_followthrough_i"].sum()),
                    int(dataframe["brf_frq_fail_below_reclaim_buf_i"].sum()),
                    int(dataframe["brf_fr_retest_armed_i"].sum()),
                    int(dataframe["brf_fr_retest_in_zone_i"].sum()),
                    int(dataframe["brf_fr_retest_seen_above_i"].sum()),
                    int(dataframe["brf_fr_retest_close_back_below_i"].sum()),
                    int(dataframe["brf_fr_retest_close_back_into_zone_i"].sum()),
                    int(dataframe["brf_fr_retest_red_close_i"].sum()),
                    int(dataframe["brf_fr_retest_signal_ok_i"].sum()),
                    int(dataframe["brf_fr_retest_entries_i"].sum()),
                    int(self._brf_no_confirm_exit_count),
                    int(self._brf_trace_attempts),
                    int(self._brf_trace_accepted),
                    int(self._brf_trace_vetoed),
                    int(self._brf_trace_overwritten),
                    brf_trace_top,
                    brf_trace_last_reason,
                    int(dataframe["brf_fr_trigger_i"].sum()),
                    int(dataframe["brf_fr_trigger_in_arm_i"].sum()),
                    vol_mode,
                    reject_mode,
                    roll_mode,
                    stretch_mode,
                    trig_mode,
                    reclaim_mode,
                    str(self.sell_brf_two_stage_enabled.value),
                    retest_filter_suffix,
                )
                self._brf_debug_last_log_rows[pair] = rows_now

        # ── BRF_CLASSIC indicators (simple bear rally fade sleeve) ──
        classic_bb = ta.BBANDS(
            dataframe,
            timeperiod=int(self.sell_brf_classic_bb_len.value),
            nbdevup=float(self.sell_brf_classic_bb_std.value),
            nbdevdn=float(self.sell_brf_classic_bb_std.value),
        )
        dataframe["brf_classic_ema50_1h"] = ta.EMA(dataframe, timeperiod=int(self.sell_brf_classic_ema50_len.value))
        dataframe["brf_classic_ema20_1h"] = ta.EMA(dataframe, timeperiod=20)
        dataframe["brf_classic_bb_mid_1h"] = classic_bb["middleband"]
        dataframe["brf_classic_bb_upper_1h"] = classic_bb["upperband"]
        dataframe["brf_classic_bb_lower_1h"] = classic_bb["lowerband"]
        dataframe["brf_classic_rsi_1h"] = ta.RSI(dataframe, timeperiod=int(self.sell_brf_classic_rsi_len.value))
        dataframe["brf_classic_ema200_4h"] = dataframe.get("htf_ema200_4h", np.nan)
        dataframe["brf_classic_ema50_4h"] = dataframe.get("htf_ema50_4h", np.nan)
        dataframe["brf_classic_atr_4h"] = dataframe.get(
            "brf_classic_pair_atr_4h",
            dataframe.get("brf_pair_atr_4h", np.nan),
        )
        dataframe["brf_classic_atr_ratio_4h"] = dataframe.get(
            "brf_classic_pair_atr_ratio_4h",
            np.nan,
        )
        if dataframe["brf_classic_atr_ratio_4h"].isna().all():
            classic_shift = max(1, int(self.sell_brf_classic_atr_rise_lookback.value)) * 4
            dataframe["brf_classic_atr_ratio_4h"] = dataframe["brf_classic_atr_4h"] / dataframe["brf_classic_atr_4h"].shift(classic_shift)

        classic_bear_buf = float(self.sell_brf_classic_bear_close_below_ema200_buf.value)
        classic_stretch = float(self.sell_brf_classic_stretch_atr_mult.value)
        classic_wick_min = float(self.sell_brf_classic_reject_upper_wick_pct_min.value)
        classic_red_required = bool(self.sell_brf_classic_reject_body_red_required.value)
        classic_cross_from = int(self.sell_brf_classic_rsi_crossdown_from.value)
        classic_overbought = int(self.sell_brf_classic_rsi_overbought.value)
        dataframe["brf_classic_bear_ok"] = (
            dataframe["brf_btc_deep_bear"].astype(bool)
            if self.sell_brf_classic_use_btc_bear_gate.value
            else True
        )
        dataframe["brf_classic_below_ema200_ok"] = (
            dataframe["close"] <= (dataframe["brf_classic_ema200_4h"] * (1.0 - classic_bear_buf))
        ).fillna(False)
        dataframe["brf_classic_rally_ok"] = (
            (dataframe["close"] > dataframe["brf_classic_ema50_1h"])
            | (dataframe["close"] >= dataframe["brf_classic_bb_upper_1h"])
        ).fillna(False)
        stretch_line = dataframe["brf_classic_ema50_1h"] + classic_stretch * dataframe["atr14"]
        if classic_stretch > 0:
            dataframe["brf_classic_stretch_ok"] = (
                (dataframe["close"] > stretch_line)
                | (dataframe["close"] >= dataframe["brf_classic_bb_upper_1h"])
            ).fillna(False)
        else:
            dataframe["brf_classic_stretch_ok"] = True
        dataframe["brf_classic_rsi_overbought_ok"] = (
            dataframe["brf_classic_rsi_1h"] >= classic_overbought
        ).fillna(False)
        classic_rsi_prev = dataframe["brf_classic_rsi_1h"].shift(1)
        classic_cross_seed = max(classic_cross_from, classic_overbought)
        dataframe["brf_classic_rsi_crossdown"] = (
            (classic_rsi_prev >= classic_cross_seed)
            & (dataframe["brf_classic_rsi_1h"] < classic_cross_from)
        ).fillna(False)
        dataframe["brf_classic_rsi_ok"] = dataframe["brf_classic_rsi_crossdown"].astype(bool)
        dataframe["brf_classic_vol_ok"] = (
            dataframe["brf_classic_atr_ratio_4h"] >= float(self.sell_brf_classic_atr_rise_ratio.value)
        ).fillna(False)
        dataframe["brf_classic_reject_ok"] = (
            (dataframe["brf_upper_wick_pct"] >= classic_wick_min)
            & ((not classic_red_required) | (dataframe["close"] < dataframe["open"]))
        ).fillna(False)
        dataframe["brf_classic_arm"] = (
            (dataframe["volume"] > 0)
            & dataframe["brf_classic_bear_ok"].astype(bool)
            & dataframe["brf_classic_below_ema200_ok"].astype(bool)
            & dataframe["brf_classic_rally_ok"].astype(bool)
            & dataframe["brf_classic_stretch_ok"].astype(bool)
            & dataframe["brf_classic_rsi_ok"].astype(bool)
            & dataframe["brf_classic_vol_ok"].astype(bool)
            & dataframe["brf_classic_reject_ok"].astype(bool)
        ).fillna(False)

        classic_window = max(1, int(self.sell_brf_classic_trigger_window_bars.value))
        classic_idx = np.arange(len(dataframe), dtype=float)
        classic_arm_idx_src = pd.Series(
            np.where(dataframe["brf_classic_arm"].values, classic_idx, np.nan),
            index=dataframe.index,
        )
        classic_arm_idx_ffill = classic_arm_idx_src.ffill(limit=classic_window)
        dataframe["brf_classic_arm_active"] = classic_arm_idx_ffill.notna()
        dataframe["brf_classic_bars_since_arm"] = pd.Series(classic_idx, index=dataframe.index) - classic_arm_idx_ffill
        dataframe["brf_classic_reject_high_ffill"] = pd.Series(
            np.where(dataframe["brf_classic_arm"].values, dataframe["high"].values, np.nan),
            index=dataframe.index,
        ).ffill(limit=classic_window)
        dataframe["brf_classic_reject_low_ffill"] = pd.Series(
            np.where(dataframe["brf_classic_arm"].values, dataframe["low"].values, np.nan),
            index=dataframe.index,
        ).ffill(limit=classic_window)

        classic_trigger_mode = str(self.sell_brf_classic_trigger_mode.value)
        classic_trigger_ready = (
            dataframe["brf_classic_arm_active"].astype(bool)
            & (dataframe["brf_classic_bars_since_arm"] >= 1)
        ).fillna(False)
        dataframe["brf_classic_trigger_ema_line"] = ta.EMA(
            dataframe,
            timeperiod=int(self.sell_brf_classic_trigger_ema_len.value),
        )
        dataframe["brf_classic_trigger_ema"] = (
            (dataframe["close"] < dataframe["brf_classic_trigger_ema_line"])
            & (
                dataframe["close"].shift(1)
                >= dataframe["brf_classic_trigger_ema_line"].shift(1)
            )
        ).fillna(False)
        classic_ll_lookback = max(1, int(self.sell_brf_classic_trigger_ll_lookback.value))
        dataframe["brf_classic_trigger_ll_floor"] = (
            dataframe["low"].shift(1).rolling(classic_ll_lookback, min_periods=classic_ll_lookback).min()
        )
        dataframe["brf_classic_trigger_ll_break"] = (
            dataframe["close"] < dataframe["brf_classic_trigger_ll_floor"]
        ).fillna(False)
        dataframe["brf_classic_trigger_close_below_bb_mid"] = (
            dataframe["close"] < dataframe["brf_classic_bb_mid_1h"]
        ).fillna(False)
        dataframe["brf_classic_trigger_any2"] = (
            dataframe["brf_classic_trigger_ema"].astype(int)
            + dataframe["brf_classic_trigger_ll_break"].astype(int)
            + dataframe["brf_classic_trigger_close_below_bb_mid"].astype(int)
            >= 2
        ).fillna(False)
        if classic_trigger_mode == "ema_crossdown_or_ll_break":
            classic_trigger_raw = (
                dataframe["brf_classic_trigger_ema"].astype(bool)
                | dataframe["brf_classic_trigger_ll_break"].astype(bool)
            ).fillna(False)
        elif classic_trigger_mode == "any2_of3":
            classic_trigger_raw = dataframe["brf_classic_trigger_any2"].astype(bool)
        else:
            classic_trigger_raw = dataframe["brf_classic_trigger_ema"].astype(bool)
        dataframe["brf_classic_trigger"] = (
            classic_trigger_ready.astype(bool)
            & classic_trigger_raw.astype(bool)
        ).fillna(False)

        dataframe["brf_classic_candidate_final"] = dataframe["brf_classic_trigger"].astype(bool)
        dataframe["brf_classic_add_signal"] = dataframe["brf_classic_candidate_final"].astype(bool)
        dataframe["brf_classic_short"] = dataframe["brf_classic_candidate_final"].astype(bool)
        dataframe["brf_classic_entry_reject_high"] = dataframe["brf_classic_reject_high_ffill"].where(
            dataframe["brf_classic_short"].astype(bool),
            np.nan,
        )

        if self.sell_brf_classic_debug_counts.value or self.sell_brf_classic_trace_entry_enabled.value:
            if self.sell_brf_classic_debug_counts.value:
                every = max(1, int(self.sell_brf_classic_debug_every_rows.value))
            else:
                every = max(1, int(self.sell_brf_classic_trace_every_n.value))
            rows_now = len(dataframe)
            last_logged = self._brf_classic_debug_last_log_rows.get(pair, -(10**9))
            if (rows_now - last_logged) >= every:
                trace_suffix = ""
                if self.sell_brf_classic_trace_entry_enabled.value:
                    top = sorted(
                        self._brf_classic_trace_veto_reason_counts.items(),
                        key=lambda kv: (-int(kv[1]), kv[0]),
                    )[:3]
                    top_str = ",".join(f"{k}:{v}" for k, v in top) if top else "none"
                    trace_suffix = (
                        " tcand=%s tapplied=%s tover=%s tconfirm=%s tveto=%s taccept=%s"
                        " tpair_open=%s trisk=%s ttop=%s"
                        % (
                            int(self._brf_classic_trace_candidates),
                            int(self._brf_classic_trace_applied),
                            int(self._brf_classic_trace_overwritten),
                            int(self._brf_classic_trace_confirm_called),
                            int(self._brf_classic_trace_confirm_veto),
                            int(self._brf_classic_trace_confirm_accept),
                            int(self._brf_classic_trace_dupe_ignored),
                            int(self._brf_classic_trace_risk_blocked),
                            top_str,
                        )
                    )
                logger.info(
                    "BRF_CLASSIC_DEBUG pair=%s rows=%s bear=%s below=%s rally=%s stretch=%s rsi=%s vol=%s reject=%s arm=%s trigger=%s final=%s%s",
                    pair,
                    rows_now,
                    int(dataframe["brf_classic_bear_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_below_ema200_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_rally_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_stretch_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_rsi_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_vol_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_reject_ok"].astype(bool).sum()),
                    int(dataframe["brf_classic_arm"].astype(bool).sum()),
                    int(dataframe["brf_classic_trigger"].astype(bool).sum()),
                    int(dataframe["brf_classic_candidate_final"].astype(bool).sum()),
                    trace_suffix,
                )
                self._brf_classic_debug_last_log_rows[pair] = rows_now

        # ── CBX indicators (Donchian + Supertrend + quality filters) ──
        dataframe = self._add_cbx_indicators(dataframe)

        # ── CBX-4h anchor indicators (4h breakout + 1h confirmation) ──
        dataframe = self._add_cbx4h_indicators(dataframe, metadata)

        # ── MR indicators (Bollinger + RSI + snapback) ──
        mr_bb = ta.BBANDS(
            dataframe,
            timeperiod=int(self.buy_mr_bb_len.value),
            nbdevup=float(self.buy_mr_bb_std.value),
            nbdevdn=float(self.buy_mr_bb_std.value),
        )
        dataframe["mr_bb_mid"] = mr_bb["middleband"]
        dataframe["mr_bb_low"] = mr_bb["lowerband"]
        dataframe["mr_bb_high"] = mr_bb["upperband"]
        dataframe["mr_bbw"] = (dataframe["mr_bb_high"] - dataframe["mr_bb_low"]) / dataframe["mr_bb_mid"]
        dataframe["mr_rsi"] = ta.RSI(dataframe, timeperiod=14)
        dataframe["mr_below_low_prev"] = (dataframe["close"].shift(1) < dataframe["mr_bb_low"].shift(1)).astype(int)
        dataframe["mr_reclaim"] = (
            (dataframe["mr_below_low_prev"] == 1)
            & (dataframe["close"] > dataframe["mr_bb_low"])
        ).astype(int)
        candle_range = (dataframe["high"] - dataframe["low"]).replace(0, np.nan)
        dataframe["mr_wick_recover"] = (dataframe["close"] - dataframe["low"]) / candle_range

        # ── Cross-sleeve ranking features (shifted, deterministic, additive only) ──
        rank_ema50 = ta.EMA(dataframe, timeperiod=50)
        rank_ema200 = ta.EMA(dataframe, timeperiod=200)
        rank_adx = ta.ADX(dataframe, timeperiod=14)
        rank_bb = ta.BBANDS(dataframe, timeperiod=20, nbdevup=2.0, nbdevdn=2.0)
        rank_bb_mid = rank_bb["middleband"].replace(0, np.nan)
        rank_bb_width = (rank_bb["upperband"] - rank_bb["lowerband"]) / rank_bb_mid
        atr_prev = dataframe["atr14"].shift(1).replace(0, np.nan)
        close_prev = dataframe["close"].shift(1).replace(0, np.nan)

        trend_strength = (rank_ema50.shift(1) - rank_ema200.shift(1)).abs() / atr_prev
        trend_score = trend_strength / (1.0 + trend_strength)
        adx_score = ((rank_adx.shift(1) - 10.0) / 25.0).clip(lower=0.0, upper=1.0)
        dataframe["rank_regime_quality"] = (
            (trend_score.fillna(0.0) * 0.6) + (adx_score.fillna(0.0) * 0.4)
        ).clip(lower=0.0, upper=1.0)

        bb_width_prev = rank_bb_width.shift(1)
        bb_width_mean = bb_width_prev.rolling(20, min_periods=5).mean().replace(0, np.nan)
        bb_width_ratio = bb_width_prev / bb_width_mean
        dataframe["rank_volexp"] = ((bb_width_ratio - 1.0) / 0.5).clip(lower=0.0, upper=1.0).fillna(0.0)

        atr_pct_prev = atr_prev / close_prev
        heat_raw = dataframe["close"].pct_change(6).abs().shift(1) / atr_pct_prev
        dataframe["rank_heat"] = (heat_raw / 2.0).clip(lower=0.0, upper=1.0).fillna(0.0)

        disloc_cap = 0.05
        disloc_raw = (rank_bb["lowerband"].shift(1) - close_prev) / close_prev
        dataframe["rank_disloc"] = (disloc_raw.clip(lower=0.0, upper=disloc_cap) / disloc_cap).fillna(0.0)

        dataframe["rank_expr"] = (atr_pct_prev / 0.05).clip(lower=0.0, upper=1.0).fillna(0.0)

        # ── Shared 5m state: derive sleeve inputs, then align to 1h bars ──
        dataframe["micro5m_pullback_signal"] = False
        dataframe["micro5m_breakout_signal"] = False
        dataframe["micro5m_signal"] = False
        dataframe["micro5m_rel_vol"] = 0.0
        dataframe["micro5m_bb_width"] = 0.0
        dataframe["micro5m_bb_width_ratio"] = 0.0
        dataframe["micro5m_atr_ratio"] = 0.0
        dataframe["micro5m_volexp_pass"] = False
        dataframe["micro5m_trend_bias"] = False
        dataframe["micro5m_confirm_pass"] = False
        dataframe["micro5m_impulse_signal"] = False
        dataframe["micro5m_reclaim_signal"] = False
        dataframe["micro5m_followthrough_signal"] = False
        dataframe["micro5m_delayed_entry_signal"] = False
        dataframe["micro5m_friction_ok"] = False
        dataframe["micro5m_score"] = 0.0
        dataframe["micro5m_dislocation"] = 0.0
        dataframe["micro5m_momo"] = 0.0
        dataframe["micro5m_edge_proxy"] = 0.0
        dataframe["micro5m_edge_proxy_bps"] = 0.0
        dataframe["e0v1e5m_signal"] = False
        dataframe["e0v1e5m_signal_ewo"] = False
        dataframe["e0v1e5m_signal_buy_1"] = False
        dataframe["e0v1e5m_close"] = 0.0
        dataframe["e0v1e5m_fastk"] = 0.0
        dataframe["e0v1e5m_bb_width"] = 0.0
        dataframe["e0v1e5m_bb_middleband2"] = 0.0
        dataframe["e0v1e5m_volume_mean_12"] = 0.0
        dataframe["e0v1e5m_volume_mean_24"] = 0.0
        if self.micro5m_enabled.value or self.e0v1e5m_enabled.value:
            try:
                micro_df = self.dp.get_pair_dataframe(pair=pair, timeframe="5m")
            except Exception:
                micro_df = None
            if micro_df is not None and not micro_df.empty:
                try:
                    micro_df = micro_df.copy()
                    micro_df["e0v1e5m_signal"] = False
                    micro_df["e0v1e5m_signal_ewo"] = False
                    micro_df["e0v1e5m_signal_buy_1"] = False
                    micro_df["e0v1e5m_close"] = pd.to_numeric(micro_df["close"], errors="coerce").fillna(0.0)
                    micro_df["e0v1e5m_fastk"] = 0.0
                    micro_df["e0v1e5m_bb_width"] = 0.0
                    micro_df["e0v1e5m_bb_middleband2"] = 0.0
                    micro_df["e0v1e5m_volume_mean_12"] = 0.0
                    micro_df["e0v1e5m_volume_mean_24"] = 0.0
                    if self.e0v1e5m_enabled.value:
                        e0_low = micro_df["low"].replace(0, np.nan)
                        e0_ema_50 = ta.EMA(micro_df, timeperiod=50)
                        e0_ema_200 = ta.EMA(micro_df, timeperiod=200)
                        micro_df["e0v1e5m_sma_15"] = ta.SMA(micro_df, timeperiod=15)
                        micro_df["e0v1e5m_cti"] = _rolling_cti(micro_df["close"], length=20)
                        micro_df["e0v1e5m_rsi"] = ta.RSI(micro_df, timeperiod=14)
                        micro_df["e0v1e5m_rsi_fast"] = ta.RSI(micro_df, timeperiod=4)
                        micro_df["e0v1e5m_rsi_slow"] = ta.RSI(micro_df, timeperiod=20)
                        micro_df["e0v1e5m_ema_8"] = ta.EMA(micro_df, timeperiod=8)
                        micro_df["e0v1e5m_ema_16"] = ta.EMA(micro_df, timeperiod=16)
                        micro_df["e0v1e5m_ewo"] = ((e0_ema_50 - e0_ema_200) / e0_low) * 100.0

                        e0_stoch = ta.STOCHF(micro_df, 5, 3, 0, 3, 0)
                        micro_df["e0v1e5m_fastk"] = pd.to_numeric(e0_stoch["fastk"], errors="coerce").fillna(0.0)

                        e0_boll = qtpylib.bollinger_bands(
                            qtpylib.typical_price(micro_df),
                            window=20,
                            stds=2,
                        )
                        e0_mid = pd.to_numeric(e0_boll["mid"], errors="coerce").replace(0, np.nan)
                        micro_df["e0v1e5m_bb_middleband2"] = e0_mid.fillna(0.0)
                        micro_df["e0v1e5m_bb_width"] = (
                            (pd.to_numeric(e0_boll["upper"], errors="coerce") - pd.to_numeric(e0_boll["lower"], errors="coerce"))
                            / e0_mid
                        ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                        micro_df["e0v1e5m_volume_mean_12"] = (
                            pd.to_numeric(micro_df["volume"], errors="coerce").rolling(12).mean().shift(1)
                        ).fillna(0.0)
                        micro_df["e0v1e5m_volume_mean_24"] = (
                            pd.to_numeric(micro_df["volume"], errors="coerce").rolling(24).mean().shift(1)
                        ).fillna(0.0)

                        e0_is_ewo = (
                            (micro_df["e0v1e5m_rsi_fast"] < float(self.e0v1e5m_buy_rsi_fast))
                            & (micro_df["close"] < micro_df["e0v1e5m_ema_8"] * float(self.e0v1e5m_buy_ema_low))
                            & (micro_df["e0v1e5m_ewo"] > float(self.e0v1e5m_buy_ewo))
                            & (micro_df["close"] < micro_df["e0v1e5m_ema_16"] * float(self.e0v1e5m_buy_ema_high))
                            & (micro_df["e0v1e5m_rsi"] < float(self.e0v1e5m_buy_rsi))
                        ).fillna(False)
                        e0_buy_1 = (
                            (micro_df["e0v1e5m_rsi_slow"] < micro_df["e0v1e5m_rsi_slow"].shift(1))
                            & (micro_df["e0v1e5m_rsi_fast"] < float(self.e0v1e5m_buy_rsi_fast_32))
                            & (micro_df["e0v1e5m_rsi"] > float(self.e0v1e5m_buy_rsi_32))
                            & (micro_df["close"] < micro_df["e0v1e5m_sma_15"] * float(self.e0v1e5m_buy_sma15_32))
                            & (micro_df["e0v1e5m_cti"] < float(self.e0v1e5m_buy_cti_32))
                        ).fillna(False)
                        micro_df["e0v1e5m_signal_ewo"] = e0_is_ewo.astype(bool)
                        micro_df["e0v1e5m_signal_buy_1"] = e0_buy_1.astype(bool)
                        micro_df["e0v1e5m_signal"] = (e0_is_ewo | e0_buy_1).astype(bool)
                    micro_df["micro5m_atr14"] = ta.ATR(micro_df, timeperiod=14)
                    micro_df["micro5m_ret1"] = micro_df["close"].pct_change()
                    micro_df["micro5m_rsi"] = ta.RSI(micro_df, timeperiod=7)
                    micro_df["micro5m_ema_fast"] = ta.EMA(micro_df, timeperiod=9)
                    micro_df["micro5m_ema20"] = ta.EMA(micro_df, timeperiod=20)
                    micro_df["micro5m_ema50"] = ta.EMA(micro_df, timeperiod=50)
                    cum_vol = micro_df["volume"].cumsum().replace(0, np.nan)
                    cum_pv = (micro_df["close"] * micro_df["volume"]).cumsum()
                    micro_df["micro5m_vwap"] = (cum_pv / cum_vol).replace([np.inf, -np.inf], np.nan)
                    micro_bb = ta.BBANDS(micro_df, timeperiod=20, nbdevup=2.0, nbdevdn=2.0)
                    micro_mid = micro_bb["middleband"].replace(0, np.nan)
                    micro_lower = micro_bb["lowerband"]
                    micro_df["micro5m_bb_width"] = (
                        (micro_bb["upperband"] - micro_bb["lowerband"]) / micro_mid
                    ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                    vol_lb = max(5, int(self.micro5m_volexp_lookback.value))
                    micro_df["micro5m_bb_width_ratio"] = (
                        micro_df["micro5m_bb_width"] / micro_df["micro5m_bb_width"].shift(vol_lb).replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                    micro_df["micro5m_atr_ratio"] = (
                        micro_df["micro5m_atr14"] / micro_df["micro5m_atr14"].shift(vol_lb).replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                    micro_df["micro5m_vol_mean"] = micro_df["volume"].rolling(20, min_periods=8).mean()
                    micro_df["micro5m_rel_vol"] = (
                        micro_df["volume"] / micro_df["micro5m_vol_mean"].replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                    atr_pass = micro_df["micro5m_atr_ratio"] >= float(self.micro5m_volexp_atr_ratio_min.value)
                    bb_pass = micro_df["micro5m_bb_width_ratio"] >= float(self.micro5m_volexp_bbwidth_ratio_min.value)
                    volexp_mode = str(self.micro5m_volexp_mode.value)
                    if volexp_mode == "atr_rise":
                        volexp_core = atr_pass
                    elif volexp_mode == "bbwidth_rise":
                        volexp_core = bb_pass
                    else:
                        volexp_core = atr_pass | bb_pass
                    micro_df["micro5m_volexp_pass"] = (
                        volexp_core & (micro_df["micro5m_rel_vol"] >= float(self.micro5m_relvol_min.value))
                    ).fillna(False)
                    micro_df["micro5m_trend_bias"] = (
                        micro_df["close"] > micro_df["micro5m_ema50"]
                    ).fillna(False)
                    micro_rsi_cross = (
                        (micro_df["micro5m_rsi"] > 40.0)
                        & (micro_df["micro5m_rsi"].shift(1) <= 40.0)
                    ).fillna(False)
                    micro_reclaim = (
                        (micro_df["close"].shift(1) < micro_df["micro5m_ema20"].shift(1))
                        & (micro_df["close"] > micro_df["micro5m_ema20"])
                    ).fillna(False)
                    micro_pullback = (micro_reclaim & micro_rsi_cross).fillna(False)
                    recent_high = micro_df["high"].shift(1).rolling(12, min_periods=6).max()
                    micro_breakout = (
                        (micro_df["close"] > recent_high)
                        & (micro_df["micro5m_ret1"] > 0)
                    ).fillna(False)
                    if self.micro5m_require_trend_bias.value:
                        micro_pullback &= micro_df["micro5m_trend_bias"].astype(bool)
                        micro_breakout &= micro_df["micro5m_trend_bias"].astype(bool)
                    confirm_bars = max(1, int(self.micro5m_confirm_ema_bars.value))
                    micro_confirm = (
                        (micro_df["close"] > micro_df["micro5m_ema_fast"])
                        & (micro_df["micro5m_ema_fast"] > micro_df["micro5m_ema_fast"].shift(confirm_bars))
                    ).fillna(False)
                    if self.micro5m_confirm_vwap.value:
                        micro_confirm &= (micro_df["close"] > micro_df["micro5m_vwap"]).fillna(False)
                    micro_df["micro5m_confirm_pass"] = micro_confirm.astype(bool)
                    eps = 1e-9
                    impulse_lb = max(1, int(self.micro5m_impulse_lookback.value))
                    reclaim_lb = max(1, int(self.micro5m_reclaim_max_bars.value))
                    follow_lb = max(1, int(self.micro5m_followthrough_max_bars.value))
                    down_impulse = micro_df["close"].shift(impulse_lb) - micro_df["close"]
                    impulse_signal = (
                        down_impulse
                        >= (float(self.micro5m_impulse_atr_mult.value) * micro_df["micro5m_atr14"])
                    ).fillna(False)
                    impulse_recent = (
                        impulse_signal.shift(1).rolling(reclaim_lb, min_periods=1).max() > 0
                    ).fillna(False)
                    candle_range = (micro_df["high"] - micro_df["low"]).replace(0, np.nan)
                    body_ratio = (
                        (micro_df["close"] - micro_df["open"]).abs()
                        / candle_range
                    ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                    upper_wick_ratio = (
                        (micro_df["high"] - np.maximum(micro_df["open"], micro_df["close"]))
                        / candle_range
                    ).replace([np.inf, -np.inf], np.nan).fillna(1.0)
                    reclaim_now = impulse_recent.astype(bool)
                    if self.micro5m_reclaim_requires_vwap.value:
                        reclaim_now &= (micro_df["close"] > micro_df["micro5m_vwap"]).fillna(False)
                    if self.micro5m_reclaim_requires_ema.value:
                        reclaim_now &= (micro_df["close"] > micro_df["micro5m_ema_fast"]).fillna(False)
                    reclaim_now &= body_ratio >= float(self.micro5m_reclaim_body_min.value)
                    reclaim_now &= upper_wick_ratio <= float(self.micro5m_reclaim_upper_wick_max.value)
                    reclaim_now = reclaim_now.fillna(False)
                    reclaim_high_ref = (
                        micro_df["high"].where(reclaim_now, np.nan).shift(1).rolling(follow_lb, min_periods=1).max()
                    )
                    follow_ret_pct = max(
                        float(self.micro5m_followthrough_min_break_pct.value),
                        float(self.micro5m_followthrough_min_ret_bps.value) / 10000.0,
                    )
                    reclaim_recent = (
                        reclaim_now.shift(1).rolling(
                            max(1, int(self.micro5m_followthrough_bars.value)),
                            min_periods=1,
                        ).max() > 0
                    ).fillna(False)
                    higher_high_ref = micro_df["high"].shift(1).rolling(
                        max(1, int(self.micro5m_higher_high_lookback.value)),
                        min_periods=1,
                    ).max()
                    higher_high_ok = pd.Series(True, index=micro_df.index, dtype=bool)
                    if self.micro5m_require_higher_high.value:
                        higher_high_ok &= (micro_df["high"] > higher_high_ref).fillna(False)
                    followthrough_now = (
                        reclaim_recent
                        & (
                            micro_df["close"]
                            > reclaim_high_ref * (1.0 + follow_ret_pct)
                        )
                        & (higher_high_ok if self.micro5m_followthrough_enabled.value else True)
                    ).fillna(False)
                    delayed_entry_signal = pd.Series(False, index=micro_df.index, dtype=bool)
                    expire_now = pd.Series(False, index=micro_df.index, dtype=bool)
                    pending_count = 0
                    expired_count = 0
                    if str(self.micro5m_entry_mode.value) == "impulse_reclaim" and self.micro5m_delayed_followthrough_enabled.value:
                        pending_window = max(1, int(self.micro5m_followthrough_window_bars.value))
                        vwap_confirm_bars = max(1, int(self.micro5m_vwap_confirm_bars.value))
                        reclaim_seq = reclaim_now.astype(int).cumsum()
                        seq_pos = pd.Series(reclaim_seq, index=micro_df.index).groupby(reclaim_seq).cumcount()
                        last_reclaim_high = micro_df["high"].where(reclaim_now, np.nan).ffill()
                        vwap_above = (micro_df["close"] > micro_df["micro5m_vwap"]).fillna(False)
                        vwap_confirm_now = (
                            vwap_above.rolling(vwap_confirm_bars, min_periods=vwap_confirm_bars).sum() >= vwap_confirm_bars
                        ).fillna(False)
                        delayed_entry_signal = (
                            (reclaim_seq > 0)
                            & (seq_pos >= 1)
                            & (seq_pos <= pending_window)
                            & vwap_confirm_now
                            & (
                                micro_df["close"]
                                > last_reclaim_high * (1.0 + follow_ret_pct)
                            )
                            & higher_high_ok
                        ).fillna(False)
                        prior_delayed_hit = (
                            delayed_entry_signal.groupby(reclaim_seq).cummax().shift(1).fillna(False)
                        )
                        expire_now = (
                            (reclaim_seq > 0)
                            & (seq_pos == (pending_window + 1))
                            & (~prior_delayed_hit)
                        ).fillna(False)
                        pending_count = int(reclaim_now.sum())
                        expired_count = int(expire_now.sum())
                    edge_proxy = (
                        (micro_df["close"] - micro_df["micro5m_vwap"])
                        / micro_df["close"].replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan).fillna(0.0)
                    dislocation_pct = (
                        (micro_lower - micro_df["close"]) / micro_df["close"].replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan).clip(lower=0.0, upper=0.02).fillna(0.0)
                    volexp_excess_pct = pd.Series(
                        np.maximum(
                            micro_df["micro5m_atr_ratio"].fillna(0.0),
                            micro_df["micro5m_bb_width_ratio"].fillna(0.0),
                        ) - 1.0,
                        index=micro_df.index,
                    ).clip(lower=0.0, upper=0.05).fillna(0.0)
                    edge_bps_proxy = (10000.0 * ((0.6 * dislocation_pct) + (0.4 * volexp_excess_pct))) - 10.0
                    friction_floor = (
                        float(self.micro5m_fee_rt_floor.value)
                        + float(self.micro5m_slip_haircut.value)
                        + float(self.micro5m_min_edge_over_friction.value)
                    )
                    friction_ok = (
                        (edge_proxy >= friction_floor)
                        & (edge_bps_proxy >= float(self.micro5m_min_edge_over_friction_bps.value))
                    ).fillna(False)
                    mode = str(self.micro5m_entry_mode.value)
                    if mode == "pullback_only":
                        micro_candidate = micro_pullback
                    elif mode == "both":
                        micro_candidate = micro_pullback | micro_breakout
                    elif mode == "impulse_reclaim":
                        if self.micro5m_delayed_followthrough_enabled.value:
                            micro_candidate = delayed_entry_signal
                        else:
                            micro_candidate = followthrough_now
                    else:
                        micro_candidate = micro_breakout
                    atr_pct_5m = (
                        micro_df["micro5m_atr14"] / micro_df["close"].replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan)
                    volexp_strength = (
                        np.maximum(
                            micro_df["micro5m_atr_ratio"].fillna(0.0),
                            micro_df["micro5m_bb_width_ratio"].fillna(0.0),
                        ) - 1.0
                    ) / 0.10
                    volexp_strength = pd.Series(volexp_strength, index=micro_df.index).clip(lower=0.0, upper=1.0).fillna(0.0)
                    rel_vol_score = ((micro_df["micro5m_rel_vol"] - 1.0) / 1.5).clip(lower=0.0, upper=1.0).fillna(0.0)
                    dislocation = (
                        (micro_lower - micro_df["close"]) / micro_df["close"].replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan)
                    dislocation = dislocation.clip(lower=0.0, upper=0.02).fillna(0.0) / 0.02
                    momo = (
                        micro_df["micro5m_ret1"] / atr_pct_5m.replace(0, np.nan)
                    ).replace([np.inf, -np.inf], np.nan)
                    momo = (momo / 2.0).clip(lower=0.0, upper=1.0).fillna(0.0)
                    micro_df["micro5m_dislocation"] = dislocation
                    micro_df["micro5m_momo"] = momo
                    micro_df["micro5m_impulse_signal"] = impulse_signal.astype(bool)
                    micro_df["micro5m_reclaim_signal"] = reclaim_now.astype(bool)
                    micro_df["micro5m_followthrough_signal"] = followthrough_now.astype(bool)
                    micro_df["micro5m_delayed_entry_signal"] = delayed_entry_signal.astype(bool)
                    micro_df["micro5m_friction_ok"] = friction_ok.astype(bool)
                    micro_df["micro5m_edge_proxy"] = edge_proxy
                    micro_df["micro5m_edge_proxy_bps"] = edge_bps_proxy
                    micro_df["micro5m_score"] = (
                        (0.35 * volexp_strength)
                        + (0.25 * rel_vol_score)
                        + (0.25 * dislocation)
                        + (0.15 * momo)
                    ).clip(0.0, 1.0)
                    micro_df["micro5m_pullback_signal"] = micro_pullback.astype(bool)
                    micro_df["micro5m_breakout_signal"] = micro_breakout.astype(bool)
                    micro_df["micro5m_signal"] = micro_candidate.astype(bool)
                    score_raw_mask = micro_candidate.astype(bool)
                    if bool(score_raw_mask.any()):
                        score_vals = micro_df.loc[score_raw_mask, "micro5m_score"].astype(float)
                        score_p10 = float(score_vals.quantile(0.10))
                        score_p50 = float(score_vals.quantile(0.50))
                        score_p90 = float(score_vals.quantile(0.90))
                        score_max = float(score_vals.max())
                    else:
                        score_p10 = score_p50 = score_p90 = score_max = 0.0
                    if mode == "impulse_reclaim":
                        raw_count = int(impulse_recent.sum())
                        volexp_count = int((impulse_recent & micro_df["micro5m_volexp_pass"].astype(bool)).sum())
                        impulse_count = int(impulse_signal.sum())
                        reclaim_count = int(reclaim_now.sum())
                        follow_count = int(followthrough_now.sum())
                        friction_count = int((followthrough_now & friction_ok).sum())
                    else:
                        raw_count = int(micro_candidate.sum())
                        volexp_count = int((micro_candidate & micro_df["micro5m_volexp_pass"].astype(bool)).sum())
                        impulse_count = 0
                        reclaim_count = 0
                        follow_count = 0
                        friction_count = 0
                    self._micro5m_pair_funnel_stats[pair] = {
                        "raw": float(raw_count),
                        "volexp": float(volexp_count),
                        "impulse": float(impulse_count),
                        "reclaim": float(reclaim_count),
                            "follow": float(follow_count),
                            "friction": float(friction_count),
                            "pending": float(pending_count),
                            "expired": float(expired_count),
                            "score_p10": score_p10,
                            "score_p50": score_p50,
                            "score_p90": score_p90,
                        "score_max": score_max,
                    }
                    micro_dates = pd.to_datetime(micro_df["date"], utc=True)
                    micro_df["micro_hour"] = (micro_dates + pd.Timedelta(minutes=5)).dt.floor("1h")
                    agg = (
                        micro_df.groupby("micro_hour", sort=True)
                        .agg(
                            micro5m_pullback_signal=("micro5m_pullback_signal", "max"),
                            micro5m_breakout_signal=("micro5m_breakout_signal", "max"),
                            micro5m_signal=("micro5m_signal", "max"),
                            micro5m_rel_vol=("micro5m_rel_vol", "last"),
                            micro5m_bb_width=("micro5m_bb_width", "last"),
                            micro5m_bb_width_ratio=("micro5m_bb_width_ratio", "last"),
                            micro5m_atr_ratio=("micro5m_atr_ratio", "last"),
                            micro5m_volexp_pass=("micro5m_volexp_pass", "last"),
                            micro5m_trend_bias=("micro5m_trend_bias", "last"),
                            micro5m_confirm_pass=("micro5m_confirm_pass", "last"),
                            micro5m_impulse_signal=("micro5m_impulse_signal", "max"),
                            micro5m_reclaim_signal=("micro5m_reclaim_signal", "max"),
                            micro5m_followthrough_signal=("micro5m_followthrough_signal", "max"),
                            micro5m_delayed_entry_signal=("micro5m_delayed_entry_signal", "max"),
                            micro5m_friction_ok=("micro5m_friction_ok", "last"),
                            micro5m_score=("micro5m_score", "max"),
                            micro5m_dislocation=("micro5m_dislocation", "max"),
                            micro5m_momo=("micro5m_momo", "last"),
                            micro5m_edge_proxy=("micro5m_edge_proxy", "max"),
                            micro5m_edge_proxy_bps=("micro5m_edge_proxy_bps", "max"),
                            e0v1e5m_signal=("e0v1e5m_signal", "max"),
                            e0v1e5m_signal_ewo=("e0v1e5m_signal_ewo", "max"),
                            e0v1e5m_signal_buy_1=("e0v1e5m_signal_buy_1", "max"),
                            e0v1e5m_close=("e0v1e5m_close", "last"),
                            e0v1e5m_fastk=("e0v1e5m_fastk", "last"),
                            e0v1e5m_bb_width=("e0v1e5m_bb_width", "last"),
                            e0v1e5m_bb_middleband2=("e0v1e5m_bb_middleband2", "last"),
                            e0v1e5m_volume_mean_12=("e0v1e5m_volume_mean_12", "last"),
                            e0v1e5m_volume_mean_24=("e0v1e5m_volume_mean_24", "last"),
                        )
                        .reset_index()
                        .rename(columns={"micro_hour": "date"})
                    )
                    agg["date"] = pd.to_datetime(agg["date"], utc=True)
                    base_dates = pd.to_datetime(dataframe["date"], utc=True)
                    dataframe = dataframe.copy()
                    dataframe["date"] = base_dates
                    dataframe = pd.merge(dataframe, agg, on="date", how="left", suffixes=("", "_microdup"))
                    for col in (
                        "micro5m_pullback_signal",
                        "micro5m_breakout_signal",
                        "micro5m_signal",
                        "micro5m_rel_vol",
                        "micro5m_bb_width",
                        "micro5m_bb_width_ratio",
                        "micro5m_atr_ratio",
                        "micro5m_volexp_pass",
                        "micro5m_trend_bias",
                        "micro5m_confirm_pass",
                        "micro5m_impulse_signal",
                        "micro5m_reclaim_signal",
                        "micro5m_followthrough_signal",
                        "micro5m_delayed_entry_signal",
                        "micro5m_friction_ok",
                        "micro5m_score",
                        "micro5m_dislocation",
                        "micro5m_momo",
                        "micro5m_edge_proxy",
                        "micro5m_edge_proxy_bps",
                        "e0v1e5m_signal",
                        "e0v1e5m_signal_ewo",
                        "e0v1e5m_signal_buy_1",
                        "e0v1e5m_close",
                        "e0v1e5m_fastk",
                        "e0v1e5m_bb_width",
                        "e0v1e5m_bb_middleband2",
                        "e0v1e5m_volume_mean_12",
                        "e0v1e5m_volume_mean_24",
                    ):
                        dup_col = f"{col}_microdup"
                        if dup_col in dataframe.columns:
                            dataframe[col] = dataframe[dup_col]
                            dataframe.drop(columns=[dup_col], inplace=True)
                    for col in (
                        "micro5m_pullback_signal",
                        "micro5m_breakout_signal",
                        "micro5m_signal",
                        "micro5m_volexp_pass",
                        "micro5m_trend_bias",
                        "micro5m_confirm_pass",
                        "micro5m_impulse_signal",
                        "micro5m_reclaim_signal",
                        "micro5m_followthrough_signal",
                        "micro5m_delayed_entry_signal",
                        "micro5m_friction_ok",
                        "e0v1e5m_signal",
                        "e0v1e5m_signal_ewo",
                        "e0v1e5m_signal_buy_1",
                    ):
                        dataframe[col] = dataframe[col].fillna(False).astype(bool)
                    for col in (
                        "micro5m_rel_vol",
                        "micro5m_bb_width",
                        "micro5m_bb_width_ratio",
                        "micro5m_atr_ratio",
                        "micro5m_score",
                        "micro5m_dislocation",
                        "micro5m_momo",
                        "micro5m_edge_proxy",
                        "micro5m_edge_proxy_bps",
                        "e0v1e5m_close",
                        "e0v1e5m_fastk",
                        "e0v1e5m_bb_width",
                        "e0v1e5m_bb_middleband2",
                        "e0v1e5m_volume_mean_12",
                        "e0v1e5m_volume_mean_24",
                    ):
                        dataframe[col] = pd.to_numeric(dataframe[col], errors="coerce").fillna(0.0)
                except Exception:
                    pass

        # ── Shared meta architecture indicators (all past/current-bar only) ──
        try:
            dataframe["meta_atr14"] = ta.ATR(dataframe, timeperiod=14)
            dataframe["meta_ema21"] = ta.EMA(dataframe, timeperiod=21)
            _meta_close = pd.to_numeric(dataframe.get("close", pd.Series(np.nan, index=dataframe.index)), errors="coerce")
            _meta_atr = pd.to_numeric(dataframe.get("meta_atr14", pd.Series(np.nan, index=dataframe.index)), errors="coerce")
            dataframe["meta_ret_1h"] = _meta_close.pct_change(1).replace([np.inf, -np.inf], np.nan).fillna(0.0)
            dataframe["meta_ret_4h"] = _meta_close.pct_change(4).replace([np.inf, -np.inf], np.nan).fillna(0.0)
            _meta_atrp = (_meta_atr / _meta_close.replace(0.0, np.nan)).replace([np.inf, -np.inf], np.nan)
            dataframe["meta_atrp"] = _meta_atrp.fillna(0.0)
            _meta_atrp_ema = _meta_atrp.ewm(span=20, adjust=False).mean()
            _meta_atrp_std = _meta_atrp.rolling(20, min_periods=10).std()
            dataframe["meta_vov_z"] = (
                (_meta_atrp - _meta_atrp_ema) / _meta_atrp_std.replace(0.0, np.nan)
            ).replace([np.inf, -np.inf], np.nan).fillna(0.0)

            _meta_dir = (_meta_close - _meta_close.shift(16)).abs()
            _meta_path = _meta_close.diff().abs().rolling(16, min_periods=16).sum()
            dataframe["meta_er_16"] = (
                _meta_dir / _meta_path.replace(0.0, np.nan)
            ).clip(lower=0.0, upper=1.0).replace([np.inf, -np.inf], np.nan).fillna(0.0)

            _meta_anchor = pd.to_numeric(
                dataframe.get("trendpb_ema_fast", dataframe.get("meta_ema21", pd.Series(np.nan, index=dataframe.index))),
                errors="coerce",
            )
            dataframe["meta_chase_atr"] = (
                (_meta_close - _meta_anchor).abs() / _meta_atr.replace(0.0, np.nan)
            ).replace([np.inf, -np.inf], np.nan).fillna(0.0)

            _meta_regime_primary = (
                dataframe.get("composite_regime", pd.Series("", index=dataframe.index))
                .fillna("")
                .astype(str)
                .map(self._regime_primary_token)
            )
            dataframe["meta_regime_primary"] = _meta_regime_primary
            _meta_flip = _meta_regime_primary.ne(_meta_regime_primary.shift(1)).fillna(True)
            _meta_groups = _meta_flip.cumsum()
            dataframe["meta_regime_bars_since_flip"] = (
                _meta_groups.groupby(_meta_groups).cumcount().fillna(0).astype(int)
            )
        except Exception:
            pass

        # ── External feature pack v1 (Fear&Greed / DXY), fail-open ──
        try:
            self._load_external_feature_pack_if_needed()
            if self._extpack_by_date:
                dt_series = pd.to_datetime(dataframe.get("date", pd.Series(index=dataframe.index)), utc=True, errors="coerce")
                date_keys = dt_series.dt.strftime("%Y-%m-%d").fillna("")
                fng_map = {k: float(v.get("fng", np.nan)) for k, v in self._extpack_by_date.items()}
                dxy_map = {k: float(v.get("dxy", np.nan)) for k, v in self._extpack_by_date.items()}
                dxy_r_map = {k: float(v.get("dxy_ret_1d", np.nan)) for k, v in self._extpack_by_date.items()}
                dataframe["ext_fng"] = date_keys.map(fng_map).astype(float)
                dataframe["ext_dxy"] = date_keys.map(dxy_map).astype(float)
                dataframe["ext_dxy_ret_1d"] = date_keys.map(dxy_r_map).astype(float)
            else:
                dataframe["ext_fng"] = np.nan
                dataframe["ext_dxy"] = np.nan
                dataframe["ext_dxy_ret_1d"] = np.nan
        except Exception:
            dataframe["ext_fng"] = np.nan
            dataframe["ext_dxy"] = np.nan
            dataframe["ext_dxy_ret_1d"] = np.nan

        # ── C v2 observability: plot flag for charting (stays 0 in backtest) ──
        dataframe["bearvol_throttle_active"] = 0

        return dataframe

    # ══════════════════════════════════════════════════════════
    # Tag-based helpers (Enhancement #1)
    # ══════════════════════════════════════════════════════════

    def _tag_bucket(self, entry_tag: str | None) -> str:
        """Map entry_tag to a sizing bucket."""
        t = (entry_tag or "").lower()
        if t.startswith("cvmr_"):
            return "cvmr"
        if t.startswith("tes_"):
            return "tes"
        if t.startswith("apc_"):
            return "apc"
        if t.startswith("sbr_"):
            return "sbr"
        if t.startswith("spreadarb_"):
            return "spreadarb"
        if t.startswith("cpdf_"):
            return "cpdf"
        if t.startswith("fcarry_"):
            return "fcarry"
        if t.startswith("cvw_"):
            return "cvw"
        if t.startswith("mofi_"):
            return "mofi"
        if t.startswith("fimr_"):
            return "fimr"
        if t.startswith("liqcascade_v2_"):
            return "liqcascade_v2"
        if t.startswith("liqcascade_"):
            return "liqcascade"
        if t.startswith("xresmom_"):
            return "xresmom"
        if t.startswith("xidiorev_"):
            return "xidiorev"
        if t.startswith("xmacrohour_"):
            return "xmacrohour"
        if t.startswith("xleadrot_"):
            return "xleadrot"
        if t.startswith("xquietbreak_"):
            return "xquietbreak"
        if t.startswith("rmom_"):
            return "rmom"
        if t.startswith("tsmom_"):
            return "tsmom"
        if t.startswith("trendxs_"):
            return "trendxs"
        if t.startswith("stoploss_"):
            return "stoploss"
        if t.startswith("idle_fr_"):
            return "idle_fr"
        if "micro_alpha_5m" in t:
            return "micro5m"
        if t.startswith("idle_"):
            return "idle"
        if "panic" in t:
            return "panic"
        if "volex" in t:
            return "veb"
        if "veb" in t:
            return "veb"
        if "mr_long" in t:
            return "mr_long"
        if "cbx" in t:
            return "cbx"
        if "brf" in t:
            return "brf_short"
        if "bearvol" in t:
            return "bearvol_short"
        if "trbk" in t and "short" in t:
            return "trbk_short"
        if "trbk" in t:
            return "trbk"
        if "trend_pullback" in t:
            return "trendpb"
        return "other"

    def _sleeve_key_from_tag(self, entry_tag: str | None) -> str:
        t = (entry_tag or "").lower()
        if self._is_cvmr_entry_tag(t):
            return "mean_reversion"
        if self._is_tes_entry_tag(t):
            return "convex"
        if self._is_apc_entry_tag(t):
            return "trend"
        if self._is_sbr_entry_tag(t):
            return "trend"
        if self._is_spreadarb_entry_tag(t):
            return "spreadarb"
        if self._is_cpdf_entry_tag(t):
            return "cpdf"
        if self._is_fcarry_entry_tag(t):
            return "fcarry"
        if self._is_cvw_entry_tag(t):
            return "mean_reversion"
        if self._is_mofi_entry_tag(t):
            return "microstructure"
        if self._is_evtpulse_entry_tag(t):
            return "event_pulse"
        if self._is_lagcatch_entry_tag(t):
            return "leadlag"
        if self._is_fimr_entry_tag(t):
            return "fimr"
        if t.startswith("rmom_"):
            return "srr"
        if t.startswith("tsmom_"):
            return "srr"
        if t.startswith("trendxs_"):
            return "srr"
        if t.startswith("stoploss_"):
            return "srr"
        if self._is_e0v1e5m_entry_tag(t):
            return "e0v1e_5m"
        if self._is_liqcascade_v2_entry_tag(t):
            return "liqcascade_v2"
        if self._is_liqcascade_entry_tag(t):
            return "liqcascade"
        if self._is_idle_fr_entry_tag(t):
            return "idle_fr"
        if self._is_idle_entry_tag(t):
            return "idle"
        if "micro_alpha_5m" in t:
            return "micro_alpha_5m"
        if "bearvol" in t:
            return "bearvol"
        if "convex" in t:
            return "convex"
        if "mr_long" in t:
            return "mean_reversion"
        if "trend_pullback" in t or t.startswith("trendpb"):
            return "trendpb"
        if "trbk" in t or "panic" in t or "veb" in t or "volex" in t or "cbx" in t or "brf" in t:
            return "trend"
        return "other"

    def _pair_sleeve_recent_stats(self, pair: str, entry_tag: str | None) -> dict[str, float]:
        if not pair:
            return {"n": 0.0, "expectancy_pct": 0.0, "loss_count": 0.0}
        sleeve = self._sleeve_key_from_tag(entry_tag)
        recent = self._pair_sleeve_edge_stats.get((pair, sleeve), [])
        lookback = max(1, int(self.pair_sleeve_edge_lookback_trades.value))
        recent = recent[-lookback:]
        n = len(recent)
        if n == 0:
            return {"n": 0.0, "expectancy_pct": 0.0, "loss_count": 0.0}
        exp_pct = float(sum(float(p) for _, p in recent)) / float(n)
        loss_count = float(sum(1 for _, p in recent if float(p) < 0.0))
        return {"n": float(n), "expectancy_pct": exp_pct, "loss_count": loss_count}

    @staticmethod
    def _feature_tag_allowlist_allows(
        entry_tag: str | None,
        allow_csv: str | None,
        exact_key: str | None = None,
        bucket_key: str | None = None,
        sleeve_key: str | None = None,
    ) -> bool:
        allow = {x.strip().lower() for x in str(allow_csv or "").split(",") if x and x.strip()}
        if not allow:
            return True
        keys = {
            str(exact_key or "").lower(),
            str(bucket_key or "").lower(),
            str(sleeve_key or "").lower(),
        }
        return any(k and k in allow for k in keys)

    def _spa_scope_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.buy_spa_enabled.value):
            return False
        if bool(self.buy_spa_apply_aux_only.value) and not self._is_auxiliary_entry_tag(entry_tag):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_spa_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _research_bucket_inc(self, key: str) -> None:
        try:
            self._research_bucket_counts[str(key)] = int(self._research_bucket_counts.get(str(key), 0)) + 1
        except Exception:
            pass

    def research_bucket_counts_snapshot(self) -> dict[str, int]:
        try:
            return dict(self._research_bucket_counts)
        except Exception:
            return {}

    def _research_bucket_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.buy_research_bucket_enabled.value):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_research_bucket_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _research_bucket_bypass_set(self) -> set[str]:
        return {
            x.strip().lower()
            for x in str(self.buy_research_bucket_bypass_csv.value or "").split(",")
            if x and x.strip()
        }

    def _research_bucket_should_bypass(self, gate_name: str, entry_tag: str | None) -> bool:
        if not self._research_bucket_applies(entry_tag):
            return False
        return str(gate_name or "").strip().lower() in self._research_bucket_bypass_set()

    def _research_bucket_open_positions_count(self) -> int:
        n = 0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._research_bucket_applies(tag):
                n += 1
        return n

    def _research_bucket_wallet_total(self) -> float:
        try:
            wallets = getattr(self, "wallets", None)
            if wallets is not None:
                total = wallets.get_total_stake_amount()
                total_f = float(total)
                if np.isfinite(total_f) and total_f > 0:
                    return total_f
        except Exception:
            pass
        wallet = self._parse_numeric(self.config.get("dry_run_wallet", None))
        if wallet is None or wallet <= 0:
            wallet = 1000.0
        return float(wallet)

    def _research_bucket_available_cap(self) -> float:
        wallet_total = self._research_bucket_wallet_total()
        open_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._research_bucket_applies(tag):
                open_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        cap = wallet_total * float(self.buy_research_bucket_wallet_cap_pct.value)
        return max(0.0, cap - open_exposure)

