    def spa_counts_snapshot(self) -> dict[str, float]:
        try:
            return {str(k): float(v) for k, v in self._spa_counts.items()}
        except Exception:
            return {}

    def _spa_recent_returns_pct(self, pair: str, entry_tag: str | None) -> list[float]:
        if not pair:
            return []
        sleeve = self._reg_alloc_sleeve_from_tag(entry_tag)
        recent = self._pair_exact_sleeve_stats.get((pair, sleeve), [])
        lookback = max(1, int(self.buy_spa_lookback_trades.value))
        clip_pct = max(0.1, float(self.buy_spa_edge_clip_pct.value))
        vals = [float(np.clip(float(p), -clip_pct, clip_pct)) for _, p in recent[-lookback:]]
        return [float(v) for v in vals if np.isfinite(v)]

    def _spa_prior_returns_pct(self, entry_tag: str | None) -> list[float]:
        sleeve = self._reg_alloc_sleeve_from_tag(entry_tag)
        lookback = max(1, int(self.buy_spa_lookback_trades.value))
        clip_pct = max(0.1, float(self.buy_spa_edge_clip_pct.value))
        prior = self._reg_alloc_recent_returns(sleeve, max(lookback * 3, lookback))
        vals = [float(np.clip(float(x) * 100.0, -clip_pct, clip_pct)) for x in prior]
        return [float(v) for v in vals if np.isfinite(v)]

    def _spa_mult(self, pair: str, entry_tag: str | None) -> tuple[float, dict[str, float | str]]:
        if not self._spa_scope_applies(entry_tag):
            return 1.0, {"reason": "disabled_or_scope"}

        self._spa_counts["calls"] = float(self._spa_counts.get("calls", 0.0)) + 1.0
        pair_vals = self._spa_recent_returns_pct(pair, entry_tag)
        n = len(pair_vals)
        min_trades = max(1, int(self.buy_spa_min_trades.value))
        if n < min_trades:
            self._spa_counts["warmup"] = float(self._spa_counts.get("warmup", 0.0)) + 1.0
            return 1.0, {"reason": "warmup", "n": float(n)}

        prior_vals = self._spa_prior_returns_pct(entry_tag)
        if prior_vals:
            prior_mu = float(np.mean(prior_vals))
            prior_wr = float(sum(1 for x in prior_vals if x > 0.0)) / float(len(prior_vals))
        else:
            prior_mu = 0.0
            prior_wr = 0.5
            self._spa_counts["fallback"] = float(self._spa_counts.get("fallback", 0.0)) + 1.0

        pair_mu = float(np.mean(pair_vals))
        pair_wr = float(sum(1 for x in pair_vals if x > 0.0)) / float(max(1, len(pair_vals)))
        shrink = max(0.0, float(self.buy_spa_shrink_strength.value))
        prior_weight = max(0.0, shrink * float(min_trades))
        conf = float(n) / max(1e-9, float(n) + prior_weight)
        post_mu = conf * pair_mu + (1.0 - conf) * prior_mu
        post_wr = conf * pair_wr + (1.0 - conf) * prior_wr

        clip_pct = max(0.1, float(self.buy_spa_edge_clip_pct.value))
        edge_score = float(np.clip(post_mu / clip_pct, -1.0, 1.0))
        wr_score = float(np.clip((post_wr - 0.5) / 0.5, -1.0, 1.0))
        raw = (
            1.0
            + float(self.buy_spa_edge_scale.value) * edge_score
            + float(self.buy_spa_winrate_scale.value) * wr_score
        )
        floor = float(self.buy_spa_floor.value)
        ceiling = float(self.buy_spa_ceiling.value)
        mult = float(np.clip(raw, floor, ceiling))

        self._spa_counts["applied"] = float(self._spa_counts.get("applied", 0.0)) + 1.0
        self._spa_counts["mult_sum"] = float(self._spa_counts.get("mult_sum", 0.0)) + float(mult)
        if abs(mult - floor) < 1e-9:
            self._spa_counts["floor_hits"] = float(self._spa_counts.get("floor_hits", 0.0)) + 1.0
        if abs(mult - ceiling) < 1e-9:
            self._spa_counts["ceiling_hits"] = float(self._spa_counts.get("ceiling_hits", 0.0)) + 1.0
        return mult, {
            "reason": "pass",
            "n": float(n),
            "pair_mu_pct": float(pair_mu),
            "pair_wr": float(pair_wr),
            "prior_mu_pct": float(prior_mu),
            "prior_wr": float(prior_wr),
            "posterior_mu_pct": float(post_mu),
            "posterior_wr": float(post_wr),
            "mult": float(mult),
            "conf": float(conf),
        }

    def _spa_gate_allows(self, pair: str, entry_tag: str | None) -> tuple[bool, str, dict[str, float | str]]:
        mult, details = self._spa_mult(pair, entry_tag)
        if not bool(self.buy_spa_enabled.value):
            return True, "disabled", details
        if not self._spa_scope_applies(entry_tag):
            return True, "scope_skip", details
        if int(float(details.get("n", 0.0) or 0.0)) < int(self.buy_spa_min_trades.value):
            return True, "warmup", details
        if bool(self.buy_spa_block_if_below.value) and float(mult) < float(self.buy_spa_block_threshold.value):
            self._spa_counts["entry_blocks"] = float(self._spa_counts.get("entry_blocks", 0.0)) + 1.0
            return False, "mult_below_threshold", details
        return True, "pass", details

    def _pair_sleeve_rank_penalty(self, pair: str, entry_tag: str | None) -> float:
        if not self.pair_sleeve_edge_enabled.value:
            return 0.0
        stats = self._pair_sleeve_recent_stats(pair, entry_tag)
        if int(stats["n"]) < int(self.pair_sleeve_edge_min_trades.value):
            return 0.0
        penalty = 0.0
        if float(stats["expectancy_pct"]) < float(self.pair_sleeve_edge_min_expectancy_pct.value):
            penalty += float(self.pair_sleeve_edge_rank_penalty.value)
        if int(stats["loss_count"]) >= int(self.pair_sleeve_edge_recent_loss_limit.value):
            penalty += float(self.pair_sleeve_edge_rank_penalty.value)
        return float(penalty)

    def _pair_sleeve_hard_block(self, pair: str, entry_tag: str | None) -> bool:
        if not self.pair_sleeve_edge_enabled.value or not self.pair_sleeve_edge_hard_block_enabled.value:
            return False
        stats = self._pair_sleeve_recent_stats(pair, entry_tag)
        blocked = (
            int(stats["n"]) >= int(self.pair_sleeve_edge_min_trades.value)
            and float(stats["expectancy_pct"]) < float(self.pair_sleeve_edge_min_expectancy_pct.value)
            and int(stats["loss_count"]) >= int(self.pair_sleeve_edge_recent_loss_limit.value)
        )
        if blocked and self.pair_sleeve_edge_debug.value:
            logger.info(
                "PAIR_SLEEVE_BLOCK pair=%s sleeve=%s n=%s expectancy_pct=%.3f losses=%s",
                pair,
                self._sleeve_key_from_tag(entry_tag),
                int(stats["n"]),
                float(stats["expectancy_pct"]),
                int(stats["loss_count"]),
            )
        return bool(blocked)

    def _trendpb_dynrel_inc(self, key: str) -> None:
        try:
            self._trendpb_dynrel_counts[str(key)] = int(self._trendpb_dynrel_counts.get(str(key), 0)) + 1
        except Exception:
            pass

    def trendpb_dynrel_counts_snapshot(self) -> dict[str, int]:
        try:
            return dict(self._trendpb_dynrel_counts)
        except Exception:
            return {}

    def _trendpb_pair_recent_stats(self, pair: str) -> dict[str, float]:
        if not pair:
            return {"n": 0.0, "expectancy_pct": 0.0, "loss_count": 0.0, "winrate_pct": 0.0}
        recent = self._trendpb_pair_stats.get(pair, [])
        lookback = max(1, int(self.buy_trendpb_dynrel_lookback_trades.value))
        recent = recent[-lookback:]
        n = len(recent)
        if n <= 0:
            return {"n": 0.0, "expectancy_pct": 0.0, "loss_count": 0.0, "winrate_pct": 0.0}
        exp_pct = float(sum(float(p) for _, p in recent)) / float(n)
        loss_count = float(sum(1 for _, p in recent if float(p) < 0.0))
        winrate_pct = float(sum(1 for _, p in recent if float(p) > 0.0)) * 100.0 / float(n)
        return {"n": float(n), "expectancy_pct": exp_pct, "loss_count": loss_count, "winrate_pct": winrate_pct}

    @staticmethod
    def _trendpb_is_failure_reason(reason: str | None) -> tuple[bool, bool]:
        reason_l = str(reason or "").lower()
        is_stoploss = ("stop_loss" in reason_l) or ("stoploss" in reason_l)
        is_failure = bool(
            is_stoploss
            or ("no_followthrough" in reason_l)
            or ("no_proof" in reason_l)
            or ("liquidation" in reason_l)
        )
        return is_failure, is_stoploss

    def _trendpb_recent_outcomes(
        self,
        pair: str | None = None,
        lookback: int | None = None,
    ) -> list[dict[str, Any]]:
        if pair:
            src = self._trendpb_outcome_by_pair.get(pair, deque())
        else:
            src = self._trendpb_outcome_history
        rows = list(src)
        if lookback is None:
            return rows
        n = max(0, int(lookback))
        if n <= 0:
            return rows
        return rows[-n:]

    def _trendpb_pair_health_stats(self, pair: str) -> dict[str, float]:
        if not pair:
            return {
                "n": 0.0,
                "expectancy_pct": 0.0,
                "fail_rate": 0.0,
                "avg_adverse_pct": 0.0,
                "stoploss_streak": 0.0,
            }
        lookback = max(1, int(self.buy_trendpb_pair_health_lookback_trades.value))
        rows = self._trendpb_recent_outcomes(pair=pair, lookback=lookback)
        n = len(rows)
        if n <= 0:
            return {
                "n": 0.0,
                "expectancy_pct": 0.0,
                "fail_rate": 0.0,
                "avg_adverse_pct": 0.0,
                "stoploss_streak": 0.0,
            }
        exp_pct = float(sum(float(r.get("profit_pct", 0.0) or 0.0) for r in rows)) / float(n)
        fail_count = int(sum(1 for r in rows if bool(r.get("is_failure", False))))
        fail_rate = float(fail_count) / float(n)
        avg_adverse = float(sum(float(r.get("adverse_pct", 0.0) or 0.0) for r in rows)) / float(n)
        sl_streak = 0
        for r in reversed(rows):
            if bool(r.get("is_stoploss", False)):
                sl_streak += 1
            else:
                break
        return {
            "n": float(n),
            "expectancy_pct": float(exp_pct),
            "fail_rate": float(fail_rate),
            "avg_adverse_pct": float(avg_adverse),
            "stoploss_streak": float(sl_streak),
        }

    def _trendpb_pair_health_rank_penalty(self, pair: str, entry_tag: str | None) -> float:
        if not bool(self.buy_trendpb_pair_health_enabled.value):
            return 0.0
        if not pair:
            return 0.0
        if not str(entry_tag or "").startswith("trend_pullback_v1"):
            return 0.0

        self._trendpb_pair_health_counts["checked"] = int(self._trendpb_pair_health_counts.get("checked", 0)) + 1
        stats = self._trendpb_pair_health_stats(pair)
        n = int(float(stats.get("n", 0.0) or 0.0))
        min_n = int(self.buy_trendpb_pair_health_min_trades.value)
        if n < min_n:
            self._trendpb_pair_health_counts["warmup"] = int(self._trendpb_pair_health_counts.get("warmup", 0)) + 1
            return 0.0

        penalty_unit = float(self.buy_trendpb_pair_health_rank_penalty.value)
        triggers = 0
        if float(stats.get("expectancy_pct", 0.0) or 0.0) < float(self.buy_trendpb_pair_health_min_expectancy_pct.value):
            triggers += 1
        if int(float(stats.get("stoploss_streak", 0.0) or 0.0)) >= int(self.buy_trendpb_pair_health_stoploss_streak_limit.value):
            triggers += 1
        if float(stats.get("avg_adverse_pct", 0.0) or 0.0) > float(self.buy_trendpb_pair_health_max_avg_adverse_pct.value):
            triggers += 1
        if float(stats.get("fail_rate", 0.0) or 0.0) > float(self.buy_trendpb_pair_health_fail_rate_limit.value):
            triggers += 1

        if triggers <= 0:
            self._trendpb_pair_health_counts["pass"] = int(self._trendpb_pair_health_counts.get("pass", 0)) + 1
            return 0.0

        self._trendpb_pair_health_counts["rank_penalty_hits"] = int(self._trendpb_pair_health_counts.get("rank_penalty_hits", 0)) + 1
        # Keep penalty bounded so ranking remains discriminatory instead of binary.
        return float(min(1.0, penalty_unit * float(triggers)))

    def _trendpb_pair_health_hard_block(self, pair: str, entry_tag: str | None) -> tuple[bool, str, dict[str, float]]:
        stats = self._trendpb_pair_health_stats(pair)
        if not bool(self.buy_trendpb_pair_health_enabled.value):
            return True, "disabled", stats
        if not bool(self.buy_trendpb_pair_health_hard_block_enabled.value):
            return True, "soft_only", stats
        if not str(entry_tag or "").startswith("trend_pullback_v1"):
            return True, "tag_skip", stats

        n = int(float(stats.get("n", 0.0) or 0.0))
        min_n = int(self.buy_trendpb_pair_health_min_trades.value)
        if n < min_n:
            self._trendpb_pair_health_counts["warmup"] = int(self._trendpb_pair_health_counts.get("warmup", 0)) + 1
            return True, "warmup", stats

        reasons: list[str] = []
        if float(stats.get("expectancy_pct", 0.0) or 0.0) < float(self.buy_trendpb_pair_health_min_expectancy_pct.value):
            reasons.append("expectancy")
        if int(float(stats.get("stoploss_streak", 0.0) or 0.0)) >= int(self.buy_trendpb_pair_health_stoploss_streak_limit.value):
            reasons.append("stoploss_streak")
        if float(stats.get("avg_adverse_pct", 0.0) or 0.0) > float(self.buy_trendpb_pair_health_max_avg_adverse_pct.value):
            reasons.append("adverse")
        if float(stats.get("fail_rate", 0.0) or 0.0) > float(self.buy_trendpb_pair_health_fail_rate_limit.value):
            reasons.append("fail_rate")

        block_min = max(1, int(self.buy_trendpb_pair_health_block_score_min.value))
        if len(reasons) >= block_min:
            self._trendpb_pair_health_counts["hard_block"] = int(self._trendpb_pair_health_counts.get("hard_block", 0)) + 1
            return False, ("combo" if len(reasons) > 1 else reasons[0]), stats
        return True, "pass", stats

    def _trendpb_adaptive_quality_state(self) -> dict[str, float]:
        lookback = max(1, int(self.buy_trendpb_adq_lookback_trades.value))
        rows = self._trendpb_recent_outcomes(pair=None, lookback=lookback)
        n = len(rows)
        if n <= 0:
            return {"n": 0.0, "fail_rate": 0.0, "expectancy_pct": 0.0, "strict_mode": 0.0}
        exp_pct = float(sum(float(r.get("profit_pct", 0.0) or 0.0) for r in rows)) / float(n)
        fail_rate = float(sum(1 for r in rows if bool(r.get("is_failure", False)))) / float(n)
        strict_mode = 0.0
        if n >= int(self.buy_trendpb_adq_min_trades.value):
            if (
                fail_rate >= float(self.buy_trendpb_adq_fail_rate_trigger.value)
                or exp_pct < float(self.buy_trendpb_adq_expectancy_floor_pct.value)
            ):
                strict_mode = 1.0
        return {
            "n": float(n),
            "fail_rate": float(fail_rate),
            "expectancy_pct": float(exp_pct),
            "strict_mode": float(strict_mode),
        }

    def _trendpb_adaptive_quality_allows(
        self,
        pair: str,
        row: pd.Series | None,
        entry_tag: str | None,
    ) -> tuple[bool, str, dict[str, float]]:
        stats = self._trendpb_adaptive_quality_state()
        if not bool(self.buy_trendpb_adaptive_quality_enabled.value):
            return True, "disabled", stats
        if not str(entry_tag or "").startswith("trend_pullback_v1"):
            return True, "tag_skip", stats
        self._trendpb_adq_counts["checked"] = int(self._trendpb_adq_counts.get("checked", 0)) + 1
        if int(float(stats.get("n", 0.0) or 0.0)) < int(self.buy_trendpb_adq_min_trades.value):
            self._trendpb_adq_counts["warmup"] = int(self._trendpb_adq_counts.get("warmup", 0)) + 1
            return True, "warmup", stats
        if float(stats.get("strict_mode", 0.0) or 0.0) <= 0.0:
            self._trendpb_adq_counts["pass"] = int(self._trendpb_adq_counts.get("pass", 0)) + 1
            return True, "pass", stats

        self._trendpb_adq_counts["strict_on"] = int(self._trendpb_adq_counts.get("strict_on", 0)) + 1
        if row is None:
            return True, "no_row", stats

        reasons: list[str] = []
        try:
            confbar_min = float(self.buy_trendpb_adq_confbar_bull_min.value)
            if confbar_min > 0:
                open_ = float(row.get("open", float("nan")))
                close_ = float(row.get("close", float("nan")))
                high_ = float(row.get("high", float("nan")))
                low_ = float(row.get("low", float("nan")))
                if np.isfinite(open_) and np.isfinite(close_) and np.isfinite(high_) and np.isfinite(low_) and high_ > low_:
                    body_ratio = (close_ - open_) / max(high_ - low_, 1e-9)
                    if body_ratio < confbar_min:
                        reasons.append("confbar")
        except Exception:
            pass

        try:
            slope_min = float(self.buy_trendpb_adq_btc_slope_min.value)
            btc_slope = float(row.get("trbk_btc_slope_4h", float("nan")))
            if np.isfinite(btc_slope) and btc_slope < slope_min:
                reasons.append("slope")
        except Exception:
            pass

        if reasons:
            if "confbar" in reasons:
                self._trendpb_adq_counts["block_confbar"] = int(self._trendpb_adq_counts.get("block_confbar", 0)) + 1
            if "slope" in reasons:
                self._trendpb_adq_counts["block_slope"] = int(self._trendpb_adq_counts.get("block_slope", 0)) + 1
            if len(reasons) > 1:
                self._trendpb_adq_counts["block_combo"] = int(self._trendpb_adq_counts.get("block_combo", 0)) + 1
            return False, ("combo" if len(reasons) > 1 else reasons[0]), stats

        self._trendpb_adq_counts["pass"] = int(self._trendpb_adq_counts.get("pass", 0)) + 1
        return True, "strict_pass", stats

    def _trendpb_dynrel_allows(self, pair: str) -> tuple[bool, str, dict[str, float]]:
        if not bool(self.buy_trendpb_dynrel_enabled.value):
            return True, "disabled", {"n": 0.0, "expectancy_pct": 0.0, "loss_count": 0.0, "winrate_pct": 0.0}
        self._trendpb_dynrel_inc("checked")
        stats = self._trendpb_pair_recent_stats(pair)
        min_n = int(self.buy_trendpb_dynrel_min_trades.value)
        if int(stats.get("n", 0.0)) < min_n:
            self._trendpb_dynrel_inc("warmup")
            self._trendpb_dynrel_inc("pass")
            return True, "warmup", stats

        triggers: list[str] = []
        if float(stats.get("expectancy_pct", 0.0)) < float(self.buy_trendpb_dynrel_min_expectancy_pct.value):
            triggers.append("expectancy")
        if int(stats.get("loss_count", 0.0)) >= int(self.buy_trendpb_dynrel_recent_loss_limit.value):
            triggers.append("losses")
        min_winrate = float(self.buy_trendpb_dynrel_min_winrate_pct.value)
        if min_winrate > 0.0 and float(stats.get("winrate_pct", 0.0)) < min_winrate:
            triggers.append("winrate")

        block_min = max(1, int(self.buy_trendpb_dynrel_block_score_min.value))
        if len(triggers) >= block_min:
            for r in triggers:
                self._trendpb_dynrel_inc(f"block_{r}")
            if len(triggers) > 1:
                self._trendpb_dynrel_inc("block_combo")
            return False, ("combo" if len(triggers) > 1 else str(triggers[0])), stats

        self._trendpb_dynrel_inc("pass")
        return True, "pass", stats

    def tqo_counts_snapshot(self) -> dict[str, int]:
        try:
            return dict(self._tqo_counts)
        except Exception:
            return {}

    def _tqo_scope_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.buy_tqo_enabled.value):
            return False
        if bool(self.buy_tqo_apply_aux_only.value) and not self._is_auxiliary_entry_tag(entry_tag):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_tqo_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _tqo_bucket_key(self, current_time: datetime | None) -> str | None:
        if current_time is None:
            return None
        try:
            ts = pd.Timestamp(current_time)
            if ts.tzinfo is None:
                ts = ts.tz_localize("UTC")
            else:
                ts = ts.tz_convert("UTC")
        except Exception:
            return None
        if str(self.buy_tqo_bucket_mode.value or "hour_of_week") == "hour":
            return f"h{int(ts.hour):02d}"
        return f"d{int(ts.weekday())}_h{int(ts.hour):02d}"

    def _tqo_recent_stats(self, entry_tag: str | None, current_time: datetime | None) -> dict[str, float | str]:
        bucket_key = self._tqo_bucket_key(current_time)
        sleeve = self._reg_alloc_sleeve_from_tag(entry_tag)
        if bucket_key is None or not sleeve:
            return {"bucket": str(bucket_key or ""), "sleeve": sleeve, "n": 0.0, "expectancy_pct": 0.0, "winrate_pct": 0.0}
        recent = self._tqo_stats.get((bucket_key, sleeve), [])
        lookback = max(1, int(self.buy_tqo_lookback_trades.value))
        recent = recent[-lookback:]
        n = len(recent)
        if n <= 0:
            return {"bucket": bucket_key, "sleeve": sleeve, "n": 0.0, "expectancy_pct": 0.0, "winrate_pct": 0.0}
        exp_pct = float(sum(float(p) for _, p in recent)) / float(n)
        winrate_pct = float(sum(1 for _, p in recent if float(p) > 0.0)) * 100.0 / float(n)
        return {
            "bucket": bucket_key,
            "sleeve": sleeve,
            "n": float(n),
            "expectancy_pct": float(exp_pct),
            "winrate_pct": float(winrate_pct),
        }

    def _tqo_allows(self, entry_tag: str | None, current_time: datetime | None) -> tuple[bool, str, dict[str, float | str]]:
        if not bool(self.buy_tqo_enabled.value):
            return True, "disabled", {"n": 0.0, "expectancy_pct": 0.0, "winrate_pct": 0.0}
        if not self._tqo_scope_applies(entry_tag):
            return True, "scope_skip", {"n": 0.0, "expectancy_pct": 0.0, "winrate_pct": 0.0}

        self._tqo_counts["checked"] = int(self._tqo_counts.get("checked", 0)) + 1
        stats = self._tqo_recent_stats(entry_tag, current_time)
        if int(float(stats.get("n", 0.0) or 0.0)) < int(self.buy_tqo_min_trades.value):
            self._tqo_counts["warmup"] = int(self._tqo_counts.get("warmup", 0)) + 1
            self._tqo_counts["pass"] = int(self._tqo_counts.get("pass", 0)) + 1
            return True, "warmup", stats

        triggers: list[str] = []
        if float(stats.get("expectancy_pct", 0.0) or 0.0) < float(self.buy_tqo_min_expectancy_pct.value):
            triggers.append("expectancy")
        if float(stats.get("winrate_pct", 0.0) or 0.0) < float(self.buy_tqo_min_winrate_pct.value):
            triggers.append("winrate")

        if len(triggers) >= max(1, int(self.buy_tqo_block_score_min.value)):
            for key in triggers:
                self._tqo_counts[f"block_{key}"] = int(self._tqo_counts.get(f"block_{key}", 0)) + 1
            if len(triggers) > 1:
                self._tqo_counts["block_combo"] = int(self._tqo_counts.get("block_combo", 0)) + 1
            return False, ("combo" if len(triggers) > 1 else str(triggers[0])), stats

        self._tqo_counts["pass"] = int(self._tqo_counts.get("pass", 0)) + 1
        return True, "pass", stats

    def _meta_inc(self, key: str) -> None:
        try:
            self._meta_counts[str(key)] = int(self._meta_counts.get(str(key), 0)) + 1
        except Exception:
            pass

    def meta_counts_snapshot(self) -> dict[str, int]:
        try:
            return dict(self._meta_counts)
        except Exception:
            return {}

    def _meta_scope_applies(self, entry_tag: str | None) -> bool:
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_meta_trend_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _meta_pairs_for_snapshot(self, pair: str | None = None) -> list[str]:
        try:
            pairs = list(self.dp.current_whitelist() or [])
        except Exception:
            pairs = []
        if pair and pair not in pairs:
            pairs.append(pair)
        return [p for p in pairs if p]

    def _meta_cross_section_snapshot(
        self,
        current_time: datetime | None,
        pair: str | None = None,
    ) -> dict[str, float | int | str | dict[str, dict[str, float | str]]]:
        if current_time is None:
            return {
                "n": 0,
                "trend_up_frac": 0.0,
                "dispersion": 0.0,
                "coherence": 0.0,
                "rows": {},
            }
        try:
            key = f"meta:{pd.Timestamp(current_time).isoformat()}"
        except Exception:
            key = f"meta:{current_time}"
        cached = self._meta_snapshot_cache.get(key)
        if cached is not None:
            return cached

        rows: dict[str, dict[str, float | str]] = {}
        rets: list[float] = []
        trend_up = 0
        for p in self._meta_pairs_for_snapshot(pair):
            row, _, _ = self._rank_row_for_time(p, current_time)
            if row is None:
                continue
            try:
                ret4 = float(row.get("meta_ret_4h", float("nan")))
            except Exception:
                ret4 = float("nan")
            comp = str(row.get("composite_regime", "") or "")
            primary = str(row.get("meta_regime_primary", "") or self._regime_primary_token(comp))
            if primary in {"TREND_UP", "VOL_EXP"}:
                trend_up += 1
            if np.isfinite(ret4):
                rets.append(float(ret4))
            rows[p] = {
                "ret4h": float(ret4) if np.isfinite(ret4) else 0.0,
                "primary": primary,
                "vol_zscore": float(row.get("vol_zscore", 0.0) or 0.0),
            }

        n = len(rows)
        if rets:
            try:
                signs = [float(np.sign(x)) for x in rets if np.isfinite(x) and abs(float(x)) > 1e-12]
                coherence = abs(float(np.mean(signs))) if signs else 0.0
            except Exception:
                coherence = 0.0
            dispersion = float(np.std(rets)) if len(rets) > 1 else 0.0
        else:
            coherence = 0.0
            dispersion = 0.0
        out: dict[str, float | int | str | dict[str, dict[str, float | str]]] = {
            "n": int(n),
            "trend_up_frac": float(trend_up) / float(n) if n > 0 else 0.0,
            "dispersion": float(dispersion),
            "coherence": float(coherence),
            "rows": rows,
        }
        self._meta_snapshot_cache = {key: out}
        return out

    def _meta_recent_heat_metrics(self) -> dict[str, float]:
        vals = list(self._meta_recent_trade_pnl_pct)
        if not vals:
            return {"loss_streak": 0.0, "mean_profit": 0.0}
        lookback = max(1, int(self.buy_meta_heat_lookback_trades.value))
        recent = vals[-lookback:]
        streak = 0
        for v in reversed(recent):
            if float(v) < 0.0:
                streak += 1
            else:
                break
        return {
            "loss_streak": float(streak),
            "mean_profit": float(np.mean(recent)) if recent else 0.0,
        }

    def _meta_current_drawdown(self) -> float:
        try:
            hwm = max(float(self._meta_equity_hwm), 1e-9)
            equity = float(self._meta_equity_value)
            return max(0.0, (hwm - equity) / hwm)
        except Exception:
            return 0.0

    def _meta_btc_shock_state(self, current_time: datetime | None) -> dict[str, float | int | bool]:
        out: dict[str, float | int | bool] = {
            "recent_hit": False,
            "active": False,
            "age_bars": 999,
            "btc_ret_1h": 0.0,
            "btc_ret_4h": 0.0,
            "btc_volz": 0.0,
            "below_ema": False,
        }
        if current_time is None:
            return out

        try:
            key = f"meta_btc_shock:{pd.Timestamp(current_time).isoformat()}"
        except Exception:
            key = f"meta_btc_shock:{current_time}"
        cached = self._meta_snapshot_cache.get(key)
        if isinstance(cached, dict) and "active" in cached:
            return dict(cached)

        try:
            btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
            df, _ = self.dp.get_analyzed_dataframe(btc_pair, self.timeframe)
            if df is None or df.empty or "date" not in df.columns:
                self._meta_snapshot_cache[key] = dict(out)
                return out

            ts = pd.Timestamp(current_time)
            rows = df.loc[df["date"] <= ts]
            if rows.empty:
                self._meta_snapshot_cache[key] = dict(out)
                return out

            memory_bars = max(0, int(self.buy_meta_btc_shock_memory_bars.value))
            tail = rows.tail(memory_bars + 1 if memory_bars > 0 else 1).copy()
            if tail.empty:
                self._meta_snapshot_cache[key] = dict(out)
                return out

            ret1 = pd.to_numeric(
                tail.get("meta_ret_1h", pd.Series(0.0, index=tail.index)),
                errors="coerce",
            ).fillna(0.0)
            ret4 = pd.to_numeric(
                tail.get("meta_ret_4h", pd.Series(0.0, index=tail.index)),
                errors="coerce",
            ).fillna(0.0)
            volz = pd.to_numeric(
                tail.get("vol_zscore", pd.Series(0.0, index=tail.index)),
                errors="coerce",
            ).fillna(0.0)
            close = pd.to_numeric(
                tail.get("close", pd.Series(np.nan, index=tail.index)),
                errors="coerce",
            ).fillna(0.0)
            ema21 = pd.to_numeric(
                tail.get("meta_ema21", pd.Series(np.nan, index=tail.index)),
                errors="coerce",
            ).fillna(0.0)

            ret1_thr = abs(float(self.buy_meta_btc_shock_ret.value))
            ret4_thr = abs(float(self.buy_meta_btc_shock_ret4h.value))
            volz_thr = float(self.buy_meta_btc_shock_volz_min.value)

            shock_mask = (
                ((ret1 <= -ret1_thr) & (volz >= volz_thr))
                | ((ret4_thr > 0.0) & (ret4 <= -ret4_thr))
            ).fillna(False)

            recent_hit = bool(shock_mask.any())
            age_bars = 999
            if recent_hit:
                pos = np.flatnonzero(shock_mask.to_numpy())
                if len(pos) > 0:
                    age_bars = int((len(tail) - 1) - int(pos[-1]))

            cur_close = float(close.iloc[-1]) if not close.empty else 0.0
            cur_ema = float(ema21.iloc[-1]) if not ema21.empty else 0.0
            ema_buffer = float(self.buy_meta_btc_shock_ema_buffer.value)
            below_ema = bool(cur_ema > 0.0 and cur_close <= (cur_ema * (1.0 + ema_buffer)))
            active = bool(recent_hit and age_bars <= memory_bars)
            if active and bool(self.buy_meta_btc_shock_require_below_ema.value):
                active = below_ema

            out = {
                "recent_hit": recent_hit,
                "active": bool(active),
                "age_bars": int(age_bars),
                "btc_ret_1h": float(ret1.iloc[-1]) if not ret1.empty else 0.0,
                "btc_ret_4h": float(ret4.iloc[-1]) if not ret4.empty else 0.0,
                "btc_volz": float(volz.iloc[-1]) if not volz.empty else 0.0,
                "below_ema": below_ema,
            }
        except Exception:
            out = dict(out)

        self._meta_snapshot_cache[key] = dict(out)
        return out

    def _meta_record_closed_trade(self, trade: Trade, rate: float) -> None:
        if self._is_lookahead_analysis_mode():
            return
        try:
            profit_pct = float(trade.calc_profit_ratio(rate))
        except Exception:
            profit_pct = float(getattr(trade, "close_profit", 0.0) or 0.0)
        profit_abs = float(getattr(trade, "profit_abs", 0.0) or 0.0)
        if profit_abs == 0.0:
            try:
                profit_abs = float(getattr(trade, "stake_amount", 0.0) or 0.0) * float(profit_pct)
            except Exception:
                profit_abs = 0.0
        self._meta_recent_trade_pnl_pct.append(float(profit_pct))
        self._meta_recent_trade_pnl_abs.append(float(profit_abs))
        self._meta_equity_value = float(self._meta_equity_value) + float(profit_abs)
        self._meta_equity_hwm = max(float(self._meta_equity_hwm), float(self._meta_equity_value))

    def _meta_layer_decision(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
        *,
        stage: str,
    ) -> tuple[bool, float, dict[str, float | str | list[str]]]:
        if stage == "entry":
            self._meta_inc("entry_calls")
        else:
            self._meta_inc("stake_calls")

        if current_time is None or row is None:
            row = self._pair_row_at_or_before_time(pair, current_time)
        if row is None:
            return True, 1.0, {"reason": "no_row", "layers": []}

        is_trend_scope = (side == "long") and self._meta_scope_applies(entry_tag)
        meta_layers: list[str] = []
        mult = 1.0
        snapshot: dict[str, float | int | str | dict[str, dict[str, float | str]]] | None = None

        def _need_snapshot() -> dict[str, float | int | str | dict[str, dict[str, float | str]]]:
            nonlocal snapshot
            if snapshot is None:
                snapshot = self._meta_cross_section_snapshot(current_time, pair)
            return snapshot

        # 1) Market breadth
        if bool(self.buy_meta_breadth_enabled.value) and is_trend_scope:
            snap = _need_snapshot()
            up_frac = float(snap.get("trend_up_frac", 0.0) or 0.0)
            hard_frac = float(self.buy_meta_breadth_hard_block_frac.value)
            min_frac = max(hard_frac + 1e-6, float(self.buy_meta_breadth_min_frac.value))
            if stage == "entry" and up_frac < hard_frac:
                self._meta_inc("blocks")
                self._meta_inc("breadth_block")
                return False, 1.0, {"reason": "meta_breadth", "layers": ["breadth"], "up_frac": up_frac}
            if stage == "stake":
                floor = float(self.buy_meta_breadth_floor.value)
                ceiling = float(self.buy_meta_breadth_ceiling.value)
                if up_frac < min_frac:
                    local = floor
                else:
                    score = float(np.clip((up_frac - min_frac) / max(1e-6, 1.0 - min_frac), 0.0, 1.0))
                    local = 1.0 + (ceiling - 1.0) * score
                if abs(local - 1.0) > 1e-9:
                    meta_layers.append("breadth")
                    mult *= float(local)
                    self._meta_inc("soft_hits")
                    self._meta_inc("breadth_soft")

        # 2) Cross-sectional dispersion
        if bool(self.buy_meta_disp_enabled.value) and is_trend_scope:
            snap = _need_snapshot()
            disp = float(snap.get("dispersion", 0.0) or 0.0)
            block_v = float(self.buy_meta_disp_block.value)
            min_v = max(block_v, float(self.buy_meta_disp_min.value))
            if stage == "entry" and disp < block_v:
                self._meta_inc("blocks")
                self._meta_inc("disp_block")
                return False, 1.0, {"reason": "meta_dispersion", "layers": ["dispersion"], "dispersion": disp}
            if stage == "stake":
                floor = float(self.buy_meta_disp_floor.value)
                ceiling = float(self.buy_meta_disp_ceiling.value)
                if disp < min_v:
                    local = floor
                else:
                    score = float(np.clip((disp - min_v) / max(min_v, 1e-6), 0.0, 1.0))
                    local = 1.0 + (ceiling - 1.0) * score
                if abs(local - 1.0) > 1e-9:
                    meta_layers.append("dispersion")
                    mult *= float(local)
                    self._meta_inc("soft_hits")
                    self._meta_inc("disp_soft")

        # 3) Directional coherence / herding throttle
        if bool(self.buy_meta_herd_enabled.value) and is_trend_scope and stage == "stake":
            snap = _need_snapshot()
            coherence = float(snap.get("coherence", 0.0) or 0.0)
            if coherence > float(self.buy_meta_herd_max_coherence.value):
                mult *= float(self.buy_meta_herd_floor.value)
                meta_layers.append("herd")
                self._meta_inc("soft_hits")
                self._meta_inc("herd_soft")

        # 4) BTC shock throttle (stateful recent-shock memory)
        if bool(self.buy_meta_btc_shock_enabled.value) and side == "long" and is_trend_scope:
            if not (bool(self.buy_meta_btc_shock_alt_only.value) and pair.upper().startswith("BTC/")):
                btc_state = self._meta_btc_shock_state(current_time)
                if bool(btc_state.get("recent_hit", False)):
                    self._meta_inc("btc_shock_hit")
                if bool(btc_state.get("active", False)):
                    self._meta_inc("btc_shock_active_entry" if stage == "entry" else "btc_shock_active_stake")
                    if stage == "entry" and bool(self.buy_meta_btc_shock_hard_block.value):
                        self._meta_inc("blocks")
                        self._meta_inc("btc_shock_block")
                        return False, 1.0, {
                            "reason": "meta_btc_shock",
                            "layers": ["btc_shock"],
                            "btc_ret_1h": float(btc_state.get("btc_ret_1h", 0.0) or 0.0),
                            "btc_ret_4h": float(btc_state.get("btc_ret_4h", 0.0) or 0.0),
                            "btc_volz": float(btc_state.get("btc_volz", 0.0) or 0.0),
                            "age_bars": int(btc_state.get("age_bars", 999) or 999),
                        }
                    if stage == "stake":
                        mult *= float(self.buy_meta_btc_shock_floor.value)
                        meta_layers.append("btc_shock")
                        self._meta_inc("soft_hits")
                        self._meta_inc("btc_shock_soft")

        # 5) Vol-of-vol throttle
        if bool(self.buy_meta_vov_enabled.value) and stage == "stake":
            vov_z = float(row.get("meta_vov_z", 0.0) or 0.0)
            if np.isfinite(vov_z) and vov_z > float(self.buy_meta_vov_z_max.value):
                mult *= float(self.buy_meta_vov_floor.value)
                meta_layers.append("vov")
                self._meta_inc("soft_hits")
                self._meta_inc("vov_soft")

        # 6) Trend efficiency gate / throttle
        if bool(self.buy_meta_eff_enabled.value) and is_trend_scope:
            er = float(row.get("meta_er_16", 0.0) or 0.0)
            if stage == "entry" and bool(self.buy_meta_eff_hard_block.value) and er < float(self.buy_meta_eff_min.value):
                self._meta_inc("blocks")
                self._meta_inc("eff_block")
                return False, 1.0, {"reason": "meta_efficiency", "layers": ["efficiency"], "er": er}
            if stage == "stake" and er < float(self.buy_meta_eff_min.value):
                mult *= float(self.buy_meta_eff_floor.value)
                meta_layers.append("efficiency")
                self._meta_inc("soft_hits")
                self._meta_inc("eff_soft")

        # 7) Regime transition dwell gate
        if bool(self.buy_meta_dwell_enabled.value) and is_trend_scope and stage == "entry":
            bars = int(row.get("meta_regime_bars_since_flip", 0) or 0)
            if bars < int(self.buy_meta_dwell_min_bars.value):
                self._meta_inc("blocks")
                self._meta_inc("dwell_block")
                return False, 1.0, {"reason": "meta_dwell", "layers": ["dwell"], "bars": float(bars)}

        # 8) Portfolio heat throttle
        if bool(self.buy_meta_heat_enabled.value) and stage == "stake":
            heat = self._meta_recent_heat_metrics()
            if (
                int(heat.get("loss_streak", 0.0) or 0.0) >= int(self.buy_meta_heat_loss_streak_trigger.value)
                or float(heat.get("mean_profit", 0.0) or 0.0) < float(self.buy_meta_heat_mean_profit_floor.value)
            ):
                mult *= float(self.buy_meta_heat_floor.value)
                meta_layers.append("heat")
                self._meta_inc("soft_hits")
                self._meta_inc("heat_soft")

        # 9) Drawdown recovery throttle
        if bool(self.buy_meta_ddrec_enabled.value) and stage == "stake":
            dd = self._meta_current_drawdown()
            if dd >= float(self.buy_meta_ddrec_activate.value):
                mult *= float(self.buy_meta_ddrec_floor.value)
                meta_layers.append("ddrec")
                self._meta_inc("soft_hits")
                self._meta_inc("ddrec_soft")

        # 10) Chase-distance guard
        if bool(self.buy_meta_chase_enabled.value) and is_trend_scope and stage == "entry":
            chase = float(row.get("meta_chase_atr", 0.0) or 0.0)
            if chase > float(self.buy_meta_chase_max_atr.value):
                self._meta_inc("blocks")
                self._meta_inc("chase_block")
                return False, 1.0, {"reason": "meta_chase", "layers": ["chase"], "chase_atr": chase}

        return True, float(mult), {"reason": "pass", "layers": meta_layers}

    def _hazard_scope_applies(self, trade: Trade) -> bool:
        if not bool(self.sell_hazard_enabled.value):
            return False
        entry_tag = getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.sell_hazard_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def hazard_counts_snapshot(self) -> dict[str, int]:
        try:
            return dict(self._hazard_counts)
        except Exception:
            return {}

    @staticmethod
    def _hazard_mfe_profit(trade: Trade, current_rate: float) -> float:
        try:
            open_rate = float(getattr(trade, "open_rate", 0.0) or 0.0)
            if open_rate <= 0:
                return 0.0
            if bool(getattr(trade, "is_short", False)):
                trough = float(getattr(trade, "min_rate", 0.0) or current_rate or open_rate)
                if trough <= 0:
                    trough = open_rate
                return max(0.0, (open_rate - trough) / open_rate)
            peak = float(getattr(trade, "max_rate", 0.0) or current_rate or open_rate)
            return max(0.0, (peak - open_rate) / open_rate)
        except Exception:
            return 0.0

    def _hazard_regime_veto(self, row: pd.Series | dict | None) -> bool:
        if not bool(self.sell_hazard_regime_veto_enabled.value):
            return False
        comp = str((row.get("composite_regime", "") if row is not None else "") or "").upper()
        allow = {x.strip().upper() for x in str(self.sell_hazard_regime_veto_tokens.value or "").split(",") if x and x.strip()}
        if not allow:
            return False
        return any(tok in comp for tok in allow)

    def _hazard_exit_reason(
        self,
        trade: Trade,
        current_time: datetime,
        current_rate: float,
        current_profit: float,
        row: pd.Series | dict | None = None,
    ) -> str | None:
        if not bool(self.sell_hazard_enabled.value):
            return None
        self._hazard_counts["calls"] = int(self._hazard_counts.get("calls", 0)) + 1

        if not self._hazard_scope_applies(trade):
            self._hazard_counts["skip_tag"] = int(self._hazard_counts.get("skip_tag", 0)) + 1
            return None

        age_h = self._trade_age_hours(trade, current_time)
        eval_h = float(self.sell_hazard_eval_hours.value)
        max_h = max(eval_h, float(self.sell_hazard_max_eval_hours.value))
        if age_h < eval_h or age_h > max_h:
            self._hazard_counts["skip_age"] = int(self._hazard_counts.get("skip_age", 0)) + 1
            return None

        if self._hazard_regime_veto(row):
            self._hazard_counts["skip_regime"] = int(self._hazard_counts.get("skip_regime", 0)) + 1
            return None

        mfe_profit = self._hazard_mfe_profit(trade, current_rate)
        min_current = float(self.sell_hazard_min_current_profit.value)
        min_mfe = float(self.sell_hazard_min_mfe_profit.value)
        if float(mfe_profit) < min_mfe and float(current_profit) < min_current:
            self._hazard_counts["exit_no_progress"] = int(self._hazard_counts.get("exit_no_progress", 0)) + 1
            return "hazard_no_progress"

        retrace_arm = float(self.sell_hazard_retrace_arm_profit.value)
        keep_frac = float(np.clip(float(self.sell_hazard_retrace_keep_frac.value), 0.0, 1.0))
        if mfe_profit >= retrace_arm:
            keep_profit = max(min_current, float(mfe_profit) * keep_frac)
            if float(current_profit) < keep_profit:
                self._hazard_counts["exit_retrace"] = int(self._hazard_counts.get("exit_retrace", 0)) + 1
                return "hazard_retrace"

        self._hazard_counts["pass"] = int(self._hazard_counts.get("pass", 0)) + 1
        return None

    def _pair_edge_rank_penalty(self, pair: str) -> float:
        if not self.pair_edge_concentration_enabled.value or not pair:
            return 0.0
        recent = self._pair_edge_stats.get(pair, [])
        lookback = max(1, int(self.pair_edge_concentration_lookback_trades.value))
        recent = recent[-lookback:]
        n = len(recent)
        if n < int(self.pair_edge_concentration_min_trades.value):
            return 0.0
        loss_count = sum(1 for _, p in recent if float(p) < 0.0)
        if loss_count >= int(self.pair_edge_concentration_loss_limit.value):
            return float(self.pair_edge_concentration_rank_penalty.value)
        return 0.0

    def _rank_concentration_scope_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.rank_concentration_enabled.value):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.rank_concentration_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _rank_concentration_penalty(self, pair: str, entry_tag: str | None) -> float:
        if not pair:
            return 0.0
        if not self._rank_concentration_scope_applies(entry_tag):
            return 0.0
        open_trades = self._safe_get_open_trades()
        if open_trades is None:
            return 0.0
        sleeve = self._sleeve_key_from_tag(entry_tag)
        same_pair_open = 0
        same_sleeve_open = 0
        for tr in open_trades:
            tr_pair = str(getattr(tr, "pair", "") or "")
            tr_tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if tr_pair == pair:
                same_pair_open += 1
            if self._sleeve_key_from_tag(str(tr_tag or "")) == sleeve:
                same_sleeve_open += 1

        pair_penalty = float(self.rank_concentration_pair_open_penalty.value) * float(max(0, same_pair_open))
        sleeve_threshold = int(self.rank_concentration_sleeve_open_threshold.value)
        sleeve_excess = max(0, int(same_sleeve_open) - sleeve_threshold)
        sleeve_penalty = float(self.rank_concentration_sleeve_open_penalty.value) * float(sleeve_excess)
        penalty = float(pair_penalty + sleeve_penalty)

        if penalty > 0.0 and bool(self.rank_concentration_debug.value):
            logger.info(
                "RANK_CONC_PENALTY pair=%s tag=%s sleeve=%s same_pair_open=%s same_sleeve_open=%s threshold=%s penalty=%.3f",
                pair,
                str(entry_tag or ""),
                sleeve,
                same_pair_open,
                same_sleeve_open,
                sleeve_threshold,
                penalty,
            )
        return penalty

    @staticmethod
    def _parse_kv_csv(s: str) -> dict[str, float]:
        out: dict[str, float] = {}
        try:
            for part in str(s or "").split(","):
                piece = part.strip()
                if not piece or "=" not in piece:
                    continue
                k, v = piece.split("=", 1)
                key = k.strip().lower()
                try:
                    val = float(v.strip())
                except Exception:
                    continue
                if key and np.isfinite(val):
                    out[key] = float(val)
        except Exception:
            return {}
        return out

    def _csv_kv_float_map(self, raw: str) -> dict[str, float]:
        return self._parse_kv_csv(raw)

    def _regime_tokens(self, composite_regime: str) -> set[str]:
        raw = str(composite_regime or "").upper()
        if not raw:
            return set()
        tokens = {t for t in re.split(r"[,|\s]+", raw) if t}
        # Composite labels are often single fused strings (e.g. TREND_UP_LOW_EXPAND).
        # Add canonical tokens via substring detection so mapping is robust.
        compact = raw.replace(" ", "")
        if "VOL_EXP" in compact or "EXPAND" in compact:
            tokens.add("VOL_EXP")
        if "TREND_UP" in compact:
            tokens.add("TREND_UP")
        if "CHOP_MR" in compact or compact.startswith("CHOP"):
            tokens.add("CHOP_MR")
        if "BEARVOL" in compact or "BEAR_VOL" in compact:
            tokens.add("BEARVOL")
        if "PANIC" in compact:
            tokens.add("PANIC")
        return tokens

    def _regime_primary_token(self, composite_regime: str) -> str:
        toks = self._regime_tokens(composite_regime)
        if "VOL_EXP" in toks:
            return "VOL_EXP"
        if "TREND_UP" in toks:
            return "TREND_UP"
        if "CHOP_MR" in toks:
            return "CHOP_MR"
        if "BEARVOL" in toks:
            return "BEARVOL"
        if "PANIC" in toks:
            return "PANIC"
        return "DEFAULT"

    def _regime_base_mult(self, composite_regime: str) -> float:
        tokens = self._regime_tokens(composite_regime)
        if "VOL_EXP" in tokens:
            return float(self.buy_regime_risk_mult_vol_exp.value)
        if "TREND_UP" in tokens:
            return float(self.buy_regime_risk_mult_trend_up.value)
        if "CHOP_MR" in tokens:
            return float(self.buy_regime_risk_mult_chop_mr.value)
        if "BEARVOL" in tokens:
            return float(self.buy_regime_risk_mult_bearvol.value)
        if "PANIC" in tokens:
            return float(self.buy_regime_risk_mult_panic.value)
        return float(self.buy_regime_risk_mult_default.value)

    def _regime_override_mult(self, sleeve: str, composite_regime: str) -> float | None:
        if not bool(self.buy_regime_risk_apply_by_sleeve.value):
            return None
        rawmap = self._csv_kv_float_map(str(self.buy_regime_risk_override_map.value or ""))
        if not rawmap:
            return None
        sleeve_key = str(sleeve or "").lower().strip()
        if not sleeve_key:
            return None
        for tok in self._regime_tokens(composite_regime):
            key = f"{sleeve_key}:{tok}".lower()
            if key in rawmap and np.isfinite(rawmap[key]):
                return float(rawmap[key])
        return None

    def _regime_risk_mult(self, composite_regime: str, enter_tag: str | None = "") -> float:
        if not bool(self.buy_regime_risk_enabled.value):
            return 1.0
        comp = str(composite_regime or "")
        if not comp.strip():
            return 1.0  # fail-open when regime is unknown

        sleeve = self._stack_sleeve_from_tag(enter_tag)
        mult = self._regime_override_mult(sleeve, comp)
        if mult is None:
            mult = self._regime_base_mult(comp)

        mn = float(self.buy_regime_risk_min_mult.value)
        mx = float(self.buy_regime_risk_max_mult.value)
        if mx < mn:
            mn, mx = mx, mn
        return float(np.clip(float(mult), mn, mx))

    def _regime2d_axes(self, composite_regime: str, atr_phase: str = "", vol_zscore: float | None = None) -> tuple[str, str]:
        toks = self._regime_tokens(composite_regime)
        trend_axis = "TREND" if ("TREND_UP" in toks or "VOL_EXP" in toks) else "CHOP"

        stress = False
        if bool(self.buy_regime2d_stress_from_panic_bear.value):
            stress = ("PANIC" in toks) or ("BEARVOL" in toks)

        try:
            atr_u = str(atr_phase or "").upper()
            if not stress and (not bool(self.buy_regime2d_stress_require_expand.value) or atr_u == "EXPAND"):
                v = float(vol_zscore) if vol_zscore is not None else float("nan")
                if np.isfinite(v) and v >= float(self.buy_regime2d_stress_volz_min.value):
                    stress = True
        except Exception:
            pass

        stress_axis = "STRESS" if stress else "NORMAL"
        return trend_axis, stress_axis

    @staticmethod
    def _regime2d_bucket(trend_axis: str, stress_axis: str) -> str:
        t = "TREND" if str(trend_axis).upper().startswith("TREND") else "CHOP"
        s = "STRESS" if str(stress_axis).upper().startswith("STRESS") else "NORMAL"
        return f"{t}_{s}"

    def _regime2d_bucket_mult(self, bucket: str) -> float:
        b = str(bucket or "").upper()
        if b == "TREND_STRESS":
            return float(self.buy_regime2d_mult_trend_stress.value)
        if b == "CHOP_NORMAL":
            return float(self.buy_regime2d_mult_chop_normal.value)
        if b == "CHOP_STRESS":
            return float(self.buy_regime2d_mult_chop_stress.value)
        return float(self.buy_regime2d_mult_trend_normal.value)

    def _regime2d_mult(self, row: pd.Series | dict | None = None) -> float:
        if not bool(self.buy_regime2d_enabled.value):
            return 1.0
        try:
            self._regime2d_counts["calls"] = float(self._regime2d_counts.get("calls", 0.0)) + 1.0
            rr = row if isinstance(row, (pd.Series, dict)) else {}
            bucket = str(rr.get("regime2d_bucket", "") or rr.get("regime2d_bucket_raw", "")).upper()
            if not bucket:
                comp = str(rr.get("composite_regime", "") or "")
                atrp = str(rr.get("atr_phase", "") or "")
                try:
                    volz = float(rr.get("vol_zscore", float("nan")))
                except Exception:
                    volz = float("nan")
                t_axis, s_axis = self._regime2d_axes(comp, atr_phase=atrp, vol_zscore=volz)
                bucket = self._regime2d_bucket(t_axis, s_axis)

            mult = float(self._regime2d_bucket_mult(bucket))
            mn = float(self.buy_regime2d_min_mult.value)
            mx = float(self.buy_regime2d_max_mult.value)
            if mx < mn:
                mn, mx = mx, mn
            mult = float(np.clip(mult, mn, mx))
            self._regime2d_counts["applied"] = float(self._regime2d_counts.get("applied", 0.0)) + 1.0
            self._regime2d_counts["mult_sum"] = float(self._regime2d_counts.get("mult_sum", 0.0)) + mult

            b = str(bucket).upper()
            if b == "TREND_NORMAL":
                self._regime2d_counts["trend_normal"] = float(self._regime2d_counts.get("trend_normal", 0.0)) + 1.0
            elif b == "TREND_STRESS":
                self._regime2d_counts["trend_stress"] = float(self._regime2d_counts.get("trend_stress", 0.0)) + 1.0
            elif b == "CHOP_NORMAL":
                self._regime2d_counts["chop_normal"] = float(self._regime2d_counts.get("chop_normal", 0.0)) + 1.0
            elif b == "CHOP_STRESS":
                self._regime2d_counts["chop_stress"] = float(self._regime2d_counts.get("chop_stress", 0.0)) + 1.0

            if bool(self.buy_regime2d_debug.value):
                logger.info("REGIME2D_MULT bucket=%s mult=%.3f", bucket, mult)
            return mult
        except Exception:
            self._regime2d_counts["fallback"] = float(self._regime2d_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    def _tqf_init_state(self) -> None:
        if not hasattr(self, "_tqf_counts"):
            self._tqf_counts = {
                "checked": 0,
                "pass": 0,
                "block_no_score": 0,
                "block_below_threshold": 0,
            }

    def _tqf_inc(self, key: str) -> None:
        self._tqf_init_state()
        self._tqf_counts[key] = int(self._tqf_counts.get(key, 0)) + 1

    def tqf_counts_snapshot(self) -> dict[str, int]:
        self._tqf_init_state()
        try:
            return dict(self._tqf_counts)
        except Exception:
            return {}

    def _tqf_parse_override_map(self, raw: str) -> dict[str, float]:
        return self._csv_kv_float_map(raw)

    def _tqf_regime_tokens(self, composite_regime: str) -> set[str]:
        return self._regime_tokens(composite_regime)

    def _tqf_sleeve_from_tag(self, enter_tag: str | None) -> str:
        bucket = self._tag_bucket(enter_tag)
        if bucket in {"cbx", "trbk", "trendpb", "panic"}:
            return bucket
        if bucket == "bearvol_short":
            return "bearvol"
        if bucket == "brf_short":
            return "brf"
        if bucket == "trbk_short":
            return "trbk"
        return str(bucket or "other")

    def _tqf_base_threshold(self, composite_regime: str) -> float:
        toks = self._tqf_regime_tokens(composite_regime)
        if "VOL_EXP" in toks:
            return float(self.buy_tqf_min_score_vol_exp.value)
        if "TREND_UP" in toks:
            return float(self.buy_tqf_min_score_trend.value)
        if "CHOP_MR" in toks:
            return float(self.buy_tqf_min_score_chop.value)
        if "BEARVOL" in toks:
            return float(self.buy_tqf_min_score_bearvol.value)
        if "PANIC" in toks:
            return float(self.buy_tqf_min_score_panic.value)
        return float(self.buy_tqf_min_score_default.value)

    def _tqf_threshold(self, sleeve: str, composite_regime: str) -> float:
        base = float(self._tqf_base_threshold(composite_regime))
        rawmap = self._tqf_parse_override_map(str(self.buy_tqf_override_map.value or ""))
        if rawmap:
            for tok in self._tqf_regime_tokens(composite_regime):
                key = f"{str(sleeve or '').lower()}:{tok}".lower()
                if key in rawmap and np.isfinite(rawmap[key]):
                    return float(np.clip(float(rawmap[key]), 0.0, 1.0))
        return float(np.clip(base, 0.0, 1.0))

    def _tqf_score(self, row: pd.Series | dict, sleeve: str, side: str = "long") -> float | None:
        try:
            if hasattr(self, "_qsize_score"):
                score, _ = self._qsize_score(row, sleeve=sleeve, side=side)
                val = float(score)
                if np.isfinite(val):
                    return float(np.clip(val, 0.0, 1.0))
        except Exception:
            return None
        return None

    def _tqf_allows(
        self,
        row: pd.Series | dict,
        enter_tag: str,
        side: str = "long",
    ) -> tuple[bool, str, float | None, float]:
        if not bool(self.buy_tqf_enabled.value):
            return True, "disabled", None, 0.0

        self._tqf_inc("checked")
        sleeve = self._tqf_sleeve_from_tag(enter_tag)
        regime = str(row.get("composite_regime", "") if isinstance(row, (dict, pd.Series)) else "")
        score = self._tqf_score(row, sleeve=sleeve, side=side)
        threshold = self._tqf_threshold(sleeve, regime)

        if score is None:
            # Fail-open: score unavailable should not block entries.
            self._tqf_inc("block_no_score")
            return True, "no_score_fail_open", None, float(threshold)

        if float(score) < float(threshold):
            self._tqf_inc("block_below_threshold")
            return False, "below_threshold", float(score), float(threshold)

        self._tqf_inc("pass")
        return True, "pass", float(score), float(threshold)

    def _rt_init_state(self) -> None:
        if not hasattr(self, "_rt_counts"):
            self._rt_counts = {
                "checked": 0,
                "pass": 0,
                "block_score": 0,
                "block_nth": 0,
            }
        if not hasattr(self, "_rt_signal_counts"):
            self._rt_signal_counts = {}

    def _rt_inc(self, key: str) -> None:
        self._rt_init_state()
        self._rt_counts[key] = int(self._rt_counts.get(key, 0)) + 1

    def rt_counts_snapshot(self) -> dict[str, int]:
        self._rt_init_state()
        try:
            return dict(self._rt_counts)
        except Exception:
            return {}

    def _rt_parse_float_map(self, raw: str) -> dict[str, float]:
        return self._csv_kv_float_map(raw)

    def _rt_parse_int_map(self, raw: str) -> dict[str, int]:
        out: dict[str, int] = {}
        try:
            for k, v in self._csv_kv_float_map(raw).items():
                if np.isfinite(v):
                    out[str(k).lower()] = int(round(float(v)))
        except Exception:
            return {}
        return out

    def _rt_regime_tokens(self, composite_regime: str) -> set[str]:
        return self._regime_tokens(composite_regime)

    def _rt_sleeve_from_tag(self, enter_tag: str) -> str:
        return self._tqf_sleeve_from_tag(enter_tag)

    def _rt_key(self, pair: str, sleeve: str, regime_token: str) -> str:
        if str(self.buy_rt_scope.value) == "regime_sleeve":
            return f"{sleeve}|{regime_token}"
        return f"{pair}|{sleeve}|{regime_token}"

    def _rt_score_threshold(self, sleeve: str, composite_regime: str) -> float | None:
        fmap = self._rt_parse_float_map(str(self.buy_rt_score_map.value or ""))
        if not fmap:
            return None
        for tok in self._rt_regime_tokens(composite_regime):
            key = f"{sleeve}:{tok}".lower()
            if key in fmap and np.isfinite(fmap[key]):
                return float(np.clip(float(fmap[key]), 0.0, 1.0))
        return None

    def _rt_n_value(self, sleeve: str, composite_regime: str) -> tuple[int | None, str | None]:
        imap = self._rt_parse_int_map(str(self.buy_rt_n_map.value or ""))
        if not imap:
            return None, None
        for tok in self._rt_regime_tokens(composite_regime):
            key = f"{sleeve}:{tok}".lower()
            if key in imap:
                return int(imap[key]), tok
        return None, None

    def _rt_qscore(self, row: pd.Series | dict, sleeve: str, side: str = "long") -> float | None:
        try:
            if hasattr(self, "_qsize_score"):
                score, _ = self._qsize_score(row, sleeve=sleeve, side=side)
                val = float(score)
                if np.isfinite(val):
                    return float(np.clip(val, 0.0, 1.0))
        except Exception:
            return None
        return None

    def _rt_allows(
        self,
        row: pd.Series | dict,
        pair: str,
        enter_tag: str,
        side: str = "long",
    ) -> tuple[bool, str]:
        if not bool(self.buy_rt_enabled.value):
            return True, "disabled"

        self._rt_inc("checked")
        sleeve = self._rt_sleeve_from_tag(enter_tag)
        regime = str(row.get("composite_regime", "") if isinstance(row, (dict, pd.Series)) else "")
        mode = str(self.buy_rt_mode.value or "score_threshold")

        if mode == "score_threshold":
            thr = self._rt_score_threshold(sleeve, regime)
            if thr is None:
                self._rt_inc("pass")
                return True, "no_rule"
            score = self._rt_qscore(row, sleeve=sleeve, side=side)
            if score is None:
                # Fail-open when score is unavailable.
                self._rt_inc("pass")
                return True, "no_score_fail_open"
            if float(score) < float(thr):
                self._rt_inc("block_score")
                return False, f"score<{float(thr):.2f}"
            self._rt_inc("pass")
            return True, "pass"

        n_val, tok = self._rt_n_value(sleeve, regime)
        if n_val is None or tok is None or int(n_val) <= 1:
            self._rt_inc("pass")
            return True, "no_rule"

        key = self._rt_key(str(pair or ""), sleeve, str(tok))
        cur = int(self._rt_signal_counts.get(key, 0)) + 1
        self._rt_signal_counts[key] = cur

        if (cur % int(n_val)) != 0:
            self._rt_inc("block_nth")
            return False, f"nth_skip_{cur}"

        self._rt_inc("pass")
        return True, "pass"

    def _reg_alloc_sleeve_from_tag(self, entry_tag: str | None) -> str:
        t = str(entry_tag or "").lower()
        if not t:
            return "other"
        if self._is_fimr_entry_tag(t):
            return "fimr"
        if self._is_spreadarb_entry_tag(t):
            return "spreadarb"
        if self._is_cpdf_entry_tag(t):
            return "cpdf"
        if self._is_fcarry_entry_tag(t):
            return "fcarry"
        if self._is_cvw_entry_tag(t):
            return "cvw"
        if self._is_mofi_entry_tag(t):
            return "mofi"
        if self._is_evtpulse_entry_tag(t):
            return "evtpulse"
        if self._is_lagcatch_entry_tag(t):
            return "lagcatch"
        if t.startswith("rmom_"):
            return "rmom"
        if t.startswith("tsmom_"):
            return "tsmom"
        if t.startswith("trendxs_"):
            return "trendxs"
        if t.startswith("stoploss_"):
            return "stoploss"
        if self._is_liqcascade_v2_entry_tag(t):
            return "liqcascade_v2"
        if self._is_liqcascade_entry_tag(t):
            return "liqcascade"
        if self._is_idle_fr_entry_tag(t):
            return "idle_fr"
        if self._is_idle_entry_tag(t):
            return "idle"
        if self._is_e0v1e5m_entry_tag(t):
            return "e0"
        if self._is_micro5m_entry_tag(t):
            return "micro"
        if "trend_pullback" in t or t.startswith("tpb"):
            return "tpb"
        if "cbx" in t:
            return "cbx"
        if "trbk" in t:
            return "trbk"
        if "volex" in t or "veb" in t:
            return "volex"
        if "bearvol" in t:
            return "bearvol"
        if "brf" in t:
            return "brf"
        if "mr_long" in t:
            return "mr"
        return self._sleeve_key_from_tag(t)

    @staticmethod
    def _reg_alloc_ts_key(current_time: datetime | None) -> str:
        if current_time is None:
            return "na"
        try:
            return current_time.strftime("%Y-%m-%dT%H")
        except Exception:
            return "na"

    def _reg_alloc_recent_returns(self, sleeve: str, lookback: int) -> list[float]:
        seq = self._reg_alloc_recent_by_sleeve.get(str(sleeve or "").lower())
        if not seq:
            return []
        vals = list(seq)
        if lookback > 0:
            vals = vals[-lookback:]
        return [float(x) for x in vals if np.isfinite(float(x))]

    def _reg_alloc_mult(self, sleeve: str, current_time: datetime | None = None) -> float:
        if not bool(self.reg_alloc_enabled.value):
            return 1.0

        try:
            self._reg_alloc_counts["calls"] = int(self._reg_alloc_counts.get("calls", 0)) + 1

            sleeve_key = str(sleeve or "other").lower()
            lookback = max(1, int(self.reg_alloc_lookback_trades.value))
            floor = float(self.reg_alloc_floor.value)
            ceiling = float(self.reg_alloc_ceiling.value)
            min_samples = max(1, int(self.reg_alloc_min_samples.value))
            deadband = max(0.0, float(self.reg_alloc_deadband.value))
            scale = max(1e-4, float(self.reg_alloc_scale.value))
            clip_abs = max(0.0, float(self.reg_alloc_return_clip.value))
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(1.0, ceiling)
            min_samples = min(min_samples, lookback)

            cache_key = (sleeve_key, self._reg_alloc_ts_key(current_time))
            cached = self._reg_alloc_cache.get(cache_key)
            if cached is not None:
                self._reg_alloc_counts["cache_hits"] = int(self._reg_alloc_counts.get("cache_hits", 0)) + 1
                return float(cached[0])

            xs = self._reg_alloc_recent_returns(sleeve_key, lookback)
            if len(xs) < min_samples:
                self._reg_alloc_counts["insufficient"] = int(self._reg_alloc_counts.get("insufficient", 0)) + 1
                self._reg_alloc_cache[cache_key] = (1.0, len(xs), 0.0)
                return 1.0

            if clip_abs > 0.0:
                xs = [float(np.clip(x, -clip_abs, clip_abs)) for x in xs]

            mu_raw = float(np.mean(xs))
            mu = 0.0 if abs(mu_raw) <= deadband else mu_raw
            z = float(np.clip(mu / scale, -1.0, 1.0))
            if z >= 0.0:
                mult_raw = 1.0 + z * (ceiling - 1.0)
            else:
                mult_raw = 1.0 + z * (1.0 - floor)

            conf_denom = max(1, lookback - min_samples)
            confidence = float(np.clip((len(xs) - min_samples) / conf_denom, 0.0, 1.0))
            mult = 1.0 + (mult_raw - 1.0) * confidence

            overrides = self._parse_kv_csv(str(self.reg_alloc_sleeve_overrides.value or ""))
            ovr = overrides.get(sleeve_key)
            if ovr is not None and np.isfinite(ovr):
                mult = min(mult, float(ovr))

            mult = float(np.clip(mult, floor, ceiling))
            self._reg_alloc_cache[cache_key] = (mult, len(xs), mu_raw)

            if bool(self.reg_alloc_debug.value) and cache_key not in self._reg_alloc_debug_seen:
                self._reg_alloc_debug_seen.add(cache_key)
                logger.info(
                    "REG_ALLOC sleeve=%s n=%s mu=%.4f mu_eff=%.4f conf=%.2f mult=%.3f floor=%.2f ceil=%.2f",
                    sleeve_key,
                    len(xs),
                    mu_raw,
                    mu,
                    confidence,
                    mult,
                    floor,
                    ceiling,
                )

            return mult
        except Exception:
            self._reg_alloc_counts["fallback"] = int(self._reg_alloc_counts.get("fallback", 0)) + 1
            return 1.0

    def _reg_alloc_snapshot(self) -> dict[str, dict[str, float]]:
        out: dict[str, dict[str, float]] = {}
        for sleeve_key, seq in self._reg_alloc_recent_by_sleeve.items():
            vals = [float(x) for x in list(seq) if np.isfinite(float(x))]
            if not vals:
                continue
            n = len(vals)
            lookback = max(1, int(self.reg_alloc_lookback_trades.value))
            clip_abs = max(0.0, float(self.reg_alloc_return_clip.value))
            vals = vals[-lookback:]
            if clip_abs > 0.0:
                vals = [float(np.clip(x, -clip_abs, clip_abs)) for x in vals]
            mu = float(np.mean(vals)) if vals else 0.0
            out[sleeve_key] = {
                "n": float(n),
                "mu": mu,
                "mult": float(self._reg_alloc_mult(sleeve_key, None)),
            }
        return out

    @staticmethod
    def _max_drawdown_from_sequence(values: list[float]) -> float:
        if not values:
            return 0.0
        csum = 0.0
        peak = 0.0
        max_dd = 0.0
        for x in values:
            csum += float(x)
            peak = max(peak, csum)
            max_dd = max(max_dd, peak - csum)
        return float(max_dd)

    def _regime_salloc_mult(
        self,
        sleeve: str,
        composite_regime: str,
        current_time: datetime | None = None,
    ) -> float:
        if not bool(self.buy_regime_salloc_enabled.value):
            return 1.0
        try:
            self._regime_salloc_counts["calls"] = int(self._regime_salloc_counts.get("calls", 0)) + 1
            sleeve_key = str(sleeve or "other").lower()
            regime_key = self._regime_primary_token(composite_regime)
            ts_key = self._reg_alloc_ts_key(current_time)
            cache_key = (sleeve_key, regime_key, ts_key)
            cached = self._regime_salloc_cache.get(cache_key)
            if cached is not None:
                self._regime_salloc_counts["cache_hits"] = int(self._regime_salloc_counts.get("cache_hits", 0)) + 1
                return float(cached[0])

            lookback = max(1, int(self.buy_regime_salloc_lookback_trades.value))
            min_samples = max(1, int(self.buy_regime_salloc_min_samples.value))
            floor = float(self.buy_regime_salloc_floor.value)
            ceiling = float(self.buy_regime_salloc_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(ceiling, 1.0)
            deadband = max(0.0, float(self.buy_regime_salloc_deadband.value))
            scale = max(1e-4, float(self.buy_regime_salloc_scale.value))
            clip_abs = max(0.0, float(self.buy_regime_salloc_return_clip.value))
            shrink_strength = float(np.clip(float(self.buy_regime_salloc_shrink_strength.value), 0.0, 1.0))

            xs = list(self._regime_salloc_recent_by_key.get((sleeve_key, regime_key), deque()))
            xs = [float(x) for x in xs[-lookback:] if np.isfinite(float(x))]
            if not xs:
                self._regime_salloc_counts["insufficient"] = int(self._regime_salloc_counts.get("insufficient", 0)) + 1
                self._regime_salloc_cache[cache_key] = (1.0, 0, 0.0)
                return 1.0

            if clip_abs > 0:
                xs = [float(np.clip(x, -clip_abs, clip_abs)) for x in xs]

            mu_raw = float(np.mean(xs))
            # Priors reduce sensitivity to sparse or noisy sleeve-regime cells.
            sleeve_vals: list[float] = []
            regime_vals: list[float] = []
            global_vals: list[float] = []
            for (s_key, r_key), seq in self._regime_salloc_recent_by_key.items():
                vals = [float(v) for v in list(seq)[-lookback:] if np.isfinite(float(v))]
                if not vals:
                    continue
                global_vals.extend(vals)
                if s_key == sleeve_key:
                    sleeve_vals.extend(vals)
                if r_key == regime_key:
                    regime_vals.extend(vals)

            mu_sleeve = float(np.mean(sleeve_vals)) if sleeve_vals else 0.0
            mu_regime = float(np.mean(regime_vals)) if regime_vals else 0.0
            mu_global = float(np.mean(global_vals)) if global_vals else 0.0
            mu_prior = float((0.45 * mu_regime) + (0.35 * mu_sleeve) + (0.20 * mu_global))

            n = len(xs)
            base_conf = float(np.clip(n / max(1.0, float(min_samples)), 0.0, 1.0))
            conf_denom = max(1, lookback - min_samples)
            full_conf = float(np.clip((n - min_samples) / conf_denom, 0.0, 1.0))
            confidence = max(base_conf * 0.5, full_conf)
            if n < min_samples:
                self._regime_salloc_counts["insufficient"] = int(self._regime_salloc_counts.get("insufficient", 0)) + 1
            prior_weight = float(np.clip((1.0 - confidence) * shrink_strength, 0.0, 1.0))
            mu_blended = float((1.0 - prior_weight) * mu_raw + prior_weight * mu_prior)

            mu = 0.0 if abs(mu_blended) <= deadband else mu_blended
            z = float(np.clip(mu / scale, -1.0, 1.0))
            mult_raw = (1.0 + z * (ceiling - 1.0)) if z >= 0 else (1.0 + z * (1.0 - floor))
            mult = float(np.clip(1.0 + (mult_raw - 1.0) * confidence, floor, ceiling))
            self._regime_salloc_cache[cache_key] = (mult, len(xs), mu_raw)
            if bool(self.buy_regime_salloc_debug.value):
                logger.info(
                    "REGIME_SALLOC sleeve=%s regime=%s n=%s mu=%.4f mu_prior=%.4f conf=%.2f mult=%.3f",
                    sleeve_key,
                    regime_key,
                    len(xs),
                    mu_raw,
                    mu_prior,
                    confidence,
                    mult,
                )
            return mult
        except Exception:
            self._regime_salloc_counts["fallback"] = int(self._regime_salloc_counts.get("fallback", 0)) + 1
            return 1.0

    def _regime_salloc_snapshot(self) -> dict[str, dict[str, float]]:
        out: dict[str, dict[str, float]] = {}
        for (sleeve, regime), seq in self._regime_salloc_recent_by_key.items():
            vals = [float(x) for x in list(seq) if np.isfinite(float(x))]
            if not vals:
                continue
            key = f"{sleeve}:{regime}"
            out[key] = {
                "n": float(len(vals)),
                "mu": float(np.mean(vals)),
            }
        return out

    def _pair_dynrank_snapshot(self, current_time: datetime | None) -> dict[str, float]:
        ts_key = self._reg_alloc_ts_key(current_time)
        cached = self._pair_dynrank_cache.get(ts_key)
        if cached is not None:
            self._pair_dynrank_counts["cache_hits"] = float(self._pair_dynrank_counts.get("cache_hits", 0.0)) + 1.0
            return cached

        lookback = max(1, int(self.buy_pair_dynrank_lookback_trades.value))
        min_trades = max(1, int(self.buy_pair_dynrank_min_trades.value))
        floor = float(self.buy_pair_dynrank_floor.value)
        ceiling = float(self.buy_pair_dynrank_ceiling.value)
        if ceiling < floor:
            floor, ceiling = ceiling, floor
        floor = min(floor, 1.0)
        ceiling = max(ceiling, 1.0)
        clip_pct = max(0.1, float(self.buy_pair_dynrank_score_clip_pct.value))
        wr_weight = max(0.0, float(self.buy_pair_dynrank_winrate_weight.value))

        # Time-decay: half-life in days (0 = uniform weighting, legacy behaviour)
        halflife_days = max(0.0, float(self.buy_pair_dynrank_time_decay_halflife_days.value))
        use_decay = halflife_days > 0.0
        if use_decay:
            decay_lambda = math.log(2.0) / max(1e-9, halflife_days * 86400.0)
            ref_epoch = current_time.timestamp() if current_time else 0.0
        else:
            decay_lambda = 0.0
            ref_epoch = 0.0

        try:
            pairs = list(self.dp.current_whitelist())
        except Exception:
            pairs = []
        if not pairs:
            pairs = list(self._pair_edge_stats.keys())

        mode = str(self.buy_pair_dynrank_mode.value or "legacy").strip().lower()
        all_clipped: list[float] = []
        for pair in pairs:
            recent = self._pair_edge_stats.get(pair, [])
            vals = [float(p) for _, p in recent[-lookback:] if np.isfinite(float(p))]
            if vals:
                all_clipped.extend(float(np.clip(v, -clip_pct, clip_pct)) for v in vals)
        global_mu = float(np.mean(all_clipped)) if all_clipped else 0.0

        scored: list[tuple[str, float, float, int]] = []
        for pair in pairs:
            recent = self._pair_edge_stats.get(pair, [])
            if not recent:
                continue
            entries = recent[-lookback:]
            entries_valid = [(ts, float(p)) for ts, p in entries if np.isfinite(float(p))]
            n = len(entries_valid)
            if n < min_trades:
                continue
            clipped = [float(np.clip(p, -clip_pct, clip_pct)) for _, p in entries_valid]

            # Compute weights (time-decay or uniform)
            if use_decay and ref_epoch > 0.0:
                weights = []
                for ts, _ in entries_valid:
                    try:
                        age_s = max(0.0, ref_epoch - ts.timestamp())
                    except Exception:
                        age_s = 0.0
                    weights.append(math.exp(-decay_lambda * age_s))
                w_sum = sum(weights) or 1.0
                weights = [w / w_sum for w in weights]
            else:
                weights = [1.0 / max(1, n)] * n

            mu = sum(c * w for c, w in zip(clipped, weights))
            winrate = sum(w for (_, p), w in zip(entries_valid, weights) if p > 0.0)
            score = mu + (winrate - 0.5) * clip_pct * wr_weight

            if mode == "net_expectancy":
                shrink = float(np.clip(float(self.buy_pair_dynrank_shrink_strength.value), 0.0, 1.0))
                mu_shrunk = float((1.0 - shrink) * mu + shrink * global_mu)
                dd = self._max_drawdown_from_sequence(clipped)
                std_vals = clipped
                std = float(np.std(std_vals, ddof=1)) if n > 1 else 0.0
                ci = 1.96 * std / max(1.0, float(math.sqrt(max(1, n))))
                cost_pen = float(self.buy_pair_dynrank_cost_penalty_pct.value)
                dd_pen = float(self.buy_pair_dynrank_dd_weight.value) * (dd / max(1.0, clip_pct * 5.0))
                ci_pen = float(self.buy_pair_dynrank_ci_weight.value) * (ci / max(1.0, clip_pct))
                turnover_pen = 0.0
                try:
                    if len(entries_valid) >= 2:
                        dt0 = entries_valid[0][0]
                        dt1 = entries_valid[-1][0]
                        span_days = max(1e-6, float((dt1 - dt0).total_seconds() / 86400.0))
                        trades_per_day = float(n) / span_days
                        turnover_pen = float(self.buy_pair_dynrank_turnover_weight.value) * max(0.0, trades_per_day - 0.5) * cost_pen
                except Exception:
                    turnover_pen = 0.0
                score = float(mu_shrunk - cost_pen - dd_pen - ci_pen - turnover_pen + (winrate - 0.5) * clip_pct * wr_weight)
            conf_denom = max(1, lookback - min_trades)
            conf = float(np.clip((n - min_trades) / conf_denom, 0.0, 1.0))
            scored.append((pair, score, conf, n))

        if not scored:
            self._pair_dynrank_counts["insufficient"] = float(self._pair_dynrank_counts.get("insufficient", 0.0)) + 1.0
            self._pair_dynrank_cache = {ts_key: {}}
            self._pair_dynrank_pct_cache = {ts_key: {}}
            return {}

        sorted_scores = sorted(float(x[1]) for x in scored)
        last_idx = max(1.0, float(len(sorted_scores) - 1))
        out: dict[str, float] = {}
        pct_out: dict[str, float] = {}
        bottom_q = float(np.clip(float(self.buy_pair_dynrank_bottom_block_quantile.value), 0.0, 1.0))
        bottom_block_enabled = bool(self.buy_pair_dynrank_bottom_block_enabled.value)

        # Cohort-aware floor: tighter floor for pairs in certain cohorts
        cohort_floor_on = bool(self.buy_pair_dynrank_cohort_floor_enabled.value)
        cohort_fl_small = float(self.buy_pair_dynrank_cohort_floor_small.value) if cohort_floor_on else floor
        cohort_fl_major = float(self.buy_pair_dynrank_cohort_floor_major.value) if cohort_floor_on else floor

        for pair, score, conf, _ in scored:
            lower_count = sum(1 for s in sorted_scores if s < score)
            equal_count = sum(1 for s in sorted_scores if s == score)
            pct = (lower_count + (equal_count - 1) / 2.0) / last_idx
            pct = float(np.clip(pct, 0.0, 1.0))
            pct_out[pair] = pct
            # Determine effective floor for this pair
            pair_floor = floor
            if cohort_floor_on:
                cohort = self._pair_cohort(pair)
                if cohort == "small":
                    pair_floor = cohort_fl_small
                elif cohort == "major":
                    pair_floor = cohort_fl_major
            mult_raw = pair_floor + pct * (ceiling - pair_floor)
            mult = 1.0 + (mult_raw - 1.0) * conf
            if bottom_block_enabled and pct <= bottom_q:
                mult = min(mult, pair_floor)
            out[pair] = float(np.clip(mult, pair_floor, ceiling))

        self._pair_dynrank_cache = {ts_key: out}
        self._pair_dynrank_pct_cache = {ts_key: pct_out}
        return out

    def _pair_dynrank_blocks_entry(self, pair: str, current_time: datetime | None) -> bool:
        if not bool(self.buy_pair_dynrank_enabled.value):
            return False
        if not bool(self.buy_pair_dynrank_bottom_block_enabled.value):
            return False
        try:
            ts_key = self._reg_alloc_ts_key(current_time)
            pct_map = self._pair_dynrank_pct_cache.get(ts_key)
            if pct_map is None:
                # Ensure snapshot/pct cache are hydrated for this timestamp.
                self._pair_dynrank_snapshot(current_time)
                pct_map = self._pair_dynrank_pct_cache.get(ts_key)
            if not pct_map:
                return False
            q = float(np.clip(float(self.buy_pair_dynrank_bottom_block_quantile.value), 0.0, 1.0))
            pct = pct_map.get(pair)
            if pct is None:
                return False
            blocked = bool(float(pct) <= q)
            if blocked:
                self._pair_dynrank_counts["entry_blocks"] = float(self._pair_dynrank_counts.get("entry_blocks", 0.0)) + 1.0
            return blocked
        except Exception:
            return False

    _COHORT_MAJORS_BASE = frozenset({"BTC", "ETH"})
    _COHORT_MIDS_BASE = frozenset({
        "LINK", "LTC", "DOT", "ADA",
        "ATOM", "UNI", "NEAR", "ETC",
        "FIL", "DOGE", "TRX",
    })

    def _pair_cohort(self, pair: str) -> str:
        base = self._pair_base_asset(pair)
        if base in self._COHORT_MAJORS_BASE:
            return "major"
        if base in self._COHORT_MIDS_BASE:
            return "mid"
        return "small"

    def _pair_cohort_mult(self, pair: str) -> float:
        if not bool(self.buy_cohort_cap_enabled.value):
            return 1.0
        cohort = self._pair_cohort(pair)
        if cohort == "major":
            return float(self.buy_cohort_cap_major_mult.value)
        if cohort == "mid":
            return float(self.buy_cohort_cap_mid_mult.value)
        return float(self.buy_cohort_cap_small_mult.value)

    def _pair_dynrank_mult(self, pair: str, current_time: datetime | None) -> float:
        if not bool(self.buy_pair_dynrank_enabled.value):
            return 1.0

        self._pair_dynrank_counts["calls"] = float(self._pair_dynrank_counts.get("calls", 0.0)) + 1.0
        try:
            snapshot = self._pair_dynrank_snapshot(current_time)
            mult = float(snapshot.get(pair, 1.0))
            if pair not in snapshot:
                self._pair_dynrank_counts["insufficient"] = float(self._pair_dynrank_counts.get("insufficient", 0.0)) + 1.0
                return 1.0
            floor = float(self.buy_pair_dynrank_floor.value)
            ceiling = float(self.buy_pair_dynrank_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(ceiling, 1.0)
            mult = float(np.clip(mult, floor, ceiling))
            self._pair_dynrank_counts["applied"] = float(self._pair_dynrank_counts.get("applied", 0.0)) + 1.0
            self._pair_dynrank_counts["mult_sum"] = float(self._pair_dynrank_counts.get("mult_sum", 0.0)) + mult
            if abs(mult - floor) < 1e-9:
                self._pair_dynrank_counts["floor_hits"] = float(self._pair_dynrank_counts.get("floor_hits", 0.0)) + 1.0
            if abs(mult - ceiling) < 1e-9:
                self._pair_dynrank_counts["ceiling_hits"] = float(self._pair_dynrank_counts.get("ceiling_hits", 0.0)) + 1.0
            if bool(self.buy_pair_dynrank_debug.value):
                logger.info("PAIR_DYNRANK pair=%s ts=%s mult=%.3f", pair, self._reg_alloc_ts_key(current_time), mult)
            return mult
        except Exception:
            self._pair_dynrank_counts["fallback"] = float(self._pair_dynrank_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    # ── Per-pair microstructure scoring (funding rate z-score → stake mult) ──

    def _load_pair_micro_if_needed(self) -> None:
        try:
            raw = Path(str(self.pair_funding_daily_file))
            path = raw if raw.is_absolute() else (Path.cwd() / raw)
            if not path.exists():
                self._pair_micro_df = None
                self._pair_micro_by_pair_date = {}
                return
            mtime = float(path.stat().st_mtime)
            if (self._pair_micro_df is not None) and (mtime == self._pair_micro_mtime):
                return

            df = pd.read_csv(path)
            if df.empty:
                self._pair_micro_df = None
                self._pair_micro_by_pair_date = {}
                self._pair_micro_mtime = mtime
                return

            # Build lookup: pair → date → {funding_rate_mean, funding_rate_sum, ...}
            by_pd: dict[str, dict[str, dict[str, float]]] = {}
            for _, row in df.iterrows():
                pair = str(row.get("pair", ""))
                date = str(row.get("date", ""))
                if not pair or not date:
                    continue
                if pair not in by_pd:
                    by_pd[pair] = {}
                by_pd[pair][date] = {
                    "funding_rate_mean": float(row.get("funding_rate_mean", 0.0)),
                    "funding_rate_sum": float(row.get("funding_rate_sum", 0.0)),
                    "funding_rate_abs_sum": float(row.get("funding_rate_abs_sum", 0.0)),
                    "funding_rate_count": float(row.get("funding_rate_count", 0.0)),
                }

            self._pair_micro_df = df
            self._pair_micro_by_pair_date = by_pd
            self._pair_micro_mtime = mtime
        except Exception:
            self._pair_micro_df = None
            self._pair_micro_by_pair_date = {}

    def _pair_micro_funding_zscore(self, pair: str, current_time: datetime | None) -> float:
        """
        Compute cross-pair z-score: how does THIS pair's recent mean funding
        compare to ALL pairs' recent mean funding on the same dates?
        High positive z-score = this pair's funding is unusually high vs peers → crowded long.
        Returns 0.0 if insufficient data.
        """
        if current_time is None:
            return 0.0
        self._load_pair_micro_if_needed()
        if not self._pair_micro_by_pair_date:
            return 0.0

        lookback = max(1, int(self.buy_pair_micro_funding_lookback_days.value))
        dt = current_time if hasattr(current_time, "strftime") else pd.Timestamp(current_time, tz="UTC")

        # Build date list
        dates: list[str] = []
        for d in range(lookback):
            try:
                dates.append((dt - pd.Timedelta(days=d)).strftime("%Y-%m-%d"))
            except Exception:
                continue

        if not dates:
            return 0.0

        # Get this pair's mean funding over lookback
        pair_data = self._pair_micro_by_pair_date.get(pair)
        if not pair_data:
            return 0.0
        pair_rates = [pair_data[day]["funding_rate_mean"] for day in dates if day in pair_data]
        if len(pair_rates) < 2:
            return 0.0
        pair_mean = sum(pair_rates) / len(pair_rates)

        # Get all pairs' mean funding over the same dates
        all_means: list[float] = []
        for p, pdata in self._pair_micro_by_pair_date.items():
            p_rates = [pdata[day]["funding_rate_mean"] for day in dates if day in pdata]
            if len(p_rates) >= 2:
                all_means.append(sum(p_rates) / len(p_rates))

        if len(all_means) < 3:
            return 0.0

        cross_mu = sum(all_means) / len(all_means)
        cross_var = sum((m - cross_mu) ** 2 for m in all_means) / max(1, len(all_means) - 1)
        cross_std = cross_var ** 0.5
        if cross_std < 1e-12:
            return 0.0

        return (pair_mean - cross_mu) / cross_std

    def _pair_micro_mult(self, pair: str, current_time: datetime | None) -> float:
        """
        Microstructure-based stake multiplier.
        Crowded-long (high positive funding z-score) → penalize new longs.
        Crowded-short (high negative funding z-score) → boost new longs.
        Neutral → 1.0.
        """
        if not bool(self.buy_pair_micro_enabled.value):
            return 1.0

        self._pair_micro_counts["calls"] = self._pair_micro_counts.get("calls", 0.0) + 1.0
        try:
            zscore = self._pair_micro_funding_zscore(pair, current_time)
            if zscore == 0.0:
                self._pair_micro_counts["missing"] = self._pair_micro_counts.get("missing", 0.0) + 1.0
                return 1.0

            floor = float(self.buy_pair_micro_funding_zscore_floor.value)
            ceiling = float(self.buy_pair_micro_funding_zscore_ceiling.value)
            extreme_pct = float(self.buy_pair_micro_funding_extreme_pct.value)

            if zscore >= extreme_pct:
                # Crowded long → penalize
                intensity = min(1.0, (zscore - extreme_pct) / max(0.5, extreme_pct))
                mult = 1.0 - (1.0 - floor) * (0.5 + 0.5 * intensity)
                self._pair_micro_counts["penalty_hits"] = self._pair_micro_counts.get("penalty_hits", 0.0) + 1.0
            elif zscore <= -extreme_pct:
                # Crowded short → boost longs
                intensity = min(1.0, (-zscore - extreme_pct) / max(0.5, extreme_pct))
                mult = 1.0 + (ceiling - 1.0) * (0.5 + 0.5 * intensity)
                self._pair_micro_counts["boost_hits"] = self._pair_micro_counts.get("boost_hits", 0.0) + 1.0
            else:
                mult = 1.0

            mult = float(np.clip(mult, floor, ceiling))
            self._pair_micro_counts["applied"] = self._pair_micro_counts.get("applied", 0.0) + 1.0

            if bool(self.buy_pair_micro_debug.value):
                logger.info("PAIR_MICRO pair=%s zscore=%.3f mult=%.3f", pair, zscore, mult)
            return mult
        except Exception:
            self._pair_micro_counts["fallback"] = self._pair_micro_counts.get("fallback", 0.0) + 1.0
            return 1.0

    # ── Fear & Greed sentiment overlay ──

    def _load_fng_if_needed(self) -> None:
        try:
            raw = Path(str(self.fng_daily_file))
            path = raw if raw.is_absolute() else (Path.cwd() / raw)
            if not path.exists():
                self._fng_by_date = {}
                return
            mtime = float(path.stat().st_mtime)
            if self._fng_by_date and mtime == self._fng_mtime:
                return

            df = pd.read_csv(path)
            by_date: dict[str, int] = {}
            for _, row in df.iterrows():
                d = str(row.get("date", ""))
                v = int(row.get("fng_value", 50))
                if d:
                    by_date[d] = v
            self._fng_by_date = by_date
            self._fng_mtime = mtime
        except Exception:
            self._fng_by_date = {}

    def _fng_mult(self, current_time: datetime | None) -> float:
        """
        Market-wide sentiment overlay:
        - Extreme Fear (<threshold) → reduce sizing (fear_mult < 1.0)
        - Extreme Greed (>threshold) → boost sizing (greed_mult > 1.0)
        - Neutral → 1.0
        """
        if not bool(self.buy_fng_enabled.value):
            return 1.0
        if current_time is None:
            return 1.0

        self._fng_counts["calls"] = self._fng_counts.get("calls", 0.0) + 1.0
        try:
            self._load_fng_if_needed()
            if not self._fng_by_date:
                self._fng_counts["missing"] = self._fng_counts.get("missing", 0.0) + 1.0
                return 1.0

            lookback = max(1, int(self.buy_fng_lookback_days.value))
            dt = current_time if hasattr(current_time, "strftime") else pd.Timestamp(current_time, tz="UTC")
            values: list[int] = []
            for d in range(lookback):
                try:
                    day = (dt - pd.Timedelta(days=d)).strftime("%Y-%m-%d")
                except Exception:
                    continue
                v = self._fng_by_date.get(day)
                if v is not None:
                    values.append(v)

            if not values:
                self._fng_counts["missing"] = self._fng_counts.get("missing", 0.0) + 1.0
                return 1.0

            avg_fng = sum(values) / len(values)
            fear_thr = int(self.buy_fng_fear_threshold.value)
            greed_thr = int(self.buy_fng_greed_threshold.value)

            if avg_fng <= fear_thr:
                mult = float(self.buy_fng_fear_mult.value)
                self._fng_counts["fear_hits"] = self._fng_counts.get("fear_hits", 0.0) + 1.0
            elif avg_fng >= greed_thr:
                mult = float(self.buy_fng_greed_mult.value)
                self._fng_counts["greed_hits"] = self._fng_counts.get("greed_hits", 0.0) + 1.0
            else:
                mult = 1.0
                self._fng_counts["neutral"] = self._fng_counts.get("neutral", 0.0) + 1.0

            if bool(self.buy_fng_debug.value):
                logger.info("FNG fng=%.1f mult=%.3f fear_thr=%d greed_thr=%d", avg_fng, mult, fear_thr, greed_thr)
            return mult
        except Exception:
            self._fng_counts["fallback"] = self._fng_counts.get("fallback", 0.0) + 1.0
            return 1.0

    # ── BTC On-Chain Regime Gate ──────────────────────────────

    def _load_onchain_if_needed(self) -> None:
        try:
            raw = Path(str(self.btc_onchain_daily_file))
            path = raw if raw.is_absolute() else (Path.cwd() / raw)
            if not path.exists():
                self._onchain_by_date = {}
                return
            mtime = float(path.stat().st_mtime)
            if self._onchain_by_date and mtime == self._onchain_mtime:
                return
            df = pd.read_csv(path)
            by_date: dict[str, dict[str, float]] = {}
            for _, row in df.iterrows():
                d = str(row.get("date", ""))
                if d:
                    by_date[d] = {
                        "active_addresses": float(row.get("active_addresses", 0) or 0),
                        "exchange_netflow_btc": float(row.get("exchange_netflow_btc", 0) or 0),
                    }
            self._onchain_by_date = by_date
            self._onchain_mtime = mtime
        except Exception:
            self._onchain_by_date = {}

    def _onchain_regime_mult(self, current_time: datetime | None) -> float:
        """
        BTC on-chain regime gate: extends 2D regime to 3D.
        Active addresses rising + exchange outflow → bullish → boost
        Active addresses falling + exchange inflow → bearish → penalize
        """
        if not bool(self.buy_onchain_regime_enabled.value):
            return 1.0
        if current_time is None:
            return 1.0

        self._onchain_counts["calls"] = self._onchain_counts.get("calls", 0.0) + 1.0
        try:
            self._load_onchain_if_needed()
            if not self._onchain_by_date:
                self._onchain_counts["missing"] = self._onchain_counts.get("missing", 0.0) + 1.0
                return 1.0

            dt = current_time if hasattr(current_time, "strftime") else pd.Timestamp(current_time, tz="UTC")
            addr_lb = max(3, int(self.buy_onchain_addr_lookback.value))
            flow_lb = max(3, int(self.buy_onchain_flow_lookback.value))

            # Collect active address and netflow values over lookback windows
            addr_values: list[float] = []
            flow_values: list[float] = []
            max_lb = max(addr_lb, flow_lb)
            for d in range(max_lb):
                try:
                    day = (dt - pd.Timedelta(days=d + 1)).strftime("%Y-%m-%d")
                except Exception:
                    continue
                entry = self._onchain_by_date.get(day)
                if entry:
                    if d < addr_lb:
                        addr_values.append(entry["active_addresses"])
                    if d < flow_lb:
                        flow_values.append(entry["exchange_netflow_btc"])

            if len(addr_values) < 5 or len(flow_values) < 3:
                self._onchain_counts["missing"] = self._onchain_counts.get("missing", 0.0) + 1.0
                return 1.0

            # Compute z-scores: recent vs lookback
            import statistics
            addr_mean = statistics.mean(addr_values)
            addr_std = statistics.stdev(addr_values) if len(addr_values) > 1 else 1.0
            addr_recent = statistics.mean(addr_values[:min(7, len(addr_values))])
            addr_zscore = (addr_recent - addr_mean) / max(addr_std, 1.0)

            flow_mean = statistics.mean(flow_values)
            flow_std = statistics.stdev(flow_values) if len(flow_values) > 1 else 1.0
            flow_zscore = (flow_mean) / max(flow_std, 1.0)  # positive = net inflow (bearish)

            addr_bull_thr = float(self.buy_onchain_addr_zscore_bull.value)
            flow_bear_thr = float(self.buy_onchain_flow_zscore_bear.value)

            # Classification: bullish when addr rising AND net outflow, bearish when opposite
            is_bull = (addr_zscore > addr_bull_thr) and (flow_zscore < 0)
            is_bear = (addr_zscore < -abs(addr_bull_thr)) or (flow_zscore > flow_bear_thr)

            if is_bull:
                mult = float(self.buy_onchain_bull_mult.value)
                self._onchain_counts["bull_hits"] = self._onchain_counts.get("bull_hits", 0.0) + 1.0
            elif is_bear:
                mult = float(self.buy_onchain_bear_mult.value)
                self._onchain_counts["bear_hits"] = self._onchain_counts.get("bear_hits", 0.0) + 1.0
            else:
                mult = 1.0
                self._onchain_counts["neutral"] = self._onchain_counts.get("neutral", 0.0) + 1.0

            if bool(self.buy_onchain_debug.value):
                logger.info(
                    "ONCHAIN addr_z=%.2f flow_z=%.2f bull=%s bear=%s mult=%.3f",
                    addr_zscore, flow_zscore, is_bull, is_bear, mult,
                )
            return mult
        except Exception:
            self._onchain_counts["fallback"] = self._onchain_counts.get("fallback", 0.0) + 1.0
            return 1.0

    # ── Pair Attention Standalone Multiplier ──────────────────

    def _pair_attention_mult(self, pair: str, current_time: datetime | None,
                             row: pd.Series | dict | None = None) -> float:
        """
        Standalone pair attention multiplier (when mode=standalone_mult).
        Uses volume z-score from dataframe row.
        """
        if not bool(self.buy_pair_attention_enabled.value):
            return 1.0
        if str(self.buy_pair_attention_mode.value) != "standalone_mult":
            return 1.0
        if row is None:
            return 1.0

        self._pair_attention_counts["calls"] = self._pair_attention_counts.get("calls", 0.0) + 1.0
        try:
            zscore = float(row.get("attention_vol_zscore", 0.0) or 0.0)
            if not np.isfinite(zscore):
                zscore = 0.0

            low_thr = float(self.buy_pair_attention_low_thr.value)
            high_thr = float(self.buy_pair_attention_high_thr.value)

            if zscore >= high_thr:
                mult = float(self.buy_pair_attention_high_mult.value)
                self._pair_attention_counts["high_hits"] = self._pair_attention_counts.get("high_hits", 0.0) + 1.0
            elif zscore <= low_thr:
                mult = float(self.buy_pair_attention_low_mult.value)
                self._pair_attention_counts["low_hits"] = self._pair_attention_counts.get("low_hits", 0.0) + 1.0
            else:
                mult = 1.0
                self._pair_attention_counts["neutral"] = self._pair_attention_counts.get("neutral", 0.0) + 1.0

            if bool(self.buy_pair_attention_debug.value):
                logger.info(
                    "PAIR_ATTENTION pair=%s zscore=%.2f mult=%.3f",
                    pair, zscore, mult,
                )
            return mult
        except Exception:
            self._pair_attention_counts["fallback"] = self._pair_attention_counts.get("fallback", 0.0) + 1.0
            return 1.0

    def _vol_target_mult(self, pair: str, current_time: datetime | None) -> float:
        if not bool(self.buy_vol_target_enabled.value):
            return 1.0

        self._vol_target_counts["calls"] = float(self._vol_target_counts.get("calls", 0.0)) + 1.0
        cache_key = (str(pair or ""), self._reg_alloc_ts_key(current_time))
        cached = self._vol_target_cache.get(cache_key)
        if cached is not None:
            self._vol_target_counts["cache_hits"] = float(self._vol_target_counts.get("cache_hits", 0.0)) + 1.0
            mult = float(cached)
            self._vol_target_counts["applied"] = float(self._vol_target_counts.get("applied", 0.0)) + 1.0
            self._vol_target_counts["mult_sum"] = float(self._vol_target_counts.get("mult_sum", 0.0)) + mult
            return mult

        try:
            tf = str(self.buy_vol_target_source_tf.value)
            period = max(1, int(self.buy_vol_target_atr_period.value))
            atr_pct = self._atr_pct_at_time(pair, tf, current_time, period, debug_log=False)
            if atr_pct is None or atr_pct <= 0:
                self._vol_target_counts["fallback"] = float(self._vol_target_counts.get("fallback", 0.0)) + 1.0
                self._vol_target_cache[cache_key] = 1.0
                return 1.0

            target = max(1e-6, float(self.buy_vol_target_target_atr_pct.value))
            strength = max(0.0, float(self.buy_vol_target_strength.value))
            floor = float(self.buy_vol_target_floor.value)
            ceiling = float(self.buy_vol_target_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(ceiling, 1.0)

            raw = float((target / float(atr_pct)) ** strength) if strength > 0 else 1.0
            mult = float(np.clip(raw, floor, ceiling))
            self._vol_target_cache[cache_key] = mult
            self._vol_target_counts["applied"] = float(self._vol_target_counts.get("applied", 0.0)) + 1.0
            self._vol_target_counts["mult_sum"] = float(self._vol_target_counts.get("mult_sum", 0.0)) + mult
            if abs(mult - floor) < 1e-9:
                self._vol_target_counts["floor_hits"] = float(self._vol_target_counts.get("floor_hits", 0.0)) + 1.0
            if abs(mult - ceiling) < 1e-9:
                self._vol_target_counts["ceiling_hits"] = float(self._vol_target_counts.get("ceiling_hits", 0.0)) + 1.0
            if bool(self.buy_vol_target_debug.value):
                logger.info(
                    "VOL_TARGET pair=%s ts=%s tf=%s atr_pct=%.5f target=%.5f mult=%.3f",
                    pair,
                    self._reg_alloc_ts_key(current_time),
                    tf,
                    float(atr_pct),
                    target,
                    mult,
                )
            return mult
        except Exception:
            self._vol_target_counts["fallback"] = float(self._vol_target_counts.get("fallback", 0.0)) + 1.0
            self._vol_target_cache[cache_key] = 1.0
            return 1.0

    @staticmethod
    def _row_pick_float(row: pd.Series | dict | None, keys: list[str]) -> float | None:
        if row is None:
            return None
        for k in keys:
            try:
                v = row.get(k) if isinstance(row, (dict, pd.Series)) else None
                if v is None:
                    continue
                vf = float(v)
                if np.isfinite(vf):
                    return vf
            except Exception:
                continue
        return None

    @staticmethod
    def _df_pick_numeric_series(
        df: pd.DataFrame | None,
        keys: list[str],
    ) -> tuple[pd.Series | None, str | None]:
        if df is None or df.empty:
            return None, None
        for k in keys:
            try:
                if k in df.columns:
                    s = pd.to_numeric(df[k], errors="coerce")
                    if isinstance(s, pd.Series) and s.notna().any():
                        return s, k
            except Exception:
                continue
        return None, None

    def _base_deriv_basis_needed(self) -> bool:
        try:
            return (
                bool(self.buy_basis_rank_enabled.value)
                or bool(self.buy_deriv_dq_use_basis.value)
                or bool(self.buy_crowding_overlay_use_basis.value)
                or (bool(self.buy_crowding_block_enabled.value) and bool(self.buy_crowding_overlay_use_basis.value))
            )
        except Exception:
            return False

    @staticmethod
    def _basis_proxy_keys() -> list[str]:
        return [
            "deriv_basis",
            "deriv_premium",
            "basis",
            "basis_pct",
            "perp_basis",
            "premium_index",
            "perp_premium",
        ]

    @staticmethod
    def _merge_asof_numeric_series(
        base_df: pd.DataFrame | None,
        src_df: pd.DataFrame | None,
        value_col: str,
    ) -> pd.Series:
        if base_df is None or base_df.empty:
            return pd.Series(dtype=float)
        out = pd.Series(np.nan, index=base_df.index, dtype=float)
        if (
            src_df is None
            or src_df.empty
            or "date" not in base_df.columns
            or "date" not in src_df.columns
            or value_col not in src_df.columns
        ):
            return out
        left = pd.DataFrame(
            {"date": pd.to_datetime(base_df["date"], utc=True, errors="coerce")},
            index=base_df.index,
        ).dropna(subset=["date"])
        if left.empty:
            return out
        right = pd.DataFrame(
            {
                "date": pd.to_datetime(src_df["date"], utc=True, errors="coerce"),
                value_col: pd.to_numeric(src_df[value_col], errors="coerce"),
            }
        ).dropna(subset=["date"]).sort_values("date")
        if right.empty:
            return out
        left_sorted = left.sort_values("date")
        merged = pd.merge_asof(left_sorted, right, on="date", direction="backward")
        out.loc[left_sorted.index] = pd.to_numeric(merged[value_col], errors="coerce").values
        return out

    def _compute_deriv_basis_proxy(
        self,
        base_df: pd.DataFrame,
        pair: str,
        timeframe: str,
    ) -> dict[str, pd.Series]:
        out = {
            "deriv_mark_close": pd.Series(np.nan, index=base_df.index, dtype=float),
            "deriv_index_close": pd.Series(np.nan, index=base_df.index, dtype=float),
            "deriv_basis": pd.Series(np.nan, index=base_df.index, dtype=float),
            "deriv_premium": pd.Series(np.nan, index=base_df.index, dtype=float),
        }
        if base_df is None or base_df.empty:
            return out

        close = pd.to_numeric(base_df.get("close"), errors="coerce")
        if not isinstance(close, pd.Series):
            close = pd.Series(np.nan, index=base_df.index, dtype=float)

        for candle_type, key in (("mark", "deriv_mark_close"), ("index", "deriv_index_close")):
            try:
                src_df = self.dp.get_pair_dataframe(pair=pair, timeframe=timeframe, candle_type=candle_type)
            except Exception:
                src_df = None
            if src_df is None or src_df.empty:
                continue
            src = src_df.copy()
            src[key] = pd.to_numeric(src.get("close"), errors="coerce")
            out[key] = self._merge_asof_numeric_series(base_df, src, key)

        mark_close = out["deriv_mark_close"]
        index_close = out["deriv_index_close"]
        basis = pd.Series(np.nan, index=base_df.index, dtype=float)
        if mark_close.notna().any() and index_close.notna().any():
            basis = ((mark_close - index_close) / index_close.replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)
        elif close.notna().any() and index_close.notna().any():
            basis = ((close - index_close) / index_close.replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)
        elif close.notna().any() and mark_close.notna().any():
            basis = ((close - mark_close) / mark_close.replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)

        out["deriv_basis"] = basis
        out["deriv_premium"] = basis.copy()
        return out

    def _add_deriv_basis_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        if not self._base_deriv_basis_needed():
            return dataframe
        proxy = self._compute_deriv_basis_proxy(dataframe, pair, str(self.timeframe))
        dataframe["deriv_mark_close"] = proxy["deriv_mark_close"]
        dataframe["deriv_index_close"] = proxy["deriv_index_close"]
        dataframe["deriv_basis"] = proxy["deriv_basis"]
        dataframe["deriv_premium"] = proxy["deriv_premium"]
        return dataframe

    @staticmethod
    def _series_latest_zscore(series: pd.Series | None, lookback: int) -> float | None:
        if series is None:
            return None
        try:
            vals = pd.to_numeric(series, errors="coerce").dropna().tail(max(10, int(lookback)))
            if vals.size < 10:
                return None
            cur = float(vals.iloc[-1])
            base = vals.iloc[:-1]
            if base.size < 8:
                return None
            mu = float(base.mean())
            sd = float(base.std(ddof=0))
            if not np.isfinite(sd) or sd <= 1e-12:
                return None
            z = (cur - mu) / sd
            if np.isfinite(z):
                return float(z)
        except Exception:
            return None
        return None

    def _funding_rate_at_or_before_time(
        self,
        pair: str,
        timeframe: str,
        current_time: datetime | None,
    ) -> float | None:
        try:
            fr = self.dp.get_pair_dataframe(pair=pair, timeframe=timeframe, candle_type="funding_rate")
            if fr is None or fr.empty:
                return None
            work = fr.copy()
            if "date" in work.columns and current_time is not None:
                ts = pd.Timestamp(current_time)
                if ts.tzinfo is None:
                    ts = ts.tz_localize("UTC")
                else:
                    ts = ts.tz_convert("UTC")
                work = work.loc[pd.to_datetime(work["date"], utc=True, errors="coerce") <= ts]
            if work is None or work.empty:
                return None
            for col in ("funding_rate", "close", "value", "funding"):
                if col in work.columns:
                    s = pd.to_numeric(work[col], errors="coerce").dropna()
                    if not s.empty:
                        val = float(s.iloc[-1])
                        if np.isfinite(val):
                            return val
            return None
        except Exception:
            return None

    def _deriv_dq_allows(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> tuple[bool, str]:
        self._deriv_dq_inc("calls")
        if not bool(self.buy_deriv_dq_enabled.value):
            self._deriv_dq_inc("pass")
            return True, "disabled"
        if bool(self.buy_deriv_dq_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            self._deriv_dq_inc("scope_skip")
            return True, "scope_skip"

        try:
            allow_csv = str(self.buy_deriv_dq_tag_allowlist.value or "").strip()
            if allow_csv:
                allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
                if allow:
                    bucket = str(self._tag_bucket(entry_tag)).lower()
                    bucket = self._router_v2_norm_bucket(bucket)
                    if bucket not in allow:
                        self._deriv_dq_inc("tag_skip")
                        return True, "tag_skip"

            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            if probe is None:
                self._deriv_dq_inc("no_row")
                self._deriv_dq_inc("fallback")
                return True, "no_row_fail_open"
            if isinstance(probe, pd.Series):
                probe = probe.copy()
            elif isinstance(probe, dict):
                probe = dict(probe)

            if bool(self.buy_deriv_dq_regime_filter_enabled.value):
                regime_csv = str(self.buy_deriv_dq_regime_filter_tokens.value or "").strip().upper()
                if regime_csv:
                    gate_toks = {x.strip() for x in regime_csv.split(",") if x.strip()}
                    regime_val = ""
                    if isinstance(probe, (pd.Series, dict)):
                        regime_val = str(probe.get("composite_regime", "")).upper()
                    if gate_toks and (not any(tok in regime_val for tok in gate_toks)):
                        self._deriv_dq_inc("scope_skip_regime")
                        return True, "scope_skip_regime"

            df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
            if df is None or df.empty:
                self._deriv_dq_inc("no_df")
                self._deriv_dq_inc("fallback")
                return True, "no_df_fail_open"
            work = df.copy()
            if current_time is not None and "date" in work.columns:
                ts = pd.Timestamp(current_time)
                if ts.tzinfo is None:
                    ts = ts.tz_localize("UTC")
                else:
                    ts = ts.tz_convert("UTC")
                work = work.loc[pd.to_datetime(work["date"], utc=True, errors="coerce") <= ts]
            if work is None or work.empty:
                self._deriv_dq_inc("no_df")
                self._deriv_dq_inc("fallback")
                return True, "no_df_fail_open"

            lookback = max(10, int(self.buy_deriv_dq_z_lookback.value))
            z_max = max(0.0, float(self.buy_deriv_dq_z_max.value))
            stale_bars = max(2, int(self.buy_deriv_dq_stale_bars.value))

            funding_keys = [
                "funding_rate",
                "funding",
                "perp_funding",
                "mark_funding_rate",
                "future_funding_rate",
                "funding_rate_1h",
                "funding_rate_4h",
            ]
            oi_keys = [
                "oi_change_pct",
                "open_interest_change_pct",
                "open_interest_pct_change",
                "oi_change",
                "oi_change_pct_1h",
                "oi_change_pct_4h",
                "oi_change_pct_5m",
            ]
            oi_abs_keys = ["open_interest", "openInterest", "oi", "oi_abs"]
            basis_keys = self._basis_proxy_keys()

            if bool(self.buy_deriv_dq_use_funding.value):
                fr_existing = self._row_pick_float(probe, funding_keys)
                if fr_existing is None:
                    fr_fallback = self._funding_rate_at_or_before_time(pair, str(self.timeframe), current_time)
                    if fr_fallback is not None and isinstance(probe, (pd.Series, dict)):
                        probe["funding_rate"] = float(fr_fallback)

            proxy_good = 0
            proxy_missing = 0
            proxy_invalid = 0

            def _check_proxy(
                enabled: bool,
                keys: list[str],
                abs_cap: float,
            ) -> None:
                nonlocal proxy_good, proxy_missing, proxy_invalid
                if not enabled:
                    return
                cur = self._row_pick_float(probe, keys)
                if cur is None or (not np.isfinite(float(cur))):
                    proxy_missing += 1
                    return
                valid = True
                if abs(float(cur)) > float(abs_cap):
                    valid = False
                series, _ = self._df_pick_numeric_series(work, keys)
                if valid and series is not None:
                    z = self._series_latest_zscore(series, lookback)
                    if z is not None and abs(float(z)) > z_max:
                        valid = False
                    tail = pd.to_numeric(series, errors="coerce").dropna().tail(stale_bars)
                    if tail.size >= stale_bars and int(tail.nunique()) <= 1:
                        valid = False
                if valid:
                    proxy_good += 1
                else:
                    proxy_invalid += 1

            _check_proxy(
                bool(self.buy_deriv_dq_use_funding.value),
                funding_keys,
                float(self.buy_deriv_dq_funding_abs_max.value),
            )
            _check_proxy(
                bool(self.buy_deriv_dq_use_oi.value),
                oi_keys,
                float(self.buy_deriv_dq_oi_abs_max.value),
            )
            _check_proxy(
                bool(self.buy_deriv_dq_use_basis.value),
                basis_keys,
                float(self.buy_deriv_dq_basis_abs_max.value),
            )

            # OI absolute delta vs volume sanity check (when absolute OI series is available).
            if bool(self.buy_deriv_dq_use_oi.value):
                oi_abs_s, _ = self._df_pick_numeric_series(work, oi_abs_keys)
                vol_s, _ = self._df_pick_numeric_series(work, ["volume"])
                if oi_abs_s is not None and vol_s is not None:
                    try:
                        oi_tail = pd.to_numeric(oi_abs_s, errors="coerce").dropna().tail(2)
                        vol_tail = pd.to_numeric(vol_s, errors="coerce").dropna().tail(1)
                        if oi_tail.size >= 2 and vol_tail.size >= 1:
                            oi_delta = abs(float(oi_tail.iloc[-1] - oi_tail.iloc[-2]))
                            vol_now = abs(float(vol_tail.iloc[-1]))
                            mult = max(0.0, float(self.buy_deriv_dq_oi_delta_volume_mult.value))
                            if np.isfinite(oi_delta) and np.isfinite(vol_now) and vol_now > 0 and oi_delta > (vol_now * mult):
                                proxy_invalid += 1
                    except Exception:
                        pass

            req = max(1, int(self.buy_deriv_dq_require_proxy_count.value))
            if proxy_good >= req:
                self._deriv_dq_inc("pass")
                return True, "pass"

            if proxy_missing > 0:
                self._deriv_dq_inc("missing_proxy")
            if proxy_invalid > 0:
                self._deriv_dq_inc("invalid_proxy")

            if proxy_invalid > 0:
                self._deriv_dq_inc("block")
                if bool(self.buy_deriv_dq_debug.value):
                    logger.info(
                        "DERIV_DQ_BLOCK pair=%s tag=%s side=%s reason=invalid_proxy good=%s missing=%s invalid=%s",
                        pair,
                        str(entry_tag or ""),
                        str(side or ""),
                        proxy_good,
                        proxy_missing,
                        proxy_invalid,
                    )
                return False, "invalid_proxy"

            if proxy_good < req:
                self._deriv_dq_inc("insufficient")
                if bool(self.buy_deriv_dq_allow_missing.value):
                    self._deriv_dq_inc("fallback")
                    return True, "insufficient_fail_open"
                self._deriv_dq_inc("block")
                return False, "insufficient_proxy"

            self._deriv_dq_inc("pass")
            return True, "pass"
        except Exception:
            self._deriv_dq_inc("fallback")
            return True, "exception_fail_open"

    def _deriv_dq_block_mode_value(self) -> str:
        try:
            mode = str(self.buy_deriv_dq_block_mode.value or "hard").strip().lower()
        except Exception:
            mode = "hard"
        if mode not in {"hard", "hybrid", "soft_only"}:
            mode = "hard"
        if mode != "hard" and (not bool(self.buy_deriv_dq_soft_enabled.value)):
            return "hard"
        return mode

    def _deriv_dq_should_block(self, reason: str) -> bool:
        mode = self._deriv_dq_block_mode_value()
        if mode == "hard":
            return True
        if mode == "soft_only":
            return False
        severe = {"invalid_proxy"}
        return str(reason or "").strip().lower() in severe

    def _causal_gate_allows(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> tuple[bool, str]:
        self._causal_gate_inc("calls")
        if not bool(self.buy_causal_gate_enabled.value):
            self._causal_gate_inc("pass")
            return True, "disabled"
        if bool(self.buy_causal_gate_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            self._causal_gate_inc("scope_skip")
            return True, "scope_skip"

        try:
            allow_csv = str(self.buy_causal_gate_tag_allowlist.value or "").strip()
            if allow_csv:
                allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
                if allow:
                    bucket = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
                    if bucket not in allow:
                        self._causal_gate_inc("tag_skip")
                        return True, "tag_skip"

            probe_row = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            if isinstance(probe_row, pd.Series):
                probe_row = probe_row.copy()
            elif isinstance(probe_row, dict):
                probe_row = dict(probe_row)
            else:
                probe_row = None

            if bool(self.buy_causal_gate_regime_filter_enabled.value):
                regime_csv = str(self.buy_causal_gate_regime_filter_tokens.value or "").strip().upper()
                if regime_csv:
                    gate_toks = {x.strip() for x in regime_csv.split(",") if x.strip()}
                    regime_val = ""
                    if isinstance(probe_row, (pd.Series, dict)):
                        regime_val = str(probe_row.get("composite_regime", "")).upper()
                    if gate_toks and (not any(tok in regime_val for tok in gate_toks)):
                        self._causal_gate_inc("scope_skip_regime")
                        return True, "scope_skip_regime"

            tf = str(self.buy_causal_gate_tf.value or self.timeframe)
            lookback = max(20, int(self.buy_causal_gate_lookback_bars.value))
            min_overlap = max(8, int(self.buy_causal_gate_min_overlap.value))
            max_lag = max(1, int(self.buy_causal_gate_max_lag.value))
            min_abs_corr = max(0.0, float(self.buy_causal_gate_min_abs_corr.value))
            min_pred = max(0.0, float(self.buy_causal_gate_min_pred_return.value))

            pair_rets = self._corr_cap_series_at_or_before_time(pair, tf, current_time, lookback + max_lag + 5)
            btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
            btc_rets = self._corr_cap_series_at_or_before_time(btc_pair, tf, current_time, lookback + max_lag + 5)
            if pair_rets is None or btc_rets is None or pair_rets.empty or btc_rets.empty:
                self._causal_gate_inc("no_data")
                return False, "no_data"

            best_corr = None
            best_lag = 0
            for lag in range(1, max_lag + 1):
                aligned = pd.concat(
                    [
                        pair_rets.rename("y"),
                        btc_rets.shift(lag).rename("x"),
                    ],
                    axis=1,
                ).dropna()
                if aligned.empty or len(aligned) < min_overlap:
                    continue
                corr = float(aligned["y"].corr(aligned["x"]))
                if not np.isfinite(corr):
                    continue
                if best_corr is None or abs(corr) > abs(float(best_corr)):
                    best_corr = corr
                    best_lag = lag

            if best_corr is None:
                self._causal_gate_inc("insufficient")
                return False, "insufficient_overlap"

            if abs(float(best_corr)) < min_abs_corr:
                self._causal_gate_inc("block_corr")
                return False, "corr_below_min"

            btc_now = float(btc_rets.iloc[-1])
            pred = float(best_corr) * btc_now
            side_l = str(side or "long").lower()
            if side_l == "long":
                if pred < min_pred:
                    self._causal_gate_inc("block_pred")
                    return False, "pred_not_supportive"
            else:
                if pred > -min_pred:
                    self._causal_gate_inc("block_pred")
                    return False, "pred_not_supportive"

            probe = probe_row if probe_row is not None else self._pair_row_at_or_before_time(pair, current_time)
            if isinstance(probe, pd.Series):
                probe = probe.copy()
            elif isinstance(probe, dict):
                probe = dict(probe)
            if bool(self.buy_causal_gate_require_deriv_proxy.value):
                fr_existing = self._row_pick_float(
                    probe,
                    [
                        "funding_rate",
                        "funding",
                        "perp_funding",
                        "mark_funding_rate",
                        "future_funding_rate",
                        "funding_rate_1h",
                        "funding_rate_4h",
                    ],
                )
                if fr_existing is None and bool(self.buy_causal_gate_use_funding.value):
                    fr_fallback = self._funding_rate_at_or_before_time(pair, str(self.timeframe), current_time)
                    if fr_fallback is not None and isinstance(probe, (pd.Series, dict)):
                        probe["funding_rate"] = float(fr_fallback)
                funding = self._row_pick_float(
                    probe,
                    [
                        "funding_rate",
                        "funding",
                        "perp_funding",
                        "mark_funding_rate",
                        "future_funding_rate",
                        "funding_rate_1h",
                        "funding_rate_4h",
                    ],
                )
                oi = self._row_pick_float(
                    probe,
                    [
                        "oi_change_pct",
                        "open_interest_change_pct",
                        "open_interest_pct_change",
                        "oi_change",
                        "oi_change_pct_1h",
                        "oi_change_pct_4h",
                    ],
                )
                have = 0
                adverse = False
                if bool(self.buy_causal_gate_use_funding.value) and funding is not None and np.isfinite(float(funding)):
                    have += 1
                    if side_l == "long":
                        adverse = adverse or (float(funding) > float(self.buy_causal_gate_funding_pos_max.value))
                    else:
                        adverse = adverse or (float(funding) < float(self.buy_causal_gate_funding_neg_min.value))
                if bool(self.buy_causal_gate_use_oi.value) and oi is not None and np.isfinite(float(oi)):
                    have += 1
                    if side_l == "long":
                        adverse = adverse or (float(oi) > float(self.buy_causal_gate_oi_pos_max.value))
                    else:
                        adverse = adverse or (float(oi) < float(self.buy_causal_gate_oi_neg_min.value))

                if have <= 0:
                    self._causal_gate_inc("block_deriv")
                    return False, "no_deriv_proxy"
                if adverse:
                    self._causal_gate_inc("block_deriv")
                    return False, "adverse_deriv_flow"

            self._causal_gate_inc("pass")
            if bool(self.buy_causal_gate_debug.value):
                logger.info(
                    "CAUSAL_GATE_PASS pair=%s side=%s tag=%s tf=%s lag=%s corr=%.4f btc_ret=%.5f pred=%.5f",
                    pair,
                    side_l,
                    str(entry_tag or ""),
                    tf,
                    best_lag,
                    float(best_corr),
                    btc_now,
                    pred,
                )
            return True, "pass"
        except Exception:
            self._causal_gate_inc("fallback")
            return True, "exception_fail_open"

    def _causal_gate_block_mode_value(self) -> str:
        try:
            mode = str(self.buy_causal_gate_block_mode.value or "hard").strip().lower()
        except Exception:
            mode = "hard"
        if mode not in {"hard", "hybrid", "soft_only"}:
            mode = "hard"
        if mode != "hard" and (not bool(self.buy_causal_gate_soft_enabled.value)):
            return "hard"
        return mode

    def _causal_gate_should_block(self, reason: str) -> bool:
        mode = self._causal_gate_block_mode_value()
        if mode == "hard":
            return True
        if mode == "soft_only":
            return False
        severe = {"adverse_deriv_flow"}
        return str(reason or "").strip().lower() in severe

    def _deriv_dq_soft_mult(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> float:
        if not bool(self.buy_deriv_dq_soft_enabled.value):
            return 1.0
        self._deriv_dq_soft_inc("calls")
        try:
            if bool(self.buy_deriv_dq_soft_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
                self._deriv_dq_soft_inc("scope_skip")
                return 1.0

            allow_csv = str(self.buy_deriv_dq_soft_tag_allowlist.value or "").strip()
            if allow_csv:
                allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
                if allow:
                    bucket = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
                    if bucket not in allow:
                        self._deriv_dq_soft_inc("tag_skip")
                        return 1.0

            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            if isinstance(probe, pd.Series):
                probe = probe.copy()
            elif isinstance(probe, dict):
                probe = dict(probe)

            if bool(self.buy_deriv_dq_regime_filter_enabled.value):
                regime_csv = str(self.buy_deriv_dq_regime_filter_tokens.value or "").strip().upper()
                if regime_csv:
                    gate_toks = {x.strip() for x in regime_csv.split(",") if x.strip()}
                    regime_val = ""
                    if isinstance(probe, (pd.Series, dict)):
                        regime_val = str(probe.get("composite_regime", "")).upper()
                    if gate_toks and (not any(tok in regime_val for tok in gate_toks)):
                        self._deriv_dq_soft_inc("scope_skip_regime")
                        return 1.0

            if probe is None:
                mult = float(self.buy_deriv_dq_soft_insufficient_mult.value)
                floor = float(self.buy_deriv_dq_soft_floor.value)
                ceil = float(self.buy_deriv_dq_soft_ceiling.value)
                mult = float(np.clip(mult, min(floor, ceil), max(floor, ceil)))
                self._deriv_dq_soft_inc("insufficient")
                self._deriv_dq_soft_inc("applied")
                self._deriv_dq_soft_inc("mult_sum", mult)
                return mult

            df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
            work = df.copy() if (df is not None and not df.empty) else None
            if work is not None and current_time is not None and "date" in work.columns:
                ts = pd.Timestamp(current_time)
                if ts.tzinfo is None:
                    ts = ts.tz_localize("UTC")
                else:
                    ts = ts.tz_convert("UTC")
                work = work.loc[pd.to_datetime(work["date"], utc=True, errors="coerce") <= ts]

            lookback = max(10, int(self.buy_deriv_dq_z_lookback.value))
            z_max = max(0.0, float(self.buy_deriv_dq_z_max.value))
            stale_bars = max(2, int(self.buy_deriv_dq_stale_bars.value))

            funding_keys = [
                "funding_rate",
                "funding",
                "perp_funding",
                "mark_funding_rate",
                "future_funding_rate",
                "funding_rate_1h",
                "funding_rate_4h",
            ]
            oi_keys = [
                "oi_change_pct",
                "open_interest_change_pct",
                "open_interest_pct_change",
                "oi_change",
                "oi_change_pct_1h",
                "oi_change_pct_4h",
                "oi_change_pct_5m",
            ]
            oi_abs_keys = ["open_interest", "openInterest", "oi", "oi_abs"]
            basis_keys = self._basis_proxy_keys()

            if bool(self.buy_deriv_dq_use_funding.value):
                fr_existing = self._row_pick_float(probe, funding_keys)
                if fr_existing is None:
                    fr_fallback = self._funding_rate_at_or_before_time(pair, str(self.timeframe), current_time)
                    if fr_fallback is not None:
                        probe["funding_rate"] = float(fr_fallback)

            proxy_good = 0
            proxy_missing = 0
            proxy_invalid = 0

            def _check_proxy(enabled: bool, keys: list[str], abs_cap: float) -> None:
                nonlocal proxy_good, proxy_missing, proxy_invalid
                if not enabled:
                    return
                cur = self._row_pick_float(probe, keys)
                if cur is None or (not np.isfinite(float(cur))):
                    proxy_missing += 1
                    return
                valid = True
                if abs(float(cur)) > float(abs_cap):
                    valid = False
                if work is not None and not work.empty:
                    series, _ = self._df_pick_numeric_series(work, keys)
                    if valid and series is not None:
                        z = self._series_latest_zscore(series, lookback)
                        if z is not None and abs(float(z)) > z_max:
                            valid = False
                        tail = pd.to_numeric(series, errors="coerce").dropna().tail(stale_bars)
                        if tail.size >= stale_bars and int(tail.nunique()) <= 1:
                            valid = False
                if valid:
                    proxy_good += 1
                else:
                    proxy_invalid += 1

            _check_proxy(
                bool(self.buy_deriv_dq_use_funding.value),
                funding_keys,
                float(self.buy_deriv_dq_funding_abs_max.value),
            )
            _check_proxy(
                bool(self.buy_deriv_dq_use_oi.value),
                oi_keys,
                float(self.buy_deriv_dq_oi_abs_max.value),
            )
            _check_proxy(
                bool(self.buy_deriv_dq_use_basis.value),
                basis_keys,
                float(self.buy_deriv_dq_basis_abs_max.value),
            )

            if bool(self.buy_deriv_dq_use_oi.value) and work is not None and not work.empty:
                oi_abs_s, _ = self._df_pick_numeric_series(work, oi_abs_keys)
                vol_s, _ = self._df_pick_numeric_series(work, ["volume"])
                if oi_abs_s is not None and vol_s is not None:
                    try:
                        oi_tail = pd.to_numeric(oi_abs_s, errors="coerce").dropna().tail(2)
                        vol_tail = pd.to_numeric(vol_s, errors="coerce").dropna().tail(1)
                        if oi_tail.size >= 2 and vol_tail.size >= 1:
                            oi_delta = abs(float(oi_tail.iloc[-1] - oi_tail.iloc[-2]))
                            vol_now = abs(float(vol_tail.iloc[-1]))
                            mult = max(0.0, float(self.buy_deriv_dq_oi_delta_volume_mult.value))
                            if np.isfinite(oi_delta) and np.isfinite(vol_now) and vol_now > 0 and oi_delta > (vol_now * mult):
                                proxy_invalid += 1
                    except Exception:
                        pass

            req = max(1, int(self.buy_deriv_dq_require_proxy_count.value))
            reason = "pass"
            mult = 1.0
            if proxy_invalid > 0:
                reason = "invalid"
                mult = float(self.buy_deriv_dq_soft_invalid_mult.value)
                self._deriv_dq_soft_inc("invalid")
            elif proxy_good < req:
                reason = "insufficient"
                mult = float(self.buy_deriv_dq_soft_insufficient_mult.value)
                self._deriv_dq_soft_inc("insufficient")

            floor = float(self.buy_deriv_dq_soft_floor.value)
            ceil = float(self.buy_deriv_dq_soft_ceiling.value)
            mult = float(np.clip(mult, min(floor, ceil), max(floor, ceil)))
            self._deriv_dq_soft_inc("applied")
            self._deriv_dq_soft_inc("mult_sum", mult)
            if bool(self.buy_deriv_dq_soft_debug.value):
                logger.info(
                    "DERIV_DQ_SOFT pair=%s side=%s tag=%s reason=%s good=%s missing=%s invalid=%s mult=%.3f",
                    pair,
                    str(side or ""),
                    str(entry_tag or ""),
                    reason,
                    proxy_good,
                    proxy_missing,
                    proxy_invalid,
                    mult,
                )
            return mult
        except Exception:
            self._deriv_dq_soft_inc("fallback")
            return 1.0

    def _causal_gate_soft_mult(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> float:
        if not bool(self.buy_causal_gate_soft_enabled.value):
            return 1.0
        self._causal_gate_soft_inc("calls")
        try:
            if bool(self.buy_causal_gate_soft_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
                self._causal_gate_soft_inc("scope_skip")
                return 1.0

            allow_csv = str(self.buy_causal_gate_soft_tag_allowlist.value or "").strip()
            if allow_csv:
                allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
                if allow:
                    bucket = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
                    if bucket not in allow:
                        self._causal_gate_soft_inc("tag_skip")
                        return 1.0

            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            if isinstance(probe, pd.Series):
                probe = probe.copy()
            elif isinstance(probe, dict):
                probe = dict(probe)

            if bool(self.buy_causal_gate_regime_filter_enabled.value):
                regime_csv = str(self.buy_causal_gate_regime_filter_tokens.value or "").strip().upper()
                if regime_csv:
                    gate_toks = {x.strip() for x in regime_csv.split(",") if x.strip()}
                    regime_val = ""
                    if isinstance(probe, (pd.Series, dict)):
                        regime_val = str(probe.get("composite_regime", "")).upper()
                    if gate_toks and (not any(tok in regime_val for tok in gate_toks)):
                        self._causal_gate_soft_inc("scope_skip_regime")
                        return 1.0

            tf = str(self.buy_causal_gate_tf.value or self.timeframe)
            lookback = max(20, int(self.buy_causal_gate_lookback_bars.value))
            min_overlap = max(8, int(self.buy_causal_gate_min_overlap.value))
            max_lag = max(1, int(self.buy_causal_gate_max_lag.value))
            min_abs_corr = max(0.0, float(self.buy_causal_gate_min_abs_corr.value))
            min_pred = max(0.0, float(self.buy_causal_gate_min_pred_return.value))
            side_l = str(side or "long").lower()

            pair_rets = self._corr_cap_series_at_or_before_time(pair, tf, current_time, lookback + max_lag + 5)
            btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
            btc_rets = self._corr_cap_series_at_or_before_time(btc_pair, tf, current_time, lookback + max_lag + 5)

            reason = "pass"
            mult = 1.0
            if pair_rets is None or btc_rets is None or pair_rets.empty or btc_rets.empty:
                reason = "no_data"
                mult = float(self.buy_causal_gate_soft_no_data_mult.value)
                self._causal_gate_soft_inc("no_data")
            else:
                best_corr = None
                for lag in range(1, max_lag + 1):
                    aligned = pd.concat([pair_rets.rename("y"), btc_rets.shift(lag).rename("x")], axis=1).dropna()
                    if aligned.empty or len(aligned) < min_overlap:
                        continue
                    corr = float(aligned["y"].corr(aligned["x"]))
                    if not np.isfinite(corr):
                        continue
                    if best_corr is None or abs(corr) > abs(float(best_corr)):
                        best_corr = corr

                if best_corr is None:
                    reason = "insufficient"
                    mult = float(self.buy_causal_gate_soft_no_data_mult.value)
                    self._causal_gate_soft_inc("insufficient")
                else:
                    btc_now = float(btc_rets.iloc[-1])
                    pred = float(best_corr) * btc_now
                    if abs(float(best_corr)) < min_abs_corr:
                        reason = "corr"
                        mult = float(self.buy_causal_gate_soft_corr_mult.value)
                        self._causal_gate_soft_inc("corr")
                    elif (side_l == "long" and pred < min_pred) or (side_l != "long" and pred > -min_pred):
                        reason = "pred"
                        mult = float(self.buy_causal_gate_soft_pred_mult.value)
                        self._causal_gate_soft_inc("pred")

                    if reason == "pass" and bool(self.buy_causal_gate_require_deriv_proxy.value):
                        funding = self._row_pick_float(
                            probe,
                            [
                                "funding_rate",
                                "funding",
                                "perp_funding",
                                "mark_funding_rate",
                                "future_funding_rate",
                                "funding_rate_1h",
                                "funding_rate_4h",
                            ],
                        )
                        if funding is None and bool(self.buy_causal_gate_use_funding.value):
                            fr_fallback = self._funding_rate_at_or_before_time(pair, str(self.timeframe), current_time)
                            if fr_fallback is not None and isinstance(probe, (pd.Series, dict)):
                                probe["funding_rate"] = float(fr_fallback)
                                funding = float(fr_fallback)
                        oi = self._row_pick_float(
                            probe,
                            [
                                "oi_change_pct",
                                "open_interest_change_pct",
                                "open_interest_pct_change",
                                "oi_change",
                                "oi_change_pct_1h",
                                "oi_change_pct_4h",
                            ],
                        )
                        have = 0
                        adverse = False
                        if bool(self.buy_causal_gate_use_funding.value) and funding is not None and np.isfinite(float(funding)):
                            have += 1
                            if side_l == "long":
                                adverse = adverse or (float(funding) > float(self.buy_causal_gate_funding_pos_max.value))
                            else:
                                adverse = adverse or (float(funding) < float(self.buy_causal_gate_funding_neg_min.value))
                        if bool(self.buy_causal_gate_use_oi.value) and oi is not None and np.isfinite(float(oi)):
                            have += 1
                            if side_l == "long":
                                adverse = adverse or (float(oi) > float(self.buy_causal_gate_oi_pos_max.value))
                            else:
                                adverse = adverse or (float(oi) < float(self.buy_causal_gate_oi_neg_min.value))
                        if have <= 0 or adverse:
                            reason = "deriv"
                            mult = float(self.buy_causal_gate_soft_deriv_mult.value)
                            self._causal_gate_soft_inc("deriv")

            floor = float(self.buy_causal_gate_soft_floor.value)
            ceil = float(self.buy_causal_gate_soft_ceiling.value)
            mult = float(np.clip(mult, min(floor, ceil), max(floor, ceil)))
            self._causal_gate_soft_inc("applied")
            self._causal_gate_soft_inc("mult_sum", mult)
            if bool(self.buy_causal_gate_soft_debug.value):
                logger.info(
                    "CAUSAL_GATE_SOFT pair=%s side=%s tag=%s reason=%s mult=%.3f",
                    pair,
                    side_l,
                    str(entry_tag or ""),
                    reason,
                    mult,
                )
            return mult
        except Exception:
            self._causal_gate_soft_inc("fallback")
            return 1.0

    def _atp_breadth(
        self,
        current_time: datetime | None,
        tf: str,
        lookback: int,
        mom_bars: int,
        min_samples: int,
        max_pairs: int,
    ) -> tuple[float | None, int]:
        self._atp_init_state()
        key = f"{self._reg_alloc_ts_key(current_time)}|{tf}|{lookback}|{mom_bars}|{max_pairs}"
        cached = self._atp_breadth_cache.get(key)
        if cached is not None:
            self._atp_inc("breadth_cache_hits", 1.0)
            return float(cached[0]), int(cached[1])

        pairs = list(self.dp.current_whitelist() or [])
        if not pairs:
            return None, 0
        max_pairs = max(1, int(max_pairs))
        if len(pairs) > max_pairs:
            pairs = pairs[:max_pairs]

        pos = 0
        valid = 0
        mb = max(2, int(mom_bars))
        for p in pairs:
            rets = self._corr_cap_series_at_or_before_time(p, tf, current_time, lookback)
            if rets is None or len(rets) < int(min_samples):
                continue
            tail = rets.tail(mb)
            if tail.empty:
                continue
            mu = float(tail.mean())
            if not np.isfinite(mu):
                continue
            valid += 1
            if mu > 0:
                pos += 1

        if valid <= 0:
            return None, 0
        breadth = float(pos / max(1, valid))
        if len(self._atp_breadth_cache) > 2000:
            try:
                for stale_k in list(self._atp_breadth_cache.keys())[:500]:
                    self._atp_breadth_cache.pop(stale_k, None)
            except Exception:
                self._atp_breadth_cache = {}
        self._atp_breadth_cache[key] = (breadth, valid)
        return breadth, valid

    def _atp_mult(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> float:
        self._atp_inc("calls", 1.0)
        if not bool(self.buy_atp_enabled.value):
            return 1.0

        try:
            if bool(self.buy_atp_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
                self._atp_inc("scope_skip", 1.0)
                return 1.0

            allow_csv = str(self.buy_atp_tag_allowlist.value or "").strip()
            if allow_csv:
                allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
                if allow:
                    bucket = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
                    if bucket not in allow:
                        self._atp_inc("tag_skip", 1.0)
                        return 1.0

            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            if bool(self.buy_atp_regime_gate_enabled.value):
                reg = str(probe.get("composite_regime", "") if isinstance(probe, (pd.Series, dict)) else "").upper()
                gate_tokens = {
                    t.strip().upper()
                    for t in str(self.buy_atp_regime_gate_tokens.value or "").split(",")
                    if t.strip()
                }
                if gate_tokens and (not any(t in reg for t in gate_tokens)):
                    self._atp_inc("gated_off", 1.0)
                    return 1.0

            tf = str(self.buy_atp_tf.value or self.timeframe)
            lookback = max(20, int(self.buy_atp_lookback_bars.value))
            mom_bars = max(2, int(self.buy_atp_mom_bars.value))
            min_samples = max(6, int(self.buy_atp_min_samples.value))
            max_pairs = max(1, int(self.buy_atp_breadth_max_pairs.value))

            rets = self._corr_cap_series_at_or_before_time(pair, tf, current_time, lookback)
            if rets is None or len(rets) < min_samples:
                self._atp_inc("insufficient", 1.0)
                return 1.0
            tail = rets.tail(mom_bars)
            if tail.empty:
                self._atp_inc("insufficient", 1.0)
                return 1.0
            mu = float(tail.mean())
            sd = float(tail.std(ddof=0))
            mom_sh = mu / max(sd, 1e-9)
            mom_score = float(np.clip((mom_sh + 1.5) / 3.0, 0.0, 1.0))

            adx = self._row_pick_float(probe, ["adx", "trbk_adx", "cbx_adx"])
            adx_floor = float(self.buy_atp_adx_floor.value)
            adx_cap = max(adx_floor + 1e-6, float(self.buy_atp_adx_cap.value))
            if adx is None or (not np.isfinite(float(adx))):
                adx_score = 0.5
            else:
                adx_score = float(np.clip((float(adx) - adx_floor) / (adx_cap - adx_floor), 0.0, 1.0))

            pair_score = 0.5 * mom_score + 0.5 * adx_score

            breadth, breadth_n = self._atp_breadth(
                current_time=current_time,
                tf=tf,
                lookback=lookback,
                mom_bars=mom_bars,
                min_samples=min_samples,
                max_pairs=max_pairs,
            )
            if breadth is None or breadth_n < 1:
                self._atp_inc("insufficient", 1.0)
                return 1.0

            w_pair = max(0.0, float(self.buy_atp_w_pair.value))
            w_breadth = max(0.0, float(self.buy_atp_w_breadth.value))
            w_mom = max(0.0, float(self.buy_atp_w_mom.value))
            w_sum = max(1e-9, w_pair + w_breadth + w_mom)
            score = ((w_pair * pair_score) + (w_breadth * float(breadth)) + (w_mom * mom_score)) / w_sum

            scale = max(0.0, float(self.buy_atp_scale.value))
            floor = float(self.buy_atp_floor.value)
            ceiling = float(self.buy_atp_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(1.0, ceiling)

            centered = (float(score) - 0.5) * 2.0
            if bool(self.buy_atp_use_asym_scale.value):
                scale_up = max(0.0, float(self.buy_atp_scale_up.value))
                scale_down = max(0.0, float(self.buy_atp_scale_down.value))
                if centered >= 0.0:
                    raw = 1.0 + centered * scale_up
                else:
                    raw = 1.0 + centered * scale_down
            else:
                raw = 1.0 + centered * scale
            mult = float(np.clip(raw, floor, ceiling))
            if bool(self.buy_atp_hysteresis_enabled.value):
                try:
                    key = f"{pair}|{str(side or '').lower()}"
                    hold_delta = max(0.0, float(self.buy_atp_hysteresis_min_delta.value))
                    ttl_bars = max(1, int(self.buy_atp_hysteresis_ttl_bars.value))
                    tf_minutes = max(1, int(self._timeframe_to_minutes(tf)))
                    ttl_seconds = float(ttl_bars * tf_minutes * 60)
                    now_ts = current_time if isinstance(current_time, datetime) else None
                    cached = self._atp_hysteresis_cache.get(key)
                    if cached is not None and now_ts is not None:
                        prev_mult, prev_ts = float(cached[0]), cached[1]
                        age_s = (now_ts - prev_ts).total_seconds()
                        if age_s >= 0 and age_s <= ttl_seconds and abs(mult - prev_mult) < hold_delta:
                            mult = float(prev_mult)
                            self._atp_inc("hysteresis_holds", 1.0)
                        else:
                            self._atp_inc("hysteresis_updates", 1.0)
                    else:
                        self._atp_inc("hysteresis_updates", 1.0)
                    if now_ts is not None:
                        self._atp_hysteresis_cache[key] = (float(mult), now_ts)
                    # Keep cache bounded.
                    if len(self._atp_hysteresis_cache) > 5000:
                        for stale_k in list(self._atp_hysteresis_cache.keys())[:1000]:
                            self._atp_hysteresis_cache.pop(stale_k, None)
                except Exception:
                    pass
            self._atp_inc("applied", 1.0)
            self._atp_inc("mult_sum", mult)
            if abs(mult - floor) < 1e-12:
                self._atp_inc("floor_hits", 1.0)
            if abs(mult - ceiling) < 1e-12:
                self._atp_inc("ceiling_hits", 1.0)
            if bool(self.buy_atp_debug.value):
                logger.info(
                    "ATP pair=%s side=%s tag=%s tf=%s score=%.3f pair_score=%.3f breadth=%.3f breadth_n=%s mom=%.3f adx=%.3f mult=%.3f",
                    pair,
                    str(side or ""),
                    str(entry_tag or ""),
                    tf,
                    float(score),
                    float(pair_score),
                    float(breadth),
                    int(breadth_n),
                    float(mom_score),
                    float(adx_score),
                    mult,
                )
            return mult
        except Exception:
            self._atp_inc("fallback", 1.0)
            return 1.0

    def _cost_gate_min_buffer_pct(self, entry_tag: str | None, composite_regime: str) -> float:
        base = max(0.0, float(self.buy_cost_gate_min_edge_buffer_pct.value))
        try:
            rawmap = self._csv_kv_float_map(str(self.buy_cost_gate_override_map.value or ""))
            if not rawmap:
                return base
            sleeve = self._reg_alloc_sleeve_from_tag(entry_tag)
            for tok in self._regime_tokens(composite_regime):
                k = f"{sleeve}:{tok}".lower()
                if k in rawmap and np.isfinite(float(rawmap[k])):
                    return max(0.0, float(rawmap[k]))
            k_def = f"{sleeve}:default".lower()
            if k_def in rawmap and np.isfinite(float(rawmap[k_def])):
                return max(0.0, float(rawmap[k_def]))
        except Exception:
            return base
        return base

    def _portfolio_current_dd_pct(self) -> float:
        try:
            if not self._portfolio_vol_returns:
                return 0.0
            eq = 1.0
            peak = 1.0
            dd = 0.0
            for r in self._portfolio_vol_returns:
                eq *= max(1e-6, 1.0 + float(r))
                peak = max(peak, eq)
                dd = max(dd, (peak - eq) / max(peak, 1e-6))
            return float(np.clip(dd * 100.0, 0.0, 100.0))
        except Exception:
            return 0.0

    def _portfolio_vol_target_mult(self, composite_regime: str = "") -> float:
        if not bool(self.buy_portfolio_vol_target_enabled.value):
            return 1.0
        self._portfolio_vol_counts["calls"] = float(self._portfolio_vol_counts.get("calls", 0.0)) + 1.0
        try:
            lookback = max(2, int(self.buy_portfolio_vol_target_lookback_trades.value))
            xs = [float(x) for x in list(self._portfolio_vol_returns)[-lookback:] if np.isfinite(float(x))]
            if len(xs) < 2:
                self._portfolio_vol_counts["insufficient"] = float(self._portfolio_vol_counts.get("insufficient", 0.0)) + 1.0
                return 1.0

            sigma_raw = float(np.std(xs, ddof=1))
            alpha = float(np.clip(float(self.buy_portfolio_vol_target_ewma_alpha.value), 0.01, 1.0))
            if self._portfolio_vol_sigma_ewma is None or not np.isfinite(float(self._portfolio_vol_sigma_ewma)):
                self._portfolio_vol_sigma_ewma = sigma_raw
            else:
                self._portfolio_vol_sigma_ewma = alpha * sigma_raw + (1.0 - alpha) * float(self._portfolio_vol_sigma_ewma)
            sigma_eff = max(1e-6, float(self._portfolio_vol_sigma_ewma))

            target = max(1e-6, float(self.buy_portfolio_vol_target_target_sigma.value))
            floor = float(self.buy_portfolio_vol_target_floor.value)
            ceiling = float(self.buy_portfolio_vol_target_ceiling.value)
            hard_cap = max(1.0, float(self.buy_portfolio_vol_target_hard_cap.value))

            # Two-speed mode: stress settings when stress regime OR drawdown is elevated.
            is_stress = False
            if bool(self.buy_portfolio_vol_target_regime_gate_enabled.value):
                gate_tokens = {
                    x.strip().upper()
                    for x in str(self.buy_portfolio_vol_target_regime_gate_tokens.value or "").split(",")
                    if x and x.strip()
                }
                reg_toks = self._regime_tokens(composite_regime)
                dd_now = self._portfolio_current_dd_pct()
                dd_gate = float(self.buy_portfolio_vol_target_stress_dd_activate_pct.value)
                stress_by_regime = bool(gate_tokens and any(t in gate_tokens for t in reg_toks))
                stress_by_dd = bool(dd_now >= dd_gate)
                is_stress = stress_by_regime or stress_by_dd
                if not is_stress:
                    self._portfolio_vol_counts["gated_off"] = float(self._portfolio_vol_counts.get("gated_off", 0.0)) + 1.0
                    return 1.0

            if is_stress:
                target = max(1e-6, float(self.buy_portfolio_vol_target_stress_target_sigma.value))
                floor = float(self.buy_portfolio_vol_target_stress_floor.value)
                ceiling = float(self.buy_portfolio_vol_target_stress_ceiling.value)
                self._portfolio_vol_counts["stress_mode"] = float(self._portfolio_vol_counts.get("stress_mode", 0.0)) + 1.0
            else:
                self._portfolio_vol_counts["normal_mode"] = float(self._portfolio_vol_counts.get("normal_mode", 0.0)) + 1.0

            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = min(max(ceiling, 1.0), hard_cap)

            raw = float(target / sigma_eff)
            mult = float(np.clip(raw, floor, ceiling))
            self._portfolio_vol_counts["applied"] = float(self._portfolio_vol_counts.get("applied", 0.0)) + 1.0
            self._portfolio_vol_counts["mult_sum"] = float(self._portfolio_vol_counts.get("mult_sum", 0.0)) + mult
            if abs(mult - floor) < 1e-9:
                self._portfolio_vol_counts["floor_hits"] = float(self._portfolio_vol_counts.get("floor_hits", 0.0)) + 1.0
            if abs(mult - ceiling) < 1e-9:
                self._portfolio_vol_counts["ceiling_hits"] = float(self._portfolio_vol_counts.get("ceiling_hits", 0.0)) + 1.0
            if bool(self.buy_portfolio_vol_target_debug.value):
                logger.info("PORTFOLIO_VOL_TARGET sigma_raw=%.5f sigma_ewma=%.5f target=%.5f mult=%.3f", sigma_raw, sigma_eff, target, mult)
            return mult
        except Exception:
            self._portfolio_vol_counts["fallback"] = float(self._portfolio_vol_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    def _crowding_proxy_quantiles(
        self,
        pair: str,
        current_time: datetime | None,
        keys: list[str],
        lookback: int,
        q_lo: float,
        q_hi: float,
    ) -> tuple[float | None, float | None]:
        try:
            df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
            if df is None or df.empty:
                return None, None
            if current_time is not None and "date" in df.columns:
                ts = pd.Timestamp(current_time)
                df = df.loc[df["date"] <= ts]
            if df is None or df.empty:
                return None, None
            s = None
            for k in keys:
                if k in df.columns:
                    s = pd.to_numeric(df[k], errors="coerce")
                    if s.notna().any():
                        break
            if s is None:
                return None, None
            vals = s.dropna()
            if vals.empty:
                return None, None
            vals = vals.tail(max(10, int(lookback)))
            if vals.size < 10:
                return None, None
            lo = float(vals.quantile(float(np.clip(q_lo, 0.0, 1.0))))
            hi = float(vals.quantile(float(np.clip(q_hi, 0.0, 1.0))))
            if not (np.isfinite(lo) and np.isfinite(hi)):
                return None, None
            return lo, hi
        except Exception:
            return None, None

    def _basis_rank_scope_applies(self, entry_tag: str | None) -> bool:
        try:
            if bool(self.buy_basis_rank_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
                return False
            allow_csv = str(self.buy_basis_rank_tag_allowlist.value or "").strip()
            if not allow_csv:
                return True
            allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
            if not allow:
                return True
            bucket = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
            return bucket in allow
        except Exception:
            return False

    def _basis_rank_snapshot(self, current_time: datetime | None) -> dict[str, float]:
        ts_key = self._reg_alloc_ts_key(current_time)
        cached = self._basis_rank_pct_cache.get(ts_key)
        if cached is not None:
            self._basis_rank_counts["cache_hits"] = float(self._basis_rank_counts.get("cache_hits", 0.0)) + 1.0
            return cached

        try:
            pairs = list(self.dp.current_whitelist())
        except Exception:
            pairs = []
        if not pairs:
            self._basis_rank_counts["insufficient"] = float(self._basis_rank_counts.get("insufficient", 0.0)) + 1.0
            self._basis_rank_pct_cache = {ts_key: {}}
            return {}

        scored: list[tuple[str, float]] = []
        for probe_pair in pairs:
            row = self._pair_row_at_or_before_time(probe_pair, current_time)
            basis = self._row_pick_float(row, self._basis_proxy_keys())
            if basis is None or (not np.isfinite(float(basis))):
                continue
            scored.append((probe_pair, float(basis)))

        if not scored:
            self._basis_rank_counts["insufficient"] = float(self._basis_rank_counts.get("insufficient", 0.0)) + 1.0
            self._basis_rank_pct_cache = {ts_key: {}}
            return {}

        sorted_vals = sorted(float(v) for _, v in scored)
        last_idx = max(1.0, float(len(sorted_vals) - 1))
        out: dict[str, float] = {}
        for probe_pair, basis in scored:
            lower_count = sum(1 for s in sorted_vals if s < basis)
            equal_count = sum(1 for s in sorted_vals if s == basis)
            pct = (lower_count + (equal_count - 1) / 2.0) / last_idx
            out[probe_pair] = float(np.clip(pct, 0.0, 1.0))

        self._basis_rank_pct_cache = {ts_key: out}
        return out

    def _basis_rank_mult(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> float:
        if not bool(self.buy_basis_rank_enabled.value):
            return 1.0
        self._basis_rank_counts["calls"] = float(self._basis_rank_counts.get("calls", 0.0)) + 1.0
        try:
            if not self._basis_rank_scope_applies(entry_tag):
                return 1.0

            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            basis = self._row_pick_float(probe, self._basis_proxy_keys())
            pct = self._basis_rank_snapshot(current_time).get(pair)
            if basis is None or pct is None or (not np.isfinite(float(basis))):
                self._basis_rank_counts["insufficient"] = float(self._basis_rank_counts.get("insufficient", 0.0)) + 1.0
                return 1.0

            cheap_q = float(np.clip(float(self.buy_basis_rank_cheap_quantile.value), 0.0, 1.0))
            exp_q = float(np.clip(float(self.buy_basis_rank_expensive_quantile.value), 0.0, 1.0))
            if exp_q < cheap_q:
                cheap_q, exp_q = exp_q, cheap_q
            require_negative = bool(self.buy_basis_rank_require_negative.value)
            basis_v = float(basis)
            pct_v = float(pct)

            side_l = str(side or "long").lower()
            cheap_long = bool(pct_v <= cheap_q) and (not require_negative or basis_v < 0.0)
            rich_long = bool(pct_v >= exp_q) or bool(require_negative and basis_v >= 0.0)
            cheap_short = bool(pct_v <= cheap_q)
            rich_short = bool(pct_v >= exp_q) and (not require_negative or basis_v > 0.0)

            mult = 1.0
            if side_l == "long":
                if cheap_long:
                    mult = float(self.buy_basis_rank_boost.value)
                    self._basis_rank_counts["cheap_hits"] = float(self._basis_rank_counts.get("cheap_hits", 0.0)) + 1.0
                elif rich_long:
                    mult = float(self.buy_basis_rank_penalty.value)
                    self._basis_rank_counts["expensive_hits"] = float(self._basis_rank_counts.get("expensive_hits", 0.0)) + 1.0
            else:
                if rich_short:
                    mult = float(self.buy_basis_rank_boost.value)
                    self._basis_rank_counts["cheap_hits"] = float(self._basis_rank_counts.get("cheap_hits", 0.0)) + 1.0
                elif cheap_short:
                    mult = float(self.buy_basis_rank_penalty.value)
                    self._basis_rank_counts["expensive_hits"] = float(self._basis_rank_counts.get("expensive_hits", 0.0)) + 1.0

            floor = float(self.buy_basis_rank_floor.value)
            ceiling = float(self.buy_basis_rank_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(ceiling, 1.0)
            mult = float(np.clip(mult, floor, ceiling))

            self._basis_rank_counts["applied"] = float(self._basis_rank_counts.get("applied", 0.0)) + 1.0
            self._basis_rank_counts["mult_sum"] = float(self._basis_rank_counts.get("mult_sum", 0.0)) + mult
            if bool(self.buy_basis_rank_debug.value):
                logger.info(
                    "BASIS_RANK pair=%s side=%s tag=%s basis=%.6f pct=%.3f mult=%.3f",
                    pair,
                    side_l,
                    str(entry_tag or ""),
                    basis_v,
                    pct_v,
                    mult,
                )
            return mult
        except Exception:
            self._basis_rank_counts["fallback"] = float(self._basis_rank_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    def _basis_rank_allows(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> tuple[bool, str]:
        if (not bool(self.buy_basis_rank_enabled.value)) or (not bool(self.buy_basis_rank_hard_gate.value)):
            return True, "disabled"
        try:
            if not self._basis_rank_scope_applies(entry_tag):
                return True, "scope_skip"
            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            basis = self._row_pick_float(probe, self._basis_proxy_keys())
            pct = self._basis_rank_snapshot(current_time).get(pair)
            if basis is None or pct is None or (not np.isfinite(float(basis))):
                self._basis_rank_counts["insufficient"] = float(self._basis_rank_counts.get("insufficient", 0.0)) + 1.0
                return True, "insufficient_fail_open"

            cheap_q = float(np.clip(float(self.buy_basis_rank_cheap_quantile.value), 0.0, 1.0))
            exp_q = float(np.clip(float(self.buy_basis_rank_expensive_quantile.value), 0.0, 1.0))
            if exp_q < cheap_q:
                cheap_q, exp_q = exp_q, cheap_q
            require_negative = bool(self.buy_basis_rank_require_negative.value)

            side_l = str(side or "long").lower()
            if side_l == "long":
                ok = bool(float(pct) <= cheap_q) and (not require_negative or float(basis) < 0.0)
                if ok:
                    return True, "pass"
                self._basis_rank_counts["entry_blocks"] = float(self._basis_rank_counts.get("entry_blocks", 0.0)) + 1.0
                return False, "not_cheap"

            ok = bool(float(pct) >= exp_q) and (not require_negative or float(basis) > 0.0)
            if ok:
                return True, "pass"
            self._basis_rank_counts["entry_blocks"] = float(self._basis_rank_counts.get("entry_blocks", 0.0)) + 1.0
            return False, "not_rich"
        except Exception:
            self._basis_rank_counts["fallback"] = float(self._basis_rank_counts.get("fallback", 0.0)) + 1.0
            return True, "exception_fail_open"

    def _crowding_state(
        self,
        pair: str,
        side: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
        require_proxy_count: int | None = None,
    ) -> dict[str, Any]:
        state: dict[str, Any] = {
            "ready": False,
            "insufficient": True,
            "crowded_long": False,
            "crowded_short": False,
            "proxy_present_count": 0,
            "funding": None,
            "basis": None,
            "oi": None,
        }
        try:
            probe = row
            if probe is None:
                probe, _, _ = self._rank_row_for_time(pair, current_time)
            if probe is None:
                probe = self._pair_row_at_or_before_time(pair, current_time)
            if probe is None:
                return state

            use_funding = bool(self.buy_crowding_overlay_use_funding.value)
            use_basis = bool(self.buy_crowding_overlay_use_basis.value)
            use_oi = bool(self.buy_crowding_overlay_use_oi.value)
            mode = str(self.buy_crowding_overlay_mode.value or "absolute").strip().lower()
            q_lookback = max(10, int(self.buy_crowding_overlay_quantile_lookback.value))
            q_lo = float(np.clip(float(self.buy_crowding_overlay_quantile_lo.value), 0.0, 1.0))
            q_hi = float(np.clip(float(self.buy_crowding_overlay_quantile_hi.value), 0.0, 1.0))
            if q_hi < q_lo:
                q_lo, q_hi = q_hi, q_lo

            funding = self._row_pick_float(
                probe,
                ["funding_rate", "funding", "perp_funding", "mark_funding_rate", "future_funding_rate", "funding_rate_1h", "funding_rate_4h"],
            )
            if funding is None and use_funding:
                funding = self._funding_rate_at_or_before_time(pair, str(self.timeframe), current_time)
            basis = self._row_pick_float(probe, self._basis_proxy_keys())
            oi = self._row_pick_float(
                probe,
                ["oi_change_pct", "open_interest_change_pct", "open_interest_pct_change", "oi_change", "oi_change_pct_1h", "oi_change_pct_4h"],
            )
            state["funding"] = funding
            state["basis"] = basis
            state["oi"] = oi

            def _proxy_eval(
                val: float | None,
                abs_long_thr: float,
                abs_short_thr: float,
                keys: list[str],
            ) -> tuple[bool | None, bool | None]:
                if val is None or (not np.isfinite(float(val))):
                    return None, None
                if mode != "percentile":
                    return bool(float(val) >= abs_long_thr), bool(float(val) <= abs_short_thr)
                lo, hi = self._crowding_proxy_quantiles(
                    pair=pair,
                    current_time=current_time,
                    keys=keys,
                    lookback=q_lookback,
                    q_lo=q_lo,
                    q_hi=q_hi,
                )
                if lo is None or hi is None:
                    return None, None
                return bool(float(val) >= float(hi)), bool(float(val) <= float(lo))

            long_hits = 0
            short_hits = 0
            proxy_present_count = 0
            if use_funding:
                c_long, c_short = _proxy_eval(
                    funding,
                    float(self.buy_crowding_overlay_funding_pos_min.value),
                    float(self.buy_crowding_overlay_funding_neg_max.value),
                    ["funding_rate", "funding", "perp_funding", "mark_funding_rate", "future_funding_rate", "funding_rate_1h", "funding_rate_4h"],
                )
                if c_long is not None:
                    proxy_present_count += 1
                    long_hits += int(bool(c_long))
                    short_hits += int(bool(c_short))
            if use_basis:
                c_long, c_short = _proxy_eval(
                    basis,
                    float(self.buy_crowding_overlay_basis_pos_min.value),
                    float(self.buy_crowding_overlay_basis_neg_max.value),
                    self._basis_proxy_keys(),
                )
                if c_long is not None:
                    proxy_present_count += 1
                    long_hits += int(bool(c_long))
                    short_hits += int(bool(c_short))
            if use_oi:
                c_long, c_short = _proxy_eval(
                    oi,
                    float(self.buy_crowding_overlay_oi_rising_min.value),
                    float(self.buy_crowding_overlay_oi_falling_min.value),
                    ["oi_change_pct", "open_interest_change_pct", "open_interest_pct_change", "oi_change", "oi_change_pct_1h", "oi_change_pct_4h"],
                )
                if c_long is not None:
                    proxy_present_count += 1
                    long_hits += int(bool(c_long))
                    short_hits += int(bool(c_short))

            req = max(
                1,
                int(
                    require_proxy_count
                    if require_proxy_count is not None
                    else int(self.buy_crowding_overlay_require_proxy_count.value)
                ),
            )
            state["proxy_present_count"] = proxy_present_count
            if proxy_present_count < req:
                return state

            state["ready"] = True
            state["insufficient"] = False
            state["crowded_long"] = bool(long_hits >= req)
            state["crowded_short"] = bool(short_hits >= req)
            return state
        except Exception:
            return state

    def _crowding_overlay_mult(
        self,
        pair: str,
        side: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> float:
        if not bool(self.buy_crowding_overlay_enabled.value):
            return 1.0
        self._crowding_overlay_counts["calls"] = float(self._crowding_overlay_counts.get("calls", 0.0)) + 1.0
        try:
            state = self._crowding_state(
                pair=pair,
                side=side,
                current_time=current_time,
                row=row,
                require_proxy_count=int(self.buy_crowding_overlay_require_proxy_count.value),
            )
            if not bool(state.get("ready", False)):
                self._crowding_overlay_counts["insufficient"] = float(self._crowding_overlay_counts.get("insufficient", 0.0)) + 1.0
                self._crowding_overlay_counts["no_proxy"] = float(self._crowding_overlay_counts.get("no_proxy", 0.0)) + 1.0
                return 1.0

            crowded_long = bool(state.get("crowded_long", False))
            crowded_short = bool(state.get("crowded_short", False))

            penalty = float(self.buy_crowding_overlay_penalty_mult.value)
            boost = float(self.buy_crowding_overlay_contrarian_boost.value)
            floor = float(self.buy_crowding_overlay_floor.value)
            ceiling = float(self.buy_crowding_overlay_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            floor = min(floor, 1.0)
            ceiling = max(1.0, ceiling)

            side_l = str(side or "long").lower()
            mult = 1.0
            if side_l == "long":
                if crowded_long:
                    mult = penalty
                    self._crowding_overlay_counts["penalty_hits"] = float(self._crowding_overlay_counts.get("penalty_hits", 0.0)) + 1.0
                elif crowded_short:
                    mult = boost
                    self._crowding_overlay_counts["boost_hits"] = float(self._crowding_overlay_counts.get("boost_hits", 0.0)) + 1.0
            else:
                if crowded_short:
                    mult = penalty
                    self._crowding_overlay_counts["penalty_hits"] = float(self._crowding_overlay_counts.get("penalty_hits", 0.0)) + 1.0
                elif crowded_long:
                    mult = boost
                    self._crowding_overlay_counts["boost_hits"] = float(self._crowding_overlay_counts.get("boost_hits", 0.0)) + 1.0

            mult = float(np.clip(mult, floor, ceiling))
            self._crowding_overlay_counts["applied"] = float(self._crowding_overlay_counts.get("applied", 0.0)) + 1.0
            self._crowding_overlay_counts["mult_sum"] = float(self._crowding_overlay_counts.get("mult_sum", 0.0)) + mult
            if bool(self.buy_crowding_overlay_debug.value):
                logger.info(
                    "CROWDING_OVERLAY pair=%s side=%s funding=%s basis=%s oi=%s crowded_long=%s crowded_short=%s mult=%.3f",
                    pair,
                    side_l,
                    "na" if state.get("funding") is None else f"{float(state['funding']):.6f}",
                    "na" if state.get("basis") is None else f"{float(state['basis']):.5f}",
                    "na" if state.get("oi") is None else f"{float(state['oi']):.5f}",
                    bool(crowded_long),
                    bool(crowded_short),
                    mult,
                )
            return mult
        except Exception:
            self._crowding_overlay_counts["fallback"] = float(self._crowding_overlay_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    def _crowding_block_allows(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> tuple[bool, str]:
        if not bool(self.buy_crowding_block_enabled.value):
            return True, "disabled"
        self._crowding_block_counts["calls"] = float(self._crowding_block_counts.get("calls", 0.0)) + 1.0
        try:
            if bool(self.buy_crowding_block_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
                self._crowding_block_counts["scope_skip"] = float(self._crowding_block_counts.get("scope_skip", 0.0)) + 1.0
                return True, "scope_skip"

            allow_csv = str(self.buy_crowding_block_tag_allowlist.value or "").strip()
            if allow_csv:
                allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
                if allow:
                    bucket = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
                    if bucket not in allow:
                        self._crowding_block_counts["tag_skip"] = float(self._crowding_block_counts.get("tag_skip", 0.0)) + 1.0
                        return True, "tag_skip"

            state = self._crowding_state(
                pair=pair,
                side=side,
                current_time=current_time,
                row=row,
                require_proxy_count=int(self.buy_crowding_block_require_proxy_count.value),
            )
            if not bool(state.get("ready", False)):
                self._crowding_block_counts["insufficient"] = float(self._crowding_block_counts.get("insufficient", 0.0)) + 1.0
                return True, "insufficient_fail_open"

            side_l = str(side or "long").lower()
            blocked = bool(state.get("crowded_long", False)) if side_l == "long" else bool(state.get("crowded_short", False))
            if blocked:
                self._crowding_block_counts["block"] = float(self._crowding_block_counts.get("block", 0.0)) + 1.0
                if bool(self.buy_crowding_block_debug.value):
                    logger.info(
                        "CROWDING_BLOCK pair=%s side=%s tag=%s funding=%s basis=%s oi=%s",
                        pair,
                        side_l,
                        str(entry_tag or ""),
                        "na" if state.get("funding") is None else f"{float(state['funding']):.6f}",
                        "na" if state.get("basis") is None else f"{float(state['basis']):.5f}",
                        "na" if state.get("oi") is None else f"{float(state['oi']):.5f}",
                    )
                return False, "overheat"

            self._crowding_block_counts["pass"] = float(self._crowding_block_counts.get("pass", 0.0)) + 1.0
            return True, "pass"
        except Exception:
            self._crowding_block_counts["fallback"] = float(self._crowding_block_counts.get("fallback", 0.0)) + 1.0
            return True, "exception_fail_open"

    def _extpack_scope_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.buy_extpack_enabled.value):
            return False
        if bool(self.buy_extpack_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_extpack_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _load_external_feature_pack_if_needed(self) -> None:
        try:
            raw = Path(str(self.external_feature_pack_file))
            path = raw if raw.is_absolute() else (Path.cwd() / raw)
            if not path.exists():
                self._extpack_df = None
                self._extpack_by_date = {}
                return
            mtime = float(path.stat().st_mtime)
            if (self._extpack_df is not None) and (mtime == self._extpack_mtime):
                return

            df = pd.read_csv(path)
            if df.empty:
                self._extpack_df = None
                self._extpack_by_date = {}
                self._extpack_mtime = mtime
                return

            date_col = None
            for c in ("date", "observation_date", "ts_utc", "timestamp"):
                if c in df.columns:
                    date_col = c
                    break
            if date_col is None:
                self._extpack_df = None
                self._extpack_by_date = {}
                self._extpack_mtime = mtime
                return

            ts = pd.to_datetime(df[date_col], utc=True, errors="coerce")
            out = pd.DataFrame(index=ts)
            out["fng"] = pd.to_numeric(df.get("fng", pd.Series(np.nan, index=df.index)), errors="coerce")
            out["dxy"] = pd.to_numeric(df.get("dxy", pd.Series(np.nan, index=df.index)), errors="coerce")
            out["dxy_ret_1d"] = pd.to_numeric(df.get("dxy_ret_1d", pd.Series(np.nan, index=df.index)), errors="coerce")
            out = out[~out.index.isna()].sort_index()
            out = out[~out.index.duplicated(keep="last")]
            if out.empty:
                self._extpack_df = None
                self._extpack_by_date = {}
                self._extpack_mtime = mtime
                return

            by_date: dict[str, dict[str, float]] = {}
            for idx, row in out.iterrows():
                key = pd.Timestamp(idx).strftime("%Y-%m-%d")
                by_date[key] = {
                    "fng": float(row.get("fng", np.nan)),
                    "dxy": float(row.get("dxy", np.nan)),
                    "dxy_ret_1d": float(row.get("dxy_ret_1d", np.nan)),
                }

            self._extpack_df = out
            self._extpack_by_date = by_date
            self._extpack_mtime = mtime
        except Exception:
            self._extpack_df = None
            self._extpack_by_date = {}

    def _extpack_row_from_time(self, current_time: datetime | None) -> dict[str, float] | None:
        if current_time is None:
            return None
        self._load_external_feature_pack_if_needed()
        if not self._extpack_by_date:
            return None
        try:
            ts = pd.Timestamp(current_time)
            if ts.tzinfo is None:
                ts = ts.tz_localize("UTC")
            else:
                ts = ts.tz_convert("UTC")
            key = ts.strftime("%Y-%m-%d")
            row = self._extpack_by_date.get(key)
            if row is not None:
                return row
            if self._extpack_df is None or self._extpack_df.empty:
                return None
            asof_idx = self._extpack_df.index.asof(ts)
            if asof_idx is None or pd.isna(asof_idx):
                return None
            rr = self._extpack_df.loc[asof_idx]
            return {
                "fng": float(rr.get("fng", np.nan)),
                "dxy": float(rr.get("dxy", np.nan)),
                "dxy_ret_1d": float(rr.get("dxy_ret_1d", np.nan)),
            }
        except Exception:
            return None

    def _external_pack_mult(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> float:
        if not bool(self.buy_extpack_enabled.value):
            return 1.0
        self._extpack_counts["calls"] = float(self._extpack_counts.get("calls", 0.0)) + 1.0
        try:
            if not self._extpack_scope_applies(entry_tag):
                self._extpack_counts["scope_skip"] = float(self._extpack_counts.get("scope_skip", 0.0)) + 1.0
                return 1.0

            ext = self._extpack_row_from_time(current_time)
            if ext is None:
                self._extpack_counts["missing"] = float(self._extpack_counts.get("missing", 0.0)) + 1.0
                return 1.0

            fng = float(ext.get("fng", np.nan))
            dxy_ret = float(ext.get("dxy_ret_1d", np.nan))
            breadth = float("nan")
            try:
                snap = self._meta_cross_section_snapshot(current_time, pair)
                breadth = float(snap.get("trend_up_frac", np.nan) or np.nan)
            except Exception:
                breadth = float("nan")

            floor = float(self.buy_extpack_floor.value)
            ceiling = float(self.buy_extpack_ceiling.value)
            if ceiling < floor:
                floor, ceiling = ceiling, floor
            mult = 1.0

            fear_max = float(self.buy_extpack_fng_fear_max.value)
            greed_min = float(self.buy_extpack_fng_greed_min.value)
            if np.isfinite(fng):
                if fng <= fear_max:
                    mult *= max(floor, 0.5 * (1.0 + floor))
                    self._extpack_counts["fear_hits"] = float(self._extpack_counts.get("fear_hits", 0.0)) + 1.0
                elif fng >= greed_min:
                    mult *= max(floor, 0.6 * (1.0 + floor))
                    self._extpack_counts["greed_hits"] = float(self._extpack_counts.get("greed_hits", 0.0)) + 1.0
            else:
                self._extpack_counts["insufficient"] = float(self._extpack_counts.get("insufficient", 0.0)) + 1.0

            dxy_thr = float(self.buy_extpack_dxy_ret1d_riskoff_min.value)
            if np.isfinite(dxy_ret) and dxy_ret >= dxy_thr:
                mult *= max(floor, 0.5 * (1.0 + floor))
                self._extpack_counts["dxy_hits"] = float(self._extpack_counts.get("dxy_hits", 0.0)) + 1.0

            b_lo = float(self.buy_extpack_breadth_low.value)
            b_hi = float(self.buy_extpack_breadth_high.value)
            if np.isfinite(breadth):
                if breadth <= b_lo:
                    mult *= max(floor, 0.5 * (1.0 + floor))
                    self._extpack_counts["breadth_hits"] = float(self._extpack_counts.get("breadth_hits", 0.0)) + 1.0
                elif breadth >= b_hi:
                    boost = min(ceiling, 1.0 + (ceiling - 1.0) * 0.50)
                    mult *= boost

            mult = float(np.clip(mult, floor, ceiling))
            self._extpack_counts["applied"] = float(self._extpack_counts.get("applied", 0.0)) + 1.0
            self._extpack_counts["mult_sum"] = float(self._extpack_counts.get("mult_sum", 0.0)) + mult
            if bool(self.buy_extpack_debug.value):
                logger.info(
                    "EXTPACK_OVERLAY pair=%s side=%s tag=%s fng=%s dxy_ret1d=%s breadth=%s mult=%.3f",
                    pair,
                    str(side or ""),
                    str(entry_tag or ""),
                    "na" if not np.isfinite(fng) else f"{fng:.2f}",
                    "na" if not np.isfinite(dxy_ret) else f"{dxy_ret:.4f}",
                    "na" if not np.isfinite(breadth) else f"{breadth:.3f}",
                    mult,
                )
            return mult
        except Exception:
            self._extpack_counts["fallback"] = float(self._extpack_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    def _calendar_scope_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.buy_cal_overlay_enabled.value):
            return False
        if bool(self.buy_cal_overlay_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_cal_overlay_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _load_calendar_events_if_needed(self) -> None:
        try:
            raw = Path(str(self.calendar_events_file))
            path = raw if raw.is_absolute() else (Path.cwd() / raw)
            if not path.exists():
                self._calendar_events = []
                self._calendar_event_epochs = []
                return
            mtime = float(path.stat().st_mtime)
            if self._calendar_events and (mtime == self._calendar_mtime):
                return

            df = pd.read_csv(path)
            if df.empty:
                self._calendar_events = []
                self._calendar_event_epochs = []
                self._calendar_mtime = mtime
                return

            ts_col = None
            for c in ("ts_utc", "timestamp", "date"):
                if c in df.columns:
                    ts_col = c
                    break
            if ts_col is None:
                self._calendar_events = []
                self._calendar_event_epochs = []
                self._calendar_mtime = mtime
                return

            ts = pd.to_datetime(df[ts_col], utc=True, errors="coerce")
            ev_col = df.get("event", pd.Series("OTHER", index=df.index)).astype(str).str.upper()
            sev_col = pd.to_numeric(df.get("severity", pd.Series(1.0, index=df.index)), errors="coerce").fillna(1.0)
            out: list[dict[str, Any]] = []
            for i in range(len(df)):
                tsv = ts.iloc[i]
                if pd.isna(tsv):
                    continue
                out.append(
                    {
                        "ts": pd.Timestamp(tsv).to_pydatetime(),
                        "event": str(ev_col.iloc[i] or "OTHER").upper(),
                        "severity": float(np.clip(float(sev_col.iloc[i]), 0.2, 2.0)),
                    }
                )
            out.sort(key=lambda x: x["ts"])
            epochs = [int(pd.Timestamp(x["ts"]).timestamp()) for x in out]
            self._calendar_events = out
            self._calendar_event_epochs = epochs
            self._calendar_mtime = mtime
        except Exception:
            self._calendar_events = []
            self._calendar_event_epochs = []

    def _calendar_event_base_mult(self, event_name: str) -> float:
        ev = str(event_name or "OTHER").upper()
        if "FOMC" in ev:
            return float(self.buy_cal_overlay_mult_fomc.value)
        if "CPI" in ev:
            return float(self.buy_cal_overlay_mult_cpi.value)
        if "NFP" in ev:
            return float(self.buy_cal_overlay_mult_nfp.value)
        if "UNLOCK" in ev:
            return float(self.buy_cal_overlay_mult_unlock.value)
        return float(self.buy_cal_overlay_mult_default.value)

    def _calendar_overlay_mult(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
    ) -> float:
        if not bool(self.buy_cal_overlay_enabled.value):
            return 1.0
        self._calendar_counts["calls"] = float(self._calendar_counts.get("calls", 0.0)) + 1.0
        try:
            if current_time is None:
                return 1.0
            if bool(self.buy_cal_overlay_long_only.value) and str(side or "long").lower() != "long":
                return 1.0
            if not self._calendar_scope_applies(entry_tag):
                self._calendar_counts["scope_skip"] = float(self._calendar_counts.get("scope_skip", 0.0)) + 1.0
                return 1.0

            self._load_calendar_events_if_needed()
            if not self._calendar_event_epochs:
                self._calendar_counts["missing"] = float(self._calendar_counts.get("missing", 0.0)) + 1.0
                return 1.0

            ts = pd.Timestamp(current_time)
            if ts.tzinfo is None:
                ts = ts.tz_localize("UTC")
            else:
                ts = ts.tz_convert("UTC")
            now_ep = int(ts.timestamp())
            pre_h = max(0.0, float(self.buy_cal_overlay_pre_hours.value))
            post_h = max(0.0, float(self.buy_cal_overlay_post_hours.value))
            lo_ep = now_ep - int(pre_h * 3600.0)
            hi_ep = now_ep + int(post_h * 3600.0)

            left = bisect.bisect_left(self._calendar_event_epochs, lo_ep)
            right = bisect.bisect_right(self._calendar_event_epochs, hi_ep)
            if left >= right:
                return 1.0

            mult = 1.0
            hit_types: set[str] = set()
            for i in range(left, right):
                ev = self._calendar_events[i]
                etype = str(ev.get("event", "OTHER")).upper()
                sev = float(ev.get("severity", 1.0) or 1.0)
                base = float(self._calendar_event_base_mult(etype))
                local = 1.0 - (1.0 - base) * float(np.clip(sev, 0.2, 2.0))
                local = float(np.clip(local, 0.30, 1.00))
                mult = min(mult, local)
                hit_types.add(etype)

            if "FOMC" in hit_types:
                self._calendar_counts["fomc_hits"] = float(self._calendar_counts.get("fomc_hits", 0.0)) + 1.0
            if "CPI" in hit_types:
                self._calendar_counts["cpi_hits"] = float(self._calendar_counts.get("cpi_hits", 0.0)) + 1.0
            if "NFP" in hit_types:
                self._calendar_counts["nfp_hits"] = float(self._calendar_counts.get("nfp_hits", 0.0)) + 1.0
            if any("UNLOCK" in x for x in hit_types):
                self._calendar_counts["unlock_hits"] = float(self._calendar_counts.get("unlock_hits", 0.0)) + 1.0
            if hit_types and not ({"FOMC", "CPI", "NFP"} & hit_types):
                self._calendar_counts["other_hits"] = float(self._calendar_counts.get("other_hits", 0.0)) + 1.0

            self._calendar_counts["applied"] = float(self._calendar_counts.get("applied", 0.0)) + 1.0
            self._calendar_counts["mult_sum"] = float(self._calendar_counts.get("mult_sum", 0.0)) + float(mult)
            if bool(self.buy_cal_overlay_debug.value):
                logger.info(
                    "CAL_OVERLAY pair=%s side=%s tag=%s events=%s mult=%.3f",
                    pair,
                    str(side or ""),
                    str(entry_tag or ""),
                    ",".join(sorted(hit_types)) if hit_types else "none",
                    float(mult),
                )
            return float(mult)
        except Exception:
            self._calendar_counts["fallback"] = float(self._calendar_counts.get("fallback", 0.0)) + 1.0
            return 1.0

    def _entry_veto_scope_applies(self, entry_tag: str | None) -> bool:
        if not bool(self.buy_entry_veto_enabled.value):
            return False
        if bool(self.buy_entry_veto_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            return False
        exact_key = self._reg_alloc_sleeve_from_tag(entry_tag)
        bucket_key = self._tag_bucket(entry_tag)
        sleeve_key = self._sleeve_key_from_tag(entry_tag)
        return self._feature_tag_allowlist_allows(
            entry_tag,
            str(self.buy_entry_veto_tag_allowlist.value or ""),
            exact_key=exact_key,
            bucket_key=bucket_key,
            sleeve_key=sleeve_key,
        )

    def _entry_veto_mode(self) -> str:
        mode = str(self.buy_entry_veto_mode.value or "hard").strip().lower()
        return mode if mode in {"hard", "soft", "hybrid"} else "hard"

    def _load_entry_veto_model_if_needed(self) -> None:
        try:
            raw = Path(str(self.entry_veto_model_file))
            path = raw if raw.is_absolute() else (Path.cwd() / raw)
            if not path.exists():
                self._entry_veto_model = None
                return
            mtime = float(path.stat().st_mtime)
            if self._entry_veto_model is not None and mtime == self._entry_veto_model_mtime:
                return
            model = json.loads(path.read_text())
            if not isinstance(model, dict):
                self._entry_veto_model = None
                self._entry_veto_model_mtime = mtime
                return
            weights = model.get("weights", {})
            if not isinstance(weights, dict):
                self._entry_veto_model = None
                self._entry_veto_model_mtime = mtime
                return
            model.setdefault("feature_order", list(weights.keys()))
            model.setdefault("bias", 0.0)
            model.setdefault("threshold_default", 0.50)
            model.setdefault("pair_symbols", [])
            model.setdefault("bucket_keys", [])
            model.setdefault("calendar_pre_hours", 12.0)
            model.setdefault("calendar_post_hours", 8.0)
            self._entry_veto_model = model
            self._entry_veto_model_mtime = mtime
        except Exception:
            self._entry_veto_model = None

    @staticmethod
    def _entry_veto_pair_symbol(pair: str) -> str:
        p = str(pair or "").upper()
        if "/" in p:
            p = p.split("/", 1)[0]
        if ":" in p:
            p = p.split(":", 1)[0]
        return p

    def _entry_veto_calendar_severity(
        self,
        current_time: datetime | None,
        pre_h: float,
        post_h: float,
    ) -> float:
        try:
            if current_time is None:
                return 0.0
            self._load_calendar_events_if_needed()
            if not self._calendar_event_epochs:
                return 0.0
            ts = pd.Timestamp(current_time)
            if ts.tzinfo is None:
                ts = ts.tz_localize("UTC")
            else:
                ts = ts.tz_convert("UTC")
            now_ep = int(ts.timestamp())
            lo_ep = now_ep - int(max(0.0, float(pre_h)) * 3600.0)
            hi_ep = now_ep + int(max(0.0, float(post_h)) * 3600.0)
            left = bisect.bisect_left(self._calendar_event_epochs, lo_ep)
            right = bisect.bisect_right(self._calendar_event_epochs, hi_ep)
            if left >= right:
                return 0.0
            sev = 0.0
            for i in range(left, right):
                ev = self._calendar_events[i]
                sev = max(sev, float(ev.get("severity", 1.0) or 1.0))
            return float(np.clip(sev, 0.0, 2.0))
        except Exception:
            return 0.0

    def _entry_veto_feature_map(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None,
        model: dict[str, Any],
    ) -> dict[str, float]:
        feats: dict[str, float] = {}

        # Generic numeric context
        hour = 0.0
        if current_time is not None:
            try:
                ts = pd.Timestamp(current_time)
                if ts.tzinfo is None:
                    ts = ts.tz_localize("UTC")
                else:
                    ts = ts.tz_convert("UTC")
                hour = float(ts.hour) + float(ts.minute) / 60.0
            except Exception:
                hour = 0.0
        feats["hour_sin"] = float(math.sin(2.0 * math.pi * (hour / 24.0)))
        feats["hour_cos"] = float(math.cos(2.0 * math.pi * (hour / 24.0)))
        feats["side_short"] = 1.0 if str(side or "long").lower() == "short" else 0.0

        # External feature pack inputs
        ext = self._extpack_row_from_time(current_time)
        fng = float(ext.get("fng", np.nan)) if isinstance(ext, dict) else float("nan")
        dxy_ret = float(ext.get("dxy_ret_1d", np.nan)) if isinstance(ext, dict) else float("nan")
        feats["fng_scaled"] = float(np.clip((fng - 50.0) / 25.0, -3.0, 3.0)) if np.isfinite(fng) else 0.0
        feats["dxy_ret_scaled"] = float(np.clip(dxy_ret / 0.010, -3.0, 3.0)) if np.isfinite(dxy_ret) else 0.0

        # Event-window severity proxy from calendar feed
        pre_h = float(model.get("calendar_pre_hours", 12.0) or 12.0)
        post_h = float(model.get("calendar_post_hours", 8.0) or 8.0)
        ev_sev = self._entry_veto_calendar_severity(current_time, pre_h=pre_h, post_h=post_h)
        feats["event_risk"] = float(np.clip(ev_sev / 2.0, 0.0, 1.0))

        # Regime + quality context (existing in-strategy features)
        bucket = str(self._tag_bucket(entry_tag) or "")
        qscore, _ = self._qsize_score(row, bucket, side)
        feats["qscore"] = float(np.clip(float(qscore), 0.0, 1.0))

        regime = ""
        try:
            if row is not None:
                regime = str(row.get("composite_regime", "") or "").upper()
        except Exception:
            regime = ""
        feats["regime_is_chop"] = 1.0 if "CHOP" in regime else 0.0
        feats["regime_is_trend"] = 1.0 if "TREND" in regime else 0.0
        feats["regime_is_bear"] = 1.0 if ("BEAR" in regime or "PANIC" in regime) else 0.0
        feats["regime_is_volexp"] = 1.0 if ("VOL_EXP" in regime or "EXPAND" in regime) else 0.0

        # Sparse one-hot features from trained model lists
        pair_sym = self._entry_veto_pair_symbol(pair).lower()
        for sym in model.get("pair_symbols", []) or []:
            s = str(sym).strip().lower()
            if s:
                feats[f"pair_{s}"] = 1.0 if pair_sym == s else 0.0
        for bk in model.get("bucket_keys", []) or []:
            b = str(bk).strip().lower()
            if b:
                feats[f"bucket_{b}"] = 1.0 if str(bucket).lower() == b else 0.0

        return feats

    def _entry_veto_predict_prob(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None,
        model: dict[str, Any],
    ) -> float:
        feats = self._entry_veto_feature_map(
            pair=pair,
            side=side,
            entry_tag=entry_tag,
            current_time=current_time,
            row=row,
            model=model,
        )
        z = float(model.get("bias", 0.0) or 0.0)
        weights = model.get("weights", {}) or {}
        for k, w in weights.items():
            try:
                z += float(w) * float(feats.get(str(k), 0.0))
            except Exception:
                continue
        return self._safe_sigmoid(float(z))

    def _entry_veto_prob_threshold(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None,
    ) -> tuple[float | None, float]:
        """
        Returns (prob, threshold). prob=None means model/row unavailable.
        """
        self._load_entry_veto_model_if_needed()
        model = self._entry_veto_model
        if not isinstance(model, dict):
            return None, 0.0
        if row is None:
            row = self._pair_row_at_or_before_time(pair, current_time)
        if row is None:
            return None, 0.0
        prob = float(self._entry_veto_predict_prob(pair, side, entry_tag, current_time, row, model))
        thr_cfg = float(self.buy_entry_veto_min_prob.value)
        threshold = float(thr_cfg if thr_cfg > 0.0 else float(model.get("threshold_default", 0.50) or 0.50))
        threshold = float(np.clip(threshold, 0.0, 0.99))
        return prob, threshold

    def _entry_veto_soft_mult(self, prob: float, threshold: float) -> float:
        floor = float(self.buy_entry_veto_soft_floor.value)
        ceil = float(self.buy_entry_veto_soft_ceiling.value)
        strength = float(np.clip(float(self.buy_entry_veto_soft_strength.value), 0.0, 1.0))
        if ceil < floor:
            floor, ceil = ceil, floor
        p = float(np.clip(float(prob), 0.0, 1.0))
        thr = float(np.clip(float(threshold), 1e-6, 0.99))

        if p >= thr:
            up_denom = max(1e-6, 1.0 - thr)
            up = float(np.clip((p - thr) / up_denom, 0.0, 1.0))
            mult = 1.0 + up * (ceil - 1.0) * strength
        else:
            dn_denom = max(1e-6, thr)
            dn = float(np.clip((thr - p) / dn_denom, 0.0, 1.0))
            mult = 1.0 - dn * (1.0 - floor) * strength
        return float(np.clip(mult, floor, ceil))

    def _entry_veto_allows(
        self,
        pair: str,
        side: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None,
    ) -> tuple[bool, float, float]:
        """
        Returns: (allowed, prob, threshold). Fail-open by default.
        """
        if not bool(self.buy_entry_veto_enabled.value):
            return True, 1.0, 0.0
        self._entry_veto_counts["calls"] = float(self._entry_veto_counts.get("calls", 0.0)) + 1.0
        try:
            if not self._entry_veto_scope_applies(entry_tag):
                self._entry_veto_counts["scope_skip"] = float(self._entry_veto_counts.get("scope_skip", 0.0)) + 1.0
                return True, 1.0, 0.0
            self._load_entry_veto_model_if_needed()
            if not isinstance(self._entry_veto_model, dict):
                self._entry_veto_counts["missing_model"] = float(self._entry_veto_counts.get("missing_model", 0.0)) + 1.0
                if bool(self.buy_entry_veto_fail_open.value):
                    return True, 1.0, 0.0
                return False, 0.0, 0.0
            prob, threshold = self._entry_veto_prob_threshold(
                pair=pair,
                side=side,
                entry_tag=entry_tag,
                current_time=current_time,
                row=row,
            )
            if prob is None:
                self._entry_veto_counts["missing_row"] = float(self._entry_veto_counts.get("missing_row", 0.0)) + 1.0
                if bool(self.buy_entry_veto_fail_open.value):
                    return True, 1.0, 0.0
                return False, 0.0, 0.0

            if prob < threshold:
                self._entry_veto_counts["block"] = float(self._entry_veto_counts.get("block", 0.0)) + 1.0
                if bool(self.buy_entry_veto_debug.value):
                    logger.info(
                        "ENTRY_VETO_BLOCK pair=%s side=%s tag=%s prob=%.3f thr=%.3f",
                        pair,
                        str(side or ""),
                        str(entry_tag or ""),
                        prob,
                        threshold,
                    )
                return False, prob, threshold

            self._entry_veto_counts["pass"] = float(self._entry_veto_counts.get("pass", 0.0)) + 1.0
            self._entry_veto_counts["prob_sum"] = float(self._entry_veto_counts.get("prob_sum", 0.0)) + prob
            if bool(self.buy_entry_veto_debug.value):
                logger.info(
                    "ENTRY_VETO_PASS pair=%s side=%s tag=%s prob=%.3f thr=%.3f",
                    pair,
                    str(side or ""),
                    str(entry_tag or ""),
                    prob,
                    threshold,
                )
            return True, prob, threshold
        except Exception:
            self._entry_veto_counts["fallback"] = float(self._entry_veto_counts.get("fallback", 0.0)) + 1.0
            return True, 1.0, 0.0

    def _cost_gate_allows(
        self,
        pair: str,
        current_time: datetime | None,
        entry_tag: str | None,
        side: str,
        row: pd.Series | dict | None = None,
    ) -> tuple[bool, str, float, float]:
        if not bool(self.buy_cost_gate_enabled.value):
            return True, "disabled", 0.0, 0.0
        self._cost_gate_counts["calls"] = int(self._cost_gate_counts.get("calls", 0)) + 1
        try:
            if row is None:
                row, _, _ = self._rank_row_for_time(pair, current_time)
            if row is None:
                row = self._pair_row_at_or_before_time(pair, current_time)
            if row is None:
                self._cost_gate_counts["no_row"] = int(self._cost_gate_counts.get("no_row", 0)) + 1
                if bool(self.buy_cost_gate_fail_open.value):
                    self._cost_gate_counts["pass"] = int(self._cost_gate_counts.get("pass", 0)) + 1
                    return True, "no_row_fail_open", 0.0, 0.0
                self._cost_gate_counts["blocked"] = int(self._cost_gate_counts.get("blocked", 0)) + 1
                return False, "no_row", 0.0, 0.0

            bucket = self._tag_bucket(entry_tag)
            qscore = None
            try:
                qscore, _ = self._qsize_score(row, bucket, side)
            except Exception:
                qscore = None
            expr = self._row_pick_float(row, ["rank_expr", "rank_expr_norm", "rank_score_base"])
            qscore_v = float(np.clip(float(qscore), 0.0, 1.0)) if qscore is not None and np.isfinite(float(qscore)) else None
            expr_v = max(0.0, float(expr)) if expr is not None and np.isfinite(float(expr)) else 0.0

            if qscore_v is None:
                self._cost_gate_counts["no_score"] = int(self._cost_gate_counts.get("no_score", 0)) + 1
                if bool(self.buy_cost_gate_fail_open.value):
                    self._cost_gate_counts["pass"] = int(self._cost_gate_counts.get("pass", 0)) + 1
                    return True, "no_score_fail_open", 0.0, 0.0

            edge = 0.0
            if qscore_v is not None:
                edge += qscore_v * float(self.buy_cost_gate_qscore_edge_scale.value)
            edge += expr_v * float(self.buy_cost_gate_expr_edge_scale.value)
            regime_label = str(row.get("composite_regime", "") or "")
            min_buffer_pct = self._cost_gate_min_buffer_pct(entry_tag, regime_label)

            funding_abs = float(self.buy_cost_gate_funding_pct.value)
            fr = self._row_pick_float(row, ["funding_rate", "funding", "perp_funding", "mark_funding_rate", "future_funding_rate"])
            if fr is not None and np.isfinite(float(fr)):
                funding_abs = abs(float(fr))

            cost = (
                float(self.buy_cost_gate_fee_rt_pct.value)
                + float(self.buy_cost_gate_slip_pct.value)
                + float(self.buy_cost_gate_turnover_penalty_pct.value)
                + funding_abs
            )
            threshold = cost + float(min_buffer_pct)
            ok = float(edge) >= float(threshold)
            if ok:
                self._cost_gate_counts["pass"] = int(self._cost_gate_counts.get("pass", 0)) + 1
                if bool(self.buy_cost_gate_debug.value):
                    logger.info(
                        "COST_GATE_ALLOW pair=%s side=%s tag=%s edge=%.4f cost=%.4f thr=%.4f",
                        pair,
                        side,
                        str(entry_tag or ""),
                        float(edge),
                        float(cost),
                        float(threshold),
                    )
                return True, "pass", float(edge), float(threshold)

            self._cost_gate_counts["blocked"] = int(self._cost_gate_counts.get("blocked", 0)) + 1
            if bool(self.buy_cost_gate_debug.value):
                logger.info(
                    "COST_GATE_BLOCK pair=%s side=%s tag=%s edge=%.4f cost=%.4f thr=%.4f",
                    pair,
                    side,
                    str(entry_tag or ""),
                    float(edge),
                    float(cost),
                    float(threshold),
                )
            return False, "below_cost", float(edge), float(threshold)
        except Exception:
            self._cost_gate_counts["fallback"] = int(self._cost_gate_counts.get("fallback", 0)) + 1
            if bool(self.buy_cost_gate_fail_open.value):
                self._cost_gate_counts["pass"] = int(self._cost_gate_counts.get("pass", 0)) + 1
                return True, "exception_fail_open", 0.0, 0.0
            self._cost_gate_counts["blocked"] = int(self._cost_gate_counts.get("blocked", 0)) + 1
            return False, "exception", 0.0, 0.0

    @staticmethod
    def _tail_csv_set(s: str) -> set[str]:
        return {x.strip().lower() for x in str(s or "").split(",") if x and x.strip()}

    def _tail_allows(self, trade: Trade) -> bool:
        if not bool(self.sell_tail_enabled.value):
            return False
        sleeves = self._tail_csv_set(str(self.sell_tail_only_sleeves.value or ""))
        if not sleeves:
            return True
        tag = str(getattr(trade, "enter_tag", "") or "")
        sleeve = self._reg_alloc_sleeve_from_tag(tag)
        return sleeve in sleeves

    def _tail_stoploss_override(
        self,
        pair: str,
        trade: Trade,
        current_rate: float,
        current_profit: float,
    ) -> float | None:
        if not self._tail_allows(trade):
            return None
        if current_rate <= 0:
            return None

        arm = float(self.sell_tail_arm_profit.value)
        if current_profit < arm:
            return None

        tid = self._trade_id(trade)
        if tid is None:
            return None

        off = float(np.clip(float(self.sell_tail_trail_offset.value), 0.0, 0.95))
        open_rate = float(getattr(trade, "open_rate", 0.0) or 0.0)
        if open_rate <= 0:
            return None

        if bool(getattr(trade, "is_short", False)):
            # For shorts, track low-water mark then place stop above it.
            lwm = float(self._tail_hwm_by_tradeid.get(tid, current_rate))
            lwm = min(lwm, float(current_rate))
            self._tail_hwm_by_tradeid[tid] = lwm
            stop_price = lwm * (1.0 + off)
            open_relative = (open_rate / stop_price) - 1.0 if stop_price > 0 else 0.0
        else:
            # For longs, track high-water mark then place stop below it.
            hwm = float(self._tail_hwm_by_tradeid.get(tid, current_rate))
            hwm = max(hwm, float(current_rate))
            self._tail_hwm_by_tradeid[tid] = hwm
            stop_price = hwm * (1.0 - off)
            open_relative = (stop_price / open_rate) - 1.0

        # TRBK tail shaping: optional minimum locked-in profit floor once tail is active.
        try:
            if self._reg_alloc_sleeve_from_tag(getattr(trade, "enter_tag", None)) == "trbk":
                trbk_floor = float(self.sell_tail_trbk_floor_open_profit.value)
                if trbk_floor > 0.0:
                    open_relative = max(float(open_relative), trbk_floor)
        except Exception:
            pass

        tail_sl = stoploss_from_open(
            open_relative,
            current_profit,
            is_short=trade.is_short,
            leverage=trade.leverage,
        )
        if tail_sl is None:
            return None

        if bool(self.sell_tail_debug.value):
            try:
                logger.info(
                    "TAIL_STOP pair=%s tag=%s trade_id=%s profit=%.4f current=%.6f stop_price=%.6f open_rel=%.4f sl=%.4f",
                    pair,
                    str(getattr(trade, "enter_tag", "") or ""),
                    tid,
                    float(current_profit),
                    float(current_rate),
                    float(stop_price),
                    float(open_relative),
                    float(tail_sl),
                )
            except Exception:
                pass
        return float(tail_sl)

    def _protect_trade_key(self, trade: Trade) -> str:
        tid = self._trade_id(trade)
        if tid is not None:
            return f"tid:{tid}"
        pair = str(getattr(trade, "pair", "") or "")
        open_dt = getattr(trade, "open_date_utc", None) or getattr(trade, "open_date", None)
        return f"{pair}:{open_dt}"

    def _init_protect_state(self) -> None:
        if not hasattr(self, "_protect_hwm"):
            self._protect_hwm = {}
        if not hasattr(self, "_protect_stage"):
            self._protect_stage = {}

    def _protect_sleeve_allows(self, trade: Trade) -> bool:
        raw = str(self.sell_protect_sleeve_allowlist.value or "").strip()
        if raw == "":
            return True
        allow = self._tail_csv_set(raw)
        # Accept both user-facing "trendpb" and internal sleeve key "tpb".
        if "trendpb" in allow:
            allow.add("tpb")
        if "tpb" in allow:
            allow.add("trendpb")
        if not allow:
            return True
        tag = str(getattr(trade, "enter_tag", "") or "")
        sleeve = self._reg_alloc_sleeve_from_tag(tag)
        return sleeve in allow

    @staticmethod
    def _trade_age_hours(trade: Trade, current_time: datetime) -> float:
        try:
            open_dt = getattr(trade, "open_date_utc", None) or getattr(trade, "open_date", None)
            if open_dt is None:
                return 0.0
            return max((current_time - open_dt).total_seconds() / 3600.0, 0.0)
        except Exception:
            return 0.0

    @staticmethod
    def _select_tightest_stoploss(*candidates: float | None) -> float:
        vals: list[float] = []
        for cand in candidates:
            if cand is None:
                continue
            try:
                v = float(cand)
            except Exception:
                continue
            if not np.isfinite(v):
                continue
            vals.append(v)
        if not vals:
            return 1.0
        return float(sorted(vals, key=lambda x: abs(x))[0])

    def _protect_stoploss_override(
        self,
        pair: str,
        trade: Trade,
        current_time: datetime,
        current_profit: float,
    ) -> float | None:
        if not bool(self.sell_protect_enabled.value):
            return None
        if not self._protect_sleeve_allows(trade):
            return None

        self._init_protect_state()
        key = self._protect_trade_key(trade)

        try:
            cp = float(current_profit)
        except Exception:
            return None
        if not np.isfinite(cp):
            return None

        prev_hwm = float(self._protect_hwm.get(key, cp))
        hwm = max(prev_hwm, cp)
        self._protect_hwm[key] = hwm

        s1_trigger = float(self.sell_protect_stage1_trigger.value)
        s1_stop = float(self.sell_protect_stage1_stop.value)
        s2_trigger = max(s1_trigger, float(self.sell_protect_stage2_trigger.value))
        s2_stop = max(s1_stop, float(self.sell_protect_stage2_stop.value))
        s3_trigger = max(s2_trigger, float(self.sell_protect_stage3_trigger.value))
        s3_offset = max(0.0, float(self.sell_protect_stage3_offset.value))
        s3_min_hours = max(0.0, float(self.sell_protect_stage3_min_hours.value))
        age_h = self._trade_age_hours(trade, current_time)

        floor_open: float | None = None
        stage = 0

        if hwm >= s1_trigger:
            floor_open = s1_stop
            stage = 1

        if hwm >= s2_trigger:
            floor_open = max(floor_open if floor_open is not None else -999.0, s2_stop)
            stage = 2

        if hwm >= s3_trigger and age_h >= s3_min_hours:
            trail_floor = max(s2_stop, hwm - s3_offset)
            floor_open = max(floor_open if floor_open is not None else -999.0, trail_floor)
            stage = 3

        if floor_open is None:
            return None

        sl = stoploss_from_open(
            float(floor_open),
            cp,
            is_short=trade.is_short,
            leverage=trade.leverage,
        )
        if sl is None:
            return None

        self._protect_stage[key] = int(stage)
        if bool(self.sell_protect_debug.value):
            try:
                logger.info(
                    "PROTECT_STOP pair=%s tag=%s trade_id=%s stage=%s cp=%.4f hwm=%.4f age_h=%.2f floor_open=%.4f sl=%.4f",
                    pair,
                    str(getattr(trade, "enter_tag", "") or ""),
                    self._trade_id(trade),
                    stage,
                    cp,
                    hwm,
                    age_h,
                    float(floor_open),
                    float(sl),
                )
            except Exception:
                pass
        return float(sl)

    def _protect_cleanup_trade(self, trade: Trade) -> None:
        try:
            key = self._protect_trade_key(trade)
            self._protect_hwm.pop(key, None)
            self._protect_stage.pop(key, None)
        except Exception:
            pass

    def _entry_cache_key(self, pair: str, current_time: datetime | None, entry_tag: str | None) -> tuple[str, str, str]:
        ts_key = "na"
        if current_time is not None:
            try:
                ts_key = pd.Timestamp(current_time).isoformat()
            except Exception:
                try:
                    ts_key = current_time.isoformat()
                except Exception:
                    ts_key = "na"
        return pair, ts_key, str(entry_tag or "")

    def _regime_for_row(self, pair: str, row: pd.Series | None, entry_tag: str | None = None) -> str:
        bucket = self._tag_bucket(entry_tag)
        if bucket == "bearvol_short":
            return "BEARVOL"
        comp = str((row.get("composite_regime", "") if row is not None else "") or "").upper()
        atrp = str((row.get("atr_phase", "") if row is not None else "") or "").upper()
        if "PANIC" in comp or "CAPITULATION" in comp:
            return "PANIC"
        if "VOL_EXP" in comp or atrp == "EXPAND":
            return "VOL_EXP"
        if bucket == "mr_long" or comp.startswith("CHOP"):
            return "CHOP_MR"
        if "TREND_UP" in comp:
            if "breakout" in (str(entry_tag or "").lower()) or bucket in {"trbk", "micro5m"}:
                return "TREND_BREAKOUT"
            return "TREND_PULLBACK"
        if bucket == "trbk":
            return "TREND_BREAKOUT"
        return "TREND_PULLBACK"

    def _regime_for_pair_time(self, pair: str, current_time: datetime | None, entry_tag: str | None = None) -> str:
        row, _, _ = self._rank_row_for_time(pair, current_time)
        return self._regime_for_row(pair, row, entry_tag)

    def _regime_alloc_budget(self, regime: str, mode: str) -> float:
        if mode == "exposure":
            return {
                "CHOP_MR": float(self.regime_alloc_chop_mr_exposure.value),
                "TREND_PULLBACK": float(self.regime_alloc_trend_pullback_exposure.value),
                "TREND_BREAKOUT": float(self.regime_alloc_trend_breakout_exposure.value),
                "VOL_EXP": float(self.regime_alloc_vol_exp_exposure.value),
                "PANIC": float(self.regime_alloc_panic_exposure.value),
                "BEARVOL": float(self.regime_alloc_bearvol_exposure.value),
            }.get(regime, float(self.regime_alloc_trend_pullback_exposure.value))
        return {
            "CHOP_MR": float(self.regime_alloc_chop_mr_risk.value),
            "TREND_PULLBACK": float(self.regime_alloc_trend_pullback_risk.value),
            "TREND_BREAKOUT": float(self.regime_alloc_trend_breakout_risk.value),
            "VOL_EXP": float(self.regime_alloc_vol_exp_risk.value),
            "PANIC": float(self.regime_alloc_panic_risk.value),
            "BEARVOL": float(self.regime_alloc_bearvol_risk.value),
        }.get(regime, float(self.regime_alloc_trend_pullback_risk.value))

    def _regime_alloc_global_budget(self, mode: str) -> float:
        total = sum(
            self._regime_alloc_budget(reg, mode)
            for reg in ("CHOP_MR", "TREND_PULLBACK", "TREND_BREAKOUT", "VOL_EXP", "PANIC", "BEARVOL")
        )
        if mode == "exposure":
            return min(1.0, float(total))
        return max(0.0, float(total))

    def _regime_alloc_sleeve_weight(self, sleeve: str) -> float:
        return {
            "micro_alpha_5m": float(self.regime_alloc_sleeve_weight_micro.value),
            "bearvol": float(self.regime_alloc_sleeve_weight_bearvol.value),
            "convex": float(self.regime_alloc_sleeve_weight_convex.value),
        }.get(sleeve, 1.0)

    def _atr_pct_at_time(
        self,
        pair: str,
        tf: str,
        ts: datetime | None,
        period: int,
        debug_log: bool = True,
    ) -> float | None:
        try:
            df = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            df = None
        if df is None or df.empty or "close" not in df.columns:
            return None
        work = df.copy()
        row = None
        if ts is not None and "date" in work.columns:
            try:
                target = pd.Timestamp(ts)
                if target.tzinfo is None:
                    target = target.tz_localize("UTC")
                else:
                    target = target.tz_convert("UTC")
                dates = pd.to_datetime(work["date"], utc=True, errors="coerce")
                loc = int(dates.searchsorted(target, side="right") - 1)
                if loc >= 0:
                    work = work.iloc[: loc + 1].copy()
                    row = work.iloc[-1]
            except Exception:
                row = None
        if row is None:
            row = work.iloc[-1]
        if work.empty:
            return None
        atr_series = pd.Series(ta.ATR(work, timeperiod=max(1, int(period))))
        atr = float(atr_series.iloc[-1]) if not atr_series.empty else 0.0
        close = float(row.get("close", 0.0) or 0.0)
        if not np.isfinite(atr) or atr <= 0 or close <= 0:
            return None
        atr_pct = max(0.0, atr / close)
        if debug_log and self.vol_stop_debug.value:
            logger.info(
                "VOLSTOP_ATR pair=%s tf=%s ts=%s atr_pct=%.6f",
                pair,
                tf,
                ts.isoformat() if ts else "na",
                atr_pct,
            )
        return atr_pct

    def _atr_pct(self, pair: str, tf: str, current_time: datetime | None) -> float:
        atr_pct = self._atr_pct_at_time(pair, tf, current_time, int(self.vol_stop_atr_period.value))
        return float(atr_pct or 0.0)

    def _friction_floor_pct(self) -> float:
        return max(
            float(self.vol_stop_fee_roundtrip_pct.value)
            + float(self.vol_stop_slip_floor_pct.value)
            + float(self.vol_stop_friction_buffer_pct.value),
            0.0,
        )

    def _vol_stop_bounds_for_sleeve(self, sleeve: str) -> tuple[float, float]:
        if sleeve == "micro_alpha_5m":
            min_stop = float(self.vol_stop_min_pct_micro.value)
            max_stop = float(self.vol_stop_max_pct_micro.value)
        else:
            min_stop = float(self.vol_stop_min_pct.value)
            max_stop = float(self.vol_stop_max_pct.value)
        if self.vol_stop_friction_floor_enabled.value:
            min_stop = max(min_stop, self._friction_floor_pct())
        max_stop = max(max_stop, min_stop)
        return min_stop, max_stop

    def _vol_stop_source_for_sleeve(self, sleeve: str) -> tuple[str, int]:
        if sleeve == "micro_alpha_5m":
            return str(self.vol_stop_micro_source_tf.value), int(self.vol_stop_micro_atr_period.value)
        return str(self.vol_stop_source_tf.value), int(self.vol_stop_atr_period.value)

    def _vol_stop_mult_for_context(self, sleeve: str, regime: str) -> float:
        sleeve_mult = {
            "micro_alpha_5m": float(self.vol_stop_mult_micro.value),
            "trend": float(self.vol_stop_mult_trend.value),
            "mean_reversion": float(self.vol_stop_mult_mean_reversion.value),
            "bearvol": float(self.vol_stop_mult_bearvol.value),
            "convex": float(self.vol_stop_mult_convex.value),
        }.get(sleeve, float(self.vol_stop_mult_default.value))
        regime_mult = {
            "CHOP_MR": float(self.vol_stop_regime_mult_chop_mr.value),
            "TREND_PULLBACK": float(self.vol_stop_regime_mult_trend_pullback.value),
            "TREND_BREAKOUT": float(self.vol_stop_regime_mult_trend_breakout.value),
            "VOL_EXP": float(self.vol_stop_regime_mult_vol_exp.value),
            "PANIC": float(self.vol_stop_regime_mult_panic.value),
            "BEARVOL": float(self.vol_stop_regime_mult_bearvol.value),
        }.get(regime, 1.0)
        return sleeve_mult * regime_mult

    def _fixed_stop_pct_for_tag(self, entry_tag: str | None) -> float:
        tag = (entry_tag or "").lower()
        if self._is_micro5m_entry_tag(tag):
            return float(self.micro5m_max_loss_pct.value)
        if "cbx" in tag:
            return float(
                self.buy_cbx4h_max_hard_stop.value
                if str(self.buy_cbx_mode.value) == "cbx_4h_anchor"
                else self.buy_cbx_max_hard_stop.value
            )
        if "mr_long" in tag:
            return float(self.sell_mr_sl_hard_cap.value)
        if self._is_brf_entry_tag(tag):
            return max(0.0, abs(float(self.stoploss)))
        return max(0.0, abs(float(self.stoploss)))

    def _csv_token_set(self, raw: str | None) -> set[str]:
        return {tok.strip() for tok in str(raw or "").split(",") if tok and tok.strip()}

    def _vol_stop_applies_to_tag(self, entry_tag: str | None) -> bool:
        if not self.vol_stop_enabled.value:
            return False
        sleeve = self._sleeve_key_from_tag(entry_tag)
        allow = self._csv_token_set(str(self.vol_stop_sleeve_allowlist.value))
        deny = self._csv_token_set(str(self.vol_stop_sleeve_denylist.value))
        if allow:
            if "*" in allow:
                return sleeve not in deny
            return sleeve in allow and sleeve not in deny
        return False

    def _effective_stop_pct_for_candidate(
        self,
        pair: str,
        current_time: datetime | None,
        entry_tag: str | None,
        rate: float | None,
    ) -> float | None:
        sleeve = self._sleeve_key_from_tag(entry_tag)
        if not self.vol_stop_enabled.value:
            return None
        if not self._vol_stop_applies_to_tag(entry_tag):
            if self.vol_stop_debug.value:
                logger.info(
                    "VOLSTOP_SKIP pair=%s ts=%s sleeve=%s reason=not_allowed",
                    pair,
                    current_time.isoformat() if current_time else "na",
                    sleeve,
                )
            return None
        regime = self._regime_for_pair_time(pair, current_time, entry_tag)
        tf, period = self._vol_stop_source_for_sleeve(sleeve)
        atr_pct = self._atr_pct_at_time(pair, tf, current_time, period)
        if atr_pct is None or atr_pct <= 0:
            if self.vol_stop_debug.value:
                logger.info(
                    "VOLSTOP_SKIP pair=%s ts=%s sleeve=%s reason=no_atr tf=%s",
                    pair,
                    current_time.isoformat() if current_time else "na",
                    sleeve,
                    tf,
                )
            return None
        mult = self._vol_stop_mult_for_context(sleeve, regime)
        if mult <= 0:
            if self.vol_stop_debug.value:
                logger.info(
                    "VOLSTOP_SKIP pair=%s ts=%s sleeve=%s reason=mult_nonpositive",
                    pair,
                    current_time.isoformat() if current_time else "na",
                    sleeve,
                )
            return None
        base_stop = atr_pct * mult
        min_stop, max_stop = self._vol_stop_bounds_for_sleeve(sleeve)
        stop_pct = float(np.clip(base_stop, min_stop, max_stop))
        if sleeve == "micro_alpha_5m":
            self._vol_stop_stats["micro_n"] = float(self._vol_stop_stats.get("micro_n", 0.0)) + 1.0
            self._vol_stop_stats["micro_base_sum"] = float(self._vol_stop_stats.get("micro_base_sum", 0.0)) + float(base_stop)
            self._vol_stop_stats["micro_stop_sum"] = float(self._vol_stop_stats.get("micro_stop_sum", 0.0)) + float(stop_pct)
            if abs(stop_pct - min_stop) < 1e-9:
                self._vol_stop_stats["micro_floor_hits"] = float(self._vol_stop_stats.get("micro_floor_hits", 0.0)) + 1.0
            else:
                self._vol_stop_stats["micro_free_hits"] = float(self._vol_stop_stats.get("micro_free_hits", 0.0)) + 1.0
            if self.vol_stop_debug.value:
                micro_n = int(self._vol_stop_stats.get("micro_n", 0))
                logger.info(
                    "MICRO_VOLSTOP_STATS floor_hits=%s free_hits=%s base_avg=%.4f stop_avg=%.4f",
                    int(self._vol_stop_stats.get("micro_floor_hits", 0)),
                    int(self._vol_stop_stats.get("micro_free_hits", 0)),
                    float(self._vol_stop_stats.get("micro_base_sum", 0.0)) / max(1, micro_n),
                    float(self._vol_stop_stats.get("micro_stop_sum", 0.0)) / max(1, micro_n),
                )
        if self.vol_stop_debug.value:
            logger.info(
                "VOLSTOP_APPLY pair=%s ts=%s sleeve=%s regime=%s tf=%s atr_pct=%.4f mult=%.4f base_stop=%.4f minp=%.4f maxp=%.4f stop_pct=%.4f",
                pair,
                current_time.isoformat() if current_time else "na",
                sleeve,
                regime,
                tf,
                atr_pct,
                mult,
                base_stop,
                min_stop,
                max_stop,
                stop_pct,
            )
        return stop_pct

    def _effective_stop_pct_for_trade(self, pair: str, trade: Trade) -> float | None:
        tid = self._trade_id(trade)
        if tid is not None and tid in self._vol_stop_pct_state:
            return float(self._vol_stop_pct_state.get(tid, 0.0) or 0.0)
        entry_tag = getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)
        if not self._vol_stop_applies_to_tag(entry_tag):
            return None
        open_dt = getattr(trade, "open_date_utc", None) or getattr(trade, "open_date", None)
        stop_pct = self._effective_stop_pct_for_candidate(pair, open_dt, entry_tag, getattr(trade, "open_rate", None))
        if stop_pct is not None and stop_pct > 0:
            if tid is not None:
                self._vol_stop_pct_state[tid] = float(stop_pct)
            return float(stop_pct)
        sleeve = self._sleeve_key_from_tag(entry_tag)
        if sleeve == "micro_alpha_5m" and self.vol_stop_cache_entry_atr.value and tid is not None:
            atr_pct = float(self._vol_stop_entry_atr_pct_state.get(tid, 0.0) or 0.0)
            if atr_pct > 0:
                regime = self._trade_regime_state.get(
                    tid,
                    self._regime_for_pair_time(pair, open_dt, entry_tag),
                )
                mult = self._vol_stop_mult_for_context(sleeve, regime)
                if mult > 0:
                    min_stop, max_stop = self._vol_stop_bounds_for_sleeve(sleeve)
                    base_stop = atr_pct * mult
                    stop_pct = float(
                        np.clip(
                            base_stop,
                            min_stop,
                            max_stop,
                        )
                    )
                    self._vol_stop_pct_state[tid] = stop_pct
                    if self.vol_stop_debug.value:
                        logger.info(
                            "VOLSTOP_FALLBACK_ENTRY_ATR pair=%s trade_id=%s sleeve=%s atr_pct=%.4f mult=%.4f base_stop=%.4f minp=%.4f maxp=%.4f stop_pct=%.4f",
                            pair,
                            tid,
                            sleeve,
                            atr_pct,
                            mult,
                            base_stop,
                            min_stop,
                            max_stop,
                            stop_pct,
                        )
                    return stop_pct
        return None

    def _bind_pending_risk_state(self, pair: str, trade: Trade) -> None:
        tid = self._trade_id(trade)
        if tid is None or tid in self._trade_regime_state:
            return
        pending = self._vol_stop_pending_state.pop(pair, None)
        if pending is None:
            stop_pct = self._effective_stop_pct_for_trade(pair, trade)
            if stop_pct is not None and stop_pct > 0:
                self._vol_stop_pct_state[tid] = float(stop_pct)
            sleeve = self._sleeve_key_from_tag(
                getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)
            )
            if sleeve == "micro_alpha_5m" and self.vol_stop_cache_entry_atr.value:
                open_dt = getattr(trade, "open_date_utc", None) or getattr(trade, "open_date", None)
                tf, period = self._vol_stop_source_for_sleeve(sleeve)
                entry_atr_pct = self._atr_pct_at_time(pair, tf, open_dt, period)
                if entry_atr_pct is not None and entry_atr_pct > 0:
                    self._vol_stop_entry_atr_pct_state[tid] = float(entry_atr_pct)
            self._trade_regime_state[tid] = self._regime_for_pair_time(
                pair,
                getattr(trade, "open_date_utc", None) or getattr(trade, "open_date", None),
                getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None),
            )
            self._trade_sleeve_state[tid] = sleeve
            return
        stop_pct = float(pending.get("stop_pct", 0.0) or 0.0)
        regime = str(pending.get("regime", "TREND_PULLBACK") or "TREND_PULLBACK")
        sleeve = str(pending.get("sleeve", "other") or "other")
        entry_atr_pct = float(pending.get("entry_atr_pct", 0.0) or 0.0)
        self._vol_stop_pct_state[tid] = stop_pct
        if entry_atr_pct > 0:
            self._vol_stop_entry_atr_pct_state[tid] = entry_atr_pct
        self._trade_regime_state[tid] = regime
        self._trade_sleeve_state[tid] = sleeve
        self._vol_stop_stats["set_calls"] = float(self._vol_stop_stats.get("set_calls", 0.0)) + 1.0
        self._vol_stop_stats["sum_stop_pct"] = float(self._vol_stop_stats.get("sum_stop_pct", 0.0)) + stop_pct
        self._vol_stop_sum_by_sleeve[sleeve] = float(self._vol_stop_sum_by_sleeve.get(sleeve, 0.0)) + stop_pct
        self._vol_stop_count_by_sleeve[sleeve] = int(self._vol_stop_count_by_sleeve.get(sleeve, 0)) + 1
        if self.vol_stop_debug.value:
            logger.info(
                "VOL_STOP_SET pair=%s trade_id=%s sleeve=%s regime=%s stop_pct=%.4f",
                pair,
                tid,
                sleeve,
                regime,
                stop_pct,
            )

    def _regime_alloc_usage(self, mode: str) -> tuple[dict[str, float], float]:
        usage: dict[str, float] = {
            "CHOP_MR": 0.0,
            "TREND_PULLBACK": 0.0,
            "TREND_BREAKOUT": 0.0,
            "VOL_EXP": 0.0,
            "PANIC": 0.0,
            "BEARVOL": 0.0,
        }
        total = 0.0
        open_trades = self._safe_get_open_trades() or []
        for tr in open_trades:
            tid = self._trade_id(tr)
            if tid is None:
                continue
            stake = float(getattr(tr, "stake_amount", 0.0) or 0.0)
            if stake <= 0:
                continue
            regime = self._trade_regime_state.get(tid)
            if regime is None:
                pair = str(getattr(tr, "pair", "") or "")
                self._bind_pending_risk_state(pair, tr)
                regime = self._trade_regime_state.get(tid, "TREND_PULLBACK")
            item = stake
            if mode == "risk":
                stop_pct = self._vol_stop_pct_state.get(tid)
                if stop_pct is None or stop_pct <= 0:
                    pair = str(getattr(tr, "pair", "") or "")
                    stop_pct = self._effective_stop_pct_for_trade(pair, tr)
                if stop_pct is None or stop_pct <= 0:
                    entry_tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
                    stop_pct = self._fixed_stop_pct_for_tag(entry_tag)
                lev = max(1.0, float(getattr(tr, "leverage", 1.0) or 1.0))
                item = stake * max(float(stop_pct or 0.0), 0.0) * lev
            usage[regime] = float(usage.get(regime, 0.0)) + item
            total += item
        return usage, total

    def _maybe_prepare_regime_alloc(
        self,
        pair: str,
        current_time: datetime,
        entry_tag: str | None,
        proposed_stake: float,
        rate: float,
    ) -> tuple[bool, dict[str, float | str]]:
        if not self.regime_alloc_enabled.value:
            return True, {}
        mode = str(self.regime_alloc_mode.value)
        regime = self._regime_for_pair_time(pair, current_time, entry_tag)
        sleeve = self._sleeve_key_from_tag(entry_tag)
        stop_pct = self._effective_stop_pct_for_candidate(pair, current_time, entry_tag, rate)
        if stop_pct is None or stop_pct <= 0:
            stop_pct = self._fixed_stop_pct_for_tag(entry_tag)
        equity = max(0.0, float(self._wallet_total() or 0.0))
        if equity <= 0:
            equity = float(self.config.get("dry_run_wallet", 1000.0) or 1000.0)
        usage_by_regime, total_used = self._regime_alloc_usage(mode)
        budget = equity * self._regime_alloc_budget(regime, mode)
        used = float(usage_by_regime.get(regime, 0.0))
        remaining = max(0.0, budget - used)
        if self.regime_alloc_apply_globally.value:
            global_budget = equity * self._regime_alloc_global_budget(mode)
            remaining = min(remaining, max(0.0, global_budget - total_used))
        remaining *= self._regime_alloc_sleeve_weight(sleeve)
        if mode == "risk":
            bucket = self._tag_bucket(entry_tag)
            est_lev = max(1.0, float(self._base_leverage(bucket)))
            remaining_stake = remaining / max(stop_pct * est_lev, 1e-6)
        else:
            remaining_stake = remaining
        proposed = max(0.0, float(proposed_stake))
        clamped = min(proposed, remaining_stake)
        min_stake = float(self.regime_alloc_min_stake_usdt.value)
        self._alloc_counts["calls"] = float(self._alloc_counts.get("calls", 0.0)) + 1.0
        self._alloc_counts["remaining_sum"] = float(self._alloc_counts.get("remaining_sum", 0.0)) + max(0.0, remaining_stake)
        if clamped < proposed:
            self._alloc_counts["clamps"] = float(self._alloc_counts.get("clamps", 0.0)) + 1.0
        if clamped < min_stake and self.regime_alloc_block_if_below_min.value:
            self._alloc_counts["blocks"] = float(self._alloc_counts.get("blocks", 0.0)) + 1.0
            details = {
                "regime": regime,
                "sleeve": sleeve,
                "mode": mode,
                "budget": budget,
                "used": used,
                "remaining": remaining_stake,
                "proposed": proposed,
                "clamped": clamped,
                "stop_pct": stop_pct,
                "blocked": "1",
            }
            if self.regime_alloc_debug.value:
                logger.info(
                    "REGIME_ALLOC_BLOCK ts=%s pair=%s regime=%s sleeve=%s mode=%s proposed=%.2f clamped=%.2f used=%.2f remaining=%.2f stop_pct=%.4f",
                    current_time.isoformat() if current_time else "na",
                    pair,
                    regime,
                    sleeve,
                    mode,
                    proposed,
                    clamped,
                    used,
                    remaining_stake,
                    stop_pct,
                )
            return False, details
        details = {
            "regime": regime,
            "sleeve": sleeve,
            "mode": mode,
            "budget": budget,
            "used": used,
            "remaining": remaining_stake,
            "proposed": proposed,
            "clamped": clamped,
            "stop_pct": stop_pct,
        }
        if self.regime_alloc_debug.value:
            logger.info(
                "REGIME_ALLOC_ALLOW ts=%s pair=%s regime=%s sleeve=%s mode=%s proposed=%.2f clamped=%.2f used=%.2f remaining=%.2f stop_pct=%.4f",
                current_time.isoformat() if current_time else "na",
                pair,
                regime,
                sleeve,
                mode,
                proposed,
                float(details["clamped"]),
                used,
                remaining_stake,
                stop_pct,
            )
        return True, details

    def _base_stake_mult(self, bucket: str) -> float:
        return {
            "panic": float(self.stake_mult_panic),
            "veb": float(self.stake_mult_veb),
            "mr_long": float(self.mr_stake_mult),
            "trbk": float(self.stake_mult_trbk),
            "trbk_short": float(self.stake_mult_trbk_short),
            "bearvol_short": float(self.stake_mult_bearvol_short),
            "brf_short": float(self.sell_brf_alloc_mult.value),
            "cbx": float(self.stake_mult_cbx),
            "micro5m": float(self.stake_mult_other),
            "liqcascade": float(self.stake_mult_other),
            "liqcascade_v2": float(self.stake_mult_other),
            "fimr": float(self.stake_mult_other),
            "spreadarb": float(self.stake_mult_other),
            "cpdf": float(self.stake_mult_other),
            "fcarry": float(self.stake_mult_other),
            "cvw": float(self.stake_mult_other),
            "mofi": float(self.stake_mult_other),
            "idle_fr": float(self.stake_mult_other),
            "other": float(self.stake_mult_other),
        }.get(bucket, 1.0)

    def _loss_streak_mult(self, bucket: str) -> float:
        """Reduce stake after consecutive losses in a bucket."""
        s = int(self._bucket_loss_streak.get(bucket, 0))
        if s <= 0:
            return 1.0
        if s == 1:
            return float(self.loss_mult_1)
        if s == 2:
            return float(self.loss_mult_2)
        return float(self.loss_mult_3p)

    def _base_leverage(self, bucket: str) -> float:
        return {
            "panic": float(self.lev_panic),
            "veb": float(self.lev_veb),
            "mr_long": float(self.mr_leverage),
            "trbk": float(self.lev_trbk),
            "trbk_short": float(self.lev_trbk_short),
            "bearvol_short": float(self.lev_bearvol_short),
            "brf_short": float(self.sell_brf_leverage.value),
            "cbx": float(self.lev_cbx),
            "micro5m": float(self.lev_other),
            "liqcascade": float(self.lev_other),
            "liqcascade_v2": float(self.lev_other),
            "fimr": float(self.lev_other),
            "spreadarb": float(self.lev_other),
            "cpdf": float(self.lev_other),
            "fcarry": float(self.lev_other),
            "cvw": float(self.lev_other),
            "mofi": float(self.lev_other),
            "idle_fr": float(self.lev_other),
            "other": float(self.lev_other),
        }.get(bucket, float(self.lev_other))

    def _cap_for_bucket(self, bucket: str) -> int | None:
        return {
            "panic": self.cap_open_trades_panic,
            "veb": self.cap_open_trades_veb,
            "mr_long": self.cap_open_trades_mr,
            "trbk": self.cap_open_trades_trbk,
            "trbk_short": self.cap_open_trades_trbk_short,
            "bearvol_short": self.cap_open_trades_bearvol_short,
            "brf_short": int(self.cap_open_trades_brf.value),
            "cbx": self.cap_open_trades_cbx,
            "micro5m": None,
            "liqcascade": None,
            "liqcascade_v2": None,
            "fimr": None,
            "spreadarb": None,
            "cpdf": None,
            "fcarry": None,
            "cvw": None,
            "mofi": None,
            "idle_fr": None,
            "idle": None,
            "other": self.cap_open_trades_other,
        }.get(bucket)

    def _count_open_trades_by_bucket(self, bucket: str) -> int:
        """Best-effort: count open trades matching bucket. Fails open (returns 0)."""
        try:
            open_trades = Trade.get_open_trades()
        except Exception:
            return 0
        n = 0
        for tr in open_trades:
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._tag_bucket(tag) == bucket:
                n += 1
        return n

    # ── Helpers: parsing, heat, adaptive TRBK cap, loss-streak decay ──

    def _parse_numeric(self, v) -> float | None:
        """Safely parse a numeric value. Returns None for 'unlimited'/invalid."""
        try:
            if v is None:
                return None
            if isinstance(v, (int, float)):
                return float(v)
            s = str(v).strip().lower()
            if not s or s in ("unlimited", "inf", "infinite", "none"):
                return None
            return float(s)
        except Exception:
            return None

    def _maybe_decay_loss_streak(self, bucket: str, idx: int) -> None:
        """Decay loss streak by 1 if enough bars elapsed since last loss."""
        if not self.loss_decay_enabled:
            return
        last_loss = self._bucket_last_loss_idx.get(bucket)
        if last_loss is None:
            return
        if idx - int(last_loss) >= int(self.loss_decay_after_bars):
            cur = int(self._bucket_loss_streak.get(bucket, 0))
            if cur > 0:
                self._bucket_loss_streak[bucket] = max(0, cur - int(self.loss_decay_step))
                self._bucket_last_loss_idx[bucket] = idx  # prevent repeated decay

    def _safe_get_open_trades(self):
        try:
            return Trade.get_open_trades()
        except Exception:
            return None

    def _count_open_trades_total(self) -> int:
        ot = self._safe_get_open_trades()
        return 0 if ot is None else len(ot)

    # ── Cross-sleeve ranking helpers ──

    def _rank_stats_key(self, entry_tag: str | None) -> str:
        return self._tag_bucket(entry_tag)

    def _rank_hitrate(self, entry_tag: str | None) -> float:
        stats = self._rank_stats.get(self._rank_stats_key(entry_tag))
        if not stats or len(stats) < 3:
            return 0.5
        try:
            return float(np.mean(list(stats)))
        except Exception:
            return 0.5

    def _rank_tag_bias(self, entry_tag: str | None) -> float:
        bucket = self._tag_bucket(entry_tag)
        return {
            "panic": float(self.rank_tag_bias_panic.value),
            "veb": float(self.rank_tag_bias_veb.value),
            "mr_long": float(self.rank_tag_bias_mr.value),
            "trbk": float(self.rank_tag_bias_trbk.value),
            "trbk_short": float(self.rank_tag_bias_trbk_short.value),
            "bearvol_short": float(self.rank_tag_bias_bearvol.value),
            "brf_short": float(self.rank_tag_bias_brf.value),
            "cbx": float(self.rank_tag_bias_cbx.value),
            "micro5m": float(self.rank_tag_bias_other.value),
            "other": float(self.rank_tag_bias_other.value),
        }.get(bucket, 0.0)

    def _rank_pair_dataframe(self, pair: str) -> pd.DataFrame | None:
        try:
            df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
            if df is not None and not df.empty:
                return df
        except Exception:
            pass
        return None

    def _rank_latest_row(self, pair: str) -> pd.Series | None:
        df = self._rank_pair_dataframe(pair)
        if df is not None:
            return df.iloc[-1]
        return None

    def _rank_row_for_time(
        self,
        pair: str,
        current_time: datetime | None,
        df: pd.DataFrame | None = None,
    ) -> tuple[pd.Series | None, int | None, pd.DataFrame | None]:
        if current_time is None:
            row = self._rank_latest_row(pair)
            if row is None:
                return None, None, df
            use_df = df if df is not None else self._rank_pair_dataframe(pair)
            if use_df is None or use_df.empty:
                return row, None, use_df
            return row, len(use_df) - 1, use_df

        use_df = df if df is not None else self._rank_pair_dataframe(pair)
        if use_df is None or use_df.empty or "date" not in use_df.columns:
            return None, None, use_df
        try:
            ts = pd.Timestamp(current_time)
            if ts.tzinfo is None:
                ts = ts.tz_localize("UTC")
            else:
                ts = ts.tz_convert("UTC")
        except Exception:
            return None, None, use_df
        try:
            dates = pd.to_datetime(use_df["date"], utc=True, errors="coerce")
            if dates.isna().all():
                return None, None, use_df
            loc = int(dates.searchsorted(ts, side="right") - 1)
            if loc < 0:
                return None, None, use_df
            return use_df.iloc[loc], loc, use_df
        except Exception:
            return None, None, use_df

    def _rank_ts_key(self, row: pd.Series | None) -> str | None:
        if row is None:
            return None
        ts = row.get("rank_ts", row.get("date", None))
        if ts is None or pd.isna(ts):
            return None
        try:
            return pd.Timestamp(ts).isoformat()
        except Exception:
            try:
                return str(ts)
            except Exception:
                return None

    def _rank_row_has_signal(self, row: pd.Series | None) -> bool:
        if row is None:
            return False
        try:
            return bool(int(row.get("enter_long", 0)) == 1 or int(row.get("enter_short", 0)) == 1)
        except Exception:
            return False

    def _rank_row_score(self, row: pd.Series | None, entry_tag: str | None, pair: str | None = None) -> float:
        if row is None:
            return -1e9
        try:
            base = float(row.get("rank_score_base", np.nan))
        except Exception:
            return -1e9
        if not np.isfinite(base):
            return -1e9
        score = base
        score += float(self.rank_w_hitrate.value) * self._rank_hitrate(entry_tag)
        score += self._rank_tag_bias(entry_tag)
        if pair:
            pair_sleeve_penalty = self._pair_sleeve_rank_penalty(pair, entry_tag)
            pair_edge_penalty = self._pair_edge_rank_penalty(pair)
            tpb_pair_health_penalty = self._trendpb_pair_health_rank_penalty(pair, entry_tag)
            conc_penalty = self._rank_concentration_penalty(pair, entry_tag)
            score -= pair_sleeve_penalty
            score -= pair_edge_penalty
            score -= tpb_pair_health_penalty
            score -= conc_penalty
            if pair_sleeve_penalty > 0.0:
                self._rank_counts["pair_sleeve_penalty_hits"] = int(self._rank_counts.get("pair_sleeve_penalty_hits", 0)) + 1
                self._rank_counts["pair_sleeve_penalty_sum"] = float(self._rank_counts.get("pair_sleeve_penalty_sum", 0.0)) + float(pair_sleeve_penalty)
            if pair_edge_penalty > 0.0:
                self._rank_counts["pair_edge_penalty_hits"] = int(self._rank_counts.get("pair_edge_penalty_hits", 0)) + 1
                self._rank_counts["pair_edge_penalty_sum"] = float(self._rank_counts.get("pair_edge_penalty_sum", 0.0)) + float(pair_edge_penalty)
            if tpb_pair_health_penalty > 0.0:
                self._rank_counts["trendpb_pair_health_penalty_hits"] = int(self._rank_counts.get("trendpb_pair_health_penalty_hits", 0)) + 1
                self._rank_counts["trendpb_pair_health_penalty_sum"] = float(self._rank_counts.get("trendpb_pair_health_penalty_sum", 0.0)) + float(tpb_pair_health_penalty)
            if conc_penalty > 0.0:
                self._rank_counts["concentration_penalty_hits"] = int(self._rank_counts.get("concentration_penalty_hits", 0)) + 1
                self._rank_counts["concentration_penalty_sum"] = float(self._rank_counts.get("concentration_penalty_sum", 0.0)) + float(conc_penalty)
        return float(score) if np.isfinite(score) else -1e9

    def _rank_samebar_snapshot(
        self,
        current_pair: str,
        current_time: datetime | None,
    ) -> tuple[str | None, dict[str, dict[str, float | str]]]:
        current_row, _, _ = self._rank_row_for_time(current_pair, current_time)
        ts_key = self._rank_ts_key(current_row)
        if ts_key is None:
            return None, {}
        cache_key = f"same:{ts_key}"
        cached = self._rank_cache.get(cache_key)
        if cached is not None:
            return ts_key, cached

        try:
            pairs = list(self.dp.current_whitelist())
        except Exception:
            pairs = []
        if current_pair and current_pair not in pairs:
            pairs.append(current_pair)

        snapshot: dict[str, dict[str, float | str]] = {}
        for p in pairs:
            row, _, _ = self._rank_row_for_time(p, current_time)
            if row is None or self._rank_ts_key(row) != ts_key:
                continue
            if not self._rank_row_has_signal(row):
                continue
            tag = str(row.get("rank_tag", row.get("enter_tag", "")) or row.get("enter_tag", ""))
            snapshot[p] = {
                "score": self._rank_row_score(row, tag, p),
                "tag": tag,
            }

        self._rank_cache = {cache_key: snapshot}
        if ts_key not in self._rank_seen_ts:
            self._rank_seen_ts.add(ts_key)
            if snapshot:
                self._rank_counts["cand_bars"] = int(self._rank_counts.get("cand_bars", 0)) + 1
                self._rank_counts["cand_total"] = int(self._rank_counts.get("cand_total", 0)) + len(snapshot)
            self._rank_counts["max_cands_seen"] = max(
                int(self._rank_counts.get("max_cands_seen", 0)),
                len(snapshot),
            )
            self._rank_counts["max_candidates_in_bar"] = max(
                int(self._rank_counts.get("max_candidates_in_bar", 0)),
                len(snapshot),
            )
        return ts_key, snapshot

    def _rank_queue_snapshot(
        self,
        current_pair: str,
        current_time: datetime | None,
    ) -> tuple[str | None, dict[str, dict[str, float | str | int]]]:
        if current_time is None:
            return None, {}
        try:
            ts = pd.Timestamp(current_time)
            if ts.tzinfo is None:
                ts = ts.tz_localize("UTC")
            else:
                ts = ts.tz_convert("UTC")
            ts_key = ts.isoformat()
        except Exception:
            return None, {}
        window_bars = max(1, int(self.rank_queue_window_bars.value))
        cache_key = f"queue:{ts_key}:{window_bars}"
        cached = self._rank_queue_cache.get(cache_key)
        if cached is not None:
            return ts_key, cached

        try:
            pairs = list(self.dp.current_whitelist())
        except Exception:
            pairs = []
        if current_pair and current_pair not in pairs:
            pairs.append(current_pair)

        snapshot: dict[str, dict[str, float | str | int]] = {}
        for p in pairs:
            df = self._rank_pair_dataframe(p)
            row_now, cur_loc, df = self._rank_row_for_time(p, current_time, df)
            if row_now is None or cur_loc is None or df is None:
                continue
            start_loc = max(0, cur_loc - window_bars + 1)
            window_df = df.iloc[start_loc:cur_loc + 1]
            if window_df.empty:
                continue
            try:
                sig_mask = (
                    window_df.get("enter_long", 0).fillna(0).astype(int).eq(1)
                    | window_df.get("enter_short", 0).fillna(0).astype(int).eq(1)
                )
            except Exception:
                continue
            if not bool(sig_mask.any()):
                continue
            rel_pos = int(np.flatnonzero(sig_mask.to_numpy())[-1])
            cand_loc = start_loc + rel_pos
            row = df.iloc[cand_loc]
            tag = str(row.get("rank_tag", row.get("enter_tag", "")) or row.get("enter_tag", ""))
            snapshot[p] = {
                "score": self._rank_row_score(row, tag, p),
                "tag": tag,
                "age": int(cur_loc - cand_loc),
            }

        self._rank_queue_cache = {cache_key: snapshot}
        if ts_key not in self._rank_queue_seen_ts:
            self._rank_queue_seen_ts.add(ts_key)
            if snapshot:
                self._rank_queue_counts["cand_bars"] = int(self._rank_queue_counts.get("cand_bars", 0)) + 1
                self._rank_queue_counts["cand_total"] = int(self._rank_queue_counts.get("cand_total", 0)) + len(snapshot)
            self._rank_queue_counts["max_cands_seen"] = max(
                int(self._rank_queue_counts.get("max_cands_seen", 0)),
                len(snapshot),
            )
        return ts_key, snapshot

    def _rank_position_size_mult(
        self,
        pair: str,
        entry_tag: str | None,
        row: pd.Series | None,
        current_time: datetime | None = None,
    ) -> float:
        if not self.rank_position_sizing_enabled.value:
            return 1.0
        if self.rank_queue_enabled.value:
            _, snapshot = self._rank_queue_snapshot(pair, current_time)
        elif self.rank_enabled.value:
            _, snapshot = self._rank_samebar_snapshot(pair, current_time)
        else:
            snapshot = {}
        if not snapshot and row is not None:
            ts_key = self._rank_ts_key(row)
            if ts_key is not None:
                _, snapshot = self._rank_samebar_snapshot(pair, current_time)
        if pair not in snapshot:
            return 1.0
        if len(snapshot) <= 1:
            return float(self.rank_psize_max_mult.value)

        try:
            current_score = float(snapshot[pair]["score"])
        except Exception:
            return 1.0
        scores = sorted(float(v["score"]) for v in snapshot.values())
        if not scores:
            return 1.0
        lower_count = sum(1 for s in scores if s < current_score)
        equal_count = sum(1 for s in scores if s == current_score)
        percentile = (lower_count + (equal_count - 1) / 2.0) / max(1.0, float(len(scores) - 1))
        percentile = float(np.clip(percentile, 0.0, 1.0))
        min_mult = float(self.rank_psize_min_mult.value)
        max_mult = float(self.rank_psize_max_mult.value)
        return min_mult + (max_mult - min_mult) * percentile

    @staticmethod
    def _clip01(x: float) -> float:
        try:
            xv = float(x)
        except Exception:
            return 0.0
        if xv < 0.0:
            return 0.0
        if xv > 1.0:
            return 1.0
        return xv

    @staticmethod
    def _qsize_ml_profile_weights(profile: str) -> dict[str, float]:
        p = str(profile or "off").strip().lower()
        if p == "lin_v1":
            return {
                "bias": -0.10,
                "trend": 0.95,
                "break": 1.20,
                "vol": 0.85,
                "x_tb": 0.45,
                "bucket_trbk": 0.06,
                "bucket_trendpb": 0.04,
                "bucket_cbx": 0.02,
                "bucket_bearvol_short": -0.22,
            }
        if p == "lin_v2":
            return {
                "bias": -0.06,
                "trend": 0.80,
                "break": 1.45,
                "vol": 0.92,
                "x_tb": 0.62,
                "bucket_trbk": 0.08,
                "bucket_trendpb": 0.03,
                "bucket_cbx": 0.00,
                "bucket_bearvol_short": -0.28,
            }
        if p == "lin_cons":
            return {
                "bias": -0.20,
                "trend": 0.75,
                "break": 1.00,
                "vol": 0.75,
                "x_tb": 0.30,
                "bucket_trbk": 0.02,
                "bucket_trendpb": 0.02,
                "bucket_cbx": 0.00,
                "bucket_bearvol_short": -0.34,
            }
        return {}

    @staticmethod
    def _safe_sigmoid(z: float) -> float:
        if z >= 0:
            ez = math.exp(-min(z, 60.0))
            return float(1.0 / (1.0 + ez))
        ez = math.exp(max(z, -60.0))
        return float(ez / (1.0 + ez))

    def _qsize_score(
        self,
        row: pd.Series | dict | None,
        sleeve: str,
        side: str = "long",
    ) -> tuple[float, dict[str, float | str]]:
        """
        Compute signal-quality score in [0, 1] from trend / breakout / vol context.
        Fail-open to score=0.5 so enabling qsize never breaks entry flow.
        """
        neutral = (0.5, {"trend": 0.5, "break": 0.5, "vol": 0.5, "reason": "neutral"})
        if row is None:
            return neutral

        try:
            side_l = str(side or "long").lower()
            sleeve_l = str(sleeve or "").lower()

            def _num(v: object) -> float:
                try:
                    f = float(v)  # type: ignore[arg-type]
                    return f if np.isfinite(f) else float("nan")
                except Exception:
                    return float("nan")

            def _pick(cols: list[str]) -> float:
                for c in cols:
                    v = _num(row.get(c, np.nan))
                    if np.isfinite(v):
                        return v
                return float("nan")

            adx = _pick(["adx", "cbx_adx", "trbk_adx"])
            trend = self._clip01((adx - 15.0) / 20.0) if np.isfinite(adx) else 0.5

            close = _num(row.get("close", np.nan))
            itf = str(self.buy_volex_informative_tf.value or "4h")
            donch_col = f"volex_itf_donch_high_{itf}"
            atr_col = f"volex_itf_atr_{itf}"

            if sleeve_l == "cbx":
                thr = _pick(["cbx4h_break_thr", "cbx4h_break_thr_4h", "cbx_breakout_thr"])
            elif sleeve_l in {"veb", "volex"}:
                thr = _pick([donch_col, "volex_itf_donch_high", "volex_donch_high_1h"])
            elif sleeve_l == "trbk":
                thr = _pick(["trbk_donch_high_4h"])
            elif sleeve_l == "trendpb":
                thr = _pick(["trendpb_ema_fast", "trendpb_prev_ema_fast"])
            else:
                thr = _pick(
                    [
                        "cbx4h_break_thr",
                        "cbx4h_break_thr_4h",
                        "cbx_breakout_thr",
                        "trbk_donch_high_4h",
                        donch_col,
                        "volex_itf_donch_high",
                        "volex_donch_high_1h",
                        "trendpb_ema_fast",
                    ]
                )

            if not np.isfinite(thr):
                thr = close

            atr = _pick([atr_col, "volex_itf_atr", "cbx_atr", "atr14", "atr"])
            if np.isfinite(atr) and atr > 0 and np.isfinite(close) and close > 0 and np.isfinite(thr):
                clearance_r = (thr - close) / atr if side_l == "short" else (close - thr) / atr
                brk = self._clip01(clearance_r / 1.0)
            else:
                brk = 0.5

            atr_phase = str(row.get("atr_phase", "") or "").upper()
            if atr_phase == "EXPAND":
                vol = 1.0
            elif atr_phase == "NEUTRAL":
                vol = 0.6
            elif atr_phase == "CONTRACT":
                vol = 0.35
            else:
                vol = 0.5

            w1 = float(self.buy_qsize_w_trend.value)
            w2 = float(self.buy_qsize_w_break.value)
            w3 = float(self.buy_qsize_w_vol.value)

            # 4th dimension: attention (volume anomaly z-score → [0,1])
            attention = 0.5  # neutral default
            w4 = 0.0
            if bool(self.buy_pair_attention_enabled.value) and str(self.buy_pair_attention_mode.value) == "qsize_feature":
                raw_z = float(row.get("attention_vol_zscore", 0.0) or 0.0)
                if np.isfinite(raw_z):
                    clip_val = float(self.buy_pair_attention_zscore_clip.value)
                    attention = self._clip01((raw_z + clip_val) / (2.0 * clip_val))
                w4 = float(self.buy_qsize_w_attention.value)

            wsum = float(w1 + w2 + w3 + w4)
            if not np.isfinite(wsum) or wsum <= 1e-9:
                score = 0.5
            else:
                score = self._clip01((w1 * trend + w2 * brk + w3 * vol + w4 * attention) / wsum)

            base_score = float(score)
            ml_profile = str(self.buy_qsize_ml_profile.value or "off").strip().lower()
            ml_blend = self._clip01(float(self.buy_qsize_ml_blend.value))
            ml_prob = float("nan")
            ml_used = False
            if self.buy_qsize_ml_enabled.value and ml_profile != "off" and ml_blend > 0:
                weights = self._qsize_ml_profile_weights(ml_profile)
                if weights:
                    regime = str(row.get("composite_regime", "") or "").upper()
                    is_riskoff = ("CHOP" in regime) or ("PANIC" in regime) or ("BEARVOL" in regime) or (atr_phase == "CONTRACT")
                    z = float(weights.get("bias", 0.0))
                    z += float(weights.get("trend", 0.0)) * float(trend)
                    z += float(weights.get("break", 0.0)) * float(brk)
                    z += float(weights.get("vol", 0.0)) * float(vol)
                    z += float(weights.get("x_tb", 0.0)) * float(trend) * float(brk)
                    z += float(weights.get(f"bucket_{sleeve_l}", 0.0))
                    if is_riskoff:
                        z -= float(self.buy_qsize_ml_riskoff_penalty.value)
                    if side_l == "short":
                        z -= float(self.buy_qsize_ml_short_penalty.value)
                    temp = max(0.2, float(self.buy_qsize_ml_temperature.value))
                    ml_prob = self._safe_sigmoid(z / temp)
                    score = self._clip01((1.0 - ml_blend) * float(score) + ml_blend * float(ml_prob))
                    ml_used = True

            comps: dict[str, float | str] = {
                "trend": float(trend),
                "break": float(brk),
                "vol": float(vol),
                "attention": float(attention),
                "atr_phase": atr_phase,
                "base_score": float(base_score),
                "ml_profile": ml_profile,
                "ml_used": "1" if ml_used else "0",
            }
            if np.isfinite(ml_prob):
                comps["ml_prob"] = float(ml_prob)
                comps["ml_blend"] = float(ml_blend)
            return float(score), comps
        except Exception:
            return neutral

    def _qsize_mult(
        self,
        score: float,
        row: pd.Series | dict | None = None,
        bucket: str = "",
        side: str = "long",
    ) -> float:
        # Convert score into stake multiplier with deadband and confidence shaping.
        # This reduces overreaction around neutral quality and limits leverage in risk-off regimes.
        mn = float(self.buy_qsize_min_mult.value)
        mx = float(self.buy_qsize_max_mult.value)
        if mx < mn:
            mn, mx = mx, mn
        s = self._clip01(score)
        center = 0.5

        deadband = min(0.49, max(0.0, float(self.buy_qsize_deadband.value)))
        conf_exp = max(0.10, float(self.buy_qsize_confidence_exp.value))
        dist = abs(s - center)

        if dist <= deadband:
            s_eff = center
        else:
            denom = max(1e-9, 0.5 - deadband)
            norm = self._clip01((dist - deadband) / denom)
            conf = norm**conf_exp
            s_eff = center + (0.5 * conf if s >= center else -0.5 * conf)

        mult = float(mn + (mx - mn) * self._clip01(s_eff))

        # Do not upscale unless quality clears a configurable minimum score.
        if s < float(self.buy_qsize_upscale_min_score.value) and mult > 1.0:
            mult = 1.0

        # Risk-off regimes should not receive leverage-like qsize upscaling.
        if self.buy_qsize_riskoff_cap_enabled.value and row is not None:
            try:
                regime = str(row.get("composite_regime", "") or "").upper()
                atr_phase = str(row.get("atr_phase", "") or "").upper()
                is_riskoff = ("CHOP" in regime) or ("PANIC" in regime) or ("BEARVOL" in regime) or (atr_phase == "CONTRACT")
                if is_riskoff:
                    mult = min(mult, float(self.buy_qsize_riskoff_cap.value))
            except Exception:
                pass

        # Cap qsize by bucket for sleeves with weaker realized quality.
        try:
            b = str(bucket or "").lower().strip()
            if b:
                cap_map = self._csv_kv_float_map(str(self.buy_qsize_bucket_cap_map.value or ""))
                if b in cap_map and np.isfinite(float(cap_map[b])):
                    mult = min(mult, float(cap_map[b]))
        except Exception:
            pass

        # Do not allow leverage-like upscaling for short sleeves by default.
        if str(side or "long").lower() == "short":
            mult = min(mult, float(self.buy_qsize_short_cap.value))

        return float(mult)

