    def _is_evtpulse_entry_tag(self, entry_tag: str | None) -> bool:
        return str(entry_tag or "").lower().startswith("evtpulse_")

    def _is_lagcatch_entry_tag(self, entry_tag: str | None) -> bool:
        return str(entry_tag or "").lower().startswith("lagcatch_")

    def _is_nalpha_entry_tag(self, entry_tag: str | None) -> bool:
        t = str(entry_tag or "").lower()
        return bool(
            t.startswith("xresmom_")
            or t.startswith("xidiorev_")
            or t.startswith("xmacrohour_")
            or t.startswith("xleadrot_")
            or t.startswith("xquietbreak_")
        )

    def _is_srr_entry_tag(self, entry_tag: str | None) -> bool:
        t = str(entry_tag or "").lower()
        return bool(
            self._is_nalpha_entry_tag(t)
            or t.startswith("rmom_")
            or t.startswith("tsmom_")
            or t.startswith("trendxs_")
            or t.startswith("stoploss_")
            or t.startswith("srr_")
        )

    def _novel_alpha_any_enabled(self) -> bool:
        return bool(
            self.buy_xresmom_enabled.value
            or self.buy_xidiorev_enabled.value
            or self.buy_xmacrohour_enabled.value
            or self.buy_xleadrot_enabled.value
            or self.buy_xquietbreak_enabled.value
        )

    def _is_idle_entry_tag(self, entry_tag: str | None) -> bool:
        return str(entry_tag or "").lower().startswith("idle_")

    def _is_auxiliary_entry_tag(self, entry_tag: str | None) -> bool:
        return bool(
            self._is_idle_entry_tag(entry_tag)
            or self._is_liqcascade_entry_tag(entry_tag)
            or self._is_liqcascade_v2_entry_tag(entry_tag)
            or self._is_fimr_entry_tag(entry_tag)
            or self._is_cvmr_entry_tag(entry_tag)
            or self._is_tes_entry_tag(entry_tag)
            or self._is_apc_entry_tag(entry_tag)
            or self._is_sbr_entry_tag(entry_tag)
            or self._is_spreadarb_entry_tag(entry_tag)
            or self._is_cpdf_entry_tag(entry_tag)
            or self._is_fcarry_entry_tag(entry_tag)
            or self._is_cvw_entry_tag(entry_tag)
            or self._is_mofi_entry_tag(entry_tag)
            or self._is_evtpulse_entry_tag(entry_tag)
            or self._is_lagcatch_entry_tag(entry_tag)
            or self._is_srr_entry_tag(entry_tag)
        )

