    def _idle_trade_key(self, trade: Trade) -> str:
        return f"{trade.pair}:{getattr(trade, 'open_date_utc', None) or getattr(trade, 'open_date', None)}"

    @staticmethod
    def _idle_trade_age_minutes(trade: Trade, current_time: datetime) -> float:
        try:
            open_dt = getattr(trade, "open_date_utc", None) or getattr(trade, "open_date", None)
            if open_dt is None:
                return 0.0
            return max((current_time - open_dt).total_seconds() / 60.0, 0.0)
        except Exception:
            return 0.0

    @staticmethod
    def _idle_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _idle_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._idle_init_state()
        dkey = self._idle_daily_bucket(current_time)
        if dkey not in self._idle_daily_state:
            self._idle_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _idle_pair_allowed(self, pair: str) -> bool:
        allow = {x.strip() for x in str(self.buy_idle_allow_pairs.value or "").split(",") if x.strip()}
        return (not allow) or (pair in allow)

    def _core_signal_present(self, row: pd.Series | dict | None) -> bool:
        try:
            if row is None:
                return False
            enter_long = int(row.get("enter_long", 0) or 0) == 1
            enter_short = int(row.get("enter_short", 0) or 0) == 1
            if not (enter_long or enter_short):
                return False
            tag = str(row.get("enter_tag", "") or "")
            return not self._is_auxiliary_entry_tag(tag)
        except Exception:
            return False

    def _open_core_trades_count(self) -> int:
        open_trades = self._safe_get_open_trades() or []
        n = 0
        for tr in open_trades:
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if not self._is_auxiliary_entry_tag(tag):
                n += 1
        return int(n)

    def _idle_trades_count(self) -> int:
        open_trades = self._safe_get_open_trades() or []
        n = 0
        for tr in open_trades:
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_idle_entry_tag(tag):
                n += 1
        return int(n)

    def _idle_core_demand(
        self,
        pair: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> bool:
        core_open = bool(self.buy_idle_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_idle_block_if_core_signal.value):
            probe = row
            if probe is None:
                probe = self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    def _idle_wallet_total(self) -> float:
        try:
            wallets = getattr(self, "wallets", None)
            if wallets is not None:
                total = wallets.get_total_stake_amount()
                total_f = float(total)
                if np.isfinite(total_f) and total_f > 0:
                    return total_f
        except Exception:
            pass
        wallet = self._parse_numeric(self.config.get("dry_run_wallet", None))
        if wallet is None or wallet <= 0:
            wallet = 1000.0
        return float(wallet)

    def _idle_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_idle_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_idle_entry_tag(tag):
                open_idle_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        reserve = wallet_total * float(self.buy_idle_core_reserve_pct.value)
        idle_cap = max(0.0, wallet_total * float(self.buy_idle_cap_pct.value) - open_idle_exposure)
        free_above_reserve = max(0.0, wallet_total - reserve - open_idle_exposure)
        return max(0.0, min(idle_cap, free_above_reserve))

    def _idle_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._idle_daily_reset_if_needed(current_time)
        dkey = self._idle_daily_bucket(current_time)
        st = self._idle_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_idle_daily_max_entries.value)
        max_l = int(self.buy_idle_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "idle_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "idle_daily_losses_cap"
        return True, "idle_daily_ok"

    def _idle_daily_limits_block(self, current_time: datetime) -> tuple[bool, str]:
        ok, reason = self._idle_daily_limits_allow(current_time)
        return (not ok), reason

    def _idle_mark_entry(self, current_time: datetime) -> None:
        self._idle_daily_reset_if_needed(current_time)
        dkey = self._idle_daily_bucket(current_time)
        st = self._idle_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _idle_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._idle_daily_reset_if_needed(current_time)
        dkey = self._idle_daily_bucket(current_time)
        st = self._idle_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._idle_last_loss_time[pair] = current_time

    def _idle_cooldown_blocks(self, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._idle_init_state()
        bars = int(self.buy_idle_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "idle_cooldown_off"
        last = self._idle_last_loss_time.get(pair)
        if last is None:
            return False, "idle_no_loss"
        need = timedelta(minutes=float(bars * 15))
        if (current_time - last) < need:
            return True, "idle_cooldown_active"
        return False, "idle_cooldown_clear"

    def _idle_add_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        volume = pd.to_numeric(dataframe.get("volume"), errors="coerce")
        rsi_len = int(self.buy_idle_rsi_len.value)
        ema_fast = int(self.buy_idle_ema_fast.value)
        ema_slow = int(self.buy_idle_ema_slow.value)
        relvol_len = int(self.buy_idle_relvol_len.value)
        atr_len = int(self.buy_idle_atr_len.value)

        dataframe["idle_rsi"] = ta.RSI(dataframe, timeperiod=rsi_len)
        dataframe["idle_ema_fast"] = ta.EMA(dataframe, timeperiod=ema_fast)
        dataframe["idle_ema_slow"] = ta.EMA(dataframe, timeperiod=ema_slow)
        vol_ma = volume.rolling(relvol_len).mean()
        dataframe["idle_relvol"] = volume / vol_ma.replace(0, np.nan)
        dataframe["idle_atr"] = ta.ATR(dataframe, timeperiod=atr_len)
        dataframe["idle_atr_pct"] = pd.to_numeric(dataframe["idle_atr"], errors="coerce") / close.replace(0, np.nan)
        dataframe["idle_long_signal"] = (
            (pd.to_numeric(dataframe["idle_rsi"], errors="coerce") <= int(self.buy_idle_rsi_long_max.value))
            & (close < pd.to_numeric(dataframe["idle_ema_fast"], errors="coerce"))
            & (pd.to_numeric(dataframe["idle_relvol"], errors="coerce") >= float(self.buy_idle_relvol_min.value))
            & (pd.to_numeric(dataframe["idle_atr_pct"], errors="coerce") <= float(self.buy_idle_atr_pct_max.value))
        ).fillna(False)
        return dataframe

    def _idle_signal(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        return self._idle_add_indicators(dataframe)

    def _idle_entry_allows(
        self,
        pair: str,
        row: pd.Series | dict,
        current_time: datetime,
    ) -> tuple[bool, str]:
        if not bool(self.buy_idle_enabled.value):
            return False, "idle_disabled"
        if not self._idle_pair_allowed(pair):
            return False, "idle_pair_block"
        if self._idle_core_demand(pair, current_time, row=row):
            return False, "idle_core_demand"
        day_ok, day_reason = self._idle_daily_limits_allow(current_time)
        if not day_ok:
            return False, day_reason
        cd_block, cd_reason = self._idle_cooldown_blocks(pair, current_time)
        if cd_block:
            return False, cd_reason
        try:
            if not bool(row.get("idle_long_signal", False)):
                return False, "idle_no_signal"
        except Exception:
            return False, "idle_no_signal"
        return True, "idle_ok"

    def _idle_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_idle_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            self._idle_init_state()
            key = self._idle_trade_key(trade)
            self._idle_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._idle_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def idle_counts_snapshot(self) -> dict[str, float]:
        self._idle_init_state()
        out = dict(self._idle_stats)
        out["idle_open_trades"] = float(self._idle_trades_count())
        out["core_open_trades"] = float(self._open_core_trades_count())
        return out

