    def _idle_fr_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_fr_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_idle_fr_entry_tag(tag):
                open_fr_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        reserve = wallet_total * float(self.buy_idle_fr_core_reserve_pct.value)
        sleeve_cap = max(0.0, wallet_total * float(self.buy_idle_fr_cap_pct.value) - open_fr_exposure)
        free_above_reserve = max(0.0, wallet_total - reserve - open_fr_exposure)
        return max(0.0, min(sleeve_cap, free_above_reserve))

    @staticmethod
    def _idle_fr_df_row_at_time(df: pd.DataFrame | None, current_time: datetime | None) -> pd.Series | None:
        try:
            if df is None or df.empty or current_time is None or "date" not in df.columns:
                return None
            ts = pd.Timestamp(current_time)
            view = df[df["date"] <= ts]
            if view.empty:
                return None
            return view.iloc[-1]
        except Exception:
            return None

    def _idle_fr_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._idle_fr_init_state()
        tf = str(self.buy_idle_fr_tf.value or "15m")
        suf = f"_{tf}"
        defaults_bool = (
            f"idle_fr_raw_shape{suf}",
            f"idle_fr_flush_ok{suf}",
            f"idle_fr_flush_prev{suf}",
            f"idle_fr_wick_ok{suf}",
            f"idle_fr_vol_ok{suf}",
            f"idle_fr_reclaim_ok{suf}",
            f"idle_fr_signal{suf}",
            f"idle_fr_btc_atr_expand{suf}",
        )

        def _ensure_defaults(df: pd.DataFrame) -> pd.DataFrame:
            for col in defaults_bool:
                if col in df.columns:
                    df[col] = df[col].fillna(False).astype(bool)
                else:
                    df[col] = False
            if f"idle_fr_btc_adx{suf}" in df.columns:
                df[f"idle_fr_btc_adx{suf}"] = pd.to_numeric(df[f"idle_fr_btc_adx{suf}"], errors="coerce")
            else:
                df[f"idle_fr_btc_adx{suf}"] = np.nan
            return df

        if not bool(self.buy_idle_fr_enabled.value):
            return _ensure_defaults(dataframe)
        if not self._idle_fr_pair_allowed(pair):
            return _ensure_defaults(dataframe)
        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure_defaults(dataframe)

        dataframe = dataframe.drop(
            columns=[*defaults_bool, f"idle_fr_btc_adx{suf}"],
            errors="ignore",
        )

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        open_ = pd.to_numeric(inf.get("open"), errors="coerce")
        high = pd.to_numeric(inf.get("high"), errors="coerce")
        low = pd.to_numeric(inf.get("low"), errors="coerce")
        volume = pd.to_numeric(inf.get("volume"), errors="coerce")

        atr_len = int(self.buy_idle_fr_atr_len.value)
        relvol_len = int(self.buy_idle_fr_relvol_len.value)
        ema_fast = int(self.buy_idle_fr_ema_fast.value)
        flush_mult = float(self.buy_idle_fr_flush_atr_mult.value)
        min_red_body_pct = float(self.buy_idle_fr_min_red_body_pct.value)
        wick_body_mult = float(self.buy_idle_fr_lower_wick_body_mult.value)
        wick_atr_mult = float(self.buy_idle_fr_lower_wick_atr_mult.value)
        relvol_min = float(self.buy_idle_fr_relvol_min.value)
        close_upper_frac = float(self.buy_idle_fr_close_in_upper_frac.value)

        inf["idle_fr_atr"] = ta.ATR(inf, timeperiod=atr_len)
        inf["idle_fr_ema_fast"] = ta.EMA(inf, timeperiod=ema_fast)
        typical = (high + low + close) / 3.0
        cum_vol = volume.cumsum()
        inf["idle_fr_vwap"] = (typical * volume).cumsum() / cum_vol.replace(0, np.nan)
        vol_ma = volume.rolling(relvol_len, min_periods=1).mean()
        inf["idle_fr_relvol"] = volume / vol_ma.replace(0, np.nan)

        body = (close - open_).abs()
        down_move = (open_ - close).clip(lower=0.0)
        lower_wick = (np.minimum(open_, close) - low).clip(lower=0.0)
        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        is_red = (close < open_).fillna(False)

        inf["idle_fr_raw_shape"] = (is_red & (down_move > 0)).fillna(False)
        inf["idle_fr_flush_ok"] = (
            is_red
            & (body >= (min_red_body_pct * close))
            & (down_move >= (flush_mult * inf["idle_fr_atr"]))
        ).fillna(False)
        inf["idle_fr_flush_prev"] = inf["idle_fr_flush_ok"].shift(1).fillna(False)
        inf["idle_fr_wick_ok"] = (
            (lower_wick >= (wick_body_mult * body.clip(lower=1e-9)))
            & (lower_wick >= (wick_atr_mult * inf["idle_fr_atr"]))
        ).fillna(False)
        inf["idle_fr_vol_ok"] = (inf["idle_fr_relvol"] >= relvol_min).fillna(False)
        reclaim_ok = (close_pos >= close_upper_frac).fillna(False)
        if bool(self.buy_idle_fr_require_reclaim_ema.value):
            reclaim_ok = reclaim_ok & (close > inf["idle_fr_ema_fast"]).fillna(False)
        if bool(self.buy_idle_fr_require_reclaim_vwap.value):
            reclaim_ok = reclaim_ok & (close > inf["idle_fr_vwap"]).fillna(False)
        inf["idle_fr_reclaim_ok"] = reclaim_ok.fillna(False)
        inf["idle_fr_signal"] = (
            (inf["idle_fr_flush_ok"] | inf["idle_fr_flush_prev"])
            & inf["idle_fr_wick_ok"]
            & inf["idle_fr_vol_ok"]
            & inf["idle_fr_reclaim_ok"]
        ).fillna(False)

        inf_cols = inf[
            [
                "date",
                "idle_fr_raw_shape",
                "idle_fr_flush_ok",
                "idle_fr_flush_prev",
                "idle_fr_wick_ok",
                "idle_fr_vol_ok",
                "idle_fr_reclaim_ok",
                "idle_fr_signal",
            ]
        ].copy()
        if tf == self.timeframe:
            for c in (
                "idle_fr_raw_shape",
                "idle_fr_flush_ok",
                "idle_fr_flush_prev",
                "idle_fr_wick_ok",
                "idle_fr_vol_ok",
                "idle_fr_reclaim_ok",
                "idle_fr_signal",
            ):
                dataframe[f"{c}{suf}"] = inf_cols[c].values
        else:
            right = inf_cols.rename(
                columns={
                    "idle_fr_raw_shape": f"idle_fr_raw_shape{suf}",
                    "idle_fr_flush_ok": f"idle_fr_flush_ok{suf}",
                    "idle_fr_flush_prev": f"idle_fr_flush_prev{suf}",
                    "idle_fr_wick_ok": f"idle_fr_wick_ok{suf}",
                    "idle_fr_vol_ok": f"idle_fr_vol_ok{suf}",
                    "idle_fr_reclaim_ok": f"idle_fr_reclaim_ok{suf}",
                    "idle_fr_signal": f"idle_fr_signal{suf}",
                }
            ).copy()
            left = dataframe.copy()
            left["_idle_fr_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
            right["_idle_fr_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
            right = right.drop(columns=["date"]).sort_values("_idle_fr_date")
            left = left.sort_values("_idle_fr_date")
            dataframe = pd.merge_asof(left, right, on="_idle_fr_date", direction="backward")
            dataframe = dataframe.sort_index()
            dataframe.drop(columns=["_idle_fr_date"], inplace=True, errors="ignore")

        if bool(self.buy_idle_fr_block_if_btc_trending.value):
            try:
                btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
                btc_df = self.dp.get_pair_dataframe(pair=btc_pair, timeframe=tf)
            except Exception:
                btc_df = None
            if btc_df is not None and not btc_df.empty:
                btc_inf = btc_df.copy()
                btc_inf["idle_fr_btc_adx"] = ta.ADX(btc_inf, timeperiod=14)
                btc_atr = ta.ATR(btc_inf, timeperiod=atr_len)
                btc_close = pd.to_numeric(btc_inf.get("close"), errors="coerce").replace(0, np.nan)
                btc_atr_pct = btc_atr / btc_close
                btc_atr_pct_ma = btc_atr_pct.rolling(relvol_len, min_periods=1).mean()
                btc_inf["idle_fr_btc_atr_expand"] = (btc_atr_pct > (btc_atr_pct_ma * 1.15)).fillna(False)
                btc_inf = btc_inf[["date", "idle_fr_btc_adx", "idle_fr_btc_atr_expand"]].copy()
                if tf == self.timeframe:
                    dataframe[f"idle_fr_btc_adx{suf}"] = btc_inf["idle_fr_btc_adx"].values
                    dataframe[f"idle_fr_btc_atr_expand{suf}"] = btc_inf["idle_fr_btc_atr_expand"].values
                else:
                    btc_right = btc_inf.rename(
                        columns={
                            "idle_fr_btc_adx": f"idle_fr_btc_adx{suf}",
                            "idle_fr_btc_atr_expand": f"idle_fr_btc_atr_expand{suf}",
                        }
                    ).copy()
                    left = dataframe.copy()
                    left["_idle_fr_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
                    btc_right["_idle_fr_date"] = pd.to_datetime(btc_right["date"], utc=True, errors="coerce")
                    btc_right = btc_right.drop(columns=["date"]).sort_values("_idle_fr_date")
                    left = left.sort_values("_idle_fr_date")
                    dataframe = pd.merge_asof(left, btc_right, on="_idle_fr_date", direction="backward")
                    dataframe = dataframe.sort_index()
                    dataframe.drop(columns=["_idle_fr_date"], inplace=True, errors="ignore")

        return _ensure_defaults(dataframe)

    def _idle_fr_entry_allows(
        self,
        pair: str,
        row: pd.Series | dict,
        current_time: datetime,
    ) -> tuple[bool, str]:
        self._idle_fr_init_state()
        tf = str(self.buy_idle_fr_tf.value or "15m")
        suf = f"_{tf}"

        if not bool(self.buy_idle_fr_enabled.value):
            return False, "idle_fr_disabled"
        if not self._idle_fr_pair_allowed(pair):
            self._idle_fr_inc("block_pair")
            return False, "idle_fr_pair_block"
        if self._idle_fr_core_demand(pair, current_time, row=row):
            self._idle_fr_inc("block_core_demand")
            return False, "idle_fr_core_demand"
        day_ok, _ = self._idle_fr_daily_limits_allow(current_time)
        if not day_ok:
            self._idle_fr_inc("block_daily")
            return False, "idle_fr_daily_block"
        cd_block, _ = self._idle_fr_cooldown_blocks(pair, current_time)
        if cd_block:
            self._idle_fr_inc("block_cooldown")
            return False, "idle_fr_cooldown"

        flush_ok = bool(row.get(f"idle_fr_flush_ok{suf}", False) or row.get(f"idle_fr_flush_prev{suf}", False))
        if not flush_ok:
            self._idle_fr_inc("block_flush")
            return False, "idle_fr_no_flush"
        self._idle_fr_inc("raw")

        if not bool(row.get(f"idle_fr_wick_ok{suf}", False)):
            self._idle_fr_inc("block_wick")
            return False, "idle_fr_no_wick"
        if not bool(row.get(f"idle_fr_vol_ok{suf}", False)):
            self._idle_fr_inc("block_volume")
            return False, "idle_fr_no_volume"
        if not bool(row.get(f"idle_fr_reclaim_ok{suf}", False)):
            self._idle_fr_inc("block_reclaim")
            return False, "idle_fr_no_reclaim"

        if bool(self.buy_idle_fr_block_if_btc_trending.value):
            btc_adx = self._parse_numeric(row.get(f"idle_fr_btc_adx{suf}", np.nan))
            if btc_adx is not None and btc_adx > float(self.buy_idle_fr_btc_adx_max.value):
                self._idle_fr_inc("block_macro")
                return False, "idle_fr_btc_trending"
        if bool(self.buy_idle_fr_block_if_atr_expand.value):
            atr_phase = str(row.get("atr_phase", "")).upper()
            btc_expand = bool(row.get(f"idle_fr_btc_atr_expand{suf}", False))
            if atr_phase == "EXPAND" or btc_expand:
                self._idle_fr_inc("block_macro")
                return False, "idle_fr_atr_expand"

        self._idle_fr_inc("allowed")
        return True, "idle_fr_ok"

    def _idle_fr_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_idle_fr_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            self._idle_fr_init_state()
            key = self._idle_trade_key(trade)
            self._idle_fr_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._idle_fr_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def idle_fr_counts_snapshot(self) -> dict[str, float]:
        self._idle_fr_init_state()
        out = {k: float(v) for k, v in self._idle_fr_counts.items()}
        out["idle_fr_open_trades"] = float(self._idle_fr_trades_count())
        out["core_open_trades"] = float(self._open_core_trades_count())
        return out

    def _lc_trades_count(self) -> int:
        n = 0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_liqcascade_entry_tag(tag):
                n += 1
        return int(n)

    def _liqcascade_pair_allowed(self, pair: str) -> bool:
        allow = {x.strip() for x in str(self.buy_lc_allow_pairs.value or "").split(",") if x.strip()}
        return (not allow) or (pair in allow)

    def _liqcascade_core_demand(
        self,
        pair: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> bool:
        core_open = bool(self.buy_lc_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_lc_block_if_core_signal.value):
            probe = row
            if probe is None:
                probe = self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    @staticmethod
    def _lc_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _lc_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._lc_init_state()
        dkey = self._lc_daily_bucket(current_time)
        if dkey not in self._lc_daily_state:
            self._lc_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _lc_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._lc_daily_reset_if_needed(current_time)
        dkey = self._lc_daily_bucket(current_time)
        st = self._lc_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_lc_daily_max_entries.value)
        max_l = int(self.buy_lc_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "lc_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "lc_daily_losses_cap"
        return True, "lc_daily_ok"

    def _lc_mark_entry(self, current_time: datetime) -> None:
        self._lc_daily_reset_if_needed(current_time)
        dkey = self._lc_daily_bucket(current_time)
        st = self._lc_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _lc_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._lc_daily_reset_if_needed(current_time)
        dkey = self._lc_daily_bucket(current_time)
        st = self._lc_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._lc_last_loss_time[pair] = current_time

    def _lc_cooldown_blocks(self, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._lc_init_state()
        bars = int(self.buy_lc_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "lc_cooldown_off"
        last = self._lc_last_loss_time.get(pair)
        if last is None:
            return False, "lc_no_loss"
        tf_minutes = max(1, self._timeframe_to_minutes(str(self.buy_lc_tf.value or "5m")))
        need = timedelta(minutes=float(bars * tf_minutes))
        if (current_time - last) < need:
            return True, "lc_cooldown_active"
        return False, "lc_cooldown_clear"

    def _liqcascade_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_liqcascade_entry_tag(tag):
                open_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        sleeve_cap = max(0.0, wallet_total * float(self.buy_lc_cap_pct.value) - open_exposure)
        return max(0.0, sleeve_cap)

    def _liqcascade_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._lc_init_state()
        tf = str(self.buy_lc_tf.value or "5m")
        suf = f"_{tf}"
        defaults_bool = (
            f"liqcascade_raw_shape{suf}",
            f"liqcascade_flush_ok{suf}",
            f"liqcascade_flush_prev{suf}",
            f"liqcascade_wick_ok{suf}",
            f"liqcascade_wick_prev{suf}",
            f"liqcascade_vol_ok{suf}",
            f"liqcascade_vol_prev{suf}",
            f"liqcascade_exhaust_ok{suf}",
            f"liqcascade_exhaust_prev{suf}",
            f"liqcascade_reclaim_ok{suf}",
            f"liqcascade_oi_ok{suf}",
            f"liqcascade_liq_ok{suf}",
            f"liqcascade_signal{suf}",
        )

        def _ensure_defaults(df: pd.DataFrame) -> pd.DataFrame:
            for col in defaults_bool:
                if col in df.columns:
                    df[col] = df[col].fillna(False).astype(bool)
                else:
                    df[col] = False
            return df

        if not bool(self.buy_lc_enabled.value):
            return _ensure_defaults(dataframe)
        if not self._liqcascade_pair_allowed(pair):
            return _ensure_defaults(dataframe)
        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure_defaults(dataframe)

        dataframe = dataframe.drop(columns=[*defaults_bool], errors="ignore")

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        open_ = pd.to_numeric(inf.get("open"), errors="coerce")
        high = pd.to_numeric(inf.get("high"), errors="coerce")
        low = pd.to_numeric(inf.get("low"), errors="coerce")
        volume = pd.to_numeric(inf.get("volume"), errors="coerce")

        atr_len = int(self.buy_lc_atr_len.value)
        relvol_len = int(self.buy_lc_relvol_len.value)
        ema_fast = int(self.buy_lc_ema_fast.value)
        flush_mult = float(self.buy_lc_flush_atr_mult.value)
        min_red_body_pct = float(self.buy_lc_min_red_body_pct.value)
        wick_body_mult = float(self.buy_lc_lower_wick_body_mult.value)
        wick_atr_mult = float(self.buy_lc_lower_wick_atr_mult.value)
        relvol_min = float(self.buy_lc_relvol_min.value)
        close_upper_frac = float(self.buy_lc_close_in_upper_frac.value)

        inf["liqcascade_atr"] = ta.ATR(inf, timeperiod=atr_len)
        inf["liqcascade_ema_fast"] = ta.EMA(inf, timeperiod=ema_fast)
        typical = (high + low + close) / 3.0
        cum_vol = volume.cumsum()
        inf["liqcascade_vwap"] = (typical * volume).cumsum() / cum_vol.replace(0, np.nan)
        vol_ma = volume.rolling(relvol_len, min_periods=1).mean()
        inf["liqcascade_relvol"] = volume / vol_ma.replace(0, np.nan)

        body = (close - open_).abs()
        down_move = (open_ - close).clip(lower=0.0)
        lower_wick = (np.minimum(open_, close) - low).clip(lower=0.0)
        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        is_red = (close < open_).fillna(False)

        flush_ok = (
            is_red
            & (body >= (min_red_body_pct * close))
            & (down_move >= (flush_mult * inf["liqcascade_atr"]))
        ).fillna(False)
        wick_ok = (
            (lower_wick >= (wick_body_mult * body.clip(lower=1e-9)))
            & (lower_wick >= (wick_atr_mult * inf["liqcascade_atr"]))
        ).fillna(False)
        vol_ok = (inf["liqcascade_relvol"] >= relvol_min).fillna(False)
        reclaim_ok = (close_pos >= close_upper_frac).fillna(False)
        if bool(self.buy_lc_require_reclaim_ema.value):
            reclaim_ok = reclaim_ok & (close > inf["liqcascade_ema_fast"]).fillna(False)
        if bool(self.buy_lc_require_reclaim_vwap.value):
            reclaim_ok = reclaim_ok & (close > inf["liqcascade_vwap"]).fillna(False)

        if "oi_change_pct" in inf.columns:
            oi_raw = inf["oi_change_pct"]
        elif "open_interest_change_pct" in inf.columns:
            oi_raw = inf["open_interest_change_pct"]
        else:
            oi_raw = pd.Series(np.nan, index=inf.index, dtype=float)
        oi_change = pd.to_numeric(oi_raw, errors="coerce")
        if not isinstance(oi_change, pd.Series):
            oi_change = pd.Series(oi_change, index=inf.index, dtype=float)
        else:
            oi_change = oi_change.reindex(inf.index)

        if "liquidation_notional_spike" in inf.columns:
            liq_raw = inf["liquidation_notional_spike"]
        elif "liq_spike" in inf.columns:
            liq_raw = inf["liq_spike"]
        else:
            liq_raw = pd.Series(np.nan, index=inf.index, dtype=float)
        liq_spike = pd.to_numeric(liq_raw, errors="coerce")
        if not isinstance(liq_spike, pd.Series):
            liq_spike = pd.Series(liq_spike, index=inf.index, dtype=float)
        else:
            liq_spike = liq_spike.reindex(inf.index)

        oi_ok = (oi_change <= -float(self.buy_lc_oi_drop_min.value)).fillna(True).astype(bool)
        liq_ok = (liq_spike >= float(self.buy_lc_liq_spike_min.value)).fillna(True).astype(bool)

        inf["liqcascade_raw_shape"] = (is_red & (down_move > 0)).fillna(False)
        inf["liqcascade_flush_ok"] = flush_ok.astype(bool)
        inf["liqcascade_flush_prev"] = inf["liqcascade_flush_ok"].shift(1).fillna(False).astype(bool)
        inf["liqcascade_wick_ok"] = wick_ok.astype(bool)
        inf["liqcascade_wick_prev"] = inf["liqcascade_wick_ok"].shift(1).fillna(False).astype(bool)
        inf["liqcascade_vol_ok"] = vol_ok.astype(bool)
        inf["liqcascade_vol_prev"] = inf["liqcascade_vol_ok"].shift(1).fillna(False).astype(bool)
        inf["liqcascade_exhaust_ok"] = (
            inf["liqcascade_flush_ok"]
            & inf["liqcascade_wick_ok"]
            & inf["liqcascade_vol_ok"]
        ).fillna(False).astype(bool)
        inf["liqcascade_exhaust_prev"] = inf["liqcascade_exhaust_ok"].shift(1).fillna(False).astype(bool)
        inf["liqcascade_reclaim_ok"] = reclaim_ok.astype(bool)
        inf["liqcascade_oi_ok"] = oi_ok.astype(bool)
        inf["liqcascade_liq_ok"] = liq_ok.astype(bool)
        inf["liqcascade_signal"] = (
            (inf["liqcascade_exhaust_ok"] | inf["liqcascade_exhaust_prev"])
            & inf["liqcascade_reclaim_ok"]
            & inf["liqcascade_oi_ok"]
            & inf["liqcascade_liq_ok"]
        ).fillna(False)

        inf_cols = inf[
            [
                "date",
                "liqcascade_raw_shape",
                "liqcascade_flush_ok",
                "liqcascade_flush_prev",
                "liqcascade_wick_ok",
                "liqcascade_wick_prev",
                "liqcascade_vol_ok",
                "liqcascade_vol_prev",
                "liqcascade_exhaust_ok",
                "liqcascade_exhaust_prev",
                "liqcascade_reclaim_ok",
                "liqcascade_oi_ok",
                "liqcascade_liq_ok",
                "liqcascade_signal",
            ]
        ].copy()
        if tf == self.timeframe:
            for c in (
                "liqcascade_raw_shape",
                "liqcascade_flush_ok",
                "liqcascade_flush_prev",
                "liqcascade_wick_ok",
                "liqcascade_wick_prev",
                "liqcascade_vol_ok",
                "liqcascade_vol_prev",
                "liqcascade_exhaust_ok",
                "liqcascade_exhaust_prev",
                "liqcascade_reclaim_ok",
                "liqcascade_oi_ok",
                "liqcascade_liq_ok",
                "liqcascade_signal",
            ):
                dataframe[f"{c}{suf}"] = inf_cols[c].values
        else:
            right = inf_cols.rename(
                columns={
                    "liqcascade_raw_shape": f"liqcascade_raw_shape{suf}",
                    "liqcascade_flush_ok": f"liqcascade_flush_ok{suf}",
                    "liqcascade_flush_prev": f"liqcascade_flush_prev{suf}",
                    "liqcascade_wick_ok": f"liqcascade_wick_ok{suf}",
                    "liqcascade_wick_prev": f"liqcascade_wick_prev{suf}",
                    "liqcascade_vol_ok": f"liqcascade_vol_ok{suf}",
                    "liqcascade_vol_prev": f"liqcascade_vol_prev{suf}",
                    "liqcascade_exhaust_ok": f"liqcascade_exhaust_ok{suf}",
                    "liqcascade_exhaust_prev": f"liqcascade_exhaust_prev{suf}",
                    "liqcascade_reclaim_ok": f"liqcascade_reclaim_ok{suf}",
                    "liqcascade_oi_ok": f"liqcascade_oi_ok{suf}",
                    "liqcascade_liq_ok": f"liqcascade_liq_ok{suf}",
                    "liqcascade_signal": f"liqcascade_signal{suf}",
                }
            ).copy()
            left = dataframe.copy()
            left["_lc_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
            right["_lc_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
            right = right.drop(columns=["date"]).sort_values("_lc_date")
            left = left.sort_values("_lc_date")
            dataframe = pd.merge_asof(left, right, on="_lc_date", direction="backward")
            dataframe = dataframe.sort_index()
            dataframe.drop(columns=["_lc_date"], inplace=True, errors="ignore")
        return _ensure_defaults(dataframe)

    def _liqcascade_entry_allows(
        self,
        pair: str,
        row: pd.Series | dict,
        current_time: datetime,
    ) -> tuple[bool, str]:
        self._lc_init_state()
        tf = str(self.buy_lc_tf.value or "5m")
        suf = f"_{tf}"

        if not bool(self.buy_lc_enabled.value):
            return False, "lc_disabled"
        if not self._liqcascade_pair_allowed(pair):
            self._lc_inc("block_pair")
            return False, "lc_pair_block"
        if self._liqcascade_core_demand(pair, current_time, row=row):
            self._lc_inc("block_core_demand")
            return False, "lc_core_demand"
        day_ok, _ = self._lc_daily_limits_allow(current_time)
        if not day_ok:
            self._lc_inc("block_daily")
            return False, "lc_daily_block"
        cd_block, _ = self._lc_cooldown_blocks(pair, current_time)
        if cd_block:
            self._lc_inc("block_cooldown")
            return False, "lc_cooldown"

        flush_ok = bool(row.get(f"liqcascade_flush_ok{suf}", False))
        flush_prev = bool(row.get(f"liqcascade_flush_prev{suf}", False))
        if not (flush_ok or flush_prev):
            self._lc_inc("block_flush")
            return False, "lc_no_flush"
        wick_ok = bool(row.get(f"liqcascade_wick_ok{suf}", False))
        wick_prev = bool(row.get(f"liqcascade_wick_prev{suf}", False))
        if not (wick_ok or wick_prev):
            self._lc_inc("block_wick")
            return False, "lc_no_wick"
        vol_ok = bool(row.get(f"liqcascade_vol_ok{suf}", False))
        vol_prev = bool(row.get(f"liqcascade_vol_prev{suf}", False))
        if not (vol_ok or vol_prev):
            self._lc_inc("block_volume")
            return False, "lc_no_volume"
        exhaust_ok = bool(row.get(f"liqcascade_exhaust_ok{suf}", False)) or bool(
            row.get(f"liqcascade_exhaust_prev{suf}", False)
        )
        if not exhaust_ok:
            self._lc_inc("block_wick")
            return False, "lc_no_exhaust"
        self._lc_inc("raw")
        if not bool(row.get(f"liqcascade_reclaim_ok{suf}", False)):
            self._lc_inc("block_reclaim")
            return False, "lc_no_reclaim"

        if bool(self.buy_lc_use_oi.value) and not bool(row.get(f"liqcascade_oi_ok{suf}", True)):
            self._lc_inc("block_oi")
            return False, "lc_oi_block"
        if bool(self.buy_lc_use_liq_feed.value) and not bool(row.get(f"liqcascade_liq_ok{suf}", True)):
            self._lc_inc("block_liq")
            return False, "lc_liq_block"

        self._lc_inc("allowed")
        return True, "lc_ok"

    def _liqcascade_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_liqcascade_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            self._lc_init_state()
            key = self._idle_trade_key(trade)
            self._lc_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._lc_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def liqcascade_counts_snapshot(self) -> dict[str, float]:
        self._lc_init_state()
        out = {k: float(v) for k, v in self._lc_counts.items()}
        out["liqcascade_open_trades"] = float(self._lc_trades_count())
        out["core_open_trades"] = float(self._open_core_trades_count())
        return out

    def _lc2_trades_count(self) -> int:
        n = 0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_liqcascade_v2_entry_tag(tag):
                n += 1
        return int(n)

    def _lc2_pair_allowed(self, pair: str) -> bool:
        allow = {x.strip() for x in str(self.buy_lc2_allow_pairs.value or "").split(",") if x.strip()}
        return (not allow) or (pair in allow)

    def _lc2_core_demand(
        self,
        pair: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> bool:
        core_open = bool(self.buy_lc2_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_lc2_block_if_core_signal.value):
            probe = row
            if probe is None:
                probe = self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    @staticmethod
    def _lc2_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _lc2_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._lc2_init_state()
        dkey = self._lc2_daily_bucket(current_time)
        if dkey not in self._lc2_daily_state:
            self._lc2_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _lc2_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._lc2_daily_reset_if_needed(current_time)
        dkey = self._lc2_daily_bucket(current_time)
        st = self._lc2_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_lc2_daily_max_entries.value)
        max_l = int(self.buy_lc2_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "lc2_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "lc2_daily_losses_cap"
        return True, "lc2_daily_ok"

    def _lc2_mark_entry(self, current_time: datetime) -> None:
        self._lc2_daily_reset_if_needed(current_time)
        dkey = self._lc2_daily_bucket(current_time)
        st = self._lc2_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _lc2_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._lc2_daily_reset_if_needed(current_time)
        dkey = self._lc2_daily_bucket(current_time)
        st = self._lc2_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._lc2_last_loss_time[pair] = current_time

    def _lc2_cooldown_blocks(self, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._lc2_init_state()
        bars = int(self.buy_lc2_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "lc2_cooldown_off"
        last = self._lc2_last_loss_time.get(pair)
        if last is None:
            return False, "lc2_no_loss"
        tf_minutes = max(1, self._timeframe_to_minutes(str(self.buy_lc2_tf.value or "5m")))
        need = timedelta(minutes=float(bars * tf_minutes))
        if (current_time - last) < need:
            return True, "lc2_cooldown_active"
        return False, "lc2_cooldown_clear"

    def _liqcascade_v2_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_liqcascade_v2_entry_tag(tag):
                open_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        sleeve_cap = max(0.0, wallet_total * float(self.buy_lc2_cap_pct.value) - open_exposure)
        return max(0.0, sleeve_cap)

    def _liqcascade_v2_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._lc2_init_state()
        tf = str(self.buy_lc2_tf.value or "5m")
        suf = f"_{tf}"
        defaults_bool = (
            f"liqcascade_v2_raw_shape{suf}",
            f"liqcascade_v2_shock_ok{suf}",
            f"liqcascade_v2_wick_ok{suf}",
            f"liqcascade_v2_vol_ok{suf}",
            f"liqcascade_v2_reclaim_ok{suf}",
            f"liqcascade_v2_flow_ok{suf}",
            f"liqcascade_v2_proxy_missing{suf}",
            f"liqcascade_v2_oi_ok{suf}",
            f"liqcascade_v2_taker_ok{suf}",
            f"liqcascade_v2_signal{suf}",
        )

        def _ensure_defaults(df: pd.DataFrame) -> pd.DataFrame:
            for col in defaults_bool:
                if col in df.columns:
                    df[col] = df[col].fillna(False).astype(bool)
                else:
                    df[col] = False
            return df

        if not bool(self.buy_lc2_enabled.value):
            return _ensure_defaults(dataframe)
        if not self._lc2_pair_allowed(pair):
            return _ensure_defaults(dataframe)
        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure_defaults(dataframe)

        dataframe = dataframe.drop(columns=[*defaults_bool], errors="ignore")

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        open_ = pd.to_numeric(inf.get("open"), errors="coerce")
        high = pd.to_numeric(inf.get("high"), errors="coerce")
        low = pd.to_numeric(inf.get("low"), errors="coerce")
        volume = pd.to_numeric(inf.get("volume"), errors="coerce")

        atr_len = int(self.buy_lc2_atr_len.value)
        relvol_len = int(self.buy_lc2_relvol_len.value)
        ema_fast = int(self.buy_lc2_ema_fast.value)
        range_shock_mult = float(self.buy_lc2_range_shock_atr_mult.value)
        min_red_body_pct = float(self.buy_lc2_min_red_body_pct.value)
        wick_body_mult = float(self.buy_lc2_lower_wick_body_mult.value)
        wick_atr_mult = float(self.buy_lc2_lower_wick_atr_mult.value)
        relvol_min = float(self.buy_lc2_relvol_min.value)
        close_upper_frac = float(self.buy_lc2_close_in_upper_frac.value)

        inf["liqcascade_v2_atr"] = ta.ATR(inf, timeperiod=atr_len)
        inf["liqcascade_v2_ema_fast"] = ta.EMA(inf, timeperiod=ema_fast)
        typical = (high + low + close) / 3.0
        cum_vol = volume.cumsum()
        inf["liqcascade_v2_vwap"] = (typical * volume).cumsum() / cum_vol.replace(0, np.nan)
        vol_ma = volume.rolling(relvol_len, min_periods=1).mean()
        inf["liqcascade_v2_relvol"] = volume / vol_ma.replace(0, np.nan)

        body = (close - open_).abs()
        lower_wick = (np.minimum(open_, close) - low).clip(lower=0.0)
        candle_range = (high - low).clip(lower=0.0)
        close_pos = (close - low) / candle_range.replace(0, np.nan)
        midpoint = low + (0.5 * candle_range)
        is_red = (close < open_).fillna(False)

        shock_ok = (
            is_red
            & (body >= (min_red_body_pct * close))
            & (candle_range >= (range_shock_mult * inf["liqcascade_v2_atr"]))
        ).fillna(False)
        wick_ok = (
            (lower_wick >= (wick_body_mult * body.clip(lower=1e-9)))
            & (lower_wick >= (wick_atr_mult * inf["liqcascade_v2_atr"]))
        ).fillna(False)
        vol_ok = (inf["liqcascade_v2_relvol"] >= relvol_min).fillna(False)

        reclaim_ok = (close_pos >= close_upper_frac).fillna(False)
        if bool(self.buy_lc2_require_reclaim_midpoint.value):
            reclaim_ok = reclaim_ok & (close > midpoint).fillna(False)
        if bool(self.buy_lc2_require_reclaim_ema.value):
            reclaim_ok = reclaim_ok & (close > inf["liqcascade_v2_ema_fast"]).fillna(False)
        if bool(self.buy_lc2_require_reclaim_vwap.value):
            reclaim_ok = reclaim_ok & (close > inf["liqcascade_v2_vwap"]).fillna(False)

        if "oi_change_pct_5m" in inf.columns:
            oi_raw = inf["oi_change_pct_5m"]
        elif "oi_change_pct" in inf.columns:
            oi_raw = inf["oi_change_pct"]
        elif "open_interest_change_pct" in inf.columns:
            oi_raw = inf["open_interest_change_pct"]
        else:
            oi_raw = pd.Series(np.nan, index=inf.index, dtype=float)
        oi_change = pd.to_numeric(oi_raw, errors="coerce")
        if not isinstance(oi_change, pd.Series):
            oi_change = pd.Series(oi_change, index=inf.index, dtype=float)
        else:
            oi_change = oi_change.reindex(inf.index)
        oi_present = oi_change.notna()
        oi_ok = (oi_change <= -float(self.buy_lc2_oi_drop_min.value)).fillna(False)

        tb = pd.to_numeric(
            inf.get("taker_buy_vol_5m", inf.get("taker_buy_vol", inf.get("taker_buy_base", np.nan))),
            errors="coerce",
        )
        ts = pd.to_numeric(
            inf.get("taker_sell_vol_5m", inf.get("taker_sell_vol", inf.get("taker_sell_base", np.nan))),
            errors="coerce",
        )
        if not isinstance(tb, pd.Series):
            tb = pd.Series(tb, index=inf.index, dtype=float)
        else:
            tb = tb.reindex(inf.index)
        if not isinstance(ts, pd.Series):
            ts = pd.Series(ts, index=inf.index, dtype=float)
        else:
            ts = ts.reindex(inf.index)
        taker_sum = (tb.fillna(0.0) + ts.fillna(0.0))
        taker_ratio = ts / taker_sum.replace(0, np.nan)
        taker_present = taker_ratio.notna()
        taker_ok = (taker_ratio >= float(self.buy_lc2_taker_sell_ratio_min.value)).fillna(False)

        flow_ok = pd.Series(False, index=inf.index, dtype=bool)
        flow_available = pd.Series(False, index=inf.index, dtype=bool)
        if bool(self.buy_lc2_use_oi.value):
            flow_ok = flow_ok | oi_ok
            flow_available = flow_available | oi_present
        if bool(self.buy_lc2_use_taker_imbalance.value):
            flow_ok = flow_ok | taker_ok
            flow_available = flow_available | taker_present

        proxy_missing = ~flow_available
        if not bool(self.buy_lc2_require_flow_proxy.value):
            flow_ok = flow_ok | proxy_missing

        inf["liqcascade_v2_raw_shape"] = (is_red & (candle_range > 0)).fillna(False)
        inf["liqcascade_v2_shock_ok"] = shock_ok.astype(bool)
        inf["liqcascade_v2_wick_ok"] = wick_ok.astype(bool)
        inf["liqcascade_v2_vol_ok"] = vol_ok.astype(bool)
        inf["liqcascade_v2_reclaim_ok"] = reclaim_ok.astype(bool)
        inf["liqcascade_v2_oi_ok"] = oi_ok.astype(bool)
        inf["liqcascade_v2_taker_ok"] = taker_ok.astype(bool)
        inf["liqcascade_v2_proxy_missing"] = proxy_missing.astype(bool)
        inf["liqcascade_v2_flow_ok"] = flow_ok.astype(bool)
        inf["liqcascade_v2_signal"] = (
            inf["liqcascade_v2_shock_ok"]
            & inf["liqcascade_v2_wick_ok"]
            & inf["liqcascade_v2_vol_ok"]
            & inf["liqcascade_v2_reclaim_ok"]
            & inf["liqcascade_v2_flow_ok"]
        ).fillna(False)

        inf_cols = inf[
            [
                "date",
                "liqcascade_v2_raw_shape",
                "liqcascade_v2_shock_ok",
                "liqcascade_v2_wick_ok",
                "liqcascade_v2_vol_ok",
                "liqcascade_v2_reclaim_ok",
                "liqcascade_v2_oi_ok",
                "liqcascade_v2_taker_ok",
                "liqcascade_v2_proxy_missing",
                "liqcascade_v2_flow_ok",
                "liqcascade_v2_signal",
            ]
        ].copy()
        if tf == self.timeframe:
            for c in (
                "liqcascade_v2_raw_shape",
                "liqcascade_v2_shock_ok",
                "liqcascade_v2_wick_ok",
                "liqcascade_v2_vol_ok",
                "liqcascade_v2_reclaim_ok",
                "liqcascade_v2_oi_ok",
                "liqcascade_v2_taker_ok",
                "liqcascade_v2_proxy_missing",
                "liqcascade_v2_flow_ok",
                "liqcascade_v2_signal",
            ):
                dataframe[f"{c}{suf}"] = inf_cols[c].values
        else:
            right = inf_cols.rename(
                columns={
                    "liqcascade_v2_raw_shape": f"liqcascade_v2_raw_shape{suf}",
                    "liqcascade_v2_shock_ok": f"liqcascade_v2_shock_ok{suf}",
                    "liqcascade_v2_wick_ok": f"liqcascade_v2_wick_ok{suf}",
                    "liqcascade_v2_vol_ok": f"liqcascade_v2_vol_ok{suf}",
                    "liqcascade_v2_reclaim_ok": f"liqcascade_v2_reclaim_ok{suf}",
                    "liqcascade_v2_oi_ok": f"liqcascade_v2_oi_ok{suf}",
                    "liqcascade_v2_taker_ok": f"liqcascade_v2_taker_ok{suf}",
                    "liqcascade_v2_proxy_missing": f"liqcascade_v2_proxy_missing{suf}",
                    "liqcascade_v2_flow_ok": f"liqcascade_v2_flow_ok{suf}",
                    "liqcascade_v2_signal": f"liqcascade_v2_signal{suf}",
                }
            ).copy()
            left = dataframe.copy()
            left["_lc2_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
            right["_lc2_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
            right = right.drop(columns=["date"]).sort_values("_lc2_date")
            left = left.sort_values("_lc2_date")
            dataframe = pd.merge_asof(left, right, on="_lc2_date", direction="backward")
            dataframe = dataframe.sort_index()
            dataframe.drop(columns=["_lc2_date"], inplace=True, errors="ignore")
        return _ensure_defaults(dataframe)

    def _liqcascade_v2_entry_allows(
        self,
        pair: str,
        row: pd.Series | dict,
        current_time: datetime,
    ) -> tuple[bool, str]:
        self._lc2_init_state()
        tf = str(self.buy_lc2_tf.value or "5m")
        suf = f"_{tf}"

        if not bool(self.buy_lc2_enabled.value):
            return False, "lc2_disabled"
        if not self._lc2_pair_allowed(pair):
            self._lc2_inc("block_pair")
            return False, "lc2_pair_block"
        if self._lc2_core_demand(pair, current_time, row=row):
            self._lc2_inc("block_core_demand")
            return False, "lc2_core_demand"
        day_ok, _ = self._lc2_daily_limits_allow(current_time)
        if not day_ok:
            self._lc2_inc("block_governance")
            return False, "lc2_daily_block"
        cd_block, _ = self._lc2_cooldown_blocks(pair, current_time)
        if cd_block:
            self._lc2_inc("block_governance")
            return False, "lc2_cooldown"

        if not bool(row.get(f"liqcascade_v2_shock_ok{suf}", False)):
            self._lc2_inc("block_shock")
            return False, "lc2_no_shock"
        self._lc2_inc("raw")
        if not bool(row.get(f"liqcascade_v2_wick_ok{suf}", False)):
            self._lc2_inc("block_wick")
            return False, "lc2_no_wick"
        if not bool(row.get(f"liqcascade_v2_vol_ok{suf}", False)):
            self._lc2_inc("block_volume")
            return False, "lc2_no_volume"
        if not bool(row.get(f"liqcascade_v2_reclaim_ok{suf}", False)):
            self._lc2_inc("block_reclaim")
            return False, "lc2_no_reclaim"

        flow_ok = bool(row.get(f"liqcascade_v2_flow_ok{suf}", False))
        proxy_missing = bool(row.get(f"liqcascade_v2_proxy_missing{suf}", False))
        if bool(self.buy_lc2_require_flow_proxy.value):
            if proxy_missing:
                self._lc2_inc("block_missing_proxy")
                return False, "lc2_missing_proxy"
            if not flow_ok:
                self._lc2_inc("block_flow_proxy")
                return False, "lc2_no_flow_proxy"
        elif proxy_missing:
            # fail-open with observability
            self._lc2_inc("block_missing_proxy")

        self._lc2_inc("allowed")
        return True, "lc2_ok"

    def _liqcascade_v2_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_liqcascade_v2_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            self._lc2_init_state()
            key = self._idle_trade_key(trade)
            self._lc2_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._lc2_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def lc2_counts_snapshot(self) -> dict[str, float]:
        self._lc2_init_state()
        out = {k: float(v) for k, v in self._lc2_counts.items()}
        out["liqcascade_v2_open_trades"] = float(self._lc2_trades_count())
        out["core_open_trades"] = float(self._open_core_trades_count())
        return out

    def _mofi_trades_count(self) -> int:
        n = 0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_mofi_entry_tag(tag):
                n += 1
        return int(n)

    def _fimr_trades_count(self) -> int:
        n = 0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_fimr_entry_tag(tag):
                n += 1
        return int(n)

    def _fimr_mode_value(self) -> str:
        mode = str(self.buy_fimr_mode.value or "short_only").strip().lower()
        if mode not in {"short_only", "long_only", "both"}:
            return "short_only"
        return mode

    def _fimr_side_enabled(self, side: str) -> bool:
        s = str(side or "").lower()
        mode = self._fimr_mode_value()
        if s == "short":
            return mode in {"short_only", "both"} and bool(self.can_short)
        if s == "long":
            return mode in {"long_only", "both"}
        return False

    def _fimr_pair_allowed(self, pair: str) -> bool:
        allow = {x.strip() for x in str(self.buy_fimr_allow_pairs.value or "").split(",") if x.strip()}
        return (not allow) or (pair in allow)

    def _fimr_core_demand(
        self,
        pair: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> bool:
        core_open = bool(self.buy_fimr_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_fimr_block_if_core_signal.value):
            probe = row
            if probe is None:
                probe = self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    @staticmethod
    def _fimr_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _fimr_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._fimr_init_state()
        dkey = self._fimr_daily_bucket(current_time)
        if dkey not in self._fimr_daily_state:
            self._fimr_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _fimr_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._fimr_daily_reset_if_needed(current_time)
        dkey = self._fimr_daily_bucket(current_time)
        st = self._fimr_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_fimr_daily_max_entries.value)
        max_l = int(self.buy_fimr_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "fimr_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "fimr_daily_losses_cap"
        return True, "fimr_daily_ok"

    def _fimr_mark_entry(self, current_time: datetime) -> None:
        self._fimr_daily_reset_if_needed(current_time)
        dkey = self._fimr_daily_bucket(current_time)
        st = self._fimr_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _fimr_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._fimr_daily_reset_if_needed(current_time)
        dkey = self._fimr_daily_bucket(current_time)
        st = self._fimr_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._fimr_last_loss_time[pair] = current_time

    def _fimr_cooldown_blocks(self, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._fimr_init_state()
        bars = int(self.buy_fimr_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "fimr_cooldown_off"
        last = self._fimr_last_loss_time.get(pair)
        if last is None:
            return False, "fimr_no_loss"
        tf_minutes = max(1, self._timeframe_to_minutes(str(self.buy_fimr_tf.value or "1h")))
        need = timedelta(minutes=float(bars * tf_minutes))
        if (current_time - last) < need:
            return True, "fimr_cooldown_active"
        return False, "fimr_cooldown_clear"

    def _fimr_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_fimr_entry_tag(tag):
                open_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        sleeve_cap = max(0.0, wallet_total * float(self.buy_fimr_cap_pct.value) - open_exposure)
        return max(0.0, sleeve_cap)

    def _fimr_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._fimr_init_state()
        tf = str(self.buy_fimr_tf.value or "1h")
        suf = f"_{tf}"
        defaults_bool = (
            f"fimr_missing_proxy{suf}",
            f"fimr_crowded_ok{suf}",
            f"fimr_stall_ok{suf}",
            f"fimr_signal_short{suf}",
            f"fimr_missing_proxy_short{suf}",
            f"fimr_crowded_ok_short{suf}",
            f"fimr_stall_ok_short{suf}",
            f"fimr_missing_proxy_long{suf}",
            f"fimr_crowded_ok_long{suf}",
            f"fimr_stall_ok_long{suf}",
            f"fimr_signal_long{suf}",
            f"fimr_funding_ok{suf}",
            f"fimr_funding_ok_long{suf}",
            f"fimr_oi_ok{suf}",
            f"fimr_oi_ok_long{suf}",
            f"fimr_basis_ok{suf}",
            f"fimr_basis_ok_long{suf}",
        )

        def _ensure_defaults(df: pd.DataFrame) -> pd.DataFrame:
            for col in defaults_bool:
                if col in df.columns:
                    df[col] = df[col].fillna(False).astype(bool)
                else:
                    df[col] = False
            return df

        if not bool(self.buy_fimr_enabled.value):
            return _ensure_defaults(dataframe)
        if not self._fimr_pair_allowed(pair):
            return _ensure_defaults(dataframe)
        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure_defaults(dataframe)

        dataframe = dataframe.drop(columns=[*defaults_bool], errors="ignore")

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        rsi_len = int(self.buy_fimr_rsi_len.value)
        ema_fast = int(self.buy_fimr_ema_fast.value)
        ema_slow = int(self.buy_fimr_ema_slow.value)
        rsi_overbought = int(self.buy_fimr_rsi_overbought.value)

        inf["fimr_rsi"] = ta.RSI(inf, timeperiod=rsi_len)
        inf["fimr_ema_fast"] = ta.EMA(inf, timeperiod=ema_fast)
        inf["fimr_ema_slow"] = ta.EMA(inf, timeperiod=ema_slow)
        mom = close.pct_change()
        rsi = pd.to_numeric(inf["fimr_rsi"], errors="coerce")
        ema_fast_s = pd.to_numeric(inf["fimr_ema_fast"], errors="coerce")
        ema_fast_down = (ema_fast_s <= ema_fast_s.shift(1)).fillna(False)
        stall_ok = (
            (rsi >= float(rsi_overbought))
            & (
                (close < ema_fast_s).fillna(False)
                | (mom <= 0.0).fillna(False)
                | ema_fast_down
            )
        ).fillna(False)

        def _pick_numeric_series(cols: tuple[str, ...]) -> pd.Series:
            for cname in cols:
                if cname in inf.columns:
                    ser = pd.to_numeric(inf[cname], errors="coerce")
                    if isinstance(ser, pd.Series):
                        return ser.reindex(inf.index)
            return pd.Series(np.nan, index=inf.index, dtype=float)

        funding = _pick_numeric_series(
            (
                f"funding_rate_{tf}",
                "funding_rate",
                "funding",
                "perp_funding",
                "mark_funding_rate",
                "future_funding_rate",
            )
        )
        oi_change = _pick_numeric_series(
            (
                f"oi_change_pct_{tf}",
                "oi_change_pct",
                "open_interest_change_pct",
                "oi_pct_change",
                "open_interest_pct_change",
                "oi_change",
            )
        )
        basis = _pick_numeric_series(
            tuple([f"basis_{tf}", *self._basis_proxy_keys()])
        )

        if funding.isna().all():
            try:
                fr_df = self.dp.get_pair_dataframe(pair=pair, timeframe=tf, candle_type="funding_rate")
            except Exception:
                fr_df = None
            if fr_df is not None and (not fr_df.empty):
                fr_df = fr_df.copy()
                fr_series = pd.to_numeric(fr_df.get("open"), errors="coerce")
                if not isinstance(fr_series, pd.Series):
                    fr_series = pd.Series(np.nan, index=fr_df.index, dtype=float)
                if fr_series.notna().sum() == 0:
                    fr_series = pd.to_numeric(fr_df.get("close"), errors="coerce")
                if isinstance(fr_series, pd.Series):
                    fr_df["__fimr_funding"] = fr_series
                    funding = self._merge_asof_numeric_series(inf, fr_df, "__fimr_funding")

        if basis.isna().all():
            basis = pd.to_numeric(
                self._compute_deriv_basis_proxy(inf, pair, tf).get("deriv_basis"),
                errors="coerce",
            )

        use_funding = bool(self.buy_fimr_use_funding.value)
        use_oi = bool(self.buy_fimr_use_oi.value)
        use_basis = bool(self.buy_fimr_use_basis.value)
        funding_ok_short = (funding >= float(self.buy_fimr_funding_pos_min.value)).fillna(False)
        funding_ok_long = (funding <= float(self.buy_fimr_funding_neg_max.value)).fillna(False)
        oi_ok_short = (oi_change >= float(self.buy_fimr_oi_rising_min.value)).fillna(False)
        oi_ok_long = (oi_change <= float(self.buy_fimr_oi_falling_min.value)).fillna(False)
        basis_ok_short = (basis >= float(self.buy_fimr_basis_pos_min.value)).fillna(False)
        basis_ok_long = (basis <= float(self.buy_fimr_basis_neg_max.value)).fillna(False)
        funding_present = funding.notna()
        oi_present = oi_change.notna()
        basis_present = basis.notna()

        crowded_ok_short = pd.Series(True, index=inf.index, dtype=bool)
        crowded_ok_long = pd.Series(True, index=inf.index, dtype=bool)
        missing_proxy_short = pd.Series(False, index=inf.index, dtype=bool)
        missing_proxy_long = pd.Series(False, index=inf.index, dtype=bool)
        selected = 0
        if use_funding:
            selected += 1
            crowded_ok_short = crowded_ok_short & funding_ok_short
            crowded_ok_long = crowded_ok_long & funding_ok_long
            missing_proxy_short = missing_proxy_short | (~funding_present)
            missing_proxy_long = missing_proxy_long | (~funding_present)
        if use_oi:
            selected += 1
            crowded_ok_short = crowded_ok_short & oi_ok_short
            crowded_ok_long = crowded_ok_long & oi_ok_long
            missing_proxy_short = missing_proxy_short | (~oi_present)
            missing_proxy_long = missing_proxy_long | (~oi_present)
        if use_basis:
            selected += 1
            crowded_ok_short = crowded_ok_short & basis_ok_short
            crowded_ok_long = crowded_ok_long & basis_ok_long
            missing_proxy_short = missing_proxy_short | (~basis_present)
            missing_proxy_long = missing_proxy_long | (~basis_present)
        if selected <= 0:
            crowded_ok_short = pd.Series(False, index=inf.index, dtype=bool)
            crowded_ok_long = pd.Series(False, index=inf.index, dtype=bool)
            missing_proxy_short = pd.Series(True, index=inf.index, dtype=bool)
            missing_proxy_long = pd.Series(True, index=inf.index, dtype=bool)

        rsi_oversold = int(self.buy_fimr_rsi_oversold.value)
        ema_fast_up = (ema_fast_s >= ema_fast_s.shift(1)).fillna(False)
        stall_ok_long = (
            (rsi <= float(rsi_oversold))
            & (
                (close > ema_fast_s).fillna(False)
                | (mom >= 0.0).fillna(False)
                | ema_fast_up
            )
        ).fillna(False)
        if bool(self.buy_fimr_require_reclaim_long.value):
            ema_slow_s = pd.to_numeric(inf["fimr_ema_slow"], errors="coerce")
            stall_ok_long = stall_ok_long & (close > ema_slow_s).fillna(False)

        mode = self._fimr_mode_value()
        allow_short = mode in {"short_only", "both"}
        allow_long = mode in {"long_only", "both"}
        if not bool(self.can_short):
            allow_short = False

        if bool(self.buy_fimr_require_stall.value):
            signal_short = crowded_ok_short & stall_ok & (~missing_proxy_short) & allow_short
            signal_long = crowded_ok_long & stall_ok_long & (~missing_proxy_long) & allow_long
        else:
            signal_short = crowded_ok_short & (~missing_proxy_short) & allow_short
            signal_long = crowded_ok_long & (~missing_proxy_long) & allow_long

        # Backward-compat aliases keep existing downstream references stable.
        inf["fimr_missing_proxy"] = missing_proxy_short.astype(bool)
        inf["fimr_crowded_ok"] = crowded_ok_short.astype(bool)
        inf["fimr_stall_ok"] = stall_ok.astype(bool)
        inf["fimr_signal_short"] = signal_short.astype(bool)
        inf["fimr_missing_proxy_short"] = missing_proxy_short.astype(bool)
        inf["fimr_crowded_ok_short"] = crowded_ok_short.astype(bool)
        inf["fimr_stall_ok_short"] = stall_ok.astype(bool)
        inf["fimr_signal_long"] = signal_long.astype(bool)
        inf["fimr_missing_proxy_long"] = missing_proxy_long.astype(bool)
        inf["fimr_crowded_ok_long"] = crowded_ok_long.astype(bool)
        inf["fimr_stall_ok_long"] = stall_ok_long.astype(bool)
        inf["fimr_funding_ok"] = funding_ok_short.astype(bool)
        inf["fimr_funding_ok_long"] = funding_ok_long.astype(bool)
        inf["fimr_oi_ok"] = oi_ok_short.astype(bool)
        inf["fimr_oi_ok_long"] = oi_ok_long.astype(bool)
        inf["fimr_basis_ok"] = basis_ok_short.astype(bool)
        inf["fimr_basis_ok_long"] = basis_ok_long.astype(bool)

        inf_cols = inf[
            [
                "date",
                "fimr_missing_proxy",
                "fimr_crowded_ok",
                "fimr_stall_ok",
                "fimr_signal_short",
                "fimr_missing_proxy_short",
                "fimr_crowded_ok_short",
                "fimr_stall_ok_short",
                "fimr_missing_proxy_long",
                "fimr_crowded_ok_long",
                "fimr_stall_ok_long",
                "fimr_signal_long",
                "fimr_funding_ok",
                "fimr_funding_ok_long",
                "fimr_oi_ok",
                "fimr_oi_ok_long",
                "fimr_basis_ok",
                "fimr_basis_ok_long",
            ]
        ].copy()

        if tf == self.timeframe:
            for c in (
                "fimr_missing_proxy",
                "fimr_crowded_ok",
                "fimr_stall_ok",
                "fimr_signal_short",
                "fimr_missing_proxy_short",
                "fimr_crowded_ok_short",
                "fimr_stall_ok_short",
                "fimr_missing_proxy_long",
                "fimr_crowded_ok_long",
                "fimr_stall_ok_long",
                "fimr_signal_long",
                "fimr_funding_ok",
                "fimr_funding_ok_long",
                "fimr_oi_ok",
                "fimr_oi_ok_long",
                "fimr_basis_ok",
                "fimr_basis_ok_long",
            ):
                dataframe[f"{c}{suf}"] = inf_cols[c].values
        else:
            right = inf_cols.rename(
                columns={
                    "fimr_missing_proxy": f"fimr_missing_proxy{suf}",
                    "fimr_crowded_ok": f"fimr_crowded_ok{suf}",
                    "fimr_stall_ok": f"fimr_stall_ok{suf}",
                    "fimr_signal_short": f"fimr_signal_short{suf}",
                    "fimr_missing_proxy_short": f"fimr_missing_proxy_short{suf}",
                    "fimr_crowded_ok_short": f"fimr_crowded_ok_short{suf}",
                    "fimr_stall_ok_short": f"fimr_stall_ok_short{suf}",
                    "fimr_missing_proxy_long": f"fimr_missing_proxy_long{suf}",
                    "fimr_crowded_ok_long": f"fimr_crowded_ok_long{suf}",
                    "fimr_stall_ok_long": f"fimr_stall_ok_long{suf}",
                    "fimr_signal_long": f"fimr_signal_long{suf}",
                    "fimr_funding_ok": f"fimr_funding_ok{suf}",
                    "fimr_funding_ok_long": f"fimr_funding_ok_long{suf}",
                    "fimr_oi_ok": f"fimr_oi_ok{suf}",
                    "fimr_oi_ok_long": f"fimr_oi_ok_long{suf}",
                    "fimr_basis_ok": f"fimr_basis_ok{suf}",
                    "fimr_basis_ok_long": f"fimr_basis_ok_long{suf}",
                }
            ).copy()
            left = dataframe.copy()
            left["_fimr_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
            right["_fimr_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
            right = right.drop(columns=["date"]).sort_values("_fimr_date")
            left = left.sort_values("_fimr_date")
            dataframe = pd.merge_asof(left, right, on="_fimr_date", direction="backward")
            dataframe = dataframe.sort_index()
            dataframe.drop(columns=["_fimr_date"], inplace=True, errors="ignore")

        return _ensure_defaults(dataframe)

    def _fimr_entry_allows(
        self,
        pair: str,
        row: pd.Series | dict,
        current_time: datetime,
        side: str = "short",
    ) -> tuple[bool, str]:
        self._fimr_init_state()
        tf = str(self.buy_fimr_tf.value or "1h")
        suf = f"_{tf}"
        side_l = str(side or "short").lower()
        if side_l not in {"long", "short"}:
            side_l = "short"

        if not bool(self.buy_fimr_enabled.value):
            return False, "fimr_disabled"
        if not self._fimr_side_enabled(side_l):
            self._fimr_inc("block_side")
            return False, f"fimr_side_{side_l}_disabled"
        if not self._fimr_pair_allowed(pair):
            self._fimr_inc("block_pair")
            return False, "fimr_pair_block"
        if self._fimr_core_demand(pair, current_time, row=row):
            self._fimr_inc("block_core_demand")
            return False, "fimr_core_demand"
        day_ok, _ = self._fimr_daily_limits_allow(current_time)
        if not day_ok:
            self._fimr_inc("block_governance")
            return False, "fimr_daily_block"
        cd_block, _ = self._fimr_cooldown_blocks(pair, current_time)
        if cd_block:
            self._fimr_inc("block_governance")
            return False, "fimr_cooldown"

        if side_l == "long":
            missing_col = f"fimr_missing_proxy_long{suf}"
            crowded_col = f"fimr_crowded_ok_long{suf}"
            stall_col = f"fimr_stall_ok_long{suf}"
        else:
            missing_col = f"fimr_missing_proxy_short{suf}"
            crowded_col = f"fimr_crowded_ok_short{suf}"
            stall_col = f"fimr_stall_ok_short{suf}"

        if bool(row.get(missing_col, False)):
            self._fimr_inc("block_missing_proxy")
            return False, "fimr_missing_proxy"
        if not bool(row.get(crowded_col, False)):
            self._fimr_inc("block_crowded")
            return False, "fimr_not_crowded"
        self._fimr_inc("raw")
        if bool(self.buy_fimr_require_stall.value) and not bool(row.get(stall_col, False)):
            self._fimr_inc("block_stall")
            return False, "fimr_no_stall"

        self._fimr_inc("allowed")
        return True, "fimr_ok"

    def _fimr_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_fimr_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            self._fimr_init_state()
            key = self._idle_trade_key(trade)
            self._fimr_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._fimr_mark_loss(trade.pair, current_time)
        except Exception:
            pass

