    @staticmethod
    def _router_v2_csv_set(raw: str) -> set[str]:
        return {x.strip().lower() for x in str(raw or "").split(",") if x.strip()}

    @staticmethod
    def _router_v2_regime_bucket(composite_regime: str) -> str:
        reg = str(composite_regime or "").upper()
        if ("PANIC" in reg) or ("CAPITULATION" in reg):
            return "panic"
        if "CHOP_MR" in reg:
            return "chop"
        if ("VOL_EXP" in reg) or ("EXPAND" in reg):
            return "vol"
        if ("TREND_UP" in reg) or ("TREND_DOWN" in reg):
            return "trend"
        return "default"

    @staticmethod
    def _router_v2_norm_bucket(bucket: str) -> str:
        b = str(bucket or "").lower()
        if b in {"trbk_short", "trbk"}:
            return "trbk"
        if b in {"bearvol_short", "bearvol"}:
            return "bearvol"
        if b in {"brf_short", "brf"}:
            return "brf"
        return b

    def _router_v2_profile_allow(self, bucket: str) -> set[str]:
        profile = str(self.buy_router_v2_policy_profile.value or "custom").lower()
        if profile == "strict":
            mapping = {
                "trend": {"trbk", "trendpb", "cbx", "sbr", "lagcatch"},
                "chop": {"trbk", "cvmr", "cvw"},
                "vol": {"trbk", "cbx", "sbr", "volex", "evtpulse"},
                "panic": {"panic", "bearvol", "brf", "cpdf", "mofi"},
                "default": {"trbk", "trendpb", "cbx", "lagcatch", "evtpulse"},
            }
            return set(mapping.get(bucket, mapping["default"]))
        if profile == "balanced":
            mapping = {
                "trend": {"trbk", "trendpb", "cbx", "apc", "sbr", "fcarry", "lagcatch", "evtpulse"},
                "chop": {"trbk", "cvmr", "cvw", "spreadarb"},
                "vol": {"trbk", "cbx", "apc", "sbr", "fcarry", "spreadarb", "evtpulse", "lagcatch"},
                "panic": {"panic", "bearvol", "brf", "cpdf", "mofi", "fcarry"},
                "default": {"trbk", "trendpb", "cbx", "cvmr", "lagcatch", "evtpulse"},
            }
            return set(mapping.get(bucket, mapping["default"]))
        # custom mode: use explicit allowlist params.
        if bucket == "trend":
            return self._router_v2_csv_set(str(self.buy_router_v2_allow_trend.value or ""))
        if bucket == "chop":
            return self._router_v2_csv_set(str(self.buy_router_v2_allow_chop.value or ""))
        if bucket == "vol":
            return self._router_v2_csv_set(str(self.buy_router_v2_allow_vol.value or ""))
        if bucket == "panic":
            return self._router_v2_csv_set(str(self.buy_router_v2_allow_panic.value or ""))
        return self._router_v2_csv_set(str(self.buy_router_v2_allow_default.value or ""))

    def _router_v2_allows(
        self,
        pair: str,
        entry_tag: str | None,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> tuple[bool, str]:
        self._router_v2_inc("calls")
        if not bool(self.buy_router_v2_enabled.value):
            self._router_v2_inc("pass")
            return True, "disabled"
        if bool(self.buy_router_v2_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            self._router_v2_inc("scope_skip")
            return True, "scope_skip"
        probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
        if isinstance(probe, (pd.Series, dict)):
            regime_val = str(probe.get("composite_regime", ""))
        else:
            regime_val = ""
        bucket = self._router_v2_regime_bucket(regime_val)
        sleeve = self._router_v2_norm_bucket(self._tag_bucket(entry_tag))
        if sleeve == "mofi":
            self._router_v2_inc("tag_skip")
            return True, "mofi_bypass"
        allow = self._router_v2_profile_allow(bucket)
        if not allow:
            self._router_v2_inc("tag_skip")
            return True, "no_rules"
        if sleeve not in allow:
            self._router_v2_inc("block_router")
            return False, f"{bucket}:{sleeve}"
        self._router_v2_inc("pass")
        return True, "pass"

    def _util_router_mult(
        self,
        pair: str,
        entry_tag: str | None,
        current_time: datetime | None = None,
    ) -> float:
        self._util_router_init_state()
        self._util_router_counts["calls"] = float(self._util_router_counts.get("calls", 0.0)) + 1.0

        if not bool(self.buy_util_router_enabled.value):
            self._util_router_counts["mult_sum"] = float(self._util_router_counts.get("mult_sum", 0.0)) + 1.0
            return 1.0

        if bool(self.buy_util_router_apply_aux_only.value) and (not self._is_auxiliary_entry_tag(entry_tag)):
            self._util_router_counts["scope_skip"] = float(self._util_router_counts.get("scope_skip", 0.0)) + 1.0
            self._util_router_counts["mult_sum"] = float(self._util_router_counts.get("mult_sum", 0.0)) + 1.0
            return 1.0

        allow_csv = str(self.buy_util_router_tag_allowlist.value or "").strip()
        if allow_csv:
            allow = {x.strip().lower() for x in allow_csv.split(",") if x.strip()}
            if allow:
                bucket = str(self._tag_bucket(entry_tag)).lower()
                if bucket not in allow:
                    self._util_router_counts["tag_skip"] = float(self._util_router_counts.get("tag_skip", 0.0)) + 1.0
                    self._util_router_counts["mult_sum"] = float(self._util_router_counts.get("mult_sum", 0.0)) + 1.0
                    return 1.0

        if bool(self.buy_util_router_core_open_guard.value) and self._open_core_trades_count() > 0:
            self._util_router_counts["core_guard_skip"] = float(self._util_router_counts.get("core_guard_skip", 0.0)) + 1.0
            self._util_router_counts["mult_sum"] = float(self._util_router_counts.get("mult_sum", 0.0)) + 1.0
            return 1.0

        hard_cap = self._parse_numeric(self.config.get("max_open_trades", None))
        open_total = float(self._count_open_trades_total())
        if hard_cap is None or hard_cap <= 0:
            util = 0.0 if open_total <= 0 else min(1.0, open_total / 5.0)
        else:
            util = max(0.0, min(1.0, open_total / float(hard_cap)))

        target = float(self.buy_util_router_target_util.value)
        target = max(1e-6, target)
        max_boost = max(0.0, float(self.buy_util_router_max_boost.value))
        min_boost = max(0.0, float(self.buy_util_router_min_boost.value))
        if max_boost < min_boost:
            max_boost, min_boost = min_boost, max_boost

        self._util_router_counts["boost_calls"] = float(self._util_router_counts.get("boost_calls", 0.0)) + 1.0
        if util >= target:
            mult = 1.0
        else:
            gap = max(0.0, (target - util) / target)
            mult = 1.0 + gap * max(0.0, max_boost - 1.0)
        mult = float(np.clip(mult, min_boost, max_boost if max_boost > 0 else 10.0))
        if mult > 1.0:
            self._util_router_counts["boost_applied"] = float(self._util_router_counts.get("boost_applied", 0.0)) + 1.0
        self._util_router_counts["mult_sum"] = float(self._util_router_counts.get("mult_sum", 0.0)) + float(mult)

        if bool(self.buy_util_router_debug.value):
            try:
                logger.info(
                    "UTIL_ROUTER pair=%s tag=%s util=%.4f target=%.4f mult=%.4f",
                    pair,
                    str(entry_tag or ""),
                    util,
                    target,
                    mult,
                )
            except Exception:
                pass
        return float(mult)

