    def _lagcatch_pair_allowed(self, pair: str) -> bool:
        market_pair = self._resolve_pair_hint(str(self.buy_lagcatch_market_pair.value or "BTC/USDT:USDT"), "BTC")
        if market_pair and self._pairs_same_base(pair, market_pair):
            return False
        return self._pair_in_allowlist(pair, str(self.buy_lagcatch_allow_pairs.value or ""))

    def _cvmr_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_cvmr_entry_tag(tag):
                open_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        cap = max(0.0, wallet_total * float(self.buy_cvmr_cap_pct.value) - open_exposure)
        return max(0.0, cap)

