    def _cvmr_add_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        open_ = pd.to_numeric(dataframe.get("open"), errors="coerce")
        high = pd.to_numeric(dataframe.get("high"), errors="coerce")
        low = pd.to_numeric(dataframe.get("low"), errors="coerce")
        volume = pd.to_numeric(dataframe.get("volume"), errors="coerce")
        tiny = 1e-9

        rsi_len = int(self.buy_cvmr_rsi_len.value)
        bb_len = int(self.buy_cvmr_bb_len.value)
        bb_std = float(self.buy_cvmr_bb_std.value)
        rv_len = int(self.buy_cvmr_relvol_len.value)
        reclaim = float(self.buy_cvmr_reclaim_frac.value)
        ema_fast_len = int(self.buy_cvmr_ema_fast.value)
        ema_slow_len = int(self.buy_cvmr_ema_slow.value)

        bb = ta.BBANDS(dataframe, timeperiod=bb_len, nbdevup=bb_std, nbdevdn=bb_std)
        dataframe["cvmr_bb_lower"] = pd.to_numeric(bb["lowerband"], errors="coerce")
        dataframe["cvmr_bb_upper"] = pd.to_numeric(bb["upperband"], errors="coerce")
        dataframe["cvmr_rsi"] = ta.RSI(dataframe, timeperiod=rsi_len)
        dataframe["cvmr_ema_fast"] = ta.EMA(dataframe, timeperiod=ema_fast_len)
        dataframe["cvmr_ema_slow"] = ta.EMA(dataframe, timeperiod=ema_slow_len)
        dataframe["cvmr_atr"] = ta.ATR(dataframe, timeperiod=14)
        dataframe["cvmr_relvol"] = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)
        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        close_pos = close_pos.replace([np.inf, -np.inf], np.nan).fillna(0.5)
        dataframe["cvmr_close_pos"] = close_pos
        body = (close - open_).abs()
        upper_wick = (high - pd.concat([open_, close], axis=1).max(axis=1)).clip(lower=0.0)
        lower_wick = (pd.concat([open_, close], axis=1).min(axis=1) - low).clip(lower=0.0)
        dataframe["cvmr_body"] = body
        dataframe["cvmr_upper_wick"] = upper_wick
        dataframe["cvmr_lower_wick"] = lower_wick
        if "composite_regime" in dataframe.columns:
            regime = dataframe["composite_regime"].astype(str).str.upper()
        else:
            regime = pd.Series("", index=dataframe.index, dtype=str)
        if bool(self.buy_cvmr_require_chop.value):
            regime_ok = regime.str.contains("CHOP_MR", na=False)
        else:
            regime_ok = pd.Series(True, index=dataframe.index, dtype=bool)

        lower = pd.to_numeric(dataframe["cvmr_bb_lower"], errors="coerce")
        upper = pd.to_numeric(dataframe["cvmr_bb_upper"], errors="coerce")
        rsi = pd.to_numeric(dataframe["cvmr_rsi"], errors="coerce")
        relvol = pd.to_numeric(dataframe["cvmr_relvol"], errors="coerce")
        ema_fast = pd.to_numeric(dataframe["cvmr_ema_fast"], errors="coerce")
        ema_slow = pd.to_numeric(dataframe["cvmr_ema_slow"], errors="coerce")
        atr = pd.to_numeric(dataframe["cvmr_atr"], errors="coerce")
        atr_pct = atr / close.replace(0, np.nan)
        bb_width = (upper - lower) / close.replace(0, np.nan)
        rsi_rebound = rsi > rsi.shift(1)
        rsi_fade = rsi < rsi.shift(1)
        trend_guard_long = (
            (ema_fast >= ema_slow) & (close >= ema_slow)
            if bool(self.buy_cvmr_require_not_downtrend.value)
            else pd.Series(True, index=dataframe.index, dtype=bool)
        )
        trend_guard_short = (
            (ema_fast <= ema_slow) & (close <= ema_slow)
            if bool(self.buy_cvmr_require_not_downtrend.value)
            else pd.Series(True, index=dataframe.index, dtype=bool)
        )
        wick_mult = float(self.buy_cvmr_min_wick_body_mult.value)
        vol_guard = (
            (atr_pct <= float(self.buy_cvmr_max_atr_pct.value))
            & (bb_width >= float(self.buy_cvmr_min_bbwidth_pct.value))
        )
        long_signal = (
            (low < lower)
            & (close > lower)
            & (close >= open_)
            & (rsi <= int(self.buy_cvmr_rsi_long_max.value))
            & (relvol >= float(self.buy_cvmr_relvol_min.value))
            & (close_pos >= reclaim)
            & (lower_wick >= wick_mult * body.clip(lower=tiny))
            & rsi_rebound
            & trend_guard_long
            & vol_guard
            & regime_ok
        )
        short_signal = (
            (high > upper)
            & (close < upper)
            & (close <= open_)
            & (rsi >= int(self.buy_cvmr_rsi_short_min.value))
            & (relvol >= float(self.buy_cvmr_relvol_min.value))
            & (close_pos <= max(0.0, 1.0 - reclaim))
            & (upper_wick >= wick_mult * body.clip(lower=tiny))
            & rsi_fade
            & trend_guard_short
            & vol_guard
            & regime_ok
        )
        dataframe["cvmr_signal_long"] = long_signal.fillna(False)
        dataframe["cvmr_signal_short"] = short_signal.fillna(False)
        return dataframe

    def _tes_add_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        open_ = pd.to_numeric(dataframe.get("open"), errors="coerce")
        high = pd.to_numeric(dataframe.get("high"), errors="coerce")
        low = pd.to_numeric(dataframe.get("low"), errors="coerce")
        volume = pd.to_numeric(dataframe.get("volume"), errors="coerce")

        rsi_len = int(self.buy_tes_rsi_len.value)
        ema_fast_len = int(self.buy_tes_ema_fast.value)
        ema_slow_len = int(self.buy_tes_ema_slow.value)
        rv_len = int(self.buy_tes_relvol_len.value)
        tiny = 1e-9

        dataframe["tes_rsi"] = ta.RSI(dataframe, timeperiod=rsi_len)
        dataframe["tes_ema_fast"] = ta.EMA(dataframe, timeperiod=ema_fast_len)
        dataframe["tes_ema_slow"] = ta.EMA(dataframe, timeperiod=ema_slow_len)
        dataframe["tes_relvol"] = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)
        body = (close - open_).abs()
        upper_wick = (high - pd.concat([open_, close], axis=1).max(axis=1)).clip(lower=0.0)
        lower_wick = (pd.concat([open_, close], axis=1).min(axis=1) - low).clip(lower=0.0)
        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        close_pos = close_pos.replace([np.inf, -np.inf], np.nan).fillna(0.5)

        rsi = pd.to_numeric(dataframe["tes_rsi"], errors="coerce")
        ema_fast = pd.to_numeric(dataframe["tes_ema_fast"], errors="coerce")
        ema_slow = pd.to_numeric(dataframe["tes_ema_slow"], errors="coerce")
        relvol = pd.to_numeric(dataframe["tes_relvol"], errors="coerce")
        if bool(self.buy_tes_require_trend_up.value):
            trend_ok = (ema_fast > ema_slow) & (close > ema_slow)
        else:
            trend_ok = pd.Series(True, index=dataframe.index, dtype=bool)
        signal = (
            (rsi >= int(self.buy_tes_rsi_short_min.value))
            & (upper_wick >= float(self.buy_tes_upper_wick_body_mult.value) * body.clip(lower=tiny))
            & (close < open_)
            & (close < ema_fast)
            & (relvol >= float(self.buy_tes_relvol_min.value))
            & trend_ok
        )
        long_signal = (
            bool(self.buy_tes_enable_long.value)
            & trend_ok
            & (low <= ema_fast)
            & (close_pos >= float(self.buy_tes_reclaim_frac.value))
            & (lower_wick >= float(self.buy_tes_lower_wick_body_mult.value) * body.clip(lower=tiny))
            & (rsi <= int(self.buy_tes_rsi_long_max.value))
            & (relvol >= float(self.buy_tes_relvol_min.value))
            & (((ema_fast - close) / ema_fast.replace(0, np.nan)) <= float(self.buy_tes_pullback_max.value))
        )
        dataframe["tes_signal_long"] = long_signal.fillna(False)
        dataframe["tes_signal_short"] = signal.fillna(False)
        return dataframe

    def _apc_add_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        open_ = pd.to_numeric(dataframe.get("open"), errors="coerce")
        close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        high = pd.to_numeric(dataframe.get("high"), errors="coerce")
        low = pd.to_numeric(dataframe.get("low"), errors="coerce")
        volume = pd.to_numeric(dataframe.get("volume"), errors="coerce")

        atr_len = int(self.buy_apc_atr_len.value)
        atr_ema_len = int(self.buy_apc_atr_ema_len.value)
        lookback = int(self.buy_apc_breakout_lookback.value)
        rv_len = int(self.buy_apc_relvol_len.value)
        ema_fast_len = int(self.buy_apc_ema_fast.value)

        dataframe["apc_atr"] = ta.ATR(dataframe, timeperiod=atr_len)
        atr = pd.to_numeric(dataframe["apc_atr"], errors="coerce")
        atr_ema = atr.ewm(span=max(2, atr_ema_len), adjust=False).mean()
        dataframe["apc_atr_expand"] = atr / atr_ema.replace(0, np.nan)
        dataframe["apc_adx"] = ta.ADX(dataframe, timeperiod=14)
        dataframe["apc_relvol"] = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)
        dataframe["apc_ema_fast"] = ta.EMA(dataframe, timeperiod=ema_fast_len)
        dataframe["apc_ema_slope"] = pd.to_numeric(dataframe["apc_ema_fast"], errors="coerce").diff()
        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        close_pos = close_pos.replace([np.inf, -np.inf], np.nan).fillna(0.5)
        body = (close - open_).abs()
        breakout_high = high.rolling(lookback, min_periods=max(5, lookback // 2)).max().shift(1)
        breakout_low = low.rolling(lookback, min_periods=max(5, lookback // 2)).min().shift(1)
        if "composite_regime" in dataframe.columns:
            regime = dataframe["composite_regime"].astype(str).str.upper()
        else:
            regime = pd.Series("", index=dataframe.index, dtype=str)
        regime_ok = ~regime.str.contains("CHOP_MR", na=False) if bool(self.buy_apc_block_chop.value) else pd.Series(True, index=dataframe.index, dtype=bool)
        if bool(self.buy_apc_trend_regime_only.value):
            regime_ok &= regime.str.contains("TREND_UP|VOL_EXP", na=False)

        atr_expand = pd.to_numeric(dataframe["apc_atr_expand"], errors="coerce")
        relvol = pd.to_numeric(dataframe["apc_relvol"], errors="coerce")
        adx = pd.to_numeric(dataframe["apc_adx"], errors="coerce")
        ema_fast = pd.to_numeric(dataframe["apc_ema_fast"], errors="coerce")
        ema_slope = pd.to_numeric(dataframe["apc_ema_slope"], errors="coerce")
        breakout_buf = float(self.buy_apc_breakout_buffer_atr.value) * atr
        breakout_ext = (close - breakout_high).clip(lower=0.0)
        chase_ok = breakout_ext <= (float(self.buy_apc_max_chase_atr.value) * atr)
        long_signal = (
            (close > (breakout_high + breakout_buf))
            & (close > ema_fast)
            & (atr_expand >= float(self.buy_apc_atr_expand_min.value))
            & (relvol >= float(self.buy_apc_relvol_min.value))
            & (adx >= float(self.buy_apc_adx_min.value))
            & (close_pos >= float(self.buy_apc_min_close_pos.value))
            & (body >= 0.25 * atr)
            & chase_ok
            & ((ema_slope > 0) if bool(self.buy_apc_require_ema_slope.value) else True)
            & regime_ok
        )
        short_signal = (
            (close < breakout_low)
            & (close < ema_fast)
            & (atr_expand >= float(self.buy_apc_atr_expand_min.value))
            & (relvol >= float(self.buy_apc_relvol_min.value))
            & (adx >= float(self.buy_apc_adx_min.value))
            & (close_pos <= max(0.0, 1.0 - float(self.buy_apc_min_close_pos.value)))
            & ((ema_slope < 0) if bool(self.buy_apc_require_ema_slope.value) else True)
            & regime_ok
        )
        dataframe["apc_signal_long"] = long_signal.fillna(False)
        dataframe["apc_signal_short"] = short_signal.fillna(False) if self.can_short else False
        return dataframe

    def _sbr_add_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        open_ = pd.to_numeric(dataframe.get("open"), errors="coerce")
        close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        high = pd.to_numeric(dataframe.get("high"), errors="coerce")
        low = pd.to_numeric(dataframe.get("low"), errors="coerce")
        volume = pd.to_numeric(dataframe.get("volume"), errors="coerce")

        atr_len = int(self.buy_sbr_atr_len.value)
        atr_ema_len = int(self.buy_sbr_atr_expand_ema_len.value)
        ema_fast_len = int(self.buy_sbr_ema_fast.value)
        lookback = int(self.buy_sbr_breakout_lookback.value)
        rv_len = int(self.buy_sbr_relvol_len.value)

        dataframe["sbr_atr"] = ta.ATR(dataframe, timeperiod=atr_len)
        atr = pd.to_numeric(dataframe["sbr_atr"], errors="coerce")
        atr_ema = atr.ewm(span=max(2, atr_ema_len), adjust=False).mean()
        atr_expand = atr / atr_ema.replace(0, np.nan)
        dataframe["sbr_adx"] = ta.ADX(dataframe, timeperiod=14)
        dataframe["sbr_ema_fast"] = ta.EMA(dataframe, timeperiod=ema_fast_len)
        dataframe["sbr_relvol"] = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)

        breakout_high = high.rolling(lookback, min_periods=max(5, lookback // 2)).max().shift(1)
        break_buf = float(self.buy_sbr_break_buffer_atr.value) * atr
        retest_dist = (breakout_high - low).clip(lower=0.0)
        chase_dist = (close - breakout_high).clip(lower=0.0)

        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        close_pos = close_pos.replace([np.inf, -np.inf], np.nan).fillna(0.5)

        adx = pd.to_numeric(dataframe["sbr_adx"], errors="coerce")
        relvol = pd.to_numeric(dataframe["sbr_relvol"], errors="coerce")
        ema_fast = pd.to_numeric(dataframe["sbr_ema_fast"], errors="coerce")
        ema_slope = ema_fast.diff()
        atr_pct = atr / close.replace(0, np.nan)
        if "composite_regime" in dataframe.columns:
            regime = dataframe["composite_regime"].astype(str).str.upper()
        else:
            regime = pd.Series("", index=dataframe.index, dtype=str)
        regime_ok = ~regime.str.contains("CHOP_MR|PANIC", na=False) if bool(self.buy_sbr_block_chop.value) else pd.Series(True, index=dataframe.index, dtype=bool)
        if bool(self.buy_sbr_require_regime_trend.value):
            regime_ok &= regime.str.contains("TREND_UP|VOL_EXP", na=False)
        retest_ok = (low <= (breakout_high + float(self.buy_sbr_retest_atr_mult.value) * atr)) & (
            low >= (breakout_high - float(self.buy_sbr_retest_atr_mult.value) * atr)
        )

        mode = str(self.buy_sbr_signal_mode.value or "strict").lower()
        if mode == "relaxed":
            # Activation-focused relaxed mode: still trend/volatility aware, but allows
            # continuation breaks that don't print a clean retest candle.
            long_signal = (
                (close > (breakout_high + 0.5 * break_buf))
                & (close > ema_fast)
                & ((close > open_) | (close_pos >= float(self.buy_sbr_min_close_pos.value)))
                & (ema_slope >= 0)
                & (adx >= 0.85 * float(self.buy_sbr_adx_min.value))
                & (relvol >= 0.85 * float(self.buy_sbr_relvol_min.value))
                & (
                    retest_ok
                    | (
                        chase_dist
                        <= (1.20 * float(self.buy_sbr_max_chase_atr.value) * atr)
                    )
                )
                & (atr_expand >= max(1.0, 0.9 * float(self.buy_sbr_atr_expand_min.value)))
                & (atr_pct <= float(self.buy_sbr_max_atr_pct.value))
                & regime_ok
            )
        else:
            long_signal = (
                (close > (breakout_high + break_buf))
                & (close > ema_fast)
                & (close > open_)
                & (ema_slope > 0)
                & (adx >= float(self.buy_sbr_adx_min.value))
                & (relvol >= float(self.buy_sbr_relvol_min.value))
                & (close_pos >= float(self.buy_sbr_min_close_pos.value))
                & retest_ok
                & (chase_dist <= float(self.buy_sbr_max_chase_atr.value) * atr)
                & (atr_expand >= float(self.buy_sbr_atr_expand_min.value))
                & (atr_pct <= float(self.buy_sbr_max_atr_pct.value))
                & regime_ok
            )
        dataframe["sbr_signal_long"] = long_signal.fillna(False)
        return dataframe

    def _spreadarb_add_indicators(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._spreadarb_init_state()
        if (not bool(self.buy_spreadarb_enabled.value)) or (not self._spreadarb_pair_allowed(pair)):
            dataframe["spreadarb_signal_long"] = False
            dataframe["spreadarb_raw_shape"] = False
            return dataframe

        btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
        eth_pair = self._resolve_ref_pair("ETH") or "ETH/USDT:USDT"
        other_pair = None
        if self._pairs_same_base(pair, btc_pair):
            other_pair = eth_pair
        elif self._pairs_same_base(pair, eth_pair):
            other_pair = btc_pair
        if not other_pair:
            dataframe["spreadarb_signal_long"] = False
            dataframe["spreadarb_raw_shape"] = False
            return dataframe

        try:
            other_df = self.dp.get_pair_dataframe(pair=other_pair, timeframe=self.timeframe)
        except Exception:
            other_df = None
        if other_df is None or other_df.empty:
            dataframe["spreadarb_signal_long"] = False
            dataframe["spreadarb_raw_shape"] = False
            return dataframe

        left = dataframe.copy()
        right = other_df[["date", "close"]].copy()
        left["_spreadarb_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
        right["_spreadarb_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
        right["spreadarb_other_close"] = pd.to_numeric(right["close"], errors="coerce")
        right = right.drop(columns=["date", "close"]).sort_values("_spreadarb_date")
        left = left.sort_values("_spreadarb_date")
        merged = pd.merge_asof(left, right, on="_spreadarb_date", direction="backward").sort_index()

        close = pd.to_numeric(merged.get("close"), errors="coerce")
        open_ = pd.to_numeric(merged.get("open"), errors="coerce")
        other_close = pd.to_numeric(merged.get("spreadarb_other_close"), errors="coerce")
        ratio = close / other_close.replace(0, np.nan)
        lb = max(12, int(self.buy_spreadarb_lookback.value))
        ratio_mu = ratio.rolling(lb, min_periods=max(6, lb // 3)).mean()
        ratio_sd = ratio.rolling(lb, min_periods=max(6, lb // 3)).std(ddof=0)
        z = (ratio - ratio_mu) / ratio_sd.replace(0, np.nan)

        vol = pd.to_numeric(merged.get("volume"), errors="coerce")
        rv_len = max(5, int(self.buy_spreadarb_relvol_len.value))
        relvol = vol / vol.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)

        raw_shape = (z <= -float(self.buy_spreadarb_z_enter.value)).fillna(False)
        signal = raw_shape & (z >= -float(self.buy_spreadarb_z_max.value))
        signal &= (z >= z.shift(1)).fillna(False)
        signal &= (relvol >= float(self.buy_spreadarb_relvol_min.value)).fillna(False)

        # V3 hardening: beta-adjusted residual + return-correlation quality gate.
        if bool(self.buy_spreadarb_v3_enabled.value):
            beta_lb = max(12, int(self.buy_spreadarb_v3_beta_lookback.value))
            minp = max(6, beta_lb // 3)
            log_close = np.log(close.replace(0, np.nan))
            log_other = np.log(other_close.replace(0, np.nan))
            ret_close = log_close.diff()
            ret_other = log_other.diff()
            corr = ret_close.rolling(beta_lb, min_periods=minp).corr(ret_other)

            cov = log_close.rolling(beta_lb, min_periods=minp).cov(log_other)
            var_other = log_other.rolling(beta_lb, min_periods=minp).var(ddof=0)
            beta_abs_max = float(self.buy_spreadarb_v3_beta_abs_max.value)
            beta = (cov / var_other.replace(0, np.nan)).clip(lower=-beta_abs_max, upper=beta_abs_max)

            resid = log_close - (beta * log_other)
            resid_mu = resid.rolling(lb, min_periods=max(6, lb // 3)).mean()
            resid_sd = resid.rolling(lb, min_periods=max(6, lb // 3)).std(ddof=0).replace(0, np.nan)
            resid_z = (resid - resid_mu) / resid_sd
            resid_recover = (resid_z - resid_z.shift(1)) >= float(self.buy_spreadarb_v3_min_resid_recover.value)

            raw_shape_v3 = (resid_z <= -float(self.buy_spreadarb_z_enter.value)).fillna(False)
            signal_v3 = raw_shape_v3 & (resid_z >= -float(self.buy_spreadarb_z_max.value))
            signal_v3 &= resid_recover.fillna(False)
            signal_v3 &= (relvol >= float(self.buy_spreadarb_relvol_min.value)).fillna(False)
            signal_v3 &= (corr >= float(self.buy_spreadarb_v3_corr_min.value)).fillna(False)
            signal_v3 &= beta.notna().fillna(False)

            raw_shape = raw_shape_v3
            signal = signal_v3
            merged["spreadarb_beta"] = beta
            merged["spreadarb_corr"] = corr
            merged["spreadarb_resid_z"] = resid_z

        if bool(self.buy_spreadarb_require_chop.value):
            regime = merged.get("composite_regime")
            if regime is not None:
                signal &= regime.astype(str).str.upper().str.contains("CHOP", na=False)

        # V2 hardening: require mean-reversion evidence and block trending cascades.
        if bool(self.buy_spreadarb_v2_enabled.value):
            z_prev = z.shift(1)
            z_recover = (z - z_prev) >= float(self.buy_spreadarb_v2_min_z_recover.value)
            signal &= z_recover.fillna(False)
            if bool(self.buy_spreadarb_v2_require_prev_extreme.value):
                prev_extreme = z_prev <= -float(self.buy_spreadarb_z_enter.value)
                signal &= prev_extreme.fillna(False)
            if bool(self.buy_spreadarb_v2_require_green.value):
                signal &= (close >= open_).fillna(False)
            try:
                adx = pd.to_numeric(ta.ADX(merged, timeperiod=14), errors="coerce")
            except Exception:
                adx = pd.Series(np.nan, index=merged.index, dtype=float)
            adx_ok = (adx <= float(self.buy_spreadarb_v2_max_adx.value)) | adx.isna()
            signal &= adx_ok.fillna(True)
            if bool(self.buy_spreadarb_v2_block_trend_regime.value):
                regime = merged.get("composite_regime")
                if regime is not None:
                    reg = regime.astype(str).str.upper()
                    signal &= ~reg.str.contains("TREND_UP|TREND_DOWN|BEAR", na=False)

        merged["spreadarb_raw_shape"] = raw_shape.fillna(False).astype(bool)
        merged["spreadarb_signal_long"] = signal.fillna(False).astype(bool)
        merged.drop(columns=["_spreadarb_date"], inplace=True, errors="ignore")
        return merged

    def _cpdf_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._cpdf_init_state()
        tf = str(self.buy_cpdf_tf.value or "15m")
        suf = f"_{tf}"
        defaults = (
            f"cpdf_raw_shape{suf}",
            f"cpdf_signal_long{suf}",
            f"cpdf_reclaim_ok{suf}",
            f"cpdf_shock_ok{suf}",
            f"cpdf_relvol_ok{suf}",
        )

        def _ensure(df: pd.DataFrame) -> pd.DataFrame:
            for c in defaults:
                if c not in df.columns:
                    df[c] = False
                else:
                    df[c] = df[c].fillna(False).astype(bool)
            return df

        if (not bool(self.buy_cpdf_enabled.value)) or (not self._cpdf_pair_allowed(pair)):
            return _ensure(dataframe)

        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure(dataframe)

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        open_ = pd.to_numeric(inf.get("open"), errors="coerce")
        high = pd.to_numeric(inf.get("high"), errors="coerce")
        low = pd.to_numeric(inf.get("low"), errors="coerce")
        volume = pd.to_numeric(inf.get("volume"), errors="coerce")
        tiny = 1e-9

        atr_len = max(5, int(self.buy_cpdf_atr_len.value))
        rz_len = max(8, int(self.buy_cpdf_retz_len.value))
        rv_len = max(5, int(self.buy_cpdf_relvol_len.value))
        ema_fast_len = max(2, int(self.buy_cpdf_ema_fast.value))

        atr = ta.ATR(inf, timeperiod=atr_len)
        ema_fast = ta.EMA(inf, timeperiod=ema_fast_len)
        ret = close.pct_change()
        ret_mu = ret.rolling(rz_len, min_periods=max(6, rz_len // 3)).mean()
        ret_sd = ret.rolling(rz_len, min_periods=max(6, rz_len // 3)).std(ddof=0)
        ret_z = (ret - ret_mu) / ret_sd.replace(0, np.nan)
        relvol = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)
        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        close_pos = close_pos.replace([np.inf, -np.inf], np.nan).fillna(0.5)
        red = (close < open_).fillna(False)

        shock_now = red & (ret_z <= -float(self.buy_cpdf_shock_z_min.value)).fillna(False)
        raw_shape = shock_now.shift(1).fillna(False)
        reclaim_ok = (close_pos >= float(self.buy_cpdf_reclaim_frac.value)).fillna(False) & (close >= open_).fillna(False)
        if bool(self.buy_cpdf_require_ema.value):
            reclaim_ok &= (close > ema_fast).fillna(False)
        relvol_ok = (relvol >= float(self.buy_cpdf_relvol_min.value)).fillna(False)
        signal = raw_shape & reclaim_ok & relvol_ok

        inf["cpdf_raw_shape"] = raw_shape.astype(bool)
        inf["cpdf_signal_long"] = signal.astype(bool)
        inf["cpdf_reclaim_ok"] = reclaim_ok.astype(bool)
        inf["cpdf_shock_ok"] = shock_now.astype(bool)
        inf["cpdf_relvol_ok"] = relvol_ok.astype(bool)

        cols = [
            "date",
            "cpdf_raw_shape",
            "cpdf_signal_long",
            "cpdf_reclaim_ok",
            "cpdf_shock_ok",
            "cpdf_relvol_ok",
        ]
        inf_cols = inf[cols].copy()

        if tf == self.timeframe:
            for c in cols[1:]:
                dataframe[f"{c}{suf}"] = inf_cols[c].values
            return _ensure(dataframe)

        right = inf_cols.rename(
            columns={
                "cpdf_raw_shape": f"cpdf_raw_shape{suf}",
                "cpdf_signal_long": f"cpdf_signal_long{suf}",
                "cpdf_reclaim_ok": f"cpdf_reclaim_ok{suf}",
                "cpdf_shock_ok": f"cpdf_shock_ok{suf}",
                "cpdf_relvol_ok": f"cpdf_relvol_ok{suf}",
            }
        ).copy()
        left = dataframe.copy()
        left["_cpdf_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
        right["_cpdf_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
        right = right.drop(columns=["date"]).sort_values("_cpdf_date")
        left = left.sort_values("_cpdf_date")
        out = pd.merge_asof(left, right, on="_cpdf_date", direction="backward").sort_index()
        out.drop(columns=["_cpdf_date"], inplace=True, errors="ignore")
        return _ensure(out)

    def _fcarry_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._fcarry_init_state()
        tf = str(self.buy_fcarry_tf.value or "1h")
        suf = f"_{tf}"
        defaults = (
            f"fcarry_missing_proxy{suf}",
            f"fcarry_funding_ok{suf}",
            f"fcarry_trend_ok{suf}",
            f"fcarry_signal_long{suf}",
        )

        def _ensure(df: pd.DataFrame) -> pd.DataFrame:
            for c in defaults:
                if c not in df.columns:
                    df[c] = False
                else:
                    df[c] = df[c].fillna(False).astype(bool)
            return df

        if (not bool(self.buy_fcarry_enabled.value)) or (not self._fcarry_pair_allowed(pair)):
            return _ensure(dataframe)

        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure(dataframe)

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        open_ = pd.to_numeric(inf.get("open"), errors="coerce")
        volume = pd.to_numeric(inf.get("volume"), errors="coerce")
        ema_fast_len = max(2, int(self.buy_fcarry_ema_fast.value))
        ema_slow_len = max(3, int(self.buy_fcarry_ema_slow.value))
        rv_len = max(5, int(self.buy_fcarry_relvol_len.value))

        inf["fcarry_ema_fast"] = ta.EMA(inf, timeperiod=ema_fast_len)
        inf["fcarry_ema_slow"] = ta.EMA(inf, timeperiod=ema_slow_len)
        inf["fcarry_adx"] = ta.ADX(inf, timeperiod=14)
        relvol = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)
        ema_fast = pd.to_numeric(inf["fcarry_ema_fast"], errors="coerce")
        ema_slow = pd.to_numeric(inf["fcarry_ema_slow"], errors="coerce")
        adx = pd.to_numeric(inf["fcarry_adx"], errors="coerce")

        funding_raw = pd.to_numeric(inf.get("funding_rate", np.nan), errors="coerce")
        if isinstance(funding_raw, pd.Series):
            funding = funding_raw.reindex(inf.index)
        else:
            funding = pd.Series(np.nan, index=inf.index, dtype=float)
            try:
                funding_val = float(funding_raw)
                if np.isfinite(funding_val):
                    funding[:] = funding_val
            except Exception:
                pass
        if funding.isna().all():
            try:
                fr_df = self.dp.get_pair_dataframe(pair=pair, timeframe=tf, candle_type="funding_rate")
            except Exception:
                fr_df = None
            if fr_df is not None and (not fr_df.empty):
                fr = fr_df.copy()
                fr["_fcarry_date"] = pd.to_datetime(fr["date"], utc=True, errors="coerce")
                fr_raw = pd.to_numeric(fr.get("open", np.nan), errors="coerce")
                if isinstance(fr_raw, pd.Series):
                    fr_series = fr_raw
                else:
                    fr_series = pd.Series(np.nan, index=fr.index, dtype=float)
                if fr_series.notna().sum() == 0:
                    fr_close = pd.to_numeric(fr.get("close", np.nan), errors="coerce")
                    if isinstance(fr_close, pd.Series):
                        fr_series = fr_close
                fr["__funding"] = fr_series
                left = inf.copy()
                left["_fcarry_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
                right = fr[["_fcarry_date", "__funding"]].sort_values("_fcarry_date")
                left = left.sort_values("_fcarry_date")
                left = pd.merge_asof(left, right, on="_fcarry_date", direction="backward").sort_index()
                funding = pd.to_numeric(left["__funding"], errors="coerce").reindex(inf.index)

        if not isinstance(funding, pd.Series):
            funding = pd.Series(np.nan, index=inf.index, dtype=float)

        funding_ok = (funding <= float(self.buy_fcarry_funding_neg_max.value)).fillna(False)
        trend_ok = (
            (close > ema_fast).fillna(False)
            & (ema_fast > ema_slow).fillna(False)
            & (adx >= float(self.buy_fcarry_adx_min.value)).fillna(False)
            & (relvol >= float(self.buy_fcarry_relvol_min.value)).fillna(False)
            & (close >= open_).fillna(False)
        )

        signal = funding_ok & trend_ok
        if bool(self.buy_fcarry_require_relaxed_regime.value) and ("composite_regime" in inf.columns):
            regime = inf["composite_regime"].astype(str).str.upper()
            signal &= ~regime.str.contains("CHOP_MR|PANIC", na=False)
        missing_proxy = funding.isna()

        inf["fcarry_missing_proxy"] = missing_proxy.astype(bool)
        inf["fcarry_funding_ok"] = funding_ok.astype(bool)
        inf["fcarry_trend_ok"] = trend_ok.astype(bool)
        inf["fcarry_signal_long"] = signal.fillna(False).astype(bool)

        inf_cols = inf[["date", "fcarry_missing_proxy", "fcarry_funding_ok", "fcarry_trend_ok", "fcarry_signal_long"]].copy()
        if tf == self.timeframe:
            for c in ("fcarry_missing_proxy", "fcarry_funding_ok", "fcarry_trend_ok", "fcarry_signal_long"):
                dataframe[f"{c}{suf}"] = inf_cols[c].values
            return _ensure(dataframe)

        right = inf_cols.rename(
            columns={
                "fcarry_missing_proxy": f"fcarry_missing_proxy{suf}",
                "fcarry_funding_ok": f"fcarry_funding_ok{suf}",
                "fcarry_trend_ok": f"fcarry_trend_ok{suf}",
                "fcarry_signal_long": f"fcarry_signal_long{suf}",
            }
        ).copy()
        left = dataframe.copy()
        left["_fcarry_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
        right["_fcarry_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
        right = right.drop(columns=["date"]).sort_values("_fcarry_date")
        left = left.sort_values("_fcarry_date")
        out = pd.merge_asof(left, right, on="_fcarry_date", direction="backward").sort_index()
        out.drop(columns=["_fcarry_date"], inplace=True, errors="ignore")
        return _ensure(out)

    def _cvw_add_indicators(self, dataframe: pd.DataFrame) -> pd.DataFrame:
        self._cvw_init_state()
        close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        open_ = pd.to_numeric(dataframe.get("open"), errors="coerce")
        high = pd.to_numeric(dataframe.get("high"), errors="coerce")
        low = pd.to_numeric(dataframe.get("low"), errors="coerce")
        volume = pd.to_numeric(dataframe.get("volume"), errors="coerce")
        tiny = 1e-9

        atr_len = max(5, int(self.buy_cvw_atr_len.value))
        vwap_len = max(5, int(self.buy_cvw_vwap_len.value))
        rv_len = max(5, int(self.buy_cvw_relvol_len.value))

        atr = ta.ATR(dataframe, timeperiod=atr_len)
        typical = (high + low + close) / 3.0
        pv = typical * volume
        vwap = pv.rolling(vwap_len, min_periods=max(3, vwap_len // 3)).sum() / volume.rolling(
            vwap_len, min_periods=max(3, vwap_len // 3)
        ).sum().replace(0, np.nan)
        relvol = volume / volume.rolling(rv_len, min_periods=max(3, rv_len // 3)).mean().replace(0, np.nan)

        candle_range = (high - low).replace(0, np.nan)
        close_pos = (close - low) / candle_range
        close_pos = close_pos.replace([np.inf, -np.inf], np.nan).fillna(0.5)
        disloc = (vwap - close) / pd.to_numeric(atr, errors="coerce").replace(0, np.nan)

        signal = (disloc >= float(self.buy_cvw_disloc_atr.value)).fillna(False)
        signal &= (close_pos >= float(self.buy_cvw_reclaim_frac.value)).fillna(False)
        signal &= (close >= open_).fillna(False)
        signal &= (relvol >= float(self.buy_cvw_relvol_min.value)).fillna(False)
        if bool(self.buy_cvw_require_chop.value):
            regime = dataframe.get("composite_regime")
            if regime is not None:
                signal &= regime.astype(str).str.upper().str.contains("CHOP_MR", na=False)

        dataframe["cvw_raw_shape"] = (disloc >= float(self.buy_cvw_disloc_atr.value)).fillna(False)
        dataframe["cvw_signal_long"] = signal.fillna(False)
        return dataframe

    def _mofi_core_demand(
        self,
        pair: str,
        current_time: datetime | None,
        row: pd.Series | dict | None = None,
    ) -> bool:
        core_open = bool(self.buy_mofi_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_mofi_block_if_core_signal.value):
            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    @staticmethod
    def _mofi_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _mofi_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._mofi_init_state()
        dkey = self._mofi_daily_bucket(current_time)
        if dkey not in self._mofi_daily_state:
            self._mofi_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _mofi_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._mofi_daily_reset_if_needed(current_time)
        dkey = self._mofi_daily_bucket(current_time)
        st = self._mofi_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_mofi_daily_max_entries.value)
        max_l = int(self.buy_mofi_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "mofi_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "mofi_daily_losses_cap"
        return True, "mofi_daily_ok"

    def _mofi_mark_entry(self, current_time: datetime) -> None:
        self._mofi_daily_reset_if_needed(current_time)
        dkey = self._mofi_daily_bucket(current_time)
        st = self._mofi_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _mofi_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._mofi_daily_reset_if_needed(current_time)
        dkey = self._mofi_daily_bucket(current_time)
        st = self._mofi_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._mofi_last_loss_time[pair] = current_time

    def _mofi_cooldown_blocks(self, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._mofi_init_state()
        bars = int(self.buy_mofi_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "mofi_cooldown_off"
        last = self._mofi_last_loss_time.get(pair)
        if last is None:
            return False, "mofi_no_loss"
        tf_minutes = max(1, self._timeframe_to_minutes(str(self.buy_mofi_tf.value or "5m")))
        need = timedelta(minutes=float(bars * tf_minutes))
        if (current_time - last) < need:
            return True, "mofi_cooldown_active"
        return False, "mofi_cooldown_clear"

    def _mofi_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._mofi_init_state()
        tf = str(self.buy_mofi_tf.value or "5m")
        suf = f"_{tf}"
        defaults_bool = (
            f"mofi_raw_shape{suf}",
            f"mofi_setup_prev{suf}",
            f"mofi_shock_ok{suf}",
            f"mofi_shock_prev{suf}",
            f"mofi_flow_ok{suf}",
            f"mofi_flow_prev{suf}",
            f"mofi_spread_ok{suf}",
            f"mofi_spread_prev{suf}",
            f"mofi_adverse_ok{suf}",
            f"mofi_adverse_prev{suf}",
            f"mofi_reclaim_ok{suf}",
            f"mofi_proxy_missing{suf}",
            f"mofi_proxy_missing_prev{suf}",
            f"mofi_signal_long{suf}",
            f"mofi_taker_ok{suf}",
            f"mofi_ofi_ok{suf}",
            f"mofi_flow_relief{suf}",
            f"mofi_spread_reclaim{suf}",
        )

        def _ensure_defaults(df: pd.DataFrame) -> pd.DataFrame:
            for col in defaults_bool:
                if col in df.columns:
                    df[col] = df[col].fillna(False).astype(bool)
                else:
                    df[col] = False
            return df

        if not bool(self.buy_mofi_enabled.value):
            return _ensure_defaults(dataframe)
        if not self._mofi_pair_allowed(pair):
            return _ensure_defaults(dataframe)
        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            inf = None
        if inf is None or inf.empty:
            return _ensure_defaults(dataframe)

        dataframe = dataframe.drop(columns=[*defaults_bool], errors="ignore")

        inf = inf.copy()
        close = pd.to_numeric(inf.get("close"), errors="coerce")
        open_ = pd.to_numeric(inf.get("open"), errors="coerce")
        high = pd.to_numeric(inf.get("high"), errors="coerce")
        low = pd.to_numeric(inf.get("low"), errors="coerce")
        volume = pd.to_numeric(inf.get("volume"), errors="coerce")

        atr_len = max(5, int(self.buy_mofi_atr_len.value))
        lb = max(2, int(self.buy_mofi_ofi_lookback.value))
        rv_len = max(3, int(self.buy_mofi_relvol_len.value))
        ema_fast = max(2, int(self.buy_mofi_ema_fast.value))

        inf["mofi_atr"] = ta.ATR(inf, timeperiod=atr_len)
        inf["mofi_ema_fast"] = ta.EMA(inf, timeperiod=ema_fast)
        vol_ma = volume.rolling(rv_len, min_periods=max(2, rv_len // 3)).mean()
        relvol = volume / vol_ma.replace(0, np.nan)

        bar_range = (high - low).clip(lower=0.0)
        close_pos = (close - low) / bar_range.replace(0, np.nan)
        spread_proxy = bar_range / close.replace(0, np.nan)
        signed_imb = ((close - open_) / bar_range.replace(0, np.nan)).clip(lower=-1.0, upper=1.0)
        flow = signed_imb.fillna(0.0) * volume.fillna(0.0)
        flow_sum = flow.rolling(lb, min_periods=max(2, lb // 2)).sum()
        vol_sum = volume.rolling(lb, min_periods=max(2, lb // 2)).sum().replace(0, np.nan)
        ofi_proxy = flow_sum / vol_sum

        ofi_ok = (ofi_proxy <= -float(self.buy_mofi_ofi_sell_min.value)).fillna(False)
        ofi_present = ofi_proxy.notna()

        tb = pd.to_numeric(
            inf.get("taker_buy_vol_5m", inf.get("taker_buy_vol", inf.get("taker_buy_base", np.nan))),
            errors="coerce",
        )
        ts = pd.to_numeric(
            inf.get("taker_sell_vol_5m", inf.get("taker_sell_vol", inf.get("taker_sell_base", np.nan))),
            errors="coerce",
        )
        if not isinstance(tb, pd.Series):
            tb = pd.Series(tb, index=inf.index, dtype=float)
        else:
            tb = tb.reindex(inf.index)
        if not isinstance(ts, pd.Series):
            ts = pd.Series(ts, index=inf.index, dtype=float)
        else:
            ts = ts.reindex(inf.index)
        taker_sum = (tb.fillna(0.0) + ts.fillna(0.0))
        taker_ratio = ts / taker_sum.replace(0, np.nan)
        taker_ok = (taker_ratio >= float(self.buy_mofi_taker_sell_ratio_min.value)).fillna(False)
        taker_present = taker_ratio.notna()

        ofi_relief = (ofi_proxy - ofi_proxy.shift(1) >= float(self.buy_mofi_v2_min_ofi_relief.value)).fillna(False)
        taker_relief = (taker_ratio.shift(1) - taker_ratio >= float(self.buy_mofi_v2_min_taker_relief.value)).fillna(False)
        flow_relief = ofi_relief.copy()
        if bool(self.buy_mofi_v2_require_taker_relief.value):
            flow_relief &= taker_relief
        else:
            flow_relief |= taker_relief

        flow_ok = ofi_ok.copy()
        flow_present = ofi_present.copy()
        if bool(self.buy_mofi_use_taker_imbalance.value):
            flow_ok = flow_ok | taker_ok
            flow_present = flow_present | taker_present
        proxy_missing = ~flow_present
        if not bool(self.buy_mofi_require_flow_proxy.value):
            flow_ok = flow_ok | proxy_missing

        red = (close < open_).fillna(False)
        shock_ok = (
            red
            & (bar_range >= float(self.buy_mofi_range_shock_atr_mult.value) * inf["mofi_atr"])
            & (relvol >= float(self.buy_mofi_relvol_min.value))
        ).fillna(False)
        spread_ok = (spread_proxy >= float(self.buy_mofi_spread_proxy_min.value)).fillna(False)
        adverse_ok = (close_pos <= float(self.buy_mofi_adverse_close_pos_max.value)).fillna(False)
        reclaim_ok = (
            (close_pos >= float(self.buy_mofi_reclaim_close_pos_min.value))
            & (close > open_).fillna(False)
            & (close > inf["mofi_ema_fast"]).fillna(False)
        ).fillna(False)
        spread_reclaim_ok = (
            spread_proxy <= float(self.buy_mofi_v2_max_reclaim_spread_proxy.value)
        ).fillna(False)
        if not bool(self.buy_mofi_v2_require_spread_compress.value):
            spread_reclaim_ok = pd.Series(True, index=inf.index, dtype=bool)

        raw_shape = (shock_ok & flow_ok & spread_ok & adverse_ok).fillna(False)
        setup_prev = raw_shape.shift(1).fillna(False)
        shock_prev = shock_ok.shift(1).fillna(False)
        flow_prev = flow_ok.shift(1).fillna(False)
        spread_prev = spread_ok.shift(1).fillna(False)
        adverse_prev = adverse_ok.shift(1).fillna(False)
        proxy_missing_prev = proxy_missing.shift(1).fillna(False)
        signal_long = (setup_prev & reclaim_ok).fillna(False)
        if bool(self.buy_mofi_v2_enabled.value):
            signal_long &= flow_relief.fillna(False)
            signal_long &= spread_reclaim_ok.fillna(False)

        inf["mofi_raw_shape"] = raw_shape.astype(bool)
        inf["mofi_setup_prev"] = setup_prev.astype(bool)
        inf["mofi_shock_ok"] = shock_ok.astype(bool)
        inf["mofi_shock_prev"] = shock_prev.astype(bool)
        inf["mofi_flow_ok"] = flow_ok.astype(bool)
        inf["mofi_flow_prev"] = flow_prev.astype(bool)
        inf["mofi_spread_ok"] = spread_ok.astype(bool)
        inf["mofi_spread_prev"] = spread_prev.astype(bool)
        inf["mofi_adverse_ok"] = adverse_ok.astype(bool)
        inf["mofi_adverse_prev"] = adverse_prev.astype(bool)
        inf["mofi_reclaim_ok"] = reclaim_ok.astype(bool)
        inf["mofi_proxy_missing"] = proxy_missing.astype(bool)
        inf["mofi_proxy_missing_prev"] = proxy_missing_prev.astype(bool)
        inf["mofi_signal_long"] = signal_long.astype(bool)
        inf["mofi_taker_ok"] = taker_ok.astype(bool)
        inf["mofi_ofi_ok"] = ofi_ok.astype(bool)
        inf["mofi_flow_relief"] = flow_relief.astype(bool)
        inf["mofi_spread_reclaim"] = spread_reclaim_ok.astype(bool)

        inf_cols = inf[
            [
                "date",
                "mofi_raw_shape",
                "mofi_setup_prev",
                "mofi_shock_ok",
                "mofi_shock_prev",
                "mofi_flow_ok",
                "mofi_flow_prev",
                "mofi_spread_ok",
                "mofi_spread_prev",
                "mofi_adverse_ok",
                "mofi_adverse_prev",
                "mofi_reclaim_ok",
                "mofi_proxy_missing",
                "mofi_proxy_missing_prev",
                "mofi_signal_long",
                "mofi_taker_ok",
                "mofi_ofi_ok",
                "mofi_flow_relief",
                "mofi_spread_reclaim",
            ]
        ].copy()
        if tf == self.timeframe:
            for c in (
                "mofi_raw_shape",
                "mofi_setup_prev",
                "mofi_shock_ok",
                "mofi_shock_prev",
                "mofi_flow_ok",
                "mofi_flow_prev",
                "mofi_spread_ok",
                "mofi_spread_prev",
                "mofi_adverse_ok",
                "mofi_adverse_prev",
                "mofi_reclaim_ok",
                "mofi_proxy_missing",
                "mofi_proxy_missing_prev",
                "mofi_signal_long",
                "mofi_taker_ok",
                "mofi_ofi_ok",
                "mofi_flow_relief",
                "mofi_spread_reclaim",
            ):
                dataframe[f"{c}{suf}"] = inf_cols[c].values
        else:
            right = inf_cols.rename(
                columns={
                    "mofi_raw_shape": f"mofi_raw_shape{suf}",
                    "mofi_setup_prev": f"mofi_setup_prev{suf}",
                    "mofi_shock_ok": f"mofi_shock_ok{suf}",
                    "mofi_shock_prev": f"mofi_shock_prev{suf}",
                    "mofi_flow_ok": f"mofi_flow_ok{suf}",
                    "mofi_flow_prev": f"mofi_flow_prev{suf}",
                    "mofi_spread_ok": f"mofi_spread_ok{suf}",
                    "mofi_spread_prev": f"mofi_spread_prev{suf}",
                    "mofi_adverse_ok": f"mofi_adverse_ok{suf}",
                    "mofi_adverse_prev": f"mofi_adverse_prev{suf}",
                    "mofi_reclaim_ok": f"mofi_reclaim_ok{suf}",
                    "mofi_proxy_missing": f"mofi_proxy_missing{suf}",
                    "mofi_proxy_missing_prev": f"mofi_proxy_missing_prev{suf}",
                    "mofi_signal_long": f"mofi_signal_long{suf}",
                    "mofi_taker_ok": f"mofi_taker_ok{suf}",
                    "mofi_ofi_ok": f"mofi_ofi_ok{suf}",
                    "mofi_flow_relief": f"mofi_flow_relief{suf}",
                    "mofi_spread_reclaim": f"mofi_spread_reclaim{suf}",
                }
            ).copy()
            left = dataframe.copy()
            left["_mofi_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
            right["_mofi_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
            right = right.drop(columns=["date"]).sort_values("_mofi_date")
            left = left.sort_values("_mofi_date")
            dataframe = pd.merge_asof(left, right, on="_mofi_date", direction="backward")
            dataframe = dataframe.sort_index()
            dataframe.drop(columns=["_mofi_date"], inplace=True, errors="ignore")
        return _ensure_defaults(dataframe)

    def _mofi_entry_allows(
        self,
        pair: str,
        row: pd.Series | dict,
        current_time: datetime,
    ) -> tuple[bool, str]:
        self._mofi_init_state()
        tf = str(self.buy_mofi_tf.value or "5m")
        suf = f"_{tf}"

        if not bool(self.buy_mofi_enabled.value):
            return False, "mofi_disabled"
        if not self._mofi_pair_allowed(pair):
            self._mofi_inc("block_pair")
            return False, "mofi_pair_block"
        if self._mofi_core_demand(pair, current_time, row=row):
            self._mofi_inc("block_core_demand")
            return False, "mofi_core_demand"
        day_ok, _ = self._mofi_daily_limits_allow(current_time)
        if not day_ok:
            self._mofi_inc("block_governance")
            return False, "mofi_daily_block"
        cd_block, _ = self._mofi_cooldown_blocks(pair, current_time)
        if cd_block:
            self._mofi_inc("block_governance")
            return False, "mofi_cooldown"

        if bool(self.buy_mofi_require_flow_proxy.value) and bool(row.get(f"mofi_proxy_missing_prev{suf}", False)):
            self._mofi_inc("block_missing_proxy")
            return False, "mofi_missing_proxy"
        if not bool(row.get(f"mofi_shock_prev{suf}", False)):
            self._mofi_inc("block_shock")
            return False, "mofi_no_shock"
        self._mofi_inc("raw")
        if not bool(row.get(f"mofi_flow_prev{suf}", False)):
            self._mofi_inc("block_flow")
            return False, "mofi_no_flow"
        if not bool(row.get(f"mofi_spread_prev{suf}", False)):
            self._mofi_inc("block_spread")
            return False, "mofi_no_spread"
        if not bool(row.get(f"mofi_adverse_prev{suf}", False)):
            self._mofi_inc("block_adverse")
            return False, "mofi_no_adverse"
        if not bool(row.get(f"mofi_reclaim_ok{suf}", False)):
            self._mofi_inc("block_reclaim")
            return False, "mofi_no_reclaim"
        if bool(self.buy_mofi_v2_enabled.value) and not bool(row.get(f"mofi_flow_relief{suf}", False)):
            self._mofi_inc("block_flow")
            return False, "mofi_no_flow_relief"
        if bool(self.buy_mofi_v2_enabled.value) and not bool(row.get(f"mofi_spread_reclaim{suf}", False)):
            self._mofi_inc("block_spread")
            return False, "mofi_no_spread_reclaim"
        if not bool(row.get(f"mofi_signal_long{suf}", False)):
            self._mofi_inc("block_reclaim")
            return False, "mofi_no_signal"

        self._mofi_inc("allowed")
        return True, "mofi_ok"

    def _mofi_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_mofi_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            self._mofi_init_state()
            key = self._idle_trade_key(trade)
            self._mofi_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._mofi_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def _evtpulse_init_state(self) -> None:
        if not hasattr(self, "_evtpulse_daily_state"):
            self._evtpulse_daily_state = {}
        if not hasattr(self, "_evtpulse_last_loss_time"):
            self._evtpulse_last_loss_time = {}
        if not hasattr(self, "_evtpulse_hwm"):
            self._evtpulse_hwm = {}
        if not hasattr(self, "_evtpulse_counts"):
            self._evtpulse_counts = {
                "raw": 0,
                "allowed": 0,
                "stamped": 0,
                "block_pair": 0,
                "block_governance": 0,
                "block_core_demand": 0,
                "block_signal": 0,
                "exit_tp": 0,
                "exit_time": 0,
                "exit_stop": 0,
                "exit_priority_liq": 0,
            }

    def evtpulse_counts_snapshot(self) -> dict[str, float]:
        self._evtpulse_init_state()
        return {str(k): float(v) for k, v in self._evtpulse_counts.items()}

    @staticmethod
    def _evtpulse_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _evtpulse_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._evtpulse_init_state()
        dkey = self._evtpulse_daily_bucket(current_time)
        if dkey not in self._evtpulse_daily_state:
            self._evtpulse_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _evtpulse_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._evtpulse_daily_reset_if_needed(current_time)
        dkey = self._evtpulse_daily_bucket(current_time)
        st = self._evtpulse_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_evtpulse_daily_max_entries.value)
        max_l = int(self.buy_evtpulse_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "evtpulse_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "evtpulse_daily_losses_cap"
        return True, "evtpulse_daily_ok"

    def _evtpulse_mark_entry(self, current_time: datetime) -> None:
        self._evtpulse_daily_reset_if_needed(current_time)
        dkey = self._evtpulse_daily_bucket(current_time)
        st = self._evtpulse_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _evtpulse_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._evtpulse_daily_reset_if_needed(current_time)
        dkey = self._evtpulse_daily_bucket(current_time)
        st = self._evtpulse_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._evtpulse_last_loss_time[pair] = current_time

    def _evtpulse_cooldown_blocks(self, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._evtpulse_init_state()
        bars = int(self.buy_evtpulse_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "evtpulse_cooldown_off"
        last = self._evtpulse_last_loss_time.get(pair)
        if last is None:
            return False, "evtpulse_no_loss"
        tf_minutes = max(1, self._timeframe_to_minutes(str(self.buy_evtpulse_tf.value or "5m")))
        need = timedelta(minutes=float(bars * tf_minutes))
        if (current_time - last) < need:
            return True, "evtpulse_cooldown_active"
        return False, "evtpulse_cooldown_clear"

    def _evtpulse_core_demand(self, pair: str, current_time: datetime | None, row: pd.Series | dict | None = None) -> bool:
        core_open = bool(self.buy_evtpulse_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_evtpulse_block_if_core_signal.value):
            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    def _evtpulse_add_informative(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        self._evtpulse_init_state()
        tf = str(self.buy_evtpulse_tf.value or "5m")
        suf = f"_{tf}"
        if (not bool(self.buy_evtpulse_enabled.value)) or (not self._evtpulse_pair_allowed(pair)):
            defaults_bool = (f"evtpulse_signal_long{suf}", f"evtpulse_proxy_missing{suf}")
            for c in defaults_bool:
                if c not in dataframe.columns:
                    dataframe[c] = False
            return dataframe

        try:
            inf = self.dp.get_pair_dataframe(pair=pair, timeframe=tf)
        except Exception:
            return dataframe
        if inf is None or inf.empty:
            return dataframe

        inf = inf.copy()
        inf["date"] = pd.to_datetime(inf["date"], utc=True, errors="coerce")
        inf["evtpulse_ema_fast"] = ta.EMA(inf, timeperiod=max(2, int(self.buy_evtpulse_ema_fast.value)))
        inf["evtpulse_ema_slow"] = ta.EMA(inf, timeperiod=max(3, int(self.buy_evtpulse_ema_slow.value)))
        inf["evtpulse_atr"] = ta.ATR(inf, timeperiod=max(2, int(self.buy_evtpulse_atr_len.value)))
        bb = qtpylib.bollinger_bands(inf["close"], window=20, stds=2)
        bbw = ((bb["upper"] - bb["lower"]) / bb["mid"].replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)
        relvol = pd.to_numeric(inf["volume"], errors="coerce") / pd.to_numeric(inf["volume"], errors="coerce").rolling(max(2, int(self.buy_evtpulse_relvol_len.value))).mean().replace(0, np.nan)
        rng = (pd.to_numeric(inf["high"], errors="coerce") - pd.to_numeric(inf["low"], errors="coerce")).abs()
        close_pos = (
            (pd.to_numeric(inf["close"], errors="coerce") - pd.to_numeric(inf["low"], errors="coerce"))
            / rng.replace(0, np.nan)
        ).replace([np.inf, -np.inf], np.nan)
        minute_tokens = {
            int(x.strip())
            for x in str(self.buy_evtpulse_minute_csv.value or "").split(",")
            if x.strip().isdigit()
        }
        if not minute_tokens:
            minute_tokens = {0, 30}
        minute_hit = inf["date"].dt.minute.isin(sorted(minute_tokens))
        signal_long = (
            minute_hit
            & (pd.to_numeric(inf["close"], errors="coerce") > inf["evtpulse_ema_fast"]).fillna(False)
            & (inf["evtpulse_ema_fast"] > inf["evtpulse_ema_slow"]).fillna(False)
            & (relvol >= float(self.buy_evtpulse_relvol_min.value)).fillna(False)
            & (rng >= float(self.buy_evtpulse_range_atr_mult.value) * inf["evtpulse_atr"]).fillna(False)
            & (close_pos >= float(self.buy_evtpulse_close_pos_min.value)).fillna(False)
            & (bbw.shift(1) <= float(self.buy_evtpulse_prev_bbw_max.value)).fillna(False)
        ).fillna(False)
        lookback_bars = max(1, int(round(60.0 / max(1.0, float(self._timeframe_to_minutes(tf))))))
        signal_recent = signal_long.astype(int).rolling(lookback_bars, min_periods=1).max().fillna(0).astype(bool)
        inf_cols = inf[["date"]].copy()
        inf_cols["evtpulse_signal_long"] = signal_recent.astype(bool)
        inf_cols["evtpulse_proxy_missing"] = False

        if bool(self.buy_evtpulse_debug.value):
            try:
                logger.info(
                    "EVTPULSE_INF pair=%s tf=%s raw5m=%s recent=%s minute_csv=%s",
                    pair,
                    tf,
                    int(signal_long.sum()),
                    int(signal_recent.sum()),
                    str(self.buy_evtpulse_minute_csv.value or ""),
                )
            except Exception:
                pass

        if tf == self.timeframe:
            dataframe[f"evtpulse_signal_long{suf}"] = inf_cols["evtpulse_signal_long"].values
            dataframe[f"evtpulse_proxy_missing{suf}"] = False
        else:
            # Drop placeholder columns before merge so the informative payload lands
            # on the canonical names instead of pandas creating *_x/*_y duplicates.
            dataframe = dataframe.drop(
                columns=[f"evtpulse_signal_long{suf}", f"evtpulse_proxy_missing{suf}"],
                errors="ignore",
            )
            right = inf_cols.rename(
                columns={
                    "evtpulse_signal_long": f"evtpulse_signal_long{suf}",
                    "evtpulse_proxy_missing": f"evtpulse_proxy_missing{suf}",
                }
            ).copy()
            left = dataframe.copy()
            left["_evtpulse_date"] = pd.to_datetime(left["date"], utc=True, errors="coerce")
            right["_evtpulse_date"] = pd.to_datetime(right["date"], utc=True, errors="coerce")
            right = right.drop(columns=["date"]).sort_values("_evtpulse_date")
            left = left.sort_values("_evtpulse_date")
            dataframe = pd.merge_asof(left, right, on="_evtpulse_date", direction="backward").sort_index()
            dataframe.drop(columns=["_evtpulse_date"], inplace=True, errors="ignore")
        dataframe[f"evtpulse_signal_long{suf}"] = (
            dataframe.get(f"evtpulse_signal_long{suf}", False)
            if isinstance(dataframe.get(f"evtpulse_signal_long{suf}", False), pd.Series)
            else pd.Series(False, index=dataframe.index, dtype=bool)
        )
        dataframe[f"evtpulse_signal_long{suf}"] = dataframe[f"evtpulse_signal_long{suf}"].fillna(False).astype(bool)
        dataframe[f"evtpulse_proxy_missing{suf}"] = (
            dataframe.get(f"evtpulse_proxy_missing{suf}", False)
            if isinstance(dataframe.get(f"evtpulse_proxy_missing{suf}", False), pd.Series)
            else pd.Series(False, index=dataframe.index, dtype=bool)
        )
        dataframe[f"evtpulse_proxy_missing{suf}"] = dataframe[f"evtpulse_proxy_missing{suf}"].fillna(False).astype(bool)
        return dataframe

    def _evtpulse_entry_allows(self, pair: str, row: pd.Series | dict, current_time: datetime) -> tuple[bool, str]:
        self._evtpulse_init_state()
        tf = str(self.buy_evtpulse_tf.value or "5m")
        suf = f"_{tf}"
        if not bool(self.buy_evtpulse_enabled.value):
            return False, "evtpulse_disabled"
        if not self._evtpulse_pair_allowed(pair):
            self._evtpulse_counts["block_pair"] += 1
            return False, "evtpulse_pair_block"
        if self._evtpulse_core_demand(pair, current_time, row=row):
            self._evtpulse_counts["block_core_demand"] += 1
            return False, "evtpulse_core_demand"
        day_ok, _ = self._evtpulse_daily_limits_allow(current_time)
        if not day_ok:
            self._evtpulse_counts["block_governance"] += 1
            return False, "evtpulse_daily_block"
        cd_block, _ = self._evtpulse_cooldown_blocks(pair, current_time)
        if cd_block:
            self._evtpulse_counts["block_governance"] += 1
            return False, "evtpulse_cooldown"
        self._evtpulse_counts["raw"] += 1
        if not bool(row.get(f"evtpulse_signal_long{suf}", False)):
            self._evtpulse_counts["block_signal"] += 1
            return False, "evtpulse_no_signal"
        self._evtpulse_counts["allowed"] += 1
        return True, "evtpulse_ok"

    def _evtpulse_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_evtpulse_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            key = self._idle_trade_key(trade)
            self._evtpulse_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._evtpulse_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def _lagcatch_init_state(self) -> None:
        if not hasattr(self, "_lagcatch_daily_state"):
            self._lagcatch_daily_state = {}
        if not hasattr(self, "_lagcatch_last_loss_time"):
            self._lagcatch_last_loss_time = {}
        if not hasattr(self, "_lagcatch_hwm"):
            self._lagcatch_hwm = {}
        if not hasattr(self, "_lagcatch_counts"):
            self._lagcatch_counts = {
                "raw": 0,
                "allowed": 0,
                "stamped": 0,
                "block_pair": 0,
                "block_governance": 0,
                "block_core_demand": 0,
                "block_signal": 0,
                "exit_tp": 0,
                "exit_time": 0,
                "exit_stop": 0,
                "exit_priority_liq": 0,
            }

    def lagcatch_counts_snapshot(self) -> dict[str, float]:
        self._lagcatch_init_state()
        return {str(k): float(v) for k, v in self._lagcatch_counts.items()}

    @staticmethod
    def _lagcatch_daily_bucket(current_time: datetime) -> str:
        return current_time.strftime("%Y-%m-%d")

    def _lagcatch_daily_reset_if_needed(self, current_time: datetime) -> None:
        self._lagcatch_init_state()
        dkey = self._lagcatch_daily_bucket(current_time)
        if dkey not in self._lagcatch_daily_state:
            self._lagcatch_daily_state = {dkey: {"entries": 0, "losses": 0}}

    def _lagcatch_daily_limits_allow(self, current_time: datetime) -> tuple[bool, str]:
        self._lagcatch_daily_reset_if_needed(current_time)
        dkey = self._lagcatch_daily_bucket(current_time)
        st = self._lagcatch_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_lagcatch_daily_max_entries.value)
        max_l = int(self.buy_lagcatch_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "lagcatch_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "lagcatch_daily_losses_cap"
        return True, "lagcatch_daily_ok"

    def _lagcatch_mark_entry(self, current_time: datetime) -> None:
        self._lagcatch_daily_reset_if_needed(current_time)
        dkey = self._lagcatch_daily_bucket(current_time)
        st = self._lagcatch_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _lagcatch_mark_loss(self, pair: str, current_time: datetime) -> None:
        self._lagcatch_daily_reset_if_needed(current_time)
        dkey = self._lagcatch_daily_bucket(current_time)
        st = self._lagcatch_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._lagcatch_last_loss_time[pair] = current_time

    def _lagcatch_core_demand(self, pair: str, current_time: datetime | None, row: pd.Series | dict | None = None) -> bool:
        core_open = bool(self.buy_lagcatch_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_lagcatch_block_if_core_signal.value):
            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    def _lagcatch_entry_allows(self, pair: str, row: pd.Series | dict, current_time: datetime) -> tuple[bool, str]:
        self._lagcatch_init_state()
        if not bool(self.buy_lagcatch_enabled.value):
            return False, "lagcatch_disabled"
        if not self._lagcatch_pair_allowed(pair):
            self._lagcatch_counts["block_pair"] += 1
            return False, "lagcatch_pair_block"
        if self._lagcatch_core_demand(pair, current_time, row=row):
            self._lagcatch_counts["block_core_demand"] += 1
            return False, "lagcatch_core_demand"
        day_ok, _ = self._lagcatch_daily_limits_allow(current_time)
        if not day_ok:
            self._lagcatch_counts["block_governance"] += 1
            return False, "lagcatch_daily_block"
        self._lagcatch_counts["raw"] += 1
        if not bool(row.get("lagcatch_signal_long", False)):
            self._lagcatch_counts["block_signal"] += 1
            return False, "lagcatch_no_signal"
        self._lagcatch_counts["allowed"] += 1
        return True, "lagcatch_ok"

    def _lagcatch_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            if not self._is_lagcatch_entry_tag(getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)):
                return
            key = self._idle_trade_key(trade)
            self._lagcatch_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._lagcatch_mark_loss(trade.pair, current_time)
        except Exception:
            pass

    def _nalpha_init_state(self) -> None:
        if not hasattr(self, "_nalpha_daily_state"):
            self._nalpha_daily_state = {}
        if not hasattr(self, "_nalpha_last_loss_time"):
            self._nalpha_last_loss_time = {}
        if not hasattr(self, "_nalpha_hwm"):
            self._nalpha_hwm = {}
        if not hasattr(self, "_nalpha_counts"):
            self._nalpha_counts = {
                "raw": 0,
                "allowed": 0,
                "stamped": 0,
                "block_pair": 0,
                "block_governance": 0,
                "block_core_demand": 0,
                "block_signal": 0,
                "exit_tp": 0,
                "exit_time": 0,
                "exit_stop": 0,
                "exit_priority_liq": 0,
            }

    def _nalpha_family_from_tag(self, entry_tag: str | None) -> str:
        t = str(entry_tag or "").lower()
        if t.startswith("xresmom_"):
            return "xresmom"
        if t.startswith("xidiorev_"):
            return "xidiorev"
        if t.startswith("xmacrohour_"):
            return "xmacrohour"
        if t.startswith("xleadrot_"):
            return "xleadrot"
        if t.startswith("xquietbreak_"):
            return "xquietbreak"
        return "other"

    def _nalpha_signal_col(self, family: str) -> str:
        return f"{family}_signal_long"

    def _nalpha_tag(self, family: str) -> str:
        return f"{family}_long"

    def _nalpha_pair_allowed(self, family: str, pair: str) -> bool:
        pair_u = str(pair or "").upper()
        if family == "xresmom":
            if pair_u.startswith("BTC/"):
                return False
            return self._pair_in_allowlist(pair, str(self.buy_xresmom_allow_pairs.value or ""))
        if family == "xidiorev":
            if pair_u.startswith("BTC/"):
                return False
            return self._pair_in_allowlist(pair, str(self.buy_xidiorev_allow_pairs.value or ""))
        if family == "xmacrohour":
            return self._pair_in_allowlist(pair, str(self.buy_xmacrohour_allow_pairs.value or ""))
        if family == "xleadrot":
            if pair_u.startswith("BTC/") or pair_u.startswith("ETH/"):
                return False
            return self._pair_in_allowlist(pair, str(self.buy_xleadrot_allow_pairs.value or ""))
        if family == "xquietbreak":
            if pair_u.startswith("BTC/"):
                return False
            return self._pair_in_allowlist(pair, str(self.buy_xquietbreak_allow_pairs.value or ""))
        return False

    @staticmethod
    def _nalpha_daily_bucket(family: str, current_time: datetime) -> str:
        return f"{family}|{current_time.strftime('%Y-%m-%d')}"

    def _nalpha_daily_reset_if_needed(self, family: str, current_time: datetime) -> None:
        self._nalpha_init_state()
        dkey = self._nalpha_daily_bucket(family, current_time)
        if dkey not in self._nalpha_daily_state:
            self._nalpha_daily_state[dkey] = {"entries": 0, "losses": 0}

    def _nalpha_daily_limits_allow(self, family: str, current_time: datetime) -> tuple[bool, str]:
        self._nalpha_daily_reset_if_needed(family, current_time)
        dkey = self._nalpha_daily_bucket(family, current_time)
        st = self._nalpha_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        max_e = int(self.buy_nalpha_daily_max_entries.value)
        max_l = int(self.buy_nalpha_daily_max_losses.value)
        if max_e > 0 and int(st.get("entries", 0)) >= max_e:
            return False, "nalpha_daily_entries_cap"
        if max_l > 0 and int(st.get("losses", 0)) >= max_l:
            return False, "nalpha_daily_losses_cap"
        return True, "nalpha_daily_ok"

    def _nalpha_mark_entry(self, family: str, current_time: datetime) -> None:
        self._nalpha_daily_reset_if_needed(family, current_time)
        dkey = self._nalpha_daily_bucket(family, current_time)
        st = self._nalpha_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["entries"] = int(st.get("entries", 0)) + 1

    def _nalpha_mark_loss(self, family: str, pair: str, current_time: datetime) -> None:
        self._nalpha_daily_reset_if_needed(family, current_time)
        dkey = self._nalpha_daily_bucket(family, current_time)
        st = self._nalpha_daily_state.setdefault(dkey, {"entries": 0, "losses": 0})
        st["losses"] = int(st.get("losses", 0)) + 1
        self._nalpha_last_loss_time[f"{family}|{pair}"] = current_time

    def _nalpha_cooldown_blocks(self, family: str, pair: str, current_time: datetime) -> tuple[bool, str]:
        self._nalpha_init_state()
        bars = int(self.buy_nalpha_cooldown_after_loss_bars.value)
        if bars <= 0:
            return False, "nalpha_cooldown_off"
        last = self._nalpha_last_loss_time.get(f"{family}|{pair}")
        if last is None:
            return False, "nalpha_no_loss"
        need = timedelta(minutes=float(max(1, self._timeframe_to_minutes(self.timeframe)) * bars))
        if (current_time - last) < need:
            return True, "nalpha_cooldown_active"
        return False, "nalpha_cooldown_clear"

    def _nalpha_core_demand(self, pair: str, current_time: datetime | None, row: pd.Series | dict | None = None) -> bool:
        core_open = bool(self.buy_nalpha_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_nalpha_block_if_core_signal.value):
            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

    def _nalpha_available_cap(self) -> float:
        wallet_total = self._idle_wallet_total()
        open_exposure = 0.0
        for tr in (self._safe_get_open_trades() or []):
            tag = getattr(tr, "enter_tag", None) or getattr(tr, "entry_tag", None)
            if self._is_nalpha_entry_tag(tag):
                open_exposure += float(getattr(tr, "stake_amount", 0.0) or 0.0)
        sleeve_cap = max(0.0, wallet_total * float(self.buy_nalpha_cap_pct.value) - open_exposure)
        return max(0.0, sleeve_cap)

    def _novel_alpha_add_context(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        if not self._novel_alpha_any_enabled():
            return dataframe

        base_close = pd.to_numeric(dataframe.get("close"), errors="coerce")
        base_high = pd.to_numeric(dataframe.get("high"), errors="coerce")
        base_low = pd.to_numeric(dataframe.get("low"), errors="coerce")
        base_vol = pd.to_numeric(dataframe.get("volume"), errors="coerce")
        base_range = (base_high - base_low).replace(0.0, np.nan)
        base_atr = ta.ATR(dataframe, timeperiod=14)
        dataframe["nalpha_ema_fast"] = ta.EMA(dataframe, timeperiod=12)
        dataframe["nalpha_ema_slow"] = ta.EMA(dataframe, timeperiod=36)
        dataframe["nalpha_relvol"] = base_vol / base_vol.rolling(20, min_periods=5).mean().replace(0.0, np.nan)
        dataframe["nalpha_atr"] = base_atr
        dataframe["nalpha_close_pos"] = ((base_close - base_low) / base_range).replace([np.inf, -np.inf], np.nan)
        dataframe["nalpha_hour_utc"] = pd.to_datetime(dataframe["date"], utc=True, errors="coerce").dt.hour.fillna(0).astype(int)
        dataframe["nalpha_pair_ret_6"] = base_close.pct_change(6)
        dataframe["nalpha_pair_ret_12"] = base_close.pct_change(12)
        dataframe["nalpha_pair_ret_24"] = base_close.pct_change(24)
        dataframe["nalpha_pair_breakout_6"] = (base_close > base_high.rolling(6).max().shift(1)).fillna(False)
        dataframe["nalpha_pair_breakout_12"] = (base_close > base_high.rolling(12).max().shift(1)).fillna(False)
        dataframe["nalpha_pair_breakout_24"] = (base_close > base_high.rolling(24).max().shift(1)).fillna(False)
        dataframe["nalpha_chase_atr"] = ((base_close - pd.to_numeric(dataframe["nalpha_ema_fast"], errors="coerce")).abs() / base_atr.replace(0.0, np.nan)).replace([np.inf, -np.inf], np.nan)
        dataframe["nalpha_range_atr"] = (base_range / base_atr.replace(0.0, np.nan)).replace([np.inf, -np.inf], np.nan)

        base_dates = pd.to_datetime(dataframe["date"], utc=True, errors="coerce")

        def _map_ref(pair_name: str, tf: str, ret_bars: int, atr_pct: bool = False) -> pd.Series:
            try:
                inf = self.dp.get_pair_dataframe(pair=pair_name, timeframe=tf)
            except Exception:
                inf = None
            if inf is None or inf.empty:
                return pd.Series(np.nan, index=dataframe.index, dtype=float)
            inf = inf.copy()
            inf_dates = pd.to_datetime(inf["date"], utc=True, errors="coerce")
            inf_close = pd.to_numeric(inf.get("close"), errors="coerce")
            if atr_pct:
                values = ta.ATR(inf, timeperiod=14) / inf_close.replace(0.0, np.nan)
            else:
                values = inf_close.pct_change(ret_bars)
            ref_series = pd.Series(pd.to_numeric(values, errors="coerce").to_numpy(), index=inf_dates).sort_index()
            return pd.to_numeric(base_dates.map(ref_series), errors="coerce").ffill()

        nalpha_btc_pair = self._resolve_ref_pair("BTC") or "BTC/USDT:USDT"
        nalpha_eth_pair = self._resolve_ref_pair("ETH") or "ETH/USDT:USDT"
        dataframe["nalpha_btc_ret_6"] = _map_ref(nalpha_btc_pair, self.timeframe, 6)
        dataframe["nalpha_btc_ret_12"] = _map_ref(nalpha_btc_pair, self.timeframe, 12)
        dataframe["nalpha_btc_ret_24"] = _map_ref(nalpha_btc_pair, self.timeframe, 24)
        dataframe["nalpha_eth_ret_6"] = _map_ref(nalpha_eth_pair, self.timeframe, 6)
        dataframe["nalpha_eth_ret_12"] = _map_ref(nalpha_eth_pair, self.timeframe, 12)
        dataframe["nalpha_btc_ret_4h"] = _map_ref(nalpha_btc_pair, "4h", 1)
        dataframe["nalpha_btc_atr_pct_4h"] = _map_ref(nalpha_btc_pair, "4h", 1, atr_pct=True)

        dataframe["nalpha_excess_btc_6"] = dataframe["nalpha_pair_ret_6"] - dataframe["nalpha_btc_ret_6"]
        dataframe["nalpha_excess_btc_12"] = dataframe["nalpha_pair_ret_12"] - dataframe["nalpha_btc_ret_12"]
        ex12 = pd.to_numeric(dataframe["nalpha_excess_btc_12"], errors="coerce")
        ex12_mu = ex12.rolling(72, min_periods=24).mean()
        ex12_sd = ex12.rolling(72, min_periods=24).std()
        dataframe["nalpha_excess_btc_12_z"] = ((ex12 - ex12_mu) / ex12_sd.replace(0.0, np.nan)).replace([np.inf, -np.inf], np.nan)
        dataframe["nalpha_eth_lead_12"] = dataframe["nalpha_eth_ret_12"] - dataframe["nalpha_btc_ret_12"]

        xresmom_ret_lb = max(2, int(self.buy_xresmom_lookback.value))
        xresmom_pair_ret = base_close.pct_change(xresmom_ret_lb)
        xresmom_btc_ret = _map_ref(nalpha_btc_pair, self.timeframe, xresmom_ret_lb)
        xresmom_excess = xresmom_pair_ret - xresmom_btc_ret

        xidio_ret_lb = max(2, int(self.buy_xidiorev_lookback.value))
        xidio_pair_ret = base_close.pct_change(xidio_ret_lb)
        xidio_btc_ret = _map_ref(nalpha_btc_pair, self.timeframe, xidio_ret_lb)
        xidio_excess = xidio_pair_ret - xidio_btc_ret
        xidio_mu = xidio_excess.rolling(72, min_periods=24).mean()
        xidio_sd = xidio_excess.rolling(72, min_periods=24).std()
        xidio_z = ((xidio_excess - xidio_mu) / xidio_sd.replace(0.0, np.nan)).replace([np.inf, -np.inf], np.nan)

        xlead_ret_lb = max(2, int(self.buy_xleadrot_lookback.value))
        xlead_pair_ret = base_close.pct_change(xlead_ret_lb)
        xlead_btc_ret = _map_ref(nalpha_btc_pair, self.timeframe, xlead_ret_lb)
        xlead_eth_ret = _map_ref(nalpha_eth_pair, self.timeframe, xlead_ret_lb)
        xlead_eth_lead = xlead_eth_ret - xlead_btc_ret

        trend_ok = (
            (base_close > pd.to_numeric(dataframe["nalpha_ema_fast"], errors="coerce"))
            & (pd.to_numeric(dataframe["nalpha_ema_fast"], errors="coerce") > pd.to_numeric(dataframe["nalpha_ema_slow"], errors="coerce"))
        ).fillna(False)
        btc_stable = (
            pd.to_numeric(dataframe["nalpha_btc_atr_pct_4h"], errors="coerce").fillna(np.inf) <= float(self.buy_xquietbreak_btc_atr_pct_max.value)
        ) & (
            pd.to_numeric(dataframe["nalpha_btc_ret_4h"], errors="coerce").abs().fillna(np.inf) <= float(self.buy_xquietbreak_btc_ret_abs_max.value)
        )

        xresmom_lb = max(2, int(self.buy_xresmom_breakout_lookback.value))
        dataframe["xresmom_signal_long"] = (
            trend_ok
            & (pd.to_numeric(xresmom_excess, errors="coerce") >= float(self.buy_xresmom_excess_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_relvol"], errors="coerce") >= float(self.buy_xresmom_relvol_min.value)).fillna(False)
            & (base_close > base_high.rolling(xresmom_lb).max().shift(1)).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_chase_atr"], errors="coerce") <= float(self.buy_xresmom_max_chase_atr.value)).fillna(False)
        ).fillna(False)

        xidio_lb = max(2, int(self.buy_xidiorev_lookback.value))
        idio_reclaim = (
            (pd.to_numeric(dataframe["nalpha_close_pos"], errors="coerce") >= float(self.buy_xidiorev_reclaim_frac.value)).fillna(False)
            & (base_close > pd.to_numeric(dataframe["nalpha_ema_fast"], errors="coerce")).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_relvol"], errors="coerce") >= float(self.buy_xidiorev_relvol_min.value)).fillna(False)
            & (base_low <= base_low.rolling(xidio_lb).min().shift(1)).fillna(False)
        )
        if bool(self.buy_xidiorev_require_btc_stable.value):
            idio_reclaim &= btc_stable.fillna(False)
        dataframe["xidiorev_signal_long"] = (
            (pd.to_numeric(xidio_z, errors="coerce") <= -float(self.buy_xidiorev_z_min.value)).fillna(False)
            & idio_reclaim
        ).fillna(False)

        macro_hours = {
            int(x.strip())
            for x in str(self.buy_xmacrohour_hours_csv.value or "").split(",")
            if x.strip()
        }
        xmacrohour_signal = (
            trend_ok
            & dataframe["nalpha_hour_utc"].isin(macro_hours)
            & (pd.to_numeric(dataframe["nalpha_relvol"], errors="coerce") >= float(self.buy_xmacrohour_relvol_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_range_atr"], errors="coerce") >= float(self.buy_xmacrohour_range_atr_mult.value)).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_close_pos"], errors="coerce") >= float(self.buy_xmacrohour_close_pos_min.value)).fillna(False)
            & (base_close > base_high.shift(1)).fillna(False)
        ).fillna(False)
        if bool(self.buy_xmacrohour_require_btc_stable.value):
            xmacrohour_signal &= btc_stable.fillna(False)
        dataframe["xmacrohour_signal_long"] = xmacrohour_signal.fillna(False)

        xlead_lb = max(2, int(self.buy_xleadrot_breakout_lookback.value))
        dataframe["xleadrot_signal_long"] = (
            trend_ok
            & (pd.to_numeric(xlead_eth_lead, errors="coerce") >= float(self.buy_xleadrot_eth_lead_min.value)).fillna(False)
            & ((pd.to_numeric(xlead_eth_ret, errors="coerce") - pd.to_numeric(xlead_pair_ret, errors="coerce")) >= float(self.buy_xleadrot_gap_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_relvol"], errors="coerce") >= float(self.buy_xleadrot_relvol_min.value)).fillna(False)
            & (base_close > base_high.rolling(xlead_lb).max().shift(1)).fillna(False)
        ).fillna(False)

        xquiet_lb = max(2, int(self.buy_xquietbreak_breakout_lookback.value))
        dataframe["xquietbreak_signal_long"] = (
            trend_ok
            & btc_stable.fillna(False)
            & (pd.to_numeric(dataframe["nalpha_excess_btc_12"], errors="coerce") >= float(self.buy_xquietbreak_excess_min.value)).fillna(False)
            & (pd.to_numeric(dataframe["nalpha_relvol"], errors="coerce") >= float(self.buy_xquietbreak_relvol_min.value)).fillna(False)
            & (base_close > base_high.rolling(xquiet_lb).max().shift(1)).fillna(False)
        ).fillna(False)

        return dataframe

    def _nalpha_entry_allows(self, family: str, pair: str, row: pd.Series | dict, current_time: datetime) -> tuple[bool, str]:
        self._nalpha_init_state()
        enabled_map = {
            "xresmom": bool(self.buy_xresmom_enabled.value),
            "xidiorev": bool(self.buy_xidiorev_enabled.value),
            "xmacrohour": bool(self.buy_xmacrohour_enabled.value),
            "xleadrot": bool(self.buy_xleadrot_enabled.value),
            "xquietbreak": bool(self.buy_xquietbreak_enabled.value),
        }
        if not enabled_map.get(family, False):
            return False, "nalpha_disabled"
        if not self._nalpha_pair_allowed(family, pair):
            self._nalpha_counts["block_pair"] += 1
            return False, "nalpha_pair_block"
        candidate_tag = self._nalpha_tag(family)
        if self._nalpha_core_demand(pair, current_time, row=row):
            if not (
                self._srr_bucket_applies(candidate_tag)
                and bool(self.buy_srr_bucket_ignore_nalpha_core_demand.value)
            ):
                self._nalpha_counts["block_core_demand"] += 1
                return False, "nalpha_core_demand"
        day_ok, _ = self._nalpha_daily_limits_allow(family, current_time)
        if not day_ok:
            self._nalpha_counts["block_governance"] += 1
            return False, "nalpha_daily_block"
        cd_block, _ = self._nalpha_cooldown_blocks(family, pair, current_time)
        if cd_block:
            self._nalpha_counts["block_governance"] += 1
            return False, "nalpha_cooldown"
        self._nalpha_counts["raw"] += 1
        if not bool(row.get(self._nalpha_signal_col(family), False)):
            self._nalpha_counts["block_signal"] += 1
            return False, "nalpha_no_signal"
        self._nalpha_counts["allowed"] += 1
        return True, "nalpha_ok"

    def _novel_alpha_apply_entries(self, dataframe: pd.DataFrame, pair: str) -> pd.DataFrame:
        if not self._novel_alpha_any_enabled():
            return dataframe
        self._nalpha_init_state()
        dataframe = self._novel_alpha_add_context(dataframe, pair)
        family_rows = [
            ("xresmom", bool(self.buy_xresmom_enabled.value), bool(self.buy_xresmom_debug.value)),
            ("xidiorev", bool(self.buy_xidiorev_enabled.value), bool(self.buy_xidiorev_debug.value)),
            ("xmacrohour", bool(self.buy_xmacrohour_enabled.value), bool(self.buy_xmacrohour_debug.value)),
            ("xleadrot", bool(self.buy_xleadrot_enabled.value), bool(self.buy_xleadrot_debug.value)),
            ("xquietbreak", bool(self.buy_xquietbreak_enabled.value), bool(self.buy_xquietbreak_debug.value)),
        ]
        for family, enabled, debug_flag in family_rows:
            if not enabled:
                continue
            sig_col = self._nalpha_signal_col(family)
            raw_long = dataframe.get(sig_col, False)
            if isinstance(raw_long, pd.Series):
                raw_long = raw_long.fillna(False).astype(bool)
            else:
                raw_long = pd.Series(False, index=dataframe.index, dtype=bool)
            mask = (
                (dataframe["enter_long"] == 0)
                & (dataframe["enter_short"] == 0)
                & (dataframe["volume"] > 0)
                & raw_long
            )
            if bool(self.buy_nalpha_block_if_core_open.value) and self._open_core_trades_count() > 0:
                mask &= False
                self._nalpha_counts["block_core_demand"] += 1
            if bool(self.buy_nalpha_block_if_core_signal.value):
                core_sig_mask = (
                    ((dataframe["enter_long"] == 1) | (dataframe["enter_short"] == 1))
                    & ~dataframe["enter_tag"].astype(str).map(self._is_auxiliary_entry_tag)
                )
                mask &= ~core_sig_mask
            if bool(mask.any()):
                for idx in mask[mask].index:
                    row_i = dataframe.loc[idx]
                    row_time = pd.Timestamp(row_i.get("date")) if "date" in row_i else None
                    if row_time is None:
                        continue
                    allow_i, reason_i = self._nalpha_entry_allows(family, pair, row_i, row_time)
                    if allow_i and int(dataframe.at[idx, "enter_long"]) != 1 and int(dataframe.at[idx, "enter_short"]) != 1:
                        dataframe.at[idx, "enter_long"] = 1
                        dataframe.at[idx, "enter_tag"] = self._nalpha_tag(family)
                        self._nalpha_mark_entry(family, row_time)
                        self._nalpha_counts["stamped"] += 1
                    elif debug_flag:
                        logger.info("NALPHA_BLOCK family=%s pair=%s ts=%s reason=%s", family, pair, row_time, reason_i)
        return dataframe

    def _nalpha_cleanup_trade(
        self,
        trade: Trade,
        current_time: datetime | None = None,
        profit_ratio: float | None = None,
    ) -> None:
        try:
            tag = getattr(trade, "enter_tag", None) or getattr(trade, "entry_tag", None)
            if not self._is_nalpha_entry_tag(tag):
                return
            key = self._idle_trade_key(trade)
            self._nalpha_hwm.pop(key, None)
            if current_time is not None:
                pnl = float(profit_ratio) if profit_ratio is not None else float(getattr(trade, "close_profit", 0.0) or 0.0)
                if pnl < 0:
                    self._nalpha_mark_loss(self._nalpha_family_from_tag(tag), trade.pair, current_time)
        except Exception:
            pass

    def _spreadarb_core_demand(self, pair: str, current_time: datetime | None, row: pd.Series | dict | None = None) -> bool:
        core_open = bool(self.buy_spreadarb_block_if_core_open.value) and self._open_core_trades_count() > 0
        core_sig = False
        if bool(self.buy_spreadarb_block_if_core_signal.value):
            probe = row if row is not None else self._pair_row_at_or_before_time(pair, current_time)
            core_sig = self._core_signal_present(probe)
        return bool(core_open or core_sig)

