                brf_variant = self._brf_variant_for_trade(pair, trade)
                if brf_variant == "classic":
                    pause = int(self.sell_brf_classic_pair_cooldown_candles.value)
                else:
                    pause = int(self.sell_brf_pair_cooldown_bars.value)
                extra_hours = int(self.sell_brf_cooldown_hours_after_sl.value)
                if brf_variant != "classic" and extra_hours > 0:
                    tf_minutes = max(1, self._timeframe_to_minutes(self.timeframe))
                    extra_bars = int(np.ceil((extra_hours * 60.0) / float(tf_minutes)))
                    pause = max(pause, extra_bars)
                self._brf_cooldown_until_idx[pair] = now_idx + pause
